  ["40:4e55"] = "Das POKéMON\
wurde auf \12BILLs PC\
übertragen.",
  ["40:4e96"] = "{STRBUF}\
POKéMON ARENA",
  ["40:4ea4"] = "LEITUNG: {STRBUF}\12Bisherige Sieger:\
{PLAYER}",
  ["40:4ec7"] = "Willkommen in der\
SPIELHALLE.",
  ["40:4ee4"] = "Brauchst du noch\
Spielmünzen?\12Oh, du hast noch\
keinen MÜNZKORB\11für deine Münzen.",
  ["40:4f2b"] = "Brauchst du noch\
Spielmünzen?\01250 Münzen kosten\
¥1000. Möchtest\11du welche kaufen?",
  ["40:4f78"] = "Dankeschön!\
Hier sind deine\01150 Münzen!",
  ["40:4f97"] = "Dankeschön!\
Hier sind deine\011500 Münzen!",
  ["40:4fb7"] = "Du hast nicht\
genügend Geld.",
  ["40:4fd4"] = "OH! Dein\
MÜNZKORB ist voll.",
  ["40:4ff5"] = "Du brauchst keine\
Münzen? Komm\11später nochmal!",
  ["40:5014"] = "Oh? Dein BEUTEL\
ist voll.\12Wir bewahren das\
für dich auf. Hol\12es dir ab, wenn\
du genügend Platz\11geschaffen hast.",
  ["40:5072"] = "Wow! Du und dein\
POKéMON versteht\11euch sehr gut!",
  ["40:509c"] = "POKéMON werden\
zutraulicher, wenn\12du viel Zeit mit\
ihnen verbringst.",
  ["40:50d1"] = "Du hast deine\
POKéMON noch nicht\11gezähmt.\12Wenn du es nicht\
gut behandelst,\11ist es einge-\11schnappt.",
  ["41:4a8a"] = "Guten Morgen!",
  ["41:4a99"] = "Hallo?\12Oh, hi, {PLAYER}!\
Hart am Arbeiten?",
  ["41:4b04"] = "Wirklich? Du bist\
in\11{STRBUF}?\12Ich war dort noch\
nie. Das ist sehr\11nett, {PLAYER}.",
  ["41:4b4a"] = "Was? Du bist in\
{STRBUF}?\12Besuch doch mal\
deine MAMA!",
  ["41:4b7d"] = "Du besuchst\
{STRBUF}?\12Du könntest ja mal\
nach Hause kommen.",
  ["41:4bb5"] = "Wow, du besuchst\
{STRBUF}?\12Viel Glück bei\
deiner Suche nach\11POKéMON!",
  ["41:4be9"] = "Das klingt wirk-\
lich hart.\12Aber, {PLAYER},\
ich weiß, dass du\12sehr ausdauernd\
bist. Du schaffst\11das schon!",
  ["41:4c40"] = "Nebenbei, du hast\
¥{STRBUF}\12gespart. Willst du\
weitersparen?",
  ["41:4c83"] = "Es ist wichtig,\
Geld zu sparen.",
  ["41:4ca6"] = "Oh, {PLAYER},\
du sparst ja gar\12nicht. Möchtest du\
sparen?",
  ["41:4ce2"] = "Nebenbei, du hast\
¥{STRBUF}\12gespart. Willst du\
wieder mit dem\12Sparen anfangen?",
  ["41:4d22"] = "O.K. Ich werde\
dein Geld sparen.",
  ["41:4d3c"] = "O.K. Ich höre auf,\
dein Geld zu spa-\11ren.",
  ["41:4d5d"] = "{PLAYER}, mach\
weiter so! Ich\11drück dir die\11Daumen!",
  ["41:4d87"] = "Hallo?\12Oh, hi, {PLAYER}!\
Hat PROF. LIND\11nicht auf dich ge-\11wartet?",
  ["41:4dba"] = "Hallo?\12Oh, hi, {PLAYER}!\
Du bist auf einer\12Mission für PROF.\
LIND? Viel Glück!",
  ["41:4dfc"] = "Hallo?\12Hi, {PLAYER}!\
Wenn du deinen\12Auftrag ausgeführt\
hast, komm nach\11Hause.",
  ["41:4e3e"] = "Hallo?\12…… {PLAYER}?\
Ich hörte von\12PROF. LIND, dass\
du auf einer\11langen Reise bist.\12Ich wünschte, du\
hättest mir davon\11erzählt…\12Wie steht's mit\
Geld? Soll ich für\11dich sparen?",
  ["41:4ec4"] = "Guten Morgen!\12Dies ist der VER-\
WALTUNGSSERVICE\12DES POKéMON-LAGE-\
RUNGS-SYSTEMS.",
  ["41:4f0d"] = "Guten Tag!\12Dies ist der VER-\
WALTUNGSSERVICE\12DES POKéMON-LAGE-\
RUNGS-SYSTEMS.",
  ["41:4f52"] = "Guten Abend!\12Dies ist der VER-\
WALTUNGSSERVICE\12DES POKéMON-LAGE-\
RUNGS-SYSTEMS.",
  ["41:4f9b"] = "Mit wem spreche\
ich?\12{PLAYER}, richtig?\
Einen Moment,\11bitte…\12……\
……",
  ["41:4fc7"] = "Entschuldige bitte\
die Wartezeit!\12{PLAYER}, deine BOX\
bietet Platz für\11{STRBUF}\11weitere POKé-\11MON.\12Zieh los und mach\
sie voll!",
  ["41:5024"] = "Entschuldige bitte\
die Wartezeit!\12{PLAYER}, deine BOX\
bietet nur noch\11Platz für {STRBUF}\11weitere POKéMON.\12Vielleicht soll-\
test du die BOX\11wechseln.",
  ["41:508a"] = "Entschuldige bitte\
die Wartezeit!\12{PLAYER}, deine BOX\
ist voll!\12Du musst die BOX\
wechseln, wenn du\12noch mehr POKé-\
MON fangen willst.",
  ["41:50ef"] = "Hi, {PLAYER}?\
Ich bin's, BILL!\12Danke, dass du das\
LAGERUNGSSYSTEM\11benutzt.\12Das letzte POKé-\
MON, das du ge-\11schickt hast, hat\11deine BOX voll ge-\11macht.\12Du musst die BOX\
wechseln, wenn du\12mehr POKéMON fan-\
gen willst.\12Bis dann!",
  ["41:5199"] = "Hallo, {PLAYER}?\12Überanstrenge dich\
nicht.\12Heile deine POKé-\
MON, wenn sie ver-\11letzt sind.",
  ["41:51e6"] = "Hallo, {PLAYER}?\12Hast du MR. POKé-\
MON getroffen?\11Toll! Komm gut\11heim!",
  ["41:5221"] = "{PLAYER}? Ich\
bin gerade sehr\11aufgeregt!\12Ein POKéMON wurde\
von hier gestoh-\12len. Wie kann je-\
mand so etwas nur\11tun?",
  ["41:5272"] = "Hallo, {PLAYER}?\12Wir untersuchen\
das EI. Es scheint\12ein POKéMON-EI\
zu sein.",
  ["41:52b9"] = "Hallo, {PLAYER}?\12Hast du meinen\
Assistenten ge-\12troffen? Er ist im\
POKéMON CENTER von\11VIOLA CITY.",
  ["41:5305"] = "Hallo, {PLAYER}?\12Wie geht es dem\
EI? Hat sich was\11getan?\12Wenn sich etwas\
tut, ruf mich\11bitte an.",
  ["41:5358"] = "Hallo, {PLAYER}?\
Wie geht es dem\11EI?\12Wie? Etwas ist ge-\
schlüpft? Wow! Was\11für ein POKéMON\11ist es?\12Bitte komm und\
zeig es mir!",
  ["41:53bc"] = "Hallo, {PLAYER}?\12Ich habe gerade\
eine neue Entde-\11ckung gemacht.\12Die Zeit, die ver-\
geht, bis etwas\12aus dem EI\
schlüpft, hängt\12vom jeweiligen\
POKéMON ab.",
  ["41:541f"] = "Hallo, {PLAYER}?\12Es ist noch immer\
ein Geheimnis,\12über welche Atta-\
cken frisch ge-\12schlüpfte POKéMON\
verfügen.\12Wir sind dabei,\
das herauszufin-\11den.",
  ["41:5484"] = "Hallo, {PLAYER}?\12Ich habe etwas Ei-\
genartiges ent-\11deckt.\12Offensichtlich\
gibt es etwas na-\12mens POKéRUS, das\
POKéMON infiziert.\12Es ist wie ein Vi-\
rus, daher heißt\11es POKéRUS.\12Es vermehrt sich\
rasch und infi-\12ziert auch andere\
POKéMON. Das\12ist aber auch\
alles.\12Es scheint, als\
würde es nichts\12tun, und nach ei-\
niger Zeit wieder\11verschwinden.\12Ich denke, es ist\
nichts Besorgnis-\11erregendes.\11Tschüss!",
  ["41:55b4"] = "H-hallo? {PLAYER}?\
Es ist eine Katas-\11trophe!\12Äh, ähm, es ist\
einfach schreck-\11lich!\12Was soll ich tun?\
Es… Oh, nein…\12Bitte komm hierher\
zurück!",
  ["41:5624"] = "Hallo, {PLAYER}?\
Wir haben etwas\12über das EI he-\
rausgefunden!\12Mein Assistent ist\
im POKéMON CENTER\12von VIOLA CITY.\
Würdest du mit ihm\11sprechen?",
  ["41:56a3"] = "{PLAYER}, wie\
stehen die Dinge?\12Ich rufe an, weil\
ich im Radio etwas\12Seltsames gehört\
habe.\12Sie sprachen über\
TEAM ROCKET.\12{PLAYER}, weißt\
du etwas darüber?\12Vielleicht ist\
TEAM ROCKET zu-\12rückgekehrt. Das\
wäre nicht auszu-\11denken.\12Entschuldige, dass\
ich dich gestört\11habe. Pass auf\11dich auf!",
  ["41:57a6"] = "Hallo, {PLAYER}?\12Ich habe hier et-\
was für dich.\12Könntest du kurz\
im LABOR vorbei-\11kommen?\12Bis später!",
  ["41:5862"] = "Hallo. Hier ist\
{STRBUF}…\12Guten Morgen,\
{PLAYER}!",
  ["41:588a"] = "Hallo. Hier ist\
{STRBUF}…\12Wie geht's,\
{PLAYER}?",
  ["41:58b3"] = "Hallo. Hier ist\
{STRBUF}…\12Guten Abend,\
{PLAYER}!",
  ["41:58db"] = "Hi. Hier ist\
{STRBUF}.\12Hi, {PLAYER}!\
Guten Morgen.",
  ["41:5904"] = "Hi. Hier ist\
{STRBUF}.\12Hi, {PLAYER}!\
Wie geht es dir?",
  ["41:592c"] = "Hi. Hier ist\
{STRBUF}.\12Hi, {PLAYER}!\
Guten Abend.",
  ["41:5955"] = "{PLAYER}, guten\
Morgen!\12Ich bin's,\
{STRBUF}.\11Wie geht es dir?",
  ["41:5989"] = "{PLAYER}, howdy!\12Ich bin's,\
{STRBUF}.\12Ist es heute nicht\
schön?",
  ["41:59b5"] = "{PLAYER}, guten\
Abend!\12Ich bin's,\
{STRBUF}.\12Hast du eine Mi-\
nute Zeit?",
  ["41:59e4"] = "Guten Morgen,\
{PLAYER}.\12Hier ist\
{STRBUF}.\12Hab ich dich ge-\
weckt?",
  ["41:5a15"] = "Hallo, {PLAYER}.\12Hier ist\
{STRBUF}.\12Wie stehen die\
Dinge?",
  ["41:5a3f"] = "Guten Abend,\
{PLAYER}.\12Hier ist\
{STRBUF}.\12Warst du noch auf?",
  ["41:5a70"] = "Wie geht es deinen\
POKéMON?\12Mein {STRBUF}\
ist voller\11Energie!",
  ["41:5ab5"] = "Wie geht es deinen\
POKéMON?\12Ich halte mein\
{STRBUF} in\12Topform, indem ich\
regelmäßig POKé-\12MON CENTER besu-\
che.",
  ["41:5b0d"] = "Mein {STRBUF}\
sieht toll aus!\12Ich wünschte, ich\
könnte es dir\11zeigen.",
  ["41:5b42"] = "Ich habe mein\
{STRBUF}\12verkleidet. Es\
sieht noch süßer\11aus als vorher.",
  ["41:5b7b"] = "Oh, yeah, ich habe\
es geschafft, ein\11starkes\11{STRBUF}\11zu besiegen.\12Ich muss mein Team\
verstärken.",
  ["41:5bcb"] = "Das musst du hö-\
ren! Vorgestern\12habe ich gegen ein\
{STRBUF}\11gekämpft.\12Es war einfach!\
Ich war aufgrund\12der Element-Klasse\
im Vorteil.",
  ["41:5c27"] = "Hey, hör mal!\
Die Tage habe ich\12fast ein\
{STRBUF}\11gefangen.\12Oh, es war soooo\
knapp!",
  ["41:5c76"] = "Stell dir vor, was\
passiert ist!\12Ich habe es schon\
wieder nicht ge-\12schafft, ein\
{STRBUF} zu\12fangen. Vielleicht\
bin ich einfach zu\11schlecht…",
  ["41:5da0"] = "Hallo? Hier ist\
{STRBUF}…\12Uh-oh… Du bist\
nicht HERBERT! Tut\11mir Leid, falsch\11verbunden.",
  ["41:5de2"] = "Hallo, hier ist\
{STRBUF}.\11Wie geht es dir,\11KATJA?\12Huch? {PLAYER}?\
Ups! Mein Fehler!",
  ["41:5e2e"] = "Bis später!",
  ["41:5e3e"] = "Bye-bye!",
  ["41:5f50"] = "Das Käferturnier\
findet heute im\12PARK statt.\12{PLAYER}, wirst\
du teilnehmen?",
  ["41:5fa4"] = "{PLAYER}, wuss-\
test du das schon?\12Ich habe gehört,\
der RADIOTURM von\12DUKATIA CITY wurde\
von TEAM ROCKET\11eingenommen.\12Aber was ist TEAM\
ROCKET eigentlich?",
  ["41:6014"] = "{PLAYER}, hast du\
die Neuigkeiten\11gehört?\12TEAM ROCKET hat\
den RADIOTURM von\12DUKATIA CITY ein-\
genommen.\12Ich frage mich, ob\
es den Angestell-\11ten gut geht…",
  ["41:608d"] = "Hi, {PLAYER}!\
Unsere FAHRRAD-\12Verkäufe brechen\
alle Rekorde!\12Das verdanken wir\
nur dir, weil du\12mit unserem FAHR-\
RAD herumgefahren\11bist.\12Als Dankeschön\
darfst du das\12FAHRRAD behalten.\
Herzlichen Dank!",
  ["42:4027"] = "Wir bewachen\
diesen Turm.\12In tiefster Dank-\
barkeit ehren wir\11hier alle POKéMON.",
  ["42:4078"] = "Da-Danke!",
  ["42:4087"] = "Die Basis jeder\
Koexistenz ist\11Zusammenarbeit.\12Lasst uns dies\
nie vergessen!",
  ["42:40dc"] = "Nur wenn du es bis\
ganz nach oben\11schaffst, erhältst\11du eine VM.",
  ["42:410e"] = "Der KNOFENSA-TURM\
wurde vor langer\12Zeit als POKéMON-\
Trainingsstätte\11errichtet.",
  ["42:414d"] = "Ein über 30 m\
grosses KNOFENSA…\12Man sagt, es wurde\
die Trägersäule\11des Turmes.",
  ["42:41a1"] = "Siehst du, wie sie\
sich bewegt?\12Die Trainer fin-\
dest du oben.",
  ["42:41da"] = "Eine PKMN-Statue…\12Sie sieht sehr\
erhaben aus.",
  ["42:42ad"] = "Wie hart wir auch\
kämpfen, der TURM\11bleibt stehen.",
  ["42:42e3"] = "Ich kämpfte hart,\
aber ich bin ein-\11fach zu schwach.",
  ["42:4303"] = "Aufgrund der\
flexiblen Säule\12ist der TURM\
erdbebensicher.",
  ["42:4345"] = "… Wirble wie\
Laub im Wind…",
  ["42:4365"] = "Ich bin schwach!",
  ["42:4373"] = "Ich habe versucht,\
KNOFENSAs elegante\12Bewegungen im\
Kampf nachzuahmen…\12Aber ich habe\
nicht intensiv\11genug trainiert.",
  ["42:43cc"] = "Eine PKMN-Statue…\12Sie sieht sehr\
erhaben aus.",
  ["42:452b"] = "WEISER: Du bist \
wirklich ein\11begabter Trainer.\12Wie abgemacht, be-\
kommst du die VM.\12Eines gebe ich dir\
noch mit: \12Behandle deine\
POKéMON besser.\12Dein Kampfstil\
ist zu aggressiv.\12POKéMON sind keine\
Kampfspielzeuge…",
  ["42:45f0"] = "…\
…Hmpf!\12Er behauptet,\
ein WEISER zu\11sein. Aber er ist\11schwach.\12Das muss noch\
geklärt werden.\12Ich würde nie ge-\
gen so einen Nar-\12ren verlieren, der\
mir rät, meine\11POKéMON gut zu\11behandeln.\12Für mich zählen\
nur starke\11POKéMON.\12Schwache POKéMON \
interessieren mich\11gar nicht.",
  ["42:46cc"] = "{RIVAL} benutzt\
FLUCHTSEIL!",
  ["42:46e4"] = "Schön, dass du\
gekommen bist!\12Der KNOFENSA-TURM\
ist eine\11Trainingsstätte.\12Trainer und\
POKéMON prüfen\12ihre Freundschaft,\
um gemeinsam eine\11rosige Zukunft\11aufzubauen.\12Und ich bin der\
letzte Test.\12Erlaube, dass ich\
die Freundschaft\11zwischen dir und\11deinem POKéMON\11überprüfe!",
  ["42:47b6"] = "Ah, sehr gut!",
  ["42:47c6"] = "Du und dein POKé-\
MON dürftet keine\12Probleme mit die-\
ser Attacke haben.\12Nimm diese VM.\
Sie enthält BLITZ.",
  ["42:4817"] = "Mit BLITZ kannst\
du die dunkelsten\11Orte erhellen.\12Um BLITZ auch\
außerhalb eines\12Kampfes anwenden\
zu können, benö-\11tigst du den ORDEN\11des ARENALEITERs\11von VIOLA CITY.",
  ["42:488c"] = "Ich hoffe, du\
lernst viel auf\11deiner Reise.",
  ["42:48ba"] = "Ich trainiere, um\
durch POKéMON die\11Erleuchtung\11zu finden!",
  ["42:48e2"] = "Besiegt von einem\
Kind!",
  ["42:48fb"] = "Je stärker die\
POKéMON werden,\11desto stärker wird\11auch ihr Trainer.\12Nein, warte! Je\
stärker der Trai-\11ner wird, desto\11stärker werden\11auch die POKéMON.",
  ["42:4961"] = "Ich will sehen,\
wie sehr du deinen\11POKéMON vertraust.",
  ["42:498b"] = "Ja, du vertraust\
ihnen wirklich!",
  ["42:49a5"] = "Du triffst bald\
auf den WEISEN.",
  ["42:49c2"] = "Mit der VM des\
WEISEN kannst du\11selbst dunkelste\11Orte erhellen.",
  ["42:49f4"] = "Denken ist eben\
Meine Stärke!",
  ["42:4a13"] = "Möge dein Weg\
erleuchtet sein.",
  ["42:4a38"] = "Dies ist ein dy-\
namisches Gemälde\11von KNOFENSA.",
  ["42:4a62"] = "Eine PKMN-Statue…\12Sie sieht sehr\
erhaben aus.",
  ["42:4b20"] = "Ich versuche, das\
Rätsel um das\12legendäre POKéMON,\
das hier landen\11soll, zu lösen.\12Man sagt, dass das\
POKéMON ständig\12fliegt, seitdem\
der TURM im Westen\11abgebrannt ist.\12Also habe ich mir\
gedacht, dass das\12POKéMON angelockt\
wird, wenn ich ein\11Item besitze, das\11es auch besitzt.\12Ich glaube, dieses\
Item ist…\12Eine BUNTSCHWINGE!\12Aber wo finde\
ich eine solche?",
  ["42:4f24"] = "…… …… ……\12…Oh, du bist es.\12Du willst stärker\
werden, also kamst\12du hierher, um das\
legendäre POKéMON,\12das hier sein\
soll, zu fangen.\11Ist es nicht so?\12Nun, das wird\
nicht passieren.\12Weil ich es näm-\
lich fangen werde!\12Ich werde der\
beste Trainer der\11Welt sein, also\11stünde mir ein\11legendäres POKéMON\11gut zu Gesicht.\12…Egal!\
Mich nervt es,\12dass ständig so\
ein Schwächling\11wie du auftaucht.",
  ["42:5093"] = "…Humpf!\12Ich hasse es, ge-\
gen Schwächlinge\12wie dich anzutre-\
ten. Es ist keine\11Herausforderung.",
  ["42:50da"] = "…Ach, Egal!\12Du wärst sowieso\
nicht fähig, ein\12legendäres POKéMON\
zu fangen.",
  ["42:5124"] = "…Humpf!\12Ich hasse es, ge-\
gen Schwächlinge\12anzutreten. Es ist\
Zeitverschwendung.",
  ["42:516d"] = "Äh, ich absolviere\
hier mein Geheim-\11training!\12Du machst mich\
ganz verlegen, \11wenn du zuschaust!",
  ["42:51ac"] = "Ich bin nur noch\
weiße Asche…",
  ["42:51cb"] = "Ich war so in mein\
Training vertieft,\12dass ich in dieses\
Loch fiel.",
  ["42:5202"] = "Meine Seele\
brennt. Ich zeige\12dir, wie heiss das\
Feuer ist!",
  ["42:5236"] = "Immer noch nicht\
heiß genug…",
  ["42:524d"] = "Früher gab es\
diese POKéMON, die\12mit hohem Tempo\
durchs Gras\11gerannt sind.\12Man sagt, dass sie\
schnell wie der\12Wind waren. Falls\
dir im Gras eines\11begegnet, wird es\11wohl davonlaufen.",
  ["42:552a"] = "Einige DIGDAS sind\
plötzlich vor mir\12aufgetaucht! Ich\
habe mich er-\11schreckt.",
  ["42:562d"] = "…… …… ……\12Es ist schon lange\
her, {PLAYER}.\12…Seit ich gegen\
dich verlor, mache\12ich mir Gedanken,\
was meinen POKéMON\11noch fehlt…\12Nun, wir haben\
eine Antwort\11gefunden.\12{PLAYER}, wir\
beweisen es dir!",
  ["42:56c5"] = "…… …… ……\12Ich glaubte immer,\
meine POKéMON so\12aufgezogen zu ha-\
ben, dass sie un-\11schlagbar seien.…\12…Aber ich\
habe versagt…",
  ["42:5722"] = "…… …… ……\12…Du hast mich\
fair besiegt.\12Das muss ich dir\
lassen. Wir werden\11uns wiedersehen.\12Ich werde der\
beste POKéMON-\11Trainer aller\11Zeiten sein.\12Und sie werden\
mir dabei helfen.\12…Hör mal, {PLAYER}.\12Eines Tages werde\
ich es dir bewei-\12sen. Dann besiege\
ich dich.",
  ["42:5808"] = "…… …… ……\12Ich habe meine\
Schuld bei dir\11abgegolten.\12Mit meinen POKéMON\
werde ich den\12CHAMP besiegen\
und weltbester\11Trainer werden.",
  ["42:5a87"] = "Moment.\12…Wirst du das\
POKéMON LIGA-\11Abenteuer\11bestreiten?\12…Bring mich nicht\
zum Lachen.\12Du bist viel\
schwächer als ich.\12Ich bin nicht mehr\
so wie früher.\12Nun habe ich die\
besten und\12stärksten POKéMON.\
Ich bin\11unschlagbar!\12{PLAYER}! Ich for-\
dere dich heraus!",
  ["42:5b65"] = "…Ich konnte nicht\
gewinnen…\12Ich habe ihm\
alles gegeben…\12Was du besitzt\
und was mir fehlt…\12Langsam begreife\
ich, was der\12Drachenmeister zu\
mir sagte…",
  ["42:5bf6"] = "…Ich habe nicht\
aufgegeben, der\11weltbeste Trainer\11zu werden…\12Ich werde\
herausfinden,\12warum ich nicht\
gewinnen kann und\11dann werde ich\11stärker…\12Wenn ich soweit\
bin, fordere ich\11dich heraus.\12Dann werde ich\
dir die Leviten\11lesen.\12…Humpf! Bleib\
bis dahin dabei.",
  ["42:5cd2"] = "…Humpf!\12Wenn es darauf\
ankommt, gibt es\11nichts, was Stärke\11Paroli bieten\11kann.\12Mehr brauche ich\
nicht.",
  ["43:4196"] = "Sieh dir meine\
Tasche an!\12Ich habe meine\
Lieblinge aus dem\12POKéDEX gedruckt\
und auf meine\11Tasche geklebt.",
  ["43:41f1"] = "Das ist ein\
BRIEF von meiner\11Tochter. Das macht\11mir Freude.",
  ["43:4228"] = "Pass bitte auf!\12…Ohh, ich muss\
aufhören, immer\12wie ein Lehrer zu\
denken.\12Du musst ein\
POKéMON-Trainer\11sein.\12Da du so hart\
arbeitest, möchte\12ich dir dies\
überreichen.",
  ["43:42d0"] = "Gib die FLINKKLAUE\
einem POKéMON.\12Manchmal erhält es\
durch sie die\11Initiative.",
  ["43:4320"] = "Ich spiele mit\
Stickern, die ich\11aus meinem POKéDEX\11gedruckt habe.",
  ["43:4352"] = "Falls ich gewinne,\
erhalte ich die\11POKéDEX-Sticker\11meines Gegners.",
  ["43:437f"] = "Ich gehe oft\
im PARK spazieren,\12aber ich meide\
das hohe Gras.\12Trainer möchten\
immer kämpfen…",
  ["43:43d9"] = "SNOBILIKAT: Fauch!",
  ["43:43ed"] = "Ich drucke meinen\
POKéDEX aus.\12Du kannst auch\
BRIEFE oder\12PC-BOXEN\
ausdrucken.",
  ["43:4441"] = "Die POKéMON-Welt\
bietet dir viel.\12Es gibt noch viele\
Dinge, über die\11wir nichts wissen.\12Aber ich weiß\
mehr als du!",
  ["43:44a7"] = "Wa-Wa-Was?",
  ["43:44b6"] = "Man kann noch\
viel lernen.\12Zum Beispiel…\12Es gibt 50\
verschiedene TMs.\12Getauschte POKéMON\
erhalten mehr\11Erfahrungspunkte.",
  ["43:4514"] = "Meine POKéMON sind\
so niedlich. Ich\11möchte sie dir\11zeigen!",
  ["43:4547"] = "Ich kann dich\
vielleicht nicht\11im Kampf besiegen…\12Aber meine\
sind viel süßer.",
  ["43:4584"] = "Mein Freund hat\
ein MARILL. Das\12ist so niedlich!\
Ich wünschte, ich\12hätte auch eines.",
  ["43:45c1"] = "Wir bewundern\
unsere POKéMON,\11auch wenn sie uns\11nicht mögen.\12Das macht eben den\
wahren FAN aus.",
  ["43:4611"] = "Mei-Mein POKéMON!",
  ["43:461d"] = "Ich habe zwar den\
Kampf verloren,\12aber meine POKéMON\
gewinnen den\11Schönheitspreis.",
  ["43:4662"] = "Was ist? Warum\
starrst du mich\11so an?\12Oh, ein Kampf?",
  ["43:4693"] = "…Hmmm…",
  ["43:469b"] = "So wie du mich\
angeschaut hast,\11habe ich geglaubt,\11du magst mich.\12Schließlich bin\
ich hübsch!",
  ["43:46e4"] = "ERHOLUNGSORT\
NATIONALPARK",
  ["43:4705"] = "Was hat diese Mel-\
dung zu bedeuten?\12Kämpfe sind nur\
im Gras gestattet.\12NATIONALPARK\
BÜRO DES WÄCHTERS",
  ["43:475a"] = "TIPPS für TRAINER\12Möchtest du deine\
BRIEFE drucken,\11öffne sie und\11drücke START.",
  ["43:48e0"] = "ULI: Ich werde\
gewinnen! Lass\11mich in Ruhe.",
  ["43:4907"] = "ALAN: Mein PARASEK\
versetzt POKéMON\11mittels PILZSPORE\11in den Schlaf.",
  ["43:4937"] = "LARS: Ich trai-\
niere schnelle\11POKéMON für\11den Kampf.",
  ["43:4960"] = "WILHELM: Gewin-\
nen, ist mir nicht\11wichtig.\12Ich suche seltene\
POKéMON.",
  ["43:49a9"] = "AXEL: Pst! Du\
hast SICHLOR ver-\12schreckt. Ich rede\
später mit dir.",
  ["43:49e6"] = "TILL: Schwäche\
Käfer-POKéMON, ehe\12du einen POKéBALL\
wirfst.",
  ["43:4a25"] = "CINDY: Was ist\
los?\12Findest du es etwa\
lustig, wenn ein\12Mädchen Käfer-\
POKéMON fängt?",
  ["43:4a70"] = "ENNO: Seit meiner\
Kindheit sammle\12ich Käfer-\
POKéMON.\12Du kannst mich\
nicht besiegen!",
  ["43:4acd"] = "GUIDO: Wenn du\
Zeit für Gespräche\12hast, solltest du\
lieber Käfer-\12POKéMON suchen.",
  ["43:4b0c"] = "MICHEL: Ich habe\
Käfer-POKéMON\11lange studiert.\12Ich werde sicher-\
lich gewinnen.",
  ["43:4b4f"] = "ERHOLUNGSORT\
NATIONALPARK",
  ["43:4b70"] = "Was hat diese Mel-\
dung zu bedeuten?\12Kämpfe sind nur\
im Gras gestattet.\12NATIONALPARK\
BÜRO DES WÄCHTERS",
  ["43:4bc5"] = "TIPPS für TRAINER\12Möchtest du deine\
BRIEFE drucken,\11öffne sie und\11drücke START.",
  ["43:4e1f"] = "Willkommen!",
  ["43:4e29"] = "Guten Tag! Leider\
bieten wir heute\11keine Führungen\11an.",
  ["43:4e62"] = "Hallo! Bist du\
wegen der GLÜCKS-\11ZAHL-SHOW hier?\12Soll ich die\
ID-Nummern deiner\11POKéMON über-\11prüfen?\12Wenn du Glück\
hast, gewinnst du\11einen Preis.",
  ["43:4ee2"] = "Die ID-Nummer\
dieser Woche\11lautet {STRBUF}.",
  ["43:4f02"] = "Mal sehen, ob\
du Glück hast.",
  ["43:4f21"] = "……\
……",
  ["43:4f26"] = "Versuche nächste\
Woche erneut\11dein Glück bei der\11GLÜCKSZAHL-SHOW.",
  ["43:4f5d"] = "Wow! Alle fünf\
Ziffern stimmen\11überein!\12Du gewinnst den\
Hauptpreis!\12Du gewinnst einen\
MEISTERBALL!",
  ["43:4fcb"] = "Hey! Die letzten\
drei Ziffern\11stimmen überein!\12Du hast den\
zweiten Preis\11gewonnen: Den\11EP-TEILER!",
  ["43:501e"] = "Ooh, die letzten\
beiden Ziffern\11stimmen überein.\12Du hast den\
dritten Preis\11gewonnen: AP-PLUS.",
  ["43:5068"] = "Leider stimmt\
keine deiner\11Ziffern überein.",
  ["43:508e"] = "Du kannst den\
Preis nicht\11tragen.\12Schaffe Platz und\
komm gleich\11wieder zurück.",
  ["43:50d5"] = "Bei uns läuft\
momentan ein\11besonderes Quiz.\12Beantworte die\
fünf Fragen\11richtig, um ein\11RADIO-MODUL\11zu gewinnen.\12Stecke es in den\
POKéCOM, um\12überall und zu\
jeder Zeit Radio\11hören zu können.\12Möchtest du am\
Quiz teilnehmen?",
  ["43:519a"] = "Frage 1:\12Kannst du dir auf\
dem POKéCOM die\11KARTE anschauen?",
  ["43:51d1"] = "Richtig!\
Frage 2:\12Ist NIDORINA immer\
weiblich?",
  ["43:5204"] = "Korrekt!\
Frage 3:\12Benötigt KURT, der\
POKéBALL-Schmied\11APRICOCO?",
  ["43:524d"] = "So weit, so gut!\
Frage 4:\12Kann KARPADOR\
keine TM-Attacken\11lernen?",
  ["43:528b"] = "Wieder richtig!\
Hier nun die\11letzte Frage:\12PROF. EICHs POKé-\
MON-TALK ist eine\11beliebte Sendung.\12Ist MARIANNE die\
Co-Moderatorin\11dieser Sendung?",
  ["43:530b"] = "Bingo! Richtig!\
Glückwunsch!\12Hier hast du\
deinen Preis:\11ein RADIO-MODUL!",
  ["43:5350"] = "{PLAYER}s POKéCOM\
kann jetzt auch\11als Radio ver-\11wendet werden!",
  ["43:5375"] = "Höre dir bitte\
unsere Shows an!",
  ["43:5399"] = "Oh, nein.\
Das war leider\12falsch. Versuch's\
noch einmal!",
  ["43:53d3"] = "Oh. Ich verstehe.\
Komm wieder, wenn\11du deine Meinung\11geändert hast.",
  ["43:5403"] = "BEN ist ein\
großartiger DJ.\12Seine sonore\
Stimme lässt mich\11dahinschmelzen!",
  ["43:5439"] = "Ich liebe MARGIT\
vom POKéMON-TALK.\12Ich kenne aber\
nur ihre Stimme.",
  ["43:5481"] = "Endlich haben wir\
den RADIOTURM\11besetzt!\12Nun wird jeder\
den TEAM ROCKET-\12Terrorapparat\
kennenlernen!\12Wir zeigen euch,\
wie böse wir sind!",
  ["43:550f"] = "Zu stark! Wir\
müssen dich im\11Auge behalten…",
  ["43:552f"] = "Du bist zu stark.\12Du könntest unsere\
Pläne zerstören.\11Ich muss die\11anderen warnen.…",
  ["43:5574"] = "EG REZEPTION\
S1 VERKAUF\12S2 PERSONAL\
S3 PRODUKTION\12S4 BÜRO DES\
INTENDANTEN",
  ["43:55be"] = "GLÜCKSKANAL!\12Gewinne mit POKé-\
MON-ID-Nummern!\12Tausche deine \
POKéMON, um viele\11ID-Nummern zu\11erhalten!",
  ["43:570e"] = "Du kannst überall\
Radio hören.\11Probier's mal aus!",
  ["43:5740"] = "Wenn POKéMON\
Schlaflieder im\11Radio hören, \11schlafen sie ein.",
  ["43:576d"] = "Warum möchten sie\
den RADIOTURM\11besetzen?",
  ["43:57a0"] = "PUMMELUFF:\
Pummel…",
  ["43:57b5"] = "Zutritt nur für\
autorisiertes\11Personal.\12Das war nicht\
immer so.\12Mit unserem\
INTENDANTEN stimmt\11irgendetwas nicht…",
  ["43:582e"] = "Schau dich in\
Ruhe um.\12Der INTENDANT ist\
wieder nett. So,\11wie er früher war.",
  ["43:5885"] = "Vor drei Jahren\
war das TEAM\11ROCKET gezwungen,\11sich aufzulösen.\12Wir arbeiten hier\
gerade an einem\11Comeback!",
  ["43:58db"] = "Pah! Keine Zeit\
für Sentimenta-\11litäten!",
  ["43:58f1"] = "Wir lassen es\
nicht zu, dass du\11unsere Pläne\11durchkreuzt!",
  ["43:5923"] = "Wir sind TEAM\
ROCKET, die POKé-\11MON-Ausbeuter!\12Wir lieben es,\
Böses zu tun! \11Hast du Angst?",
  ["43:596a"] = "Du glaubst, du\
bist ein Held?",
  ["43:5983"] = "Wir sind nicht\
immer böse. Wir\11tun nur, wonach\11uns ist.",
  ["43:59b7"] = "Hey! Halte dich\
aus unseren Ange-\11legenheiten raus!",
  ["43:59d7"] = "Uff. Ich gebe auf.",
  ["43:59ea"] = "Unsere VORSTÄNDE\
wollen die Macht\11an sich reißen.\12Sie haben Großes\
vor. Ich frage\11mich, was das\11wohl ist?",
  ["43:5a4e"] = "Hahaha!\12Wie langweilig.\
Es war viel zu\12leicht, hier das \
Ruder zu\11übernehmen!\12Komm schon!\
Heitere mich auf!",
  ["43:5aa9"] = "We-Wer bist du?",
  ["43:5aba"] = "Du hast mich\
besiegt. Das werde\11ich nicht\11vergessen!",
  ["43:5ade"] = "S1 VERKAUF",
  ["43:5ae8"] = "PROF. EICHs POKé-\
MON-TALK\12Die beste Show\
am Äther!",
  ["43:5b1b"] = "Überall, jederzeit\
POKéMON Radio",
  ["43:5cbf"] = "Wir haben die Rufe\
von allen bekann-\12ten POKéMON auf\
Tonband.\12Es sind zirka 200.",
  ["43:5d20"] = "Für Trainer sind\
POKéMON wie\11Lebenspartner.\12Es ist schreck-\
lich, wie TEAM\12ROCKET versucht,\
alle POKéMON zu\11kontrollieren.",
  ["43:5d89"] = "Bei uns gibt\
es rund um die Uhr\12Unterhaltungs-\
sendungen.\12Ich versuche\
auch, rund um die\11Uhr zu arbeiten!",
  ["43:5df2"] = "Der Anführer von\
TEAM ROCKET hat\11sich selbst\11eingeschlossen.\12Aber der INTENDANT\
besitzt einen\11Schlüssel.\12Du findest ihn\
im vierten Stock.\12Bitte rette ihn!",
  ["43:5e69"] = "Hast du den\
INTENDANTEN\11retten können?",
  ["43:5e80"] = "Danke!\
Du bist mein Held!\12Dies ist ein\
Zeichen meiner\11Wertschätzung.",
  ["43:5ebf"] = "Es ist SONNENTAG.\
Feuerattacken\11werden kurzzeitig\11verstärkt.",
  ["43:5efa"] = "Du warst einfach\
traumhaft!",
  ["43:5f16"] = "Mir wurden strikte\
Befehle erteilt.\12Ich soll jeden,\
der TEAM ROCKET\11herausfordert,\11pulverisieren!",
  ["43:5f66"] = "Was?!",
  ["43:5f6e"] = "Ich bin meinen\
Pflichten nicht\11nachgekommen…\12Ich werde dafür\
bezahlen müssen…",
  ["43:5fa2"] = "Es ist ein tolles\
Gefühl, POKéMON\11für Verbrechen\11einzusetzen.",
  ["43:5fd2"] = "Machst du Witze?",
  ["43:5fe2"] = "Verlieren macht\
mich mürrisch!\12Mist! Ich hasse\
unfähige POKéMON!",
  ["43:601b"] = "Warum hat sich der\
Rollladen geöff-\12net? Hast du etwas\
damit zu tun?",
  ["43:6060"] = "Ich bin erledigt!",
  ["43:606e"] = "Was?! Du bist an\
unseren Männern im\11UNTERGRUND\11vorbeigekommen?\12Wie hast du das\
fertiggebracht?",
  ["43:60b2"] = "Was macht ein\
fremdes Kind hier?\12Wer bist du?",
  ["43:60e1"] = "Ts! Ich habe\
dich nicht\11ernst genommen!",
  ["43:60ff"] = "Huahahaha…\12Ich kann Signale\
jeder Stärke von\11hier aussenden.",
  ["43:6142"] = "Dies ist der\
Schlitz für\11den TÜRÖFFNER.",
  ["43:615a"] = "{PLAYER} benutzt\
den TÜRÖFFNER.",
  ["43:6174"] = "S2 PERSONAL",
  ["43:6182"] = "POKéMON-MUSIK mit\
DJ BEN",
  ["43:62b0"] = "Als ich bei\
den RUINEN war,\11hörte ich Radio.\12Ich empfing eine\
seltsame Sendung.",
  ["43:6306"] = "MARGIT: Warum?\
Warum muss ich\11das über mich\11ergehen lassen?\12MAUZI, hilf mir!",
  ["43:6349"] = "MARGIT: Oh! Mein\
süßer Retter!\12Nimm dies als\
Zeichen meines\11Dankes!",
  ["43:638d"] = "MARGIT: Für POKé-\
MON mit Normal-\12attacken ist das\
genau das\11Richtige.",
  ["43:63ca"] = "MARGIT: Wir hören\
uns in PROF.\12EICHs POKéMON-\
TALKSHOW wieder.",
  ["43:6404"] = "MAUZI: Mauzi…",
  ["43:6415"] = "Du hast vor, den\
INTENDANTEN zu\11retten?\12Dies wird nicht\
möglich sein, da\11ich dich besiege!",
  ["43:646d"] = "Nein! Unglaublich!",
  ["43:6480"] = "Ich kann es nicht\
glauben, ich\11wurde besiegt!",
  ["43:64a2"] = "Stopp! Ich bin als\
TEAM ROCKET-\11Festung bekannt!\12Keinen Schritt\
weiter!",
  ["43:64ee"] = "Die Festung wurde\
gestürmt!",
  ["43:6507"] = "Du hast dir meinen\
Respekt verdient.\11Hier ist ein Tipp\11für dich.\12Es ist noch nicht\
zu spät. Noch\11kannst du\11umkehren.",
  ["43:6562"] = "Sind POKéMON\
nicht wirklich\11niedlich?\12Ich denke, meine\
POKéMON sind\12niedlich - nachdem\
sie deine besiegt\11haben!",
  ["43:65b3"] = "Oh, nein! Sie sind\
absolut unnütz!",
  ["43:65cf"] = "Ich liebe mein\
hübsches Äußeres!\12Wer schert sich\
um POKéMON?",
  ["43:6600"] = "Exzellent.\12Mit dem RADIOTURM\
können wir\11unser Vorhaben in\11die Tat umsetzen.",
  ["43:6641"] = "Hmmm…\12Jeder große Plan\
hat einen Haken.",
  ["43:6669"] = "Glaubst du allen\
Ernstes, TEAM\11ROCKET aufhalten\11zu können?",
  ["43:669c"] = "S3 PRODUKTION",
  ["43:66ab"] = "S3 STUDIO 2",
  ["43:686a"] = "D-Du! Bist du\
gekommen, um mich\11zu retten?",
  ["43:6889"] = "Ist es das, was du\
erwartet hast?\12Falsch! Ich bin\
ein Betrüger!\12Ich gebe vor, der\
Echte zu sein, um\12unsere Übernahme\
vorzubereiten.\12Möchtest du wis-\
sen, wo wir den\11echten INTENDANTEN\11versteckt haben?\12Ich werde es dir\
verraten, wenn\11du mich besiegst!",
  ["43:6965"] = "O.K. Ich sage\
dir, wo er ist.",
  ["43:6988"] = "Wir haben den\
echten INTENDANTEN\12in das UNTERGRUND-\
LAGERHAUS\11verschleppt.\12Es ist am Ende\
des UNTERGRUNDs.\12Ich bezweifle\
aber, dass du\11so weit kommst.",
  ["43:6a0d"] = "Kleiner, kennst\
du mich noch\12aus dem VERSTECK\
in MAHAGONIA CITY?\12Damals habe ich\
verloren, aber\11diesmal wird mir\11das nicht pas-\11sieren.",
  ["43:6a70"] = "Das darf nicht\
wahr sein!\12Ich habe mich so\
angestrengt und\11dennoch verloren…",
  ["43:6aaa"] = "{PLAYER}, richtig?\12Ein Knirps wie du\
weiß den Glamour\12von TEAM ROCKET\
nicht zu schätzen.\12Eigentlich schade.\
Mir imponiert\11deine Stärke.",
  ["43:6b23"] = "Oh? Du bist\
so weit gekommen?\12Du musst ein aus-\
gezeichneter Trai-\11ner sein.\12Wir planen, die\
RADIOSTATION zu\12annektieren und\
unsere Rückkehr\11bekanntzugeben.\12Das sollte unseren\
Anführer GIOVANNI\12überzeugen, sein\
Solo-Training\11abzubrechen und\11zurückzukehren.\12Wir werden unseren\
früheren Ruhm\11wiedererlangen.\12Ich werde nicht\
zulassen, dass du\11unsere Pläne\11durchkreuzt.",
  ["43:6c45"] = "Nein! Vergib mir,\
GIOVANNI!",
  ["43:6c60"] = "Wie kann das sein?\12Unsere Träume wur-\
den zerschlagen.\12Ich konnte meine\
Aufgabe nicht\11erfüllen.\12Wie GIOVANNI\
werde ich TEAM\12ROCKET hier und\
heute auflösen.\12Leb wohl.",
  ["43:6d04"] = "INTENDANT:\
{PLAYER},\12vielen Dank!\
Dein Wagemut hat\12alle POKéMON\
dieses Landes\12gerettet.\
Ich weiß, es ist\12nicht viel, aber\
nimm dies.",
  ["43:6d7e"] = "Früher stand genau\
hier in DUKATIA\11CITY ein Turm.\12Aber er war alt\
und baufällig.\12Also haben wir\
dort die RADIO-\11STATION errichtet.\12Beim Abriss\
fanden wir dies\11auf der Spitze.\12Man sagt, riesige\
POKéMON flogen\12früher über\
DUKATIA CITY.\12Vielleicht hat ein\
POKéMON diesen\11Gegenstand ver-\11loren.\12Ähnlich wie jenes,\
das am ZINNTURM\12in TEAK CITY\
auftaucht.\12O.K., ich muss in\
mein BÜRO zurück.",
  ["43:6ee3"] = "Früher stand genau\
hier in DUKATIA\11CITY ein Turm.\12Aber er war alt\
und baufällig.\12Also haben wir\
dort die RADIO-\11STATION errichtet.\12Beim Abriss\
fanden wir dies\11auf der Spitze.\12Man sagt, riesige\
POKéMON flogen\12früher über\
DUKATIA CITY.\12Vielleicht hat ein\
POKéMON diesen\11Gegenstand ver-\11loren.\12Ähnlich wie jenes,\
das bei den\12STRUDELINSELN nahe\
bei ANEMONIA CITY\11auftaucht.\12O.K., ich muss in\
mein BÜRO zurück.",
  ["43:7049"] = "INTENDANT: Hallo,\
{PLAYER}!\12Weißt du, ich\
liebe POKéMON.\12Ich habe diese\
RADIOSTATION \12gegründet, um\
meiner Liebe zu\11POKéMON Ausdruck\11zu verleihen.\12Es wäre toll, wenn\
unsere Sendungen\11beliebt wären.",
  ["43:70e3"] = "BEN: Hörst du dir\
unsere Musik an?",
  ["43:7105"] = "S4 Büro des\
INTENDANTEN",
  ["43:711e"] = "S4 STUDIO 1",
  ["44:409f"] = "Hm? Das ist doch\
ein POKéDEX, nicht\11wahr? Darf ich\11ihn sehen?\12Es gibt so viele\
unterschiedliche\11POKéMON.\12Hm? Was ist das?\12Was ist das für\
ein POKéMON?\12Es sieht aus wie\
die merkwürdigen\12Zeichen an den\
Wänden in den\11RUINEN.\12Falls diese Zei-\
chen tatsächlich \11POKéMON sind, dann\11gibt es noch\11viel mehr davon.\12Ich weiß! Lass\
mich deinen POKé-\11DEX erweitern.\11Mir nach!",
  ["44:42c3"] = "Hm… Dies ist ein\
merkwürdiger Ort.",
  ["44:42e3"] = "…",
  ["44:42e6"] = "Ich komme oft\
hierher, um nach-\11zudenken.",
  ["44:42fd"] = "RÄTSELSTEIN\
PUZZLEKAMMER",
  ["44:431a"] = "ALPH-RUINEN\
Fremde willkommen!",
  ["44:433a"] = "ALPH-RUINEN\
FORSCHUNGSZENTRUM\12ALPH-RUINEN:\
Zuständige Behörde",
  ["44:443c"] = "Dies ist eine\
Nachbildung eines\11antiken POKéMON.",
  ["44:4461"] = "Ein POKéMON, das\
mittels\12regenbogenfarbener\
Schwingen grazil\11durch die\11Lüfte schwebte.",
  ["44:4516"] = "Willkommen in\
diesem Raum.\12Dies sind\
verschiebbare\11Bodenplatten, die\12ein POKéMON dar-\
stellen, das von\11Menschen aus der\11Antike gemalt\11wurde.\12Verschiebe die\
Platten so, dass\11ein Bild entsteht.\12Rechts findest du\
eine Beschreibung\11des POKéMON.",
  ["44:45cb"] = "Dies ist eine\
Nachbildung eines\11antiken POKéMON.",
  ["44:45f0"] = "Ein POKéMON, das\
sich am Meeres-\12grund versteckte\
und mit seinen\11Augen auf dem\11Rücken die Um-\11gebung genau\11beobachtete.",
  ["44:46bb"] = "Dies ist eine\
Nachbildung eines\11antiken POKéMON.",
  ["44:46e0"] = "Dieses POKéMON\
bewegte sich mit\12Hilfe seiner zehn\
Tentakel fort.",
  ["44:4795"] = "Dies ist eine\
Nachbildung eines\11antiken POKéMON.",
  ["44:47ba"] = "Dieses Flug-POKé-\
MON griff seine\12Beute mittels\
seiner sensen-\11artigen Reißzähne\11an.",
  ["44:484a"] = "Eine seltsame\
Anwesenheit ist\11hier zu spüren…",
  ["44:486d"] = "Dies ist ein\
großer Raum, aber\11er ist leer.",
  ["44:489b"] = "Dieser Ort strahlt\
eine eigenartige\11Mystik aus.\12Man könnte es fast\
schon als äthe-\11risch bezeichnen.",
  ["44:48e5"] = "Antike Bauten sind\
oft Grabstätten\11für Könige.\12Wie zum Beispiel\
die Pyramiden.",
  ["44:4933"] = "Dies ist eine\
Nachbildung eines\11antiken POKéMON.",
  ["44:4b1e"] = "Geschafft!\12Ich habe deinen\
POKéDEX erweitert.\12Ich habe dir einen\
optionalen POKéDEX\12extra für ICOGNITO\
eingebaut. Er\12speichert sie in\
der Reihenfolge,\11in der du sie\11fängst.",
  ["44:4ba0"] = "{PLAYER}s POKéDEX\
wurde erweitert.",
  ["44:4bb7"] = "Jedes ICOGNITO,\
das du fängst,\11wird darin einge-\11tragen.\12Schlage nach,\
um zu erfahren,\11wie viele es gibt.",
  ["44:4c05"] = "Hast du alle\
verschiedenen\11ICOGNITOS?\12Das ist eine\
Spitzenleistung!\12Ich habe den\
Drucker aufge-\11stellt, um\11ICOGNITOS Daten\11auszudrucken.\12Du kannst ihn\
jederzeit gerne\11benutzen.",
  ["44:4c93"] = "Die RUINEN sind\
zirka 1500\11Jahre alt.\12Aber niemand weiß,\
warum sie erbaut\11wurden.",
  ["44:4ceb"] = "Ich frage mich,\
wie viele POKéMON\11wohl in den RUINEN\11leben?",
  ["44:4d1e"] = "Es gibt POKéMON\
in den RUINEN?\12Das sind unfass-\
bare Neuigkeiten!\12Das müssen wir\
erforschen.",
  ["44:4d71"] = "An die Wände der\
RUINEN sind selt-\12same Zeichen\
gemalt.\12Sie sind der\
Schlüssel zur\11Lösung des Rätsels\11um die RUINEN.",
  ["44:4ded"] = "Die seltsamen\
POKéMON, die du in\11den RUINEN gesehen\11hast?\12Es scheint, sie\
ähneln den\12Zeichnungen an\
den Wänden.\12Hmm…\12Das bedeutet, es\
gibt viele\11von ihnen…",
  ["44:4e8b"] = "ALPH-RUINEN\
10. Forschungsjahr",
  ["44:4eae"] = "Geheimnisvolles\
POKéMON\11Name: ICOGNITO\01226 verschiedene\
gefunden.",
  ["44:4ee3"] = "Das scheint noch\
nicht zu\11funktionieren.",
  ["44:4f02"] = "ICOGNITO kann\
gedruckt werden.",
  ["44:4f5b"] = "Es gibt viele\
wissenschaftliche\11Bücher dort.\12Antike Ruinen…\
Geheimnisse der\11Antike…",
  ["44:505c"] = "Du bist auf dem\
Weg nach AZALEA\11CITY, nicht wahr?\12Lass meine POKéMON\
entscheiden, ob\11du eines Kampfes\11würdig bist.",
  ["44:50b0"] = "Oh, oh, oh!",
  ["44:50bd"] = "O.K.! Ich habe\
mich entschieden.\12Ich gehe erst,\
wenn meine POKéMON\11stärker sind!",
  ["44:5106"] = "Um POKéMON zu\
finden, wandere\11ich durch das\11Land.\12Suchst du auch\
nach POKéMON?\12Dann bist du\
mein Rivale!",
  ["44:516c"] = "Uff. Mein armes\
POKéMON…",
  ["44:5182"] = "Jeden Freitag\
kannst du POKéMON\12in dieser Höhle\
brüllen hören.",
  ["44:51c4"] = "Whoa! Was für\
eine Überraschung!\12Ich habe nicht\
erwartet, hier auf\11jemanden zu\11treffen!",
  ["44:51ff"] = "Whoa! Du hast\
es mir gegeben!",
  ["44:521a"] = "Ich wurde ge-\
nötigt, eine\11FLEGMONRUTE zu\11kaufen.\12Mir tut das arme\
POKéMON Leid.",
  ["44:5266"] = "ZUBATs SUPERSCHALL\
verwirrt mein\11POKéMON noch\11immer.\12Das ärgert mich\
wirklich sehr!",
  ["44:52b1"] = "Ich bin durch!",
  ["44:52c0"] = "Am Wochenende\
kannst du POKéMON\12in dieser Höhle\
brüllen hören.",
  ["44:5300"] = "Mit Licht jagt\
einem eine Höhle\11keine Angst ein.\12Bist du stark\
genug, jagen dir\11POKéMON keine\11Angst ein.",
  ["44:5345"] = "BLITZ!",
  ["44:534d"] = "Das Feuer meines\
POKéMON\11erleuchtet diese\11Höhle.",
  ["44:546e"] = "Mir ist schon\
lange niemand\11mehr begegnet.\12Hab keine Angst.\
Lass uns kämpfen!",
  ["44:54bb"] = "Uurggh…",
  ["44:54c4"] = "Ich bin lange\
herumgeirrt…\12Das hier macht mir\
nichts aus, aber\11ich bin hungrig!",
  ["44:5510"] = "Sieh mal einer an!\
Ein Besucher!",
  ["44:552e"] = "Wahahah! Du setzt\
dich ja zur Wehr!",
  ["44:554c"] = "Ich wohne hier\
unten.\12Wenn du möchtest,\
kannst du bei\11mir einziehen.\12Es ist noch\
genügend Platz.",
  ["44:559b"] = "Wer ist da?\12Lass mich und\
meine POKéMON\11in Frieden!\11",
  ["44:55c4"] = "Verschwinde…\
Geh weg!!",
  ["44:55d2"] = "Nur ich und meine\
POKéMON. Ich\11bin überglücklich.",
  ["44:5601"] = "Ich bin hierher\
gekommen, um\11meine POKéMON-\11Forschungen\11durchzuführen.\12Ich zeige dir\
meine Ergebnisse\11in einem Kampf!",
  ["44:5668"] = "Du hast es mir\
aber gezeigt!",
  ["44:5681"] = "Ich sollte meine\
Ergebnisse sammeln\11und anschließend\11veröffentlichen.\12Vielleicht werde\
ich so berühmt\11wie PROF. LIND.",
  ["44:57bf"] = "Es gibt zwei\
verschiedene Arten\11von Menschen.\12Jene mit Stil\
und jene ohne.\12Zu welcher zählst\
du dich?",
  ["44:5826"] = "Dein Stil ist\
beeindruckend!",
  ["44:5841"] = "Dein POKéMON-Stil\
ist imposant und\11abwechslungsreich,\11das gebe ich zu.\12Du wirst immer\
besser!",
  ["44:5895"] = "Ich trainiere\
momentan. Möchtest\11du kämpfen?",
  ["44:58b8"] = "Oh, nein! Du bist\
zu gut für mich.",
  ["44:58d9"] = "Ich werde solange\
trainieren, bis\11ich besser bin.",
  ["44:5907"] = "Für meine Lieb-\
lings-POKéMON\11würde ich überall\11hingehen.\12Das würde jeder\
wahre Trainer tun.",
  ["44:5958"] = "Ich kümmere mich\
lieber um meine\11Babys, aber…!",
  ["44:597c"] = "Nur einmal in\
der Woche kommt\11ein POKéMON\11ans Wasser.\12Dieses POKéMON\
hätte ich gerne\11gesehen.…",
  ["44:5b06"] = "KURT: Hallo!\
{PLAYER}!\12Die Wache ganz\
oben ist\11weggelaufen, als\11ich sie anschrie.\12Aber dann bin\
ich in den\11BRUNNEN gefallen.\12Ich bin so hart \
auf meinem Rücken\11gelandet, dass ich\11mich nicht mehr\11bewegen kann.\12Mist! Wenn ich\
fit wäre, würden\12meine POKéMON\
sie bestrafen…\12Ah, mir ist nicht\
zu helfen.\12{PLAYER}, zeig\
ihnen, wie mutig\11du bist. Tu es für\11mich!",
  ["44:5c1d"] = "KURT: Weiter so,\
{PLAYER}!\12TEAM ROCKET ist\
abgehauen.\12Meinem Rücken geht\
es schon besser.\11Lass uns gehen.",
  ["44:5c78"] = "Mist! Ich stand\
da oben Wache, als\12ein Verrückter\
vorbeikam und\11mich anschrie.\12Ich bin so\
erschrocken, dass\11ich hier hinunter\11gefallen bin.\12Ich glaube, ich\
lasse meine Wut\11an dir aus!",
  ["44:5d1f"] = "Arrgh! Heute ist\
NICHT mein Tag!",
  ["44:5d3b"] = "Klar haben wir den\
FLEGMONS die\12RUTEN abgetrennt\
und dann verkauft.\12Wir wollen nur\
Profit machen.\12Genau! Wir sind\
TEAM ROCKET und\12für Geld machen\
wir alles!",
  ["44:5dde"] = "Was willst du?\12Wenn du uns bei\
der Arbeit störst,\11gibt es für dich\11keine Gnade!",
  ["44:5e23"] = "Du hast dich heute\
wacker geschlagen,\11Kleiner!\11Wir sehen uns!",
  ["44:5e54"] = "Yeah, TEAM ROCKET\
wurde vor drei\11Jahren zer-\11schlagen.\12Aber wir haben\
unsere Arbeit im\11Untergrund\11fortgesetzt.\12Nun kannst du\
zusehen, wie wir\11für Unruhe sorgen!",
  ["44:5ee5"] = "Wir sollen auf-\
hören, den\11FLEGMONS ihre\11RUTEN abzutrennen?\12Wenn wir auf dich\
hören würden, wäre\11der Ruf von TEAM\11ROCKET ruiniert!",
  ["44:5f37"] = "Du bist…\
zu stark…",
  ["44:5f4a"] = "Wir brauchen das\
Geld, aber mit\11FLEGMONRUTEN?\12Manchmal ist es\
hart, ein ROCKET\11RÜPEL zu sein!",
  ["44:5f9b"] = "Wir sollen auf-\
hören, den\11FLEGMONS ihre\11RUTEN abzutrennen?\12Ja, versuche, uns\
alle zu besiegen!",
  ["44:5fd3"] = "Du vorlautes Balg!",
  ["44:5fe5"] = "FLEGMONRUTEN\
wachsen schnell\11nach!\12Was ist falsch\
daran, sie\11zu verkaufen?",
  ["44:6023"] = "Ein FLEGMON mit\
abgetrennter\11RUTE…\12Huh? Es trägt\
einen BRIEF.\11BRIEF lesen?",
  ["44:6061"] = "{PLAYER} liest den\
BRIEF.\12Sei so lieb und\
kümmere dich bitte\12um Opa und das\
FLEGMON.\12Danke, Papa",
  ["44:60b9"] = "Ein FLEGMON mit\
abgetrennter\11RUTE…",
  ["44:6182"] = "Ich warte darauf,\
dass sich FLEGMON\11entwickelt.\12Aufgrund meiner\
Beobachtungen\11habe ich eine\11neue Entdeckung\11gemacht.\12Trägt FLEGMON\
einen KING-STEIN\12wird es oft von\
einem MUSCHAS\11gebissen.\12Hier, ich gebe\
dir einen von\11meinen.",
  ["44:624a"] = "Ich werde mich wie\
FLEGMON verhalten.\12Ich werde geduldig\
abwarten, bis es\11sich entwickelt.",
  ["44:62c5"] = "Die Leute kommen\
zum LEUCHTTURM, um\11zu trainieren.\12Aufgrund der\
vielen Trainer\11ist es nicht\11einfach, sich bis\11ganz nach oben\11vorzukämpfen.",
  ["44:631a"] = "Früher haben POKé-\
MON nachts die\12Gewässer um\
OLIVIANA CITY er-\11hellt.\12Der LEUCHTTURM\
wurde errichtet,\11um diese POKéMON\11zu ehren.",
  ["44:646b"] = "Seefahrer scheuen\
keine harten\11Kämpfe!",
  ["44:64a1"] = "Uff!\
Ich habe verloren!",
  ["44:64af"] = "Du hast Power!\
Möchtest du\12mit mir die Meere\
unsicher machen?",
  ["44:64e9"] = "Hm? Dies ist kein\
Ort für Spielchen.",
  ["44:650c"] = "Ah! Ich sehe, du\
meinst es ernst.",
  ["44:652f"] = "Ganz oben ist ein\
POKéMON, das den\11LEUCHTTURM\11betreibt.\12Ich habe gehört,\
dass es krank ist\12und dass normale\
Medizin nicht\12hilft.",
  ["44:6625"] = "Warum bist du\
gekommen? Bist du\12zum Gaffen hier?\
Es ist besser, du\11gehst!",
  ["44:666e"] = "Du sorgst dich\
wirklich…",
  ["44:6689"] = "Wie, zum Geier,\
bist du hier\11hochgekommen?\12Ich möchte das\
kranke POKéMON\12besuchen, aber ich\
schaffe es nicht\11bis nach oben…",
  ["44:66dd"] = "Matrosen sind\
nett und stark.\11Wie bist du?",
  ["44:670f"] = "Du bist auch nett\
und stark…",
  ["44:672e"] = "Jedes Mal wenn\
ich nach OLIVIANA\11CITY komme, gehe\11ich in die ARENA.\12Der POKéMON-Typ\
der ARENALEITERIN\12hat sich geändert,\
ohne dass ich\11es bemerkte.",
  ["44:679e"] = "Ich bereise die\
Welt, um meine\11POKéMON zu\11trainieren. Ich\11möchte mit dir\11kämpfen.",
  ["44:67e1"] = "…Seufz… Ich muss\
mehr trainieren…",
  ["44:6801"] = "JASMIN trainierte\
früher Gestein-\11POKéMON wie ONIX.",
  ["44:68bc"] = "JASMIN muss krank\
vor Sorge um das\11POKéMON hier sein.\12Man sieht sie\
momentan nicht\11einmal lächeln.",
  ["44:690f"] = "Ich habe im\
Moment auch nichts\11zu lachen…",
  ["44:692e"] = "Apropos krank: Mir\
ist zu Ohren\12gekommen, dass es\
in ANEMONIA CITY\11eine gute APOTHEKE\11geben soll.",
  ["44:696f"] = "JASMIN ist die\
ARENALEITERIN in\11dieser Stadt.\12Ich möchte, dass\
sie mit mir\11zurückkommt.\12Es ist besser,\
niemand stellt\11sich mir in den\11Weg!",
  ["44:69d5"] = "Uh! Meine POKéMON!",
  ["44:69e6"] = "O.K. Jeder wäre\
besorgt, wenn\11seine POKéMON\11verletzt sind.\12Ich werde für das\
POKéMON beten,\12dann kann JASMIN\
in die ARENA\11zurückkehren.",
  ["44:6aef"] = "Ich hatte vor,\
gegen JASMIN zu\12kämpfen, aber sie\
ist nicht da. Wie\11wäre es mit dir?",
  ["44:6b3a"] = "Wow, du hast mich\
überwältigt!",
  ["44:6b5b"] = "Ein ARENALEITER\
muss nicht nur\12stark sein. Auch\
Mitgefühl\11zeichnet ihn aus.",
  ["44:6bb0"] = "Wir fliegen\
ziemlich hoch.\12Meine Vogel-POKé-\
MON sind in\11Bestform.",
  ["44:6beb"] = "Ups…Sie\
sind abgestürzt…",
  ["44:6bff"] = "Mein POKéMON hat\
das FLIEGEN in\11ANEMONIA CITY\11gelernt.\12Da ich ein\
Verlierer bin,\11fliege ich nun\11fort, über das\11Meer…",
  ["44:6dbd"] = "JASMIN: … Dieses\
POKéMON hat\12das Meer immer\
erleuchtet.\12…Aber plötzlich\
wurde es krank… Es\11schnappt nach\11Luft…\12…Ich weiß, dass\
es eine gut\12sortierte APOTHEKE\
in ANEMONIA CITY\11gibt…\12Aber dafür musst\
du über das Meer…\12Und ich kann AMPHI\
nicht unbeaufsich-\11tigt zurücklassen…",
  ["44:6ea0"] = "…Vielleicht\
könntest du die\11Medizin für mich\11besorgen? Bitte!",
  ["44:6ed5"] = "JASMIN: …Wird\
diese Arznei AMPHI\11helfen?",
  ["44:6eff"] = "{PLAYER} übergibt\
JASMIN den\11GEHEIMTRANK.",
  ["44:6f26"] = "JASMIN: …Hm,\
Sei bitte nicht\11beleidigt…\12…AMPHI nimmt\
die Arznei nur\11von mir…",
  ["44:6f80"] = "JASMIN: …\12AMPHI, wie geht\
es dir?",
  ["44:6fa8"] = "JASMIN: …Oh, ich\
bin erleichtert…\12Das ist einfach\
wundervoll…\12Ich danke dir\
vielmals.\12…Ich kehre in die\
ARENA zurück …",
  ["44:701b"] = "JASMIN: …Ich ver-\
stehe…",
  ["44:702d"] = "…AMPHI, halte\
durch!",
  ["44:703f"] = "AMPHI: …\
…Pa…Paluu …",
  ["44:7055"] = "Es hat Probleme\
mit der Atmung…",
  ["44:7079"] = "AMPHI: Palu!\
Palulu!\12AMPHI: Palu!\
Palulu!",
  ["45:4126"] = "Arrgh… Du hast\
die Geheimtreppe\11gefunden…",
  ["45:414f"] = "Heheh! Das\
Experiment verlief\11wie am Schnürchen.\12KARPADOR ist\
wertlos, aber\12GARADOS verkauft\
sich gut.",
  ["45:41bc"] = "Urrgh…\12Seine Drachen-\
POKéMON sind\11stark…",
  ["45:41e5"] = "SIEGFRIED:\
DRAGORAN,\12HYPERSTRAHL!",
  ["45:4204"] = "Was hat dich auf-\
gehalten, {PLAYER}?\12Das habe ich mir\
gleich gedacht.\12Die merkwürdigen\
Radiowellen kommen\11von hier.",
  ["45:4259"] = "Die Treppe\
ist hier.",
  ["45:4275"] = "SIEGFRIED:\
{PLAYER},\12wir sollten uns\
trennen, um diesen\12Ort zu erforschen.\
Ich gehe zuerst.",
  ["45:47cd"] = "Hey!\
Eindringling!\11Alarm!",
  ["45:47e3"] = "Mist… Ich habe\
versagt…",
  ["45:47f4"] = "Ich bin dran!\
Es gibt kein\11Entkommen!",
  ["45:4814"] = "In den POKéMON-\
Statuen sind Über-\11wachungskameras\11installiert.\12Wir greifen weiter\
an, bis du einen\11Geheimschalter\11betätigst.",
  ["45:4876"] = "Dies war einmal\
ein Ninjaversteck.\12Es wurden Fallen\
aufgestellt, um\11Eindringlinge wie\11dich zu verwirren.",
  ["45:48c6"] = "Ich hab's…",
  ["45:48d1"] = "O.K. Ich verrate\
dir ein Geheimnis\11über unseren\11Unterschlupf.\12Das Feld da vorne\
am Boden ist ein\11Warpfeld.\12Sobald du es\
betrittst, wirst\12du zurück zum\
Eingang gewarpt.",
  ["45:4972"] = "Hehe. Bist du\
glücklich, Punk?\12Los! Mach einen\
weiteren Schritt.\12Wir haben Fallen\
in den Boden\11eingebaut!",
  ["45:49cd"] = "Kawumm!",
  ["45:49d6"] = "Ich weiß nicht,\
wo die Fallen\11aufgestellt sind.\12Du musst deinen\
ganzen Mut\11zusammennehmen\11und weitergehen.",
  ["45:4a37"] = "Das ist eine\
SNOBILIKAT-Statue…\12Es ist ein\
seltsamer Glanz\11in ihren Augen.",
  ["45:4a68"] = "Ein Geheimschal-\
ter! Betätige ihn!",
  ["45:4a8b"] = "Der Schalter\
steht auf AUS.",
  ["45:4f65"] = "Bleib stehen, wo\
du bist!",
  ["45:4f7b"] = "Wir können es\
nicht zulassen,\11dass ein Balg\11hier herumläuft.\12Das schadet\
TEAM ROCKETs\11Stolz.\12Wie stark du auch\
bist, du kannst\12es nicht mit uns\
beiden aufnehmen.\12Tut uns Leid,\
Kleiner! Jetzt\11wirst du zermalmt.",
  ["45:5044"] = "Heh! Sei nicht so\
egoistisch.\11Teile den Spaß.",
  ["45:5075"] = "Wie? Du hattest\
einen Komplizen?\12Wo ist dein\
Ehrgefühl?\12Ich, GIOVANNIs\
Stellvertreter,\12werde dir zeigen,\
was es bedeutet,\12sich mit TEAM\
ROCKET anzulegen!",
  ["45:5114"] = "Ts, du bist\
wirklich gut.\12So ein Mist.\12Wenn du bei TEAM\
ROCKET einsteigen\12würdest, wärest\
du sofort im\11VORSTAND.",
  ["45:517e"] = "…Dieses Versteck\
ist gesäubert…\12Das ist gut. Das\
Sende-Experiment\11war ein voller\11Erfolg.\12Es ist egal,\
was aus dem\11Versteck wird.\12Wir haben höhere\
Ziele.\12Schon bald wirst\
du die wahre Macht\12von TEAM ROCKET\
würdigen.\12Amüsiere dich,\
solange du noch\11kannst…\12Fufufufu…",
  ["45:5290"] = "SIEGFRIED: Genug!\
Wir haben hier\12alle Anhänger von\
TEAM ROCKET\11besiegt.\12Aber der Junge,\
auf den ich traf,\12macht mir wirklich\
Sorgen.…",
  ["45:5306"] = "Sorry, {PLAYER}.\
Ich habe beobach-\12tet, wie geschickt\
du bist. Daher\11habe ich mich\11zurückgehalten.\12Jetzt müssen wir\
nur noch dieses\12merkwürdige Signal\
abschalten.",
  ["45:5387"] = "Diese Maschine\
ist die Wurzel\11allen Übels.\12Ich sehe leider\
keinen Schalter…\12Uns bleibt keine\
andere Wahl. Wir\12müssen alle\
LEKTROBALS\11besiegen.\12Das sollte\
genügen, um die\12Maschine\
abzuschalten.\12Die POKéMON trifft\
keine Schuld,\12daher fühle ich\
mich schuldig.\12{PLAYER}, wir soll-\
ten uns besser\11trennen.",
  ["45:54a2"] = "SIEGFRIED: Ich\
übernehme diese\11Seite.",
  ["45:54c1"] = "SIEGFRIED: Das\
merkwürdige Signal\11ist verschwunden.\12Der SEE sollte\
sich wieder\11normalisiert\11haben.\12Du bist ein Held!\
Ich möchte dir im\12Namen aller\
POKéMON danken.\12Ja. Du solltest\
das annehmen.\12Ich habe es hier\
gefunden, kann es\11aber nicht\11gebrauchen.",
  ["45:55b0"] = "Das ist WHIRLPOOL.\
Gib dies einem\12POKéMON, um\
reißende Strudel\11zu durchqueren.\12Aber vergiss\
nicht:\12Du benötigst den\
ORDEN der ARENA\12in MAHAGONIA CITY,\
um die VM\11außerhalb eines\11Kampfes\11einzusetzen.",
  ["45:564c"] = "{PLAYER}…\12Es ist ein langer\
und steiniger Weg\12bis zum\
POKéMON-MEISTER.\12Bist du bereit,\
diesen Weg\11zu beschreiten?\12…\12Ich verstehe. Du\
hast Recht.\12Wenn du die Flinte\
so schnell ins\12Korn wirfst,\
hattest du nie\12vor, diesen Traum\
zu verwirklichen.\12Ich freue mich,\
dich wiederzu-\11sehen!",
  ["45:574f"] = "SIEGFRIED: Bist du\
in Ordnung?\12Deine POKéMON sind\
müde und verletzt.\12Gib ihnen\
ein wenig von\11meiner Medizin.",
  ["45:57af"] = "SIEGFRIED:\
{PLAYER},\12lasst uns für die\
POKéMON unser\12Bestes geben.",
  ["45:57da"] = "Die Türe öffnet\
sich nicht?\12Nun, oh.\
Sie ist Passwort-\11geschützt. Nur\12TEAM ROCKET hat\
Zugriff.",
  ["45:5831"] = "Was? Ich habe\
verloren?",
  ["45:5840"] = "Heh, ich bin doch\
nur ein RÜPEL.\12Ich kenne das\
Passwort nicht.\11Pech gehabt.",
  ["45:5882"] = "Oh, ein Kind? Ich\
mag das zwar\12nicht, aber ich\
muss dich aus-\11schalten.",
  ["45:58c1"] = "Ich wusste, ich\
würde verlieren…",
  ["45:58d2"] = "Meine letzte\
Mission wurde auch\11von einem Kind\11vereitelt.\12Als wir POKéMON\
entführten,\12tauchte ein Kind\
mit roten Haaren\12und fiesem Blick\
auf und hat\11mich vermöbelt…",
  ["45:5968"] = "Du miese, kleine\
Ratte!",
  ["45:5981"] = "Grrrr…",
  ["45:5989"] = "Heh, nur der Boss\
kennt das Passwort\11für diese Tür.\12Wo er ist?\
Wer weiß? Schau\11doch selbst nach.",
  ["45:59f1"] = "Die Tür ist\
verschlossen…\12Sie lässt sich nur\
mit einem Passwort\11öffnen.",
  ["45:5a23"] = "Die Tür ist\
verschlossen…\12{PLAYER} gibt das\
Paswort ein.\12Die Tür wurde\
entriegelt!",
  ["45:5a5f"] = "Der Radiotrans-\
mitter sendet das\12unheimliche\
Signal aus.\12Er läuft auf\
vollen Touren.",
  ["45:5abb"] = "Endlich wurde der\
unheimliche Radio-\12transmitter\
abgeschaltet.",
  ["45:5e2f"] = "SIEGFRIED: Man\
benötigt zwei\12Passwörter, um Zu-\
tritt zum Quartier\11des Bosses zu\11bekommen.\12Nur ein paar Mit-\
glieder von TEAM\11ROCKET kennen sie.\12Diese Auskunft hat\
mir dieser\11ROCKET gegeben.\12{PLAYER}, los!\
Holen wir uns\11die Passwörter.",
  ["45:5eeb"] = "Urrggh… Der Typ\
mit dem Umhang ist\11furchtbar stark…",
  ["45:5f1d"] = "…\12Habe ich dir nicht\
gesagt, dass ich\12TEAM ROCKET\
zerschlage?\12…Sag mir, wer war\
der Typ mit dem\12Umhang, der die\
Drachen-POKéMON\11einsetzte?\12Meine POKéMON\
waren keine Gegner\11für ihn.\12Die Niederlage\
macht mir nichts\12aus. Mit stärkeren\
POKéMON kann ich\11ihn besiegen.\12Was mich wurmt\
ist, was er zu\11mir gesagt hat…\12Er sagte, dass ich\
meine POKéMON\12nicht ausreichend\
liebe und ihnen\11nicht vertraue.\12Ich bin wütend,\
dass ich gegen so\11ein Großmaul\11verloren habe.\12…Humpf! Für Typen\
wie dich habe\11ich keine Zeit!",
  ["45:60b6"] = "Was? Wer bist du?\
Dies ist das Büro\12unseres Anführers\
GIOVANNI.\12Er trainiert, seit\
das TEAM ROCKET\12vor drei Jahren\
zerschlagen wurde.\12Wir sind sicher,\
dass er eines\12Tages zurückkehren\
wird, um das\11Kommando wieder\11zu übernehmen.\12Darum halten wir\
Wache.\12Ich lasse nicht\
zu, dass es\11hier laut wird!",
  ["45:61c7"] = "Ich… Ich konnte\
nichts machen…\12Bitte vergib\
mir, GIOVANNI…",
  ["45:61fe"] = "Das darf mich\
nicht belasten.\12Ich muss es den\
anderen sagen…",
  ["45:623b"] = "KRAMURX: Das\
Passwort lautet…\12PREISET GIOVANNI.",
  ["45:6265"] = "Ob ich das\
Passwort weiß?\12Vielleicht.\12Schwächlinge\
werden es nie\11erfahren!",
  ["45:62a7"] = "O.K. Genug.\
Ich verrate es\11dir.",
  ["45:62c7"] = "Das Passwort zum\
Büro vom Boss\11lautet\12FLEGMONRUTE.\12Es ist aber\
nutzlos, denn du\11benötigst zwei\11Passwörter.",
  ["45:6327"] = "Hiuck-hiuck-hiuck!\12Du forderst mich\
zu einem Kampf\12heraus? Pah! Du\
bist dumm, aber du\11hast Mumm!\12Das mag ich!\12Falls du mich\
besiegst, verrate\12ich dir ein\
Passwort für das\11Büro vom Boss!",
  ["45:63cd"] = "Hiuck-hiuck-hiuck!\
Du bist gut!",
  ["45:63ed"] = "Hiuck-hiuck-hiuck!\12Das Passwort für\
das Büro vom Boss…\12Uh,… ich glaube,\
es lautet\11RATTIKARLRUTE.",
  ["45:6443"] = "Früher arbeitete\
ich für SILPH,\12aber jetzt leite\
ich TEAM ROCKETs\11Forschungen.\12Ein Kind wie du,\
das sich überall\11einmischt, muss\11bestraft werden.",
  ["45:64b8"] = "Nur wegen eines\
kleinen taktischen\11Fehlers…",
  ["45:64d8"] = "Ein Radiosignal,\
das POKéMON um den\11Verstand bringt…\12Mein Experiment\
war ein voller\11Erfolg.\12Meine Beförderung\
ist gewiss. Dieser\12Verlust bedeutet\
nichts.",
  ["45:6562"] = "Es ist mir egal,\
dass POKéMON bei\11unserem Experiment\11Schmerzen\11zugefügt werden.",
  ["45:6595"] = "Meine Stärke ist\
das Denken, nicht\11das Kämpfen.",
  ["45:65c0"] = "Wenn wir das\
Radiosignal ver-\12stärken, könnte\
man es im ganzen\11Land empfangen…\12Allein der Gedanke\
entzückt mich!",
  ["45:6626"] = "Die Tür ist\
verschlossen…\12Zum Öffnen werden\
zwei Passwörter\11benötigt.",
  ["45:6659"] = "Die Tür ist\
verschlossen…\12{PLAYER} gibt beide\
Passwörter ein.\12Die Tür ist\
entriegelt!",
  ["45:6a44"] = "Oh, Mist… Mein\
Boss wird sauer\11sein…\12Das PORENTA, das\
mit dem ZER-\12SCHNEIDER Bäume\
fällt, um nach\11Holzkohle zu\11suchen, ist\11abgehauen.\12Ich traue mich\
nicht in den\11STEINEICHENWALD,\11um nach ihm\11zu suchen.\12Er ist so groß,\
dunkel und\11unheimlich…",
  ["45:6b01"] = "Wow! Vielen Dank\
auch!\12Die POKéMON von\
meinem Boss\11gehorchen mir\11nicht, da ich\11keinen ORDEN\11besitze.",
  ["45:6b57"] = "Das ist das\
verschollene\11POKéMON!",
  ["45:6b6e"] = "PORENTA: Quack!",
  ["45:6b81"] = "Ah! Mein PORENTA!\12Du hast es für uns\
gefunden, Kleiner?\12Wir können ohne\
es nicht den\12ZERSCHNEIDER\
einsetzen, mit dem\11wir Bäume fällen, \11um Holzkohle zu\11finden.\12Danke, Kleiner!\12Wie kann ich\
dir danken…\12Ah genau! Nimm\
dies.",
  ["45:6c29"] = "Diese VM enthält\
ZERSCHNEIDER.\12Bring sie einem\
POKéMON bei, um\11kleine Sträucher\11zu zerschneiden.\12Du benötigst noch\
den ORDEN aus der\12ARENA von AZALEA\
CITY, um sie\11einzusetzen.",
  ["45:6ca8"] = "Soll ich dich\
lehren, wie man\12ein Köhler wird?\12In zehn Jahren\
wirst du ein\11Meister sein!",
  ["45:6d03"] = "Was ich mache?\12Ich setze\
KOPFNUSS ein, um\11Bäume zu\11schütteln.\12Das macht Spaß!\
Probier es doch\11auch einmal!",
  ["45:6d55"] = "Benutze KOPFNUSS,\
um Bäume zu\11schütteln. Manch-\11mal fallen schla-\11fende POKéMON\11herunter.",
  ["45:6d97"] = "Der STEINEICHEN-\
WALD ist so dicht,\12dass man den\
Himmel nicht sehen\11kann.\12Halte Ausschau\
nach verlorenen\11Gegenständen.",
  ["45:6e11"] = "STEINEICHENWALD-\
SCHREIN…\12Er wurde zu Ehren\
des Waldpatrons\11aufgestellt…",
  ["46:42dc"] = "Ich wurde aus\
der SPIELHALLE\11hinausgeworfen.\12Ich habe versucht,\
mit Hilfe meines\11POKéMON zu mogeln…",
  ["46:4329"] = "…Grummel…",
  ["46:4334"] = "Ich glaube, dass\
ich lieber fair\11spielen sollte…",
  ["46:4362"] = "Beschränkst du\
dich beim Kämpfen\11nur auf einen Typ?\12Wenn du die Stär-\
ken deiner Typen\12kennst, hast du im\
Kampf Vorteile.",
  ["46:43cb"] = "Oh, oh, oh!",
  ["46:43d8"] = "Ich kenne die\
Stärken und\11Schwächen meiner\11POKéMON.\12Aber ich setze nur\
einen POKéMON-Typ\11ein.",
  ["46:441a"] = "Meine POKéMON\
kommen gerade vom\11Coiffeur!\12Ich zeige dir, wie\
stark sie sind!",
  ["46:4458"] = "Arghhh!",
  ["46:4462"] = "Deine POKéMON\
mögen dich mehr,\12wenn du sie zum\
Coiffeur bringst.",
  ["46:449b"] = "Ich glaube, du\
besitzt seltene\11POKéMON.\12Zeig sie mir!",
  ["46:44d7"] = "Guah! Ich habe\
verloren! Ich\11dreh durch!",
  ["46:44f9"] = "Erstellst du einen\
POKéDEX? Ich habe\11einen heißen\11Tipp für dich.\12WANDERER TOM auf\
ROUTE 33 ist sehr\11freundlich.\12Er ruft dich an,\
wenn er seltene\11POKéMON sieht.",
  ["46:457a"] = "Die Tür ist\
verschlossen…",
  ["46:458d"] = "Die Tür ist\
entriegelt.",
  ["46:45a0"] = "Mit dem KELLER-\
ÖFFNER wird die\11Türe entriegelt.",
  ["46:45c3"] = "Willkommen!\12Ich leite den\
POKéMON-SALON!\12Ich bin der ältere\
und Bessere der\11beiden COIFFEUR-\11BRÜDER.\12Ich verleihe\
deinen POKéMON ein\11schöneres Äußeres\11für nur ¥500.\12Soll ich damit\
anfangen?",
  ["46:4664"] = "Bei welchem\
POKéMON soll ich\11Hand anlegen?",
  ["46:4682"] = "O.K.! Sieh her,\
wie schön es wird!",
  ["46:46a2"] = "Hier! Fertig!",
  ["46:46b4"] = "Ist das wahr? Das\
ist eine Schande!",
  ["46:46d3"] = "Du hast nicht\
genügend Geld.",
  ["46:46f5"] = "Ich mache nur\
einen Haarschnitt\11pro Tag; und für\11heute bin ich\11fertig.",
  ["46:4726"] = "Willkommen im\
POKéMON-SALON!\12Ich bin der\
jüngere und\11preiswertere der\11beiden COIFFEUR-\11BRÜDER.\12Ich verschönere\
deine POKéMON\11für nur ¥300.\12Also? Wie wär's?",
  ["46:47bb"] = "Welches POKéMON\
soll ich be-\11arbeiten?",
  ["46:47d8"] = "O.K.! Es wird\
cool aussehen!",
  ["46:47f4"] = "Bitteschön!\
Fertig!",
  ["46:480c"] = "Nein? \
Schade!",
  ["46:4825"] = "Du hast nicht\
genügend Geld.",
  ["46:4845"] = "Ich mache nur\
einen Haarschnitt\12pro Tag; und für\
heute bin ich\11fertig.",
  ["46:4889"] = "{STRBUF} sieht\
fröhlicher aus.",
  ["46:48a6"] = "{STRBUF} sieht\
glücklich aus.",
  ["46:48b8"] = "{STRBUF}\
ist entzückt!",
  ["46:48ce"] = "Wir haben heute\
geschlossen.",
  ["46:48e4"] = "BIS HIERHER\
UND NICHT WEITER",
  ["46:4e67"] = "Stehenbleiben!\12Ich sah dich und\
bin dir gefolgt.\12Hör auf, mir\
nachzustellen, ich\12muss mich um TEAM\
ROCKET kümmern.\12…Moment.\
Du hast mich schon\11besiegt, oder?\12Das war nur\
Dusel.\12Ich begleiche\
meine Rechnungen!",
  ["46:4f27"] = "…Warum…\
Warum habe ich\11verloren?\12Ich habe die\
stärksten POKéMON\11zusammengetragen.\12Ich habe mich so\
angestrengt.\12Warum habe ich\
bloß verloren?",
  ["46:4f8c"] = "…Ich verstehe\
es nicht…\12Ist es wahr, was\
dieser SIEGFRIED\11erzählt?\12Dass ich meine\
POKéMON nicht\11richtig behandle?\12Liebe…\12Vertrauen…\12Fehlt mir das\
wirklich?\12Verhindern diese\
Mängel, dass ich\11gewinne?\12Ich… Ich verstehe\
es nicht.\12Aber es wird\
hier nicht enden.\12Nicht jetzt.\
Nicht deswegen.\12Ich werde meinen\
Traum, der welt-\12beste POKéMON-\
Trainer zu sein,\11nicht aufgeben!",
  ["46:50cc"] = "Hm. Das ist meine\
wahre Stärke,\11du Schwächling.\12TEAM ROCKET wird\
dank mir nur noch\11Geschichte sein.\12Ich werde diesen\
SIEGFRIED wie\11einen Wurm\11zertreten.",
  ["46:5140"] = "Ich wurde da unten\
zu einem Kampf\11herausgefordert.\12Da unten herrschen\
rauhe Sitten. Sei\11auf der Hut.",
  ["46:519a"] = "Da unten gibt es\
Geschäfte…\12Aber da unten sind\
auch Trainer. Ich\12traue mich nicht\
hinunter.",
  ["46:51f5"] = "Öffne einen Roll-\
laden und ein an-\11derer schließt.\12Ich wette, du\
kommst nicht so\11weit, wie du es\11dir vorstellst!",
  ["46:5239"] = "Verflixt! Meine\
Unentschlossenheit\11war mein Ruin!",
  ["46:525a"] = "Auch ich bin…\
verwirrt. Der\12letzte Schalter\
muss zuerst\11betätigt werden,\11aber…",
  ["46:52a2"] = "Uff!\12Wir sind von den\
Rollläden ver-\11wirrt!\12Ich verrate dir\
ein Geheimnis,\11wenn du mich\11besiegst!",
  ["46:52ff"] = "Arghh… Ich\
hab's vermasselt.",
  ["46:5311"] = "O.K. Ein Hinweis!\12Betätige die\
Schalter in einer\11anderen Reihen-\11folge.\12Dadurch wird das\
Öffnen und Schlie-\11ßen der Rollläden\11verändert.",
  ["46:5378"] = "Wirf deine\
Goodies herüber!",
  ["46:5391"] = "Gnade!",
  ["46:5399"] = "Stehlen und\
Hehlen! Das ist\11die Basis aller\11Verbrechen, Junge!",
  ["46:53c5"] = "Sie haben das\
Projekt abge-\11brochen, noch ehe\11sie fertig waren.\12Ich suche nach\
Überresten der\11Beute.",
  ["46:5416"] = "Das ist zuviel!",
  ["46:5425"] = "UNTERGRUND\
LAGERHAUS?\12Warum möchtest du\
dorthin?\12Da unten wirst\
du nichts finden.",
  ["46:547c"] = "Es ist mir egal,\
wenn du dich\11verläufst.\12Du tauchst hier\
auf! Du bist nur\11ein Opfer!",
  ["46:54c6"] = "Urk! Du glaubst,\
du bist cool, häh?",
  ["46:54e9"] = "Durch deine Venen\
fließt wohl Eis,\11da du TEAM ROCKET\11nicht für bare\11Münze nimmst.",
  ["46:551e"] = "Hier steht\
SCHALTER 1.",
  ["46:5535"] = "Hast du dich\
verirrt? Nein, das\11kann nicht sein.\12Es ist keine Angst\
in deinem Blick.\12Ich zeige dir\
etwas, das dir\11Angst macht!",
  ["46:55a0"] = "Wie konntest du?",
  ["46:55b0"] = "Geh nur! Verlaufe\
dich! Dann wirst\11du feststellen,\11dass es mir egal\11ist!",
  ["46:55e1"] = "Er ist ausge-\
schaltet.\11Einschalten?",
  ["46:55f7"] = "Er ist einge-\
schaltet.\11Ausschalten?",
  ["46:560d"] = "Hier steht\
SCHALTER 2.",
  ["46:5624"] = "Hier steht\
SCHALTER 3.",
  ["46:563b"] = "Hier steht\
NOTFALL.",
  ["46:5795"] = "Hey, Kleiner! Du\
hältst uns auf!\12Wir arbeiten stets\
im Hintergrund,\12damit uns niemand\
sieht!",
  ["46:57f7"] = "Ich verliere die\
Lust am Arbeiten,\11wenn mir jemand\11zusieht.\12Hey Kleiner,\
zisch ab!",
  ["46:5840"] = "Oohah! Oohah!\12Das Zeug am\
Boden ist Plunder.\12Nimm es dir, wenn\
du möchtest!",
  ["46:5886"] = "MASCHOK: Mascho!",
  ["46:59b3"] = "Wie bist du\
so weit gekommen?\12Ich denke, es gibt\
keine andere\11Lösung, um dich\11loszuwerden.",
  ["46:59fd"] = "Er wurde mich los…",
  ["46:5a11"] = "TEAM ROCKET wird\
weitermachen.\11Sie warten auf die\11Rückkehr von\11GIOVANNI.\12Wir werden alles\
dafür geben.",
  ["46:5a70"] = "Weiter kommst\
du nicht!\12Ich habe niemals\
Mitleid mit meinen\11Gegnern, auch\11nicht mit Kindern!",
  ["46:5abf"] = "Verdammt!",
  ["46:5aca"] = "Ich habe verloren…\12Bitte vergib mir,\
GIOVANNI!",
  ["46:5af0"] = "Hiuck-hiuck-hiuck!\
Ich kenne dich!\12Du hast mich in\
unserem Versteck\11richtig vermöbelt!",
  ["46:5b34"] = "Hiuck-hiuck-hiuck!\
So ist das also?",
  ["46:5b57"] = "Hiuck-hiuck-hiuck!\
Das war grandios!\11Ich werde dich\11nicht vergessen!",
  ["46:5b8f"] = "INTENDANT: Wie?\
Was? Du willst\11mich retten?\12Danke!\12Der RADIOTURM!\12Was geschieht\
dort?\12Von TEAM ROCKET\
besetzt?\12Hier, nimm diesen\
TÜRÖFFNER.",
  ["46:5c24"] = "INTENDANT: Damit\
kannst du den\11Rollladen im S2\11öffnen.",
  ["46:5c56"] = "Ich flehe dich an,\
uns zu helfen.\12Niemand weiß, was\
sie vorhaben, wenn\12sie erst Kontrolle\
über den Trans-\11mitter erlangen.\12Sie könnten sogar\
mit einem Spezial-\12signal alle POKé-\
MON kontrollieren!\12Bitte hilf mir!\
Du bist meine\11letzte Rettung.\12Bitte rette den\
RADIOTURM…\12Und alle POKéMON\
in diesem Land!",
  ["46:5f3d"] = "Hey!\12Ich bin der KARATE\
CHAMP!\12Ich trainiere hier\
allein im Dunkeln!\12Du!\
Kämpfe mit mir!\12Arggh!",
  ["46:5f99"] = "Waaaarggh!\
Ich wurde besiegt!",
  ["46:5fb0"] = "Ich… Ich bin am\
Boden zerstört…\12Ich habe nicht gut\
genug trainiert…\12Eine Niederlage\
ist nunmal eine\11Niederlage. Das\11gebe ich zu.\12Als Beweis für\
deinen Sieg gebe\12ich dir dieses\
seltene Kampf-\11POKéMON.",
  ["46:6045"] = "{PLAYER} erhält\
RABAUZ.",
  ["46:605a"] = "RABAUZ ist ein\
Kampf-POKéMON.\12Es entwickelt sich\
zu einem stärkeren\11POKéMON.\12Arbeite so hart\
weiter. Ich werde\11auch weiterhin\11trainieren.\12Lebe wohl!",
  ["46:60cf"] = "Du kannst keine\
weiteren POKéMON\11mehr tragen!",
  ["46:61cc"] = "Der Fels ist\
heruntergefallen.",
  ["46:6267"] = "Er steckt im\
Eis fest.",
  ["47:41c8"] = "Uargh!",
  ["47:4292"] = "…\
…",
  ["47:4297"] = "…",
  ["47:429a"] = "…\
…",
  ["47:438b"] = "Wow! Du hast\
mich verwirrt!\12Da ich mein\
SCHATTENGLAS trug,\12habe ich dich\
nicht bemerkt.\12Was ich hier\
mache?\12Hey, mach dir\
darüber keine\11Gedanken.\12Ich gebe dir ein\
SCHATTENGLAS\11und du vergisst,\11dass du mich\11gesehen hast,\11in Ordnung?",
  ["47:4458"] = "SCHATTENGLAS ver-\
stärkt die Kraft\11von Unlicht-\11Attacken.",
  ["47:459c"] = "SANDRA: O.K.\
Ich würdige deine\12Stärke. Nimm\
diesen ORDEN.",
  ["47:45e1"] = "{PLAYER} erhält\
den DRACHENORDEN.",
  ["47:45fa"] = "Von nun an können\
deine POKéMON die\12Fähigkeit KASKADE\
einsetzen.\12Ferner werden\
dich alle POKéMON\12als Trainer\
anerkennen und dir\12bedingungslos\
gehorchen.\12Ich möchte dir\
noch diese TM\11geben.",
  ["47:46d6"] = "Sie enthält\
FEUERODEM.\12Nein, das hat\
nichts mit meinem\11Atem zu tun.\12Wenn du sie nicht\
möchtest, musst du\11sie nicht nehmen.",
  ["47:4754"] = "Du hast also\
alle ORDEN\11gesammelt.\12Dein Ziel ist\
die POKéMON\12LIGA auf dem\
INDIGO PLATEAU.\12Weißt du, wie du\
dorthin gelangst?\12Gehe von hier nach\
NEUBORKIA.\12Setze SURFER ein\
und begib dich\11nach Osten. Diese\11Route ist sehr\11hart.\12Wage es nicht,\
in der POKéMON\11LIGA zu verlieren!\12Wenn du verlierst,\
macht das meine\12Niederlage gegen\
dich noch härter!",
  ["47:4881"] = "DRACHENSCHREIN\12Der Schrein ehrt\
die Drachen POKé-\12MON, die früher\
in der DRACHEN-\11HÖHLE gelebt haben\11sollen.",
  ["47:48d6"] = "…\
Was? {PLAYER}?\12…Nein, ich\
möchte jetzt nicht\11mit dir kämpfen…\12Meine POKéMON sind\
noch nicht bereit,\11dich zu schlagen.\12Ich darf sie nicht\
zu schroff\11behandeln.\12Ich muss diszipli-\
nierter sein, wenn\12ich der weltbeste\
POKéMON-Trainer\11werden möchte…",
  ["47:4980"] = "…\12Wow…\12Du musst lernen,\
mir aus dem Weg\11zu gehen…",
  ["47:49a6"] = "{PLAYER} findet\
{STRBUF}!",
  ["47:49b8"] = "{PLAYER} kann\
keine weiteren\11Items mehr tragen.",
  ["48:4101"] = "Wow, dein POKéCOM\
ist beeindruckend!\12Hast du den von\
Mama bekommen?",
  ["48:413e"] = "Warte, {PLAYER}!",
  ["48:4148"] = "Was hast du vor?",
  ["48:4168"] = "Es ist gefährlich,\
ohne POKéMON das\11Haus zu verlassen!\12Auf dem Weg zur\
nächsten Stadt\12können jederzeit\
wilde POKéMON\12auftauchen.",
  ["48:41ce"] = "Oh! Dein POKéMON\
ist bezaubernd!\12Ich wünschte, ich\
hätte auch eines.",
  ["48:41fc"] = "Hi, {PLAYER}!\
Du willst schon\11gehen?\12Du solltest nicht\
gehen, ohne deiner\12Mama Bescheid zu\
sagen.",
  ["48:4240"] = "Ruf deine Mama mit\
dem POKéCOM an,\12damit sie weiß,\
was du machst.",
  ["48:427e"] = "Yo, {PLAYER}!\12Ich habe gehört,\
PROF. LIND hat\11neue POKéMON\11entdeckt.",
  ["48:42b0"] = "……\12Das ist also das\
berühmte LIND-\11POKéMON-LABOR…",
  ["48:42d7"] = "…Was starrst du\
so?",
  ["48:42f2"] = "NEUBORKIA\12Die Stadt, in der\
der Wind der Er-\11neuerung weht",
  ["48:4332"] = "Haus von {PLAYER}",
  ["48:433c"] = "LIND-POKéMON-LABOR",
  ["48:434a"] = "PROF. LINDs HAUS",
  ["48:45ae"] = "Du bist doch ein\
Anfänger, oder?\12Das ist O.K.! Es\
ist noch kein\11Meister vom Himmel\11gefallen!\12Wenn du willst,\
bringe ich dir ein\11paar Tricks bei.",
  ["48:463a"] = "Also gut!\
Folge mir!",
  ["48:4650"] = "Das ist ein POKé-\
MON-CENTER. Hier\12kannst du deine\
POKéMON heilen.\12Du wirst diese\
Dienste sehr oft\12in Anspruch nehmen\
müssen.",
  ["48:46cf"] = "Das ist ein POKé-\
SUPERMARKT.\12Hier werden BÄLLE\
verkauft, mit de-\12nen du POKéMON\
fangen kannst.\12Außerdem findest\
du hier viele\11nützliche Items.",
  ["48:4724"] = "Zur ROUTE 30 geht\
es hier entlang.\12Du wirst dort auf\
viele Trainer und\12ihre POKéMON\
treffen.",
  ["48:4772"] = "Wie du sehen\
kannst, befinden\12wir uns hier am\
Meer.\12Manche POKéMON\
findet man nur im\11Wasser.",
  ["48:47b7"] = "Hier…\12Das ist mein Haus!\
Danke, dass du mir\11Gesellschaft ge-\11leistet hast.\12Lass mich dir ein\
kleines Präsent\11geben!",
  ["48:4803"] = "Der POKéCOM von\
{PLAYER} verfügt\11nun über eine\11KARTE!",
  ["48:481c"] = "Der POKéCOM wird\
vielseitiger, wenn\11du ihn mit MODULEN\11erweiterst.\12Ich wünsche dir\
viel Glück für\11deine Reise!",
  ["48:486a"] = "Oh… Ich mache so\
etwas gerne…\12Du kannst mich\
immer besuchen.",
  ["48:48ad"] = "…\12Du hast ein POKé-\
MON aus dem LABOR.\12Welch eine Ver-\
schwendung für ei-\11nen Schwächling\11wie dich.\12…\12Hast du kapiert,\
wovon ich spreche?\12Auch ich habe ein\
gutes POKéMON.\12Ich zeige dir, was\
ich meine!",
  ["48:4942"] = "Hmpf. Bist du we-\
nigstens froh über\11deinen Sieg?",
  ["48:4961"] = "…\12Mein Name ist ???.\12Ich werde der\
weltbeste POKé-\11MON-Trainer sein!",
  ["48:49a5"] = "Hmpf. Das war pure\
Zeitverschwendung.",
  ["48:49c7"] = "…\12Mein Name ist ???.\12Ich werde der\
weltbeste POKé-\11MON-Trainer sein!",
  ["48:4a0b"] = "Hast du mit dem\
alten Mann am\11POKéMON-CENTER\11gesprochen?\12Er wird dir eine\
KARTE von JOHTO\11für deinen POKé-\11COM gegeben.",
  ["48:4a63"] = "Du kannst gehen,\
wohin du willst -\11solange du mit\11POKéMON unterwegs\11bist, wird es\11immer lustig sein.",
  ["48:4a91"] = "Zu MR. POKéMONs\
Haus ist es noch\11ein ganzes Stück.",
  ["48:4abc"] = "Ich habe gegen die\
Trainer auf der\11Straße gekämpft.\12Meine POKéMON\
haben verloren!\12Ich muss sie rasch\
in ein POKéMON-\12CENTER bringen.",
  ["48:4b21"] = "Ich habe ein\
POKéMON gefan-\12gen, das ein Item\
bei sich hatte.\12Ich glaube, es war\
ZAUBERWASSER.\12Ich brauche es\
nicht. Möchtest du\11es haben?",
  ["48:4b7c"] = "Ich gehe wieder\
zum Fischen.",
  ["48:4b9b"] = "ROSALIA CITY\12Die Stadt der\
duftenden Blumen",
  ["48:4bd0"] = "HAUS DES\
FREMDENFÜHRERS",
  ["48:4d29"] = "Allo!\
Bist du eine\12Trainer? Ast du\
gewonnen in dem\12Kampf gegen den\
ARENALEITER?",
  ["48:4d62"] = "Ooh, la la!\
Sehr übsch!",
  ["48:4d81"] = "Aja? Dann lernen\
sollst du!\11Folge mir!",
  ["48:4daf"] = "Isch bin eine\
Lehrer. Es ist gut\11für disch, bei mir\11zu lernen!",
  ["48:4ddf"] = "Man sagt, dass im\
KNOFENSA-TURM\11Geister umgehen.\12POKéMON-Atta-\
cken des Typs Nor-\12mal zeigen bei\
Geistern keine\11Wirkung.",
  ["48:4e49"] = "Hey, bist du ein\
POKéMON-Trainer?\12Schlägst du den\
hiesigen ARENA-\12LEITER, dann\
darfst du dich\12bald zur Elite\
zählen!",
  ["48:4ea5"] = "FALK von der\
POKéMON-ARENA\12in VIOLA CITY ist\
ein großartiger\12Trainer!\12Er hat die Arena\
seines Vaters ge-\12erbt und hat dort\
hervorragende Ar-\12beit geleistet.",
  ["48:4f1b"] = "Ich habe einen\
wackeligen Baum\11gesehen!\12Wenn du ihn be-\
rührst, windet er\11sich und tanzt!\11Cool!",
  ["48:4f68"] = "VIOLA CITY\12Die Stadt der\
Nostalgie",
  ["48:4f92"] = "VIOLA CITY\
POKéMON ARENA-\11LEITER: FALK\12Der elegante\
Meister der Flug-\11POKéMON",
  ["48:4fda"] = "KNOFENSA-TURM\12Erfahre die Art\
der POKéMON",
  ["48:5003"] = "EARLs POKé-\
MON-AKADEMIE",
  ["48:51e7"] = "…Sag mir\
etwas.\12Ist es wahr, dass\
TEAM ROCKET zu-\11rückgekehrt ist?\12Was? Du hast sie\
geschlagen? Ha!\11Hör auf zu lügen!\12Du machst keine\
Witze? Dann lass\11uns sehen, wie gut\11du bist!",
  ["48:5280"] = "… Hmpf! Nutzlose\
POKéMON!\12He, du! Du hast\
nur gewonnen, weil\12meine POKéMON\
schwach sind.",
  ["48:52cd"] = "Ich hasse\
Schwäche!\12POKéMON, Trainer.\
Es macht keinen\11Unterschied, wer\11oder was.\12Ich werde stark\
sein und das\11Schwache aus-\11löschen!\12Das gilt auch für\
TEAM ROCKET.\12Nur gemeinsam sind\
sie stark. Aber\12triffst du auf ei-\
nen allein, ist er\11schwach.\12Ich hasse sie.\12Geh mir aus dem\
Weg. Ein Schwäch-\12ling wie du ist\
nicht mehr als\11eine Ablenkung.",
  ["48:53f5"] = "…Hmpf! Ich wusste,\
dass du lügst.",
  ["48:5415"] = "Es ist gefährlich,\
da hineinzugehen.\11Deshalb stehe ich\11hier Wache.\12Bin ich nicht ein\
barmherziger\11Samariter?",
  ["48:5461"] = "Hast du schon mal\
eine FLEGMONRUTE\11probiert? Sie soll\11sehr lecker sein.\12Du bist sicher\
froh, dass ich dir\11das gesagt habe.",
  ["48:54b5"] = "Alle FLEGMONS sind\
aus der Stadt ver-\11schwunden…\12Ich hörte, dass\
ihre RUTEN ver-\11kauft werden.",
  ["48:550d"] = "Die FLEGMONS sind\
zurückgekehrt.\12Vermutlich haben\
sie wieder irgend-\12wo gefaulenzt.",
  ["48:5568"] = "Bist du gekommen,\
um KURT zu bitten,\11dir ein paar BÄLLE\11zu machen?\12Eine Menge Leute\
wollen das.",
  ["48:55b4"] = "Gehe durch AZALEA\
CITY und du lan-\11dest im STEINEI-\11CHENWALD.\12Aber diese dürren\
Bäume machen es\12unmöglich, weiter-\
zukommen.\12Die POKéMON des\
KÖHLERS können die\11Bäume mit dem ZER-\11SCHNEIDER fällen.",
  ["48:564a"] = "FLEGMON: …\12…… …… ……",
  ["48:565d"] = "…… ……Gähn?",
  ["48:5679"] = "AZALEA CITY\
Hier leben Men-\12schen und POKéMON\
in Harmonie",
  ["48:56b2"] = "KURTs HAUS",
  ["48:56c0"] = "AZALEA CITY\
PKMN-ARENA\11LEITUNG: KAI\12Die lebende Käfer-\
POKéMON-Enzyklo-\11pädie",
  ["48:5706"] = "Der FLEGMON-BRUN-\
NEN ist auch be-\12kannt als REGEN-\
MACHERQUELLE\12Die Leute hier\
glauben, dass das\11Gähnen eines FLEG-\11MONS Regen er-\11zeugt.\12Laut den Aufzeich-\
nungen soll das\12Gähnen eines FLEG-\
MONS vor 400 Jah-\12ren eine Dürre be-\
endet haben.",
  ["48:57ac"] = "HOLZKOHLE-OFEN",
  ["48:57bb"] = "STEINEICHENWALD\12Tritt durch das\
Tor",
  ["48:5936"] = "Du hast das Meer\
überquert, um\12hierher zu kommen?\
Das war sicher\11nicht einfach.\12Es wäre viel ein-\
facher, wenn deine\12POKéMON FLIEGEN\
einsetzen könnten…",
  ["48:59a8"] = "Ohne den ORDEN\
dieser Stadt ist\11FLIEGEN nutzlos.\12Wenn du den ARENA-\
LEITER geschlagen\11hast, besuche mich\11wieder.\12Ich werde dir dann\
ein Geschenk über-\11reichen.",
  ["48:5a28"] = "Das ist der ORDEN\
der ARENA von\11ANEMONIA CITY!\12Dann soll dir\
diese VM gehören.",
  ["48:5a62"] = "Bring deinen POKé-\
MON FLIEGEN bei.\12Du kannst dann so-\
fort in jede Stadt\12FLIEGEN, die du\
bereits besucht\11hast.",
  ["48:5abc"] = "Mein Mann hat ge-\
gen dich verloren.\11Also muss er här-\11ter trainieren.\12Das ist auch gut\
so. Er hat in\11letzter Zeit etwas\11Speck angesetzt.",
  ["48:5b24"] = "Setzt du FLIEGEN\
ein, kannst du di-\12rekt von hier aus\
nach OLIVIANA CITY\11reisen.",
  ["48:5b5e"] = "Die Felsen nörd-\
lich der Stadt\11können zerschmet-\11tert werden.\12Vielleicht findest\
du etwas unter\11ihnen.\12Deine POKéMON\
können ZERTRÜMME-\11RER einsetzen, um\11sie aus dem Weg zu\11räumen.",
  ["48:5bd9"] = "HARTWIG, der ARE-\
NALEITER steigt\12gerne mit seinen\
POKéMON in den\11Ring.",
  ["48:5c78"] = "ANEMONIA CITY\12Eine Hafenstadt\
umgeben von stür-\11mischer See",
  ["48:5ca7"] = "ANEMONIA CITY\
POKéMON ARENA\12LEITER: HARTWIG\12Er spricht durch\
seine Fäuste",
  ["48:5cee"] = "500 Jahre voller\
Tradition.\12APOTHEKE von\
ANEMONIA CITY\12Gerne erwarten wir\
Ihre medizinischen\11Fragen",
  ["48:5d3d"] = "FOTOSTUDIO von\
ANEMONIA CITY\12Machen Sie einen\
Schnappschuss zur\11Erinnerung!",
  ["48:5ec6"] = "Der neue RADIOTURM\
wurde erbaut, um\12den alten zu er-\
setzen.",
  ["48:5f06"] = "Es soll einen neu-\
en FAHRRADLADEN\12geben, aber ich\
kann ihn nirgends\11finden.",
  ["48:5f43"] = "Hat sich dieser\
Mann in Schwarz\12als Mitglied von\
TEAM ROCKET ver-\12kleidet? Wie däm-\
lich!",
  ["48:5f8a"] = "Gehörte dieser\
Mann in Schwarz\12wirklich zu TEAM\
ROCKET? Ich kann\12es nicht glauben!",
  ["48:5fd0"] = "Der RADIOTURM in\
DUKATIA CITY ist\11ein Wahrzeichen.\12Zurzeit läuft ge-\
rade eine Werbe-\11kampagne.\12Sie können deinen\
POKéCOM modifi-\12zieren, so dass er\
auch als Radio\12verwendet werden\
kann.",
  ["48:6071"] = "Oh, dein POKéCOM\
ist auch ein\11Radio!",
  ["48:6093"] = "E-he-he-he…\12Ich habe Ärger be-\
kommen, weil ich\12im Keller des\
KAUFHAUSES ge-\11spielt habe.",
  ["48:60e0"] = "Der Mann in diesem\
Haus bewertet dei-\11ne POKéMON-Namen.\12Er kann deine\
POKéMON auch\11umbenennen.",
  ["48:612c"] = "Wow! Das ist eine\
große Stadt. Ich\12finde mich noch\
gar nicht zurecht.",
  ["48:616a"] = "Das ist also der\
RADIOTURM…",
  ["48:6187"] = "Was willst du, du\
Nervensäge? Hau\11ab!",
  ["48:61ab"] = "Aus dem Weg! Ver-\
schwinde!",
  ["48:61ca"] = "Den RADIOTURM ein-\
nehmen…\12Was? Das geht dich\
nichts an!",
  ["48:6207"] = "POKéMON? Sie sind\
nicht mehr als\12Werkzeuge zum\
Geldscheffeln!",
  ["48:623f"] = "Bald wird sich un-\
ser Traum er-\11füllen…\12So lange hat es\
schon gedauert…",
  ["48:627c"] = "Hey, Kleiner! Du\
hast hier nichts\11zu suchen!",
  ["48:62a8"] = "Komm und werde\
Zeuge der Macht\11von TEAM ROCKET!",
  ["48:62d4"] = "DUKATIA CITY\
BAHNHOF",
  ["48:62ec"] = "DUKATIA CITY\
RADIOTURM",
  ["48:6308"] = "Große Auswahl an\
POKéMON-Artikeln!\12DUKATIA CITY\
KAUFHAUS",
  ["48:6341"] = "ARENA von\
DUKATIA CITY\11LEITERIN: BIANKA\12Ein unglaublich\
hübsches Mädchen!",
  ["48:6386"] = "DUKATIA CITY\12Die festliche\
Stadt mit opulen-\11tem Charme",
  ["48:63b8"] = "Die Welt ist ein\
Radweg!\11FAHRRADLADEN",
  ["48:63de"] = "Dein Spielplatz!\12DUKATIA CITY\
SPIELHALLE",
  ["48:640b"] = "NAMENBEWERTER\12Möchtest du deine\
Spitznamen bewer-\11ten lassen?",
  ["48:6435"] = "UNTERGRUND-\
EINGANG",
  ["48:644b"] = "UNTERGRUND-\
EINGANG",
  ["49:40d7"] = "…\12Du schon wieder?\12Kein Grund zur Pa-\
nik. Mit Verlie-\12rern wie dir gebe\
ich mich nicht ab.\12Apropos Verlierer:\
die ARENALEITERIN\12dieser Stadt ist\
nicht hier.\12Sie kümmert sich\
wohl gerade um ein\12krankes POKéMON im\
LEUCHTTURM.\12Hmpf! Bu-Huu!\
Wozu soll das nur\11gut sein?\12Ein POKéMON, das\
nicht kämpfen\11kann, ist wertlos!\12Warum trainierst\
du nicht im\11LEUCHTTURM?\12Wer weiß, viel-\
leicht wirst du\11dadurch ein wenig\11stärker!",
  ["49:4235"] = "Nachts sind dunkle\
Straßen gefähr-\11lich.\12Auch das Meer\
wirkt viel bedroh-\12licher in der\
pechschwarzen\11Finsternis!\12Ohne das Licht des\
LEUCHTTURMS könnte\12kein Schiff das\
Meer bereisen.",
  ["49:42e1"] = "Dieses Ding da ist\
doch ein POKéCOM.\11Wow, das ist cool!",
  ["49:431e"] = "Wow, du hast einen\
POKéDEX!\12Das ist so toll!",
  ["49:434e"] = "Hallo, Jungchen!\
Die See ist schön!\12Sing mit mir!\
Yo-ho! Seebären\11sind so cool!…",
  ["49:439a"] = "OLIVIANA CITY\12Das Tor zu einer\
neuen Welt",
  ["49:43ca"] = "HAFEN von OLIVIANA\
CITY\11SCHNELLBOOT-PIER",
  ["49:43e7"] = "OLIVIANA CITY\
POKéMON ARENA-\11LEITERIN: JASMIN\12Ein stahlhartes\
Mädchen!",
  ["49:442a"] = "LEUCHTTURM von\
OLIVIANA CITY,\11auch bekannt als\11GLITZER-LEUCHTTURM",
  ["49:4604"] = "Es gab zwei Türme\
in TEAK CITY. Ei-\12nen im Osten, ei-\
nen im Westen.",
  ["49:4646"] = "Na, Junge?\
Hast du gelernt zu\12tanzen wie die\
KIMONO GIRLS?\12Ich habe gehört,\
dass dir ein ei-\12genartiger Mann\
etwas Nettes geben\12wird, wenn du zu\
ihrem TANZTHEATER\11gehst.",
  ["49:46de"] = "Ich will im TANZ-\
THEATER üben.\12Kommst du mit?",
  ["49:471d"] = "Der Turm war ur-\
sprünglich viel\12höher, aber er\
wurde durch ein\11Feuer beschädigt.",
  ["49:4761"] = "Drei große POKéMON\
sind in verschie-\11dene Richtungen\11davongelaufen! Was\11waren das für\11welche?",
  ["49:47a4"] = "Es kursiert ein\
Gerücht über den\11LEUCHTTURM in OLI-\11VIANA CITY.\12Das POKéMON, das\
als Leuchtfeuer\12dient, wurde\
krank. Sieht so\12aus, als wären sie\
in Schwierig-\11keiten.",
  ["49:481d"] = "Das POKéMON im\
LEUCHTTURM von\11OLIVIANA CITY wur-\11de geheilt.\12Jetzt können die\
Schiffe wieder ge-\11fahrlos nachts in\11See stechen.",
  ["49:487e"] = "Ich hörte, dass\
POKéMON am SEE DES\12ZORNS Unruhe stif-\
ten. Das würde ich\11gerne sehen.",
  ["49:48c3"] = "TEAK CITY\
Eine historische\12Stadt, wo Vergan-\
genheit und Gegen-\12wart aufeinander-\
treffen",
  ["49:4905"] = "ZINNTURM\12Man sagt, ein le-\
gendäres POKéMON\12soll dort sein",
  ["49:493a"] = "TEAK CITY\
POKéMON ARENA-\11LEITER: JENS\12Der mystische Se-\
her der Zukunft",
  ["49:497e"] = "TANZTHEATER VON\
TEAK CITY",
  ["49:4996"] = "TURMRUINE\12Er wurde durch ein\
mysteriöses Feuer\11zerstört.\12Bitte nicht betre-\
ten!",
  ["49:4b65"] = "Hi, Kleiner! Ich\
sehe, du bist neu\11in MAHAGONIA CITY.\12Du musst unbedingt\
einen WUTKEKS pro-\11bieren!\12Ich habe einen da-\
bei. Für nur ¥300\11gehört er dir.",
  ["49:4c03"] = "Gut! Genieße ihn!",
  ["49:4c14"] = "Du hast nicht ge-\
nug Geld.",
  ["49:4c31"] = "Dann eben nicht…",
  ["49:4c41"] = "Du hast keinen\
Platz mehr.",
  ["49:4c5f"] = "Die WUTKEKSE sind\
ausverkauft.\12Ich verschwinde.\
Stör mich nicht,\11Söhnchen.",
  ["49:4ca2"] = "Hast du vor, die\
GARADOS am SEE an-\11zusehen?",
  ["49:4cda"] = "Die KARPADORS sind\
zum SEE DES ZORNS\11zurückgekehrt.\12Das sind gute Neu-\
igkeiten für die\11Angler.",
  ["49:4d33"] = "Wenn du schon so\
weit gekommen\12bist, solltest du\
dir die Zeit neh-\12men, um etwas\
Sightseeing zu un-\11ternehmen.\12Geh nach Norden\
und sieh dir den\12SEE DES ZORNS an.",
  ["49:4daf"] = "Besuche Großmut-\
ters Laden. Sie\12verkauft Artikel,\
die du sonst nir-\12gends bekommen\
kannst.",
  ["49:4deb"] = "MAHAGONIA CITY\12Willkommen in der\
Stadt der Ninja",
  ["49:4e1b"] = "Versuchen Sie den\
leckeren WUTKEKS!",
  ["49:4e4e"] = "MAHAGONIA CITY\
POKéMON ARENA-\11LEITER: NORBERT\12Der Lehrer der\
Härte des Winters",
  ["49:5063"] = "Dieser See ist\
voller GARADOS.\11Aber sonst gibt es\11hier nichts…\12Die KARPADORS wer-\
den also gezwun-\11gen, sich zu ent-\11wickeln…",
  ["49:50c0"] = "Bist du wegen der\
Gerüchte hier?\12Du bist {PLAYER}?\
Ich bin SIEGFRIED,\11ein Trainer wie\11du.\12Ich hörte einige\
Gerüchte. Also kam\11ich hierher, um\11einige Nachfor-\11schungen anzustel-\11len…\12Ich habe gesehen,\
wie du kämpfst,\11{PLAYER}.\12Man kann sagen,\
dass du ein Trai-\12ner von bemerkens-\
wertem Format\11bist.\12Würdest du mir bei\
meinen Nachfor-\11schungen helfen?",
  ["49:51d2"] = "SIEGFRIED: Exzel-\
lent!\12Es sieht so aus,\
als würde jemand\12die KARPADORS im\
SEE zwingen, sich\11zu entwickeln.\12Die Ursache ist\
das mysteriöse\12Radiosignal aus\
MAHAGONIA CITY.\12Ich werde auf dich\
warten, {PLAYER}.",
  ["49:527d"] = "Oh… Solltest du\
deine Meinung än-\11dern, dann hilf\11mir bitte.",
  ["49:52b1"] = "SIEGFRIED: Na?\
Wirst du mir hel-\11fen?",
  ["49:52d7"] = "GARADOS: Gashaa!",
  ["49:52eb"] = "{PLAYER} erhält\
ROTE HAUT.",
  ["49:5304"] = "Die GARADOS sind\
wütend!\12Das ist ein böses\
Omen!",
  ["49:532d"] = "Haha! Die KARPA-\
DORS beißen!",
  ["49:5350"] = "Ich habe gehört,\
dieser See ent-\11stand durch wüten-\11de GARADOS.\12Ich frage mich, ob\
da eine Verbindung\12zu der momentanen\
Situation besteht!",
  ["49:53c7"] = "Täuschen mich mei-\
ne Augen? Ich sah\12ein rotes GARADOS\
im SEE…\12Aber ich dachte,\
GARADOS sind blau!",
  ["49:542e"] = "Lass die POKéMON,\
die ich gerade ge-\11fangen habe,\11kämpfen!",
  ["49:545a"] = "Ich mag zwar ein\
guter Angler sein,\12aber als Trainer\
habe ich versagt…",
  ["49:549b"] = "Ich werde mich als\
Angler beweisen.\11Ich werde tagein,\11tagaus POKéMON\11fangen.",
  ["49:54cc"] = "Ich kann tun, was\
ich will. Ich fan-\12ge immer nur die\
gleichen POKéMON…",
  ["49:5503"] = "Meine Schnur hat\
sich verheddert…",
  ["49:551d"] = "Warum kann ich\
keine guten POKé-\11MON fangen?",
  ["49:553e"] = "Trifft ein Trainer\
auf einen anderen,\12so muss er ihn he-\
rausfordern.\12Das ist unsere Be-\
stimmung.",
  ["49:5594"] = "Wow…\
Toller Kampf!",
  ["49:55a8"] = "POKéMON und\
ihre Trainer wer-\12den durch ständi-\
ges Kämpfen immer\11stärker.",
  ["49:55eb"] = "Was geschah mit\
dem roten GARADOS?\12Es ist fort?\12Oh, dann bin ich\
umsonst hergekom-\11men.\12Ich weiß was! Lass\
uns kämpfen!",
  ["49:5651"] = "Der war gut!",
  ["49:565e"] = "Stell dir vor, ich\
habe ein rosa\11SMETTBO gesehen!",
  ["49:5690"] = "MITKO: Na, wie\
geht es dir?\12Ich bin MITKO von\
Mittwoch. Soll\12heißen, heute ist\
Mittwoch.",
  ["49:56e9"] = "Freut mich, dich\
kennenzulernen.\11Nimm dir bitte ein\11Souvenir.",
  ["49:5717"] = "MITKO: SCHWARZGURT\
verstärkt die\11Kraft von Kampf-\11Attacken.",
  ["49:5750"] = "MITKO: Da du mich\
gefunden hast,\12musst du meine\
Brüder und Schwes-\12tern getroffen\
haben.\12Oder hattest du\
einfach nur Glück?",
  ["49:57b5"] = "MITKO: Heute ist\
nicht Mittwoch.\11Wie schade.",
  ["49:57e3"] = "SEE DES ZORNS,\
auch bekannt als\11GARADOS-SEE",
  ["49:580f"] = "HAUS DES PROFI-\
ANGLERS",
  ["49:5994"] = "Tut mir Leid.\12Unsere ARENALEI-\
TERIN trainiert in\11der Höhle da hin-\11ten.\12Ich weiß nicht,\
wann unsere LEITE-\11RIN zurückkommen\11wird.",
  ["49:5a01"] = "Unsere ARENALEI-\
TERIN erwartet\11dich.\12Für einen Trainer-\
Frischling wie\12dich ist es schier\
unmöglich, gegen\11sie zu gewinnen.",
  ["49:5a6b"] = "Du hast unsere\
ARENALEITERIN be-\11siegt? Erstaun-\11lich!\12Mit deiner Stärke\
solltest du auch\12in der POKéMON\
LIGA erfolgreich\11sein.",
  ["49:5ad0"] = "Nur Drachen-Trai-\
ner dürfen hier\12trainieren. Bitte\
geh wieder!",
  ["49:5b0e"] = "Da SANDRA, die\
Drachenmeisterin,\12es erlaubt hat,\
darfst du eintre-\11ten.",
  ["49:5b4e"] = "Mein Radio ist im\
Eimer. Seit kurzem\11empfange ich nur\11dieses eigenartige\11Signal.",
  ["49:5b87"] = "Aruuu! Stimmen in\
meinem Kopf!\12Häh? Ich höre\
Radio!",
  ["49:5bc1"] = "Willst du, dass\
deine POKéMON ei-\11nige Attacken ver-\11gessen?",
  ["49:5bf5"] = "Ich will ein Dra-\
chentrainer wer-\11den. Genau wie\11SANDRA.",
  ["49:5c1f"] = "SAMSON: …\12Heute ist Samstag…\12Ich bin SAMSON von\
Samstag…",
  ["49:5c4f"] = "Du kannst das\
haben…",
  ["49:5c63"] = "SAMSON: …\12BANNSTICKER…\12Geist-Attacken\
werden stärker…\12Es ist geradezu\
beängstigend…",
  ["49:5cae"] = "SAMSON: …\12Wir sehen uns an\
einem anderen\11Samstag wieder…\12Aber ich werde\
dann keine Ge-\11schenke mehr\11haben…",
  ["49:5cf8"] = "SAMSON: Heute ist\
nicht Samstag…",
  ["49:5d16"] = "Wow, du bist über\
den EISPFAD gekom-\11men?\12Du musst ein rich-\
tiger Heißsporn\11sein!",
  ["49:5d5f"] = "EBENHOLZ CITY\12Ein ruhiger Ort in\
den Bergen",
  ["49:5d89"] = "EBENHOLZ CITY\
POKéMON ARENA-\11LEITERIN: SANDRA\12Die gesegnete Dra-\
chen-POKéMON-\11Trainerin",
  ["49:5dd1"] = "HAUS DES ATTACKEN-\
VERLERNERS",
  ["49:5de7"] = "DRACHENHÖHLE\
VORAUS",
  ["49:5dfb"] = "TIPPS FÜR TRAINER\12Ein POKéMON, das\
eine WUNDERBEERE\12trägt, kann von\
sich aus Status-\11veränderungen hei-\11len",
  ["49:5f27"] = "SILBERBERG",
  ["4a:4175"] = "Ich treffe die\
letzten Vorberei-\12tungen für die\
POKéMON LIGA.",
  ["4a:41ab"] = "Ich habe es\
vermasselt!",
  ["4a:41b7"] = "Es ist sehr\
schwer, in der\11LIGA zu gewinnen.\12Ich muss mehr\
trainieren.\12Ich habe gehört,\
dass die TOP VIER\12aus der LIGA noch\
stärker sind als\11die ARENALEITER.",
  ["4a:4246"] = "Wenn du harte\
Kämpfe bestrei-\11test, wirst du\11stärker.",
  ["4a:4276"] = "Gah! Das Leben ist\
noch härter!",
  ["4a:4293"] = "Um zur POKéMON\
LIGA zu gelangen,\12musst du die\
SIEGESSTRASSE\11passieren.\12Die SIEGESSTRASSE\
ist schwierig.\12Eigentlich geht\
niemand dorthin!",
  ["4a:430b"] = "Da du es bis\
hierher geschafft\11hast, musst du\11gut sein.\12Ich werde in\
diesem Kampf\11alles geben!",
  ["4a:436c"] = "Nein! Ich kann\
das nicht glauben!",
  ["4a:4386"] = "Ich bezwang acht\
ARENALEITER, also\12hatte ich genug\
Selbstbewusstsein.\12Das nächste Mal\
muss ich mich mehr\11anstrengen.",
  ["4a:43e5"] = "Ich habe gegen\
einen Trainer\11namens {RIVAL}\11verloren.\12Er war sehr\
stark, aber…\12Es schien, als\
sei er vom Siegen\11besessen.\12Seine POKéMON\
taten mir Leid.",
  ["4a:446e"] = "POKéMON sind keine\
Kriegswerkzeuge.",
  ["4a:4488"] = "POKéMON sind\
unschätzbare,\11lebenslange\11Partner.",
  ["4a:44b3"] = "Wow, sieh dir all\
die ORDEN an! Ich\11bin beeindruckt.\12Aber es reicht dir\
nicht, sie nur zu\12sammeln, oder?",
  ["4a:4519"] = "Guter Kampf!",
  ["4a:4527"] = "Menschen und POKé-\
MON wachsen mit\11ihren Erfahrungen.\12Du darfst nicht\
faul und selbstge-\11fällig werden.",
  ["4a:4573"] = "Heute fühle ich\
mich grossartig!\12Ich fühle mich so\
stark, dass ich\11den LIGA-CHAMP\11besiegen könnte!",
  ["4a:45bc"] = "Nein! Nicht in\
diesem Kampf!",
  ["4a:45d5"] = "Das Angeln und\
POKéMON sind sehr\12ähnlich. Wenn du\
aufgibst, ist es\11vorüber.",
  ["4a:4613"] = "ROUTE 26\12POKéMON LIGA\
EMPFANG",
  ["4a:486a"] = "Heh!",
  ["4a:4870"] = "Weißt du, was du\
gerade getan hast?\12Du hast deinen\
ersten Schritt in\11KANTO gemacht.\12Sieh auf die KARTE\
in deinem POKéCOM.",
  ["4a:48d8"] = "Du siehst sehr\
stark aus. Ich\11will gegen dich\11kämpfen!",
  ["4a:4904"] = "Juhu!",
  ["4a:490a"] = "Wenn du das hier\
erfolgreich über-\12stehst, wirst du\
die Wahrheit\11erkennen!\12Entschuldigung,\
ich wollte nur\11etwas Geistreiches\11sagen.",
  ["4a:497b"] = "Hm? Du bist gut,\
nicht wahr?",
  ["4a:4997"] = "Wie ich dachte!",
  ["4a:49ab"] = "Ein guter Trainer\
erkennt andere\11gute Trainer.",
  ["4a:49de"] = "Du solltest die\
wilden POKéMON,\12die hier leben,\
nicht unter-\12schätzen.",
  ["4a:4a18"] = "Oh! Du bist\
viel zu stark!",
  ["4a:4a34"] = "Du bist zwar nur\
ein Kind, aber man\12darf dich auch\
nicht unter-\12schätzen.",
  ["4a:4a72"] = "Hier kommen nur\
selten Menschen\11vorbei.\12Trainierst du\
vollkommen allein?",
  ["4a:4ab3"] = "Oh! Du bist\
wirklich stark!",
  ["4a:4acd"] = "Ich teste\
POKéMON in deren\11verschiedenen\11Entwicklungs-\11stufen.\12Entwickelte\
POKéMON sind\11stärker.\12Sie lernen die\
Attacken aber erst\11mit höherem Level.",
  ["4a:4b54"] = "Sag nichts!\12Lass mich raten,\
woran du denkst.\12Mmmmmmm…\12Ich weiß! Du\
denkst darüber\11nach, zur POKéMON\11LIGA zu gehen!",
  ["4a:4bc0"] = "Das ist zuviel!",
  ["4a:4bd1"] = "Deine Fähigkeiten\
versprechen gute\11Ergebnisse in der\11POKéMON LIGA.\12Ich spüre das.",
  ["4a:4c21"] = "Zwitscher!\
Zwitscher!",
  ["4a:4c39"] = "Zwitscher!",
  ["4a:4c41"] = "VOGELFÄNGER wie\
ich imitieren\12Vogelstimmen, um\
dadurch den\11POKéMON Befehle\11zu erteilen.",
  ["4a:4c7e"] = "TOHJO-FÄLLE\12Die Verbindung\
zwischen\11KANTO und JOHTO",
  ["4a:4d53"] = "ROUTE 28",
  ["4a:4ed2"] = "POKéMON verstecken\
sich im Gras.\12Niemand weiß, wann\
sie auftauchen…",
  ["4a:4f0a"] = "Ich habe dich\
schon öfters ge-\12sehen. Wie viele\
POKéMON hast du\11bereits gefangen?\12Du willst, dass\
ich dir zeige, wie\11man POKéMON fängt?",
  ["4a:4f78"] = "So geht das!\12Wenn du sie zuerst\
schwächst, kannst\11du sie leichter\11fangen.",
  ["4a:4fc2"] = "Oh. In Ordnung.\12Egal, wenn du\
viele POKéMON\12fangen möchtest,\
musst du weite\11Wege gehen.",
  ["4a:500e"] = "Häh? Du willst mir\
zeigen, wie man\11POKéMON fängt?",
  ["4a:503f"] = "Yo. Wie geht es\
deinen POKéMON?\12Sind sie schwach\
und nicht bereit\12zu kämpfen, halte\
dich vom Gras\11fern.",
  ["4a:5097"] = "Siehst Du die\
Stufen hier?\12Du kannst nicht\
hinaufklettern,\11dafür aber\11herunterspringen!\12Du kannst nach\
NEUBORKIA gehen,\12ohne durch das\
Gras zu laufen.",
  ["4a:5104"] = "Ich wollte eine\
Pause einlegen,\12darum habe ich\
meinen Spielstand\11abgespeichert.",
  ["4a:5177"] = "Ich warte auf\
POKéMON, die\12nur des Nachts\
auftauchen.",
  ["4a:51a7"] = "Ich warte auf\
POKéMON, die\12nur am VORMITTAG\
auftauchen.",
  ["4a:51dd"] = "DIETLINDE: Ich\
glaube, wir\12begegnen uns zum\
ersten Mal!\12Darf ich mich\
vorstellen? Ich\12bin DIETLINDE\
von Dienstag.",
  ["4a:525a"] = "Da wir uns zum\
ersten Mal sehen,\12schenke ich dir\
ein ROSA BAND.",
  ["4a:529a"] = "DIETLINDE: Findest\
du nicht auch,\11dass es sehr\11schön ist?\12Attacken der\
Elementklasse\11Normal, werden\11dadurch stärker.\12Ich bin sicher,\
du kannst es\11gebrauchen.",
  ["4a:5312"] = "DIETLINDE: Bist\
du MONJA meiner\11älteren Schwester\11schon begegnet?\12Oder meinem\
kleinen Bruder\11MITKO?\12Ich bin das zweite\
von sieben\11Kindern.",
  ["4a:5384"] = "DIETLINDE: Heute\
ist nicht Diens-\11tag. Das ist\11schade…",
  ["4a:53b9"] = "ROUTE 29\12ROSALIA CITY -\
NEUBORKIA",
  ["4a:53e4"] = "ROUTE 29\12ROSALIA CITY -\
NEUBORKIA",
  ["4a:55ad"] = "Los, RATTFRATZ!\12TACKLE!",
  ["4a:55c3"] = "Was? Das ist ein\
harter Kampf!\11Lass mich in Ruhe!",
  ["4a:55f0"] = "Ich habe verloren.\
Ich muss noch mehr\11POKéMON fangen.\12Warte! Du siehst\
schwach aus! Lass\11uns kämpfen!",
  ["4a:5649"] = "Ugh. Ich habe\
keine POKéMON\11mehr.",
  ["4a:566a"] = "Ich benötige\
mehr POKéMON zum\11Kämpfen.\12Ich werde mir\
welche fangen!",
  ["4a:56ae"] = "Du bist ein POKé-\
MON-Trainer, oder?\12Dann musst du\
kämpfen!",
  ["4a:56e5"] = "Das ist seltsam.\
Davor habe ich\11gewonnen.",
  ["4a:5703"] = "Ein guter Trainer\
werden ist nicht\11einfach.\12Ich kämpfe gegen\
andere Trainer, um\11besser zu werden.",
  ["4a:575e"] = "Anstatt eines\
Käfer-POKéMON\11traf ich auf\11einen Trainer!",
  ["4a:5789"] = "Argh! du bist\
zu stark!",
  ["4a:57a2"] = "Mir sind während\
des Fangens die\11POKéBÄLLE aus-\11gegangen.\12Ich hätte mehr\
kaufen sollen…",
  ["4a:57f0"] = "Das Haus von\
MR. POKéMON ist\11gleich da vorne!",
  ["4a:581a"] = "Jedem macht das\
Kämpfen Spaß!",
  ["4a:584a"] = "Ich bin kein\
Trainer.\12Wenn du einem in\
die Augen siehst,\11dann bereite dich\11auf einen Kampf\11vor.",
  ["4a:5891"] = "ROUTE 30\12VIOLA CITY -\
ROSALIA CITY",
  ["4a:58ba"] = "Das Haus von\
MR. POKéMON?\11Immer geradeaus.",
  ["4a:58db"] = "Das Haus von\
MR.POKéMON",
  ["4a:58ec"] = "TIPPS für TRAINER\12Du sollst keine\
POKéMON stehlen!\12POKéBÄLLE dürfen\
nur bei wilden\11POKéMON eingesetzt\11werden!",
  ["4a:5b1e"] = "DUNKELHÖHLE…\12Wenn ein POKéMON\
für Licht sorgen\11könnte, würde ich\11sie erforschen.",
  ["4a:5b54"] = "Ich habe einige\
POKéMON gefangen.\11Lass uns kämpfen!",
  ["4a:5b87"] = "Awwwww…",
  ["4a:5b90"] = "Du kannst POKéMON\
fangen, auch wenn\12du bereits sechs\
bei dir trägst.\12Fängst du eines,\
wird es automa-\11tisch auf die BOX\11im PC übertragen.",
  ["4a:5bf8"] = "… Uargh… Hä?\12Heute bin ich auf\
der Suche nach\11POKéMON zu viel\11gelaufen.\12Meine Füße schmer-\
zen und ich bin\11müde…\12Wenn ich ein wil-\
des POKéMON wäre,\11würde ich mich\11leicht fangen\11lassen…\12…Zzzz…",
  ["4a:5c80"] = "…Zzzz… Häh?\12Was ist? Du\
hast einen BRIEF\11für mich?",
  ["4a:5caf"] = "{PLAYER} übergibt\
das POKéMON, das\11den BRIEF trägt.",
  ["4a:5cd9"] = "Mal sehen…\12…die DUNKELHÖHLE\
führt zu einem\11anderen Weg…\12Gut zu wissen.\12Danke, dass du mir\
den BRIEF\11brachtest.\12Mein Freund ist\
ein netter Mensch,\11genau wie du!\12Ich möchte mich\
bei dir dafür\11revanchieren!\12Ich hab's! Ich\
möchte dir das\11hier geben!",
  ["4a:5dbb"] = "TM50 enthält\
NACHTMAHR.\12Dies ist eine\
gemeine Attacke,\12die einem schlaf-\
endem Gegner\11kontinuierlich\11KP abzieht.\12Uuuuuuh…\
Das ist fies…\12Ich möchte nicht\
schlecht träumen.",
  ["4a:5e46"] = "Der BRIEF ist\
nicht für mich.",
  ["4a:5e5e"] = "Was ist so beson-\
ders an diesem\11POKéMON?\12Es trägt keinen\
BRIEF.",
  ["4a:5e97"] = "Was? Du möchtest\
nichts?",
  ["4a:5eb6"] = "Wenn ich dir die-\
ses POKéMON weg-\12nehme, womit\11willst du dann\
kämpfen?",
  ["4a:5efa"] = "Ich habe ein gutes\
POKéMON in der\11DUNKELHÖHLE\11gefunden.\12Ich ziehe es groß,\
um später gegen\11FALK anzutreten.\12Er ist der ARENA-\
LEITER von VIOLA\11CITY.",
  ["4a:5f6a"] = "ROUTE 31\12VIOLA CITY -\
ROSALIA CITY",
  ["4a:5f93"] = "DUNKELHÖHLE",
  ["4b:42a5"] = "Warte!\
Warum die Eile?",
  ["4b:42c0"] = "{PLAYER}, oder?\
Ein Typ mit einer\12Brille hat nach\
dir gefragt.\12Kümmere dich um\
ihn. Er erwartet\12dich im PKMN-\
CENTER.",
  ["4b:43c5"] = "Warst du schon in\
der POKéMON ARENA?\12Dort kannst du\
deine POKéMON und\11dich auf die Probe\11stellen.\12Es ist eine Art\
Ritus für alle\11Trainer!",
  ["4b:443a"] = "Du besitzt einige\
gute POKéMON.\12Sie sind bestimmt\
wegen der vielen\12Kämpfe, die du mit\
ihnen bei VIOLA\11CITY absolviert\11hast, so gut.\12Das Training in\
der ARENA muss von\12großem Nutzen\
gewesen sein.\12Nimm dies als\
Andenken an\11VIOLA CITY.\12Damit werden\
Pflanzen-Attacken\11verstärkt.",
  ["4b:452a"] = "Die Erfahrungen\
von VIOLA CITY\12werden dir auf\
deiner Reise von\11großem Nutzen\11sein.",
  ["4b:456e"] = "Wie möchtest du\
die schmackhafte,\12gehaltvolle\
FLEGMONRUTE\11zubereitet haben?\12Für dich jetzt nur\
¥1,000,000!\12Möchtest du sie?",
  ["4b:45e4"] = "Ts! Ich dachte,\
die Kinder von\11heute wären\11stinkreich…",
  ["4b:4611"] = "Du möchtest sie\
nicht? Dann mach\11dich vom Acker!",
  ["4b:4636"] = "Wow!\12Wegen dir habe ich\
den Fisch ver-\11loren!",
  ["4b:4659"] = "Platsch!",
  ["4b:4663"] = "Geduld…\
Die Voraussetzung\12für das Angeln und\
für POKéMON ist\11dieselbe.",
  ["4b:46a4"] = "Ich bin ein guter\
Angler, aber ein\11noch besserer\11Trainer!",
  ["4b:46d3"] = "Ts! Ich wollte\
die Sache\11beschleunigen…",
  ["4b:46f1"] = "Angeln ist eine\
Leidenschaft für\12das ganze Leben.\
POKéMON sind\11Freunde fürs\11Leben!",
  ["4b:4863"] = "Meine POKéMON?\
Frisch gefangen!",
  ["4b:487d"] = "PLATSCHER?",
  ["4b:4886"] = "Frisch gefangene\
POKéMON können\12gut trainierten\
nicht Paroli\11bieten.",
  ["4b:48c2"] = "Ich habe dich hier\
noch nie gesehen.\12Du denkst also,\
du bist stark?",
  ["4b:4907"] = "Du bist stark!",
  ["4b:4916"] = "Ich versuche, mit\
meinen Lieblingen\11der Beste zu sein.\12Ich setze nicht\
auf zähe POKéMON,\11wie die anderen.",
  ["4b:497c"] = "Ich habe gute\
POKéMON im\11Gras gefunden!\12Ich denke, sie\
passen ganz gut\11zu mir!",
  ["4b:49bf"] = "Mist. Ich dachte,\
ich könnte\11gewinnen.",
  ["4b:49dd"] = "Im Gras findest\
du viele Dinge.",
  ["4b:4a02"] = "Dieser Blick…\
Wie faszinierend.",
  ["4b:4a20"] = "Hm. Das ist\
enttäuschend.",
  ["4b:4a3e"] = "Wenn du nicht\
kämpfen möchtest,\11vermeide Blick-\11kontakt.",
  ["4b:4a73"] = "A-ha. Ja,\
du weißt…\12Wie bitte? Kampf?\
Ich telefoniere.\12Oh, O.K. Aber\
mach schnell.",
  ["4b:4ad2"] = "Nimm es leicht!\
Das ist gemein!",
  ["4b:4aed"] = "Ich hatte einen\
netten Plausch.",
  ["4b:4b0c"] = "Dieser ORDEN! Er\
ist aus VIOLA\11CITY!\12Du hast FALK\
besiegt?",
  ["4b:4b41"] = "Ich kenne meine\
Schwächen.",
  ["4b:4b61"] = "Ich sollte in der\
ARENA von VIOLA\11CITY weiter\11trainieren.",
  ["4b:4bc0"] = "BRÜLL!\
DIE LEUTE LAUFEN\12DAVON, WENN ICH\
BRÜLLE! DU ABER\11WOLLTEST MICH\11SEHEN!\12DAS GEFÄLLT MIR!\
HIER BITTESCHÖN!",
  ["4b:4c19"] = "BRÜLL!\
ES IST BRÜLLER!\12SOGAR POKéMON\
LAUFEN DAVON,\11WENN DU IHN\11EINSETZT!",
  ["4b:4c4e"] = "FRIEDA: Juhu!\
Es ist Freitag!\12Ich bin FRIEDA\
von Freitag!\12Schön dich\
kennenzulernen",
  ["4b:4c91"] = "Hier, GIFTSTICH\
ist für dich!",
  ["4b:4caf"] = "FRIEDA: Gib es\
einem POKéMON, das\11über Gift-Attacken\11verfügt.\12Oh!\12Es ist gemein!\12Du wirst dich\
wundern, wie\11effektiv deine\11Gift-Attacken\11werden!",
  ["4b:4d27"] = "FRIEDA: Hossa!\
Welchen Wochentag\11hast du am\11liebsten?\12Ich liebe Freitag.\
Daran gibt es\11keinen Zweifel!\12Denkst du nicht\
auch, dass Freitag\11großartig ist?",
  ["4b:4d8c"] = "FRIEDA: Ist heute\
nicht Freitag?\12Es wäre langwei-\
lig, wenn nicht!",
  ["4b:4dc7"] = "ROUTE 32\12VIOLA CITY -\
AZALEA CITY",
  ["4b:4deb"] = "ALPH-RUINEN\
OSTEINGANG",
  ["4b:4e08"] = "EINHEITSTUNNEL\
Geradeaus",
  ["4b:4fad"] = "Ich bin durch den\
Tunnel gegangen,\11aber ich habe noch\12viel Energie\
übrig.",
  ["4b:4ff1"] = "Nicht schlecht! Du\
hast viel Schwung!",
  ["4b:5011"] = "In den Bergen sind\
wir WANDERER\11in unserem\11Element.",
  ["4b:503e"] = "ROUTE 33",
  ["4b:52ee"] = "Hier \
trainiere ich!",
  ["4b:530f"] = "Was ist passiert?",
  ["4b:531f"] = "Ich werde noch\
härter trainieren.\12Ich möchte doch\
ein ARENALEITER\11werden.",
  ["4b:536c"] = "Ich bin der\
POKéMON-Experte\11in meiner Klasse.",
  ["4b:538e"] = "Nein! Es gibt noch\
bessere Trainer…",
  ["4b:53b0"] = "Ich strenge mich\
sehr an, damit ich\11der Star von\11meiner Klasse bin.",
  ["4b:53e2"] = "Ich weiß, dass ich\
POKéMON gut\11aufziehen kann.\12Möchtest du dich\
davon überzeugen?",
  ["4b:541a"] = "Meine Leistung war\
nicht gut genug!",
  ["4b:5439"] = "Vielleicht sollte\
ich eines meiner\11POKéMON in eine\11PENSION bringen.\11Was soll ich tun?",
  ["4b:5473"] = "Bist du\
ein Trainer?\12Hast du Lust zu\
einem Übungskampf?",
  ["4b:54a4"] = "Oh nein! Ich habe\
noch nie gewonnen…",
  ["4b:54be"] = "Du bist mir zu\
stark. Das ist\11keine Übung\11für mich.",
  ["4b:54ea"] = "Wer ist da? Was\
ist dein Begehr?",
  ["4b:550f"] = "Du bist ein\
starker,\11junger Gegner.",
  ["4b:552a"] = "Ja, heute scheint\
alles in Ordnung\12zu sein. Benimm\
dich und halte\11dich aus\11Schwierigkeiten\11heraus.",
  ["4b:5570"] = "Ich bin auf der\
Suche nach ver-\11dächtigen\11Individuen.",
  ["4b:559c"] = "Ich habe gerade\
mein POKéMON\11aus der PENSION\11wieder abgeholt.\12Sehen wir mal,\
wie stark es\11geworden ist!",
  ["4b:55e7"] = "Warum muss es auf\
diese Weise enden?",
  ["4b:5602"] = "Mein POKéMON\
kannte Attacken,\11von denen ich\11nicht wusste, dass\11es sie hat.\12Das war überaus\
erstaunlich!",
  ["4b:5649"] = "LOLA: Juhu! \
Ein Junge hat uns\11gefunden!",
  ["4b:5669"] = "LOLA: Oje!\
Er ist zu stark!",
  ["4b:5688"] = "LOLA: Du wirst\
meine Schwester\11EDNA noch\11kennenlernen!",
  ["4b:56b6"] = "LOLA: Ist dieser\
Strand nicht\11herrlich?\12Er ist unsere\
geheime\11Zuflucht!",
  ["4b:56f4"] = "ELSE: Dein Sieg\
über LOLA muss\11gesühnt werden!",
  ["4b:5722"] = "ELSE: Es tut\
mir so Leid,\11Schwesterchen!",
  ["4b:573f"] = "ELSE: Werde nur\
nicht eingebildet!\11Meine Schwester\11EDNA ist sehr\11stark!",
  ["4b:576f"] = "ELSE: Sonnen-\
licht kräftigt\11deinen Körper.",
  ["4b:5799"] = "EDNA: Du warst\
wirklich gemein\11zu meinen kleinen\11Schwestern!",
  ["4b:57c9"] = "EDNA: Nein! Ich\
kann nicht\11glauben, dass ich\11verloren habe.",
  ["4b:57eb"] = "EDNA: Du bist zu\
stark. Ich hatte\11keine Chance.\12Hier. Das hast du\
dir verdient.",
  ["4b:5834"] = "EDNA: Bitte \
entschuldige, dass\11wir dich über-\11fallen haben.\12Wir hätten nicht\
gedacht, dass uns\12hier jemand\
findet. Du hast\11uns überrascht.",
  ["4b:58b1"] = "ROUTE 34\12DUKATIA CITY -\
AZALEA CITY\12STEINEICHENWALD\
Irgendwo\11dazwischen",
  ["4b:58f6"] = "TIPPS für TRAINER\
Bäume mit BEEREN\12tragen jeden Tag\
neue BEEREN.\12Merke dir, welche\
BEEREN an den\11Bäumen wachsen",
  ["4b:595a"] = "PENSION\12Wir ziehen Dein\
POKéMON für\11Dich auf!",
  ["4b:5c09"] = "Ich habe aus dem\
Radio POKéMON-\12Daten erhalten.\
Ich glaube, ich\11bin gut.",
  ["4b:5c44"] = "Ich teile aus!",
  ["4b:5c4d"] = "Die Musik aus dem\
Radio beeinflusst\11die Stimmung von\11wilden POKéMON.",
  ["4b:5c81"] = "Ich werde meiner\
Freundin zeigen,\11wie cool ich bin!",
  ["4b:5cac"] = "Ach, hättest du\
doch verloren…",
  ["4b:5cd0"] = "Du hast mich vor\
meiner Freundin\11lächerlich\11gemacht…",
  ["4b:5cfd"] = "Mein Freund ist\
schwach. Er kann\11mich nicht\11beschützen.",
  ["4b:5d29"] = "Meine Güte, bist\
du stark!",
  ["4b:5d43"] = "Auf meine\
POKéMON kann\11ich mich eher\11verlassen als auf\11meinen Freund.",
  ["4b:5d73"] = "Gehst du auch\
zur PKMN-ARENA?",
  ["4b:5d96"] = "Oh, ich habe\
verloren…",
  ["4b:5daa"] = "Die ORDEN\
sind hübsch.\11Deshalb sammle ich\11sie.",
  ["4b:5dd6"] = "Welche Art von\
POKéBALL\11benutzt du?",
  ["4b:5df8"] = "Mist! Nicht\
schnell genug!",
  ["4b:5e11"] = "Manche POKéMON\
rennen sofort weg.\12Versuche, sie mit\
KURTs TURBOBALL\11einzufangen. \12Sobald ich eine\
APRIKOKO WSS\11finde, bringe ich\11sie zu KURT.\12Er macht dann\
daraus einen maß-\11gefertigten\11POKéBALL.",
  ["4b:5eaa"] = "Siehe meine\
Virtuosität, mit\11der ich die BÄLLE\11jongliere!",
  ["4b:5ece"] = "Puh, das war ein\
Ruck!",
  ["4b:5ee6"] = "Ich wollte dich\
mit meinem preis-\11gekrönten\11POKéMON beein-\11drucken.\12Aber bei deinem\
Können bleibt mir\11die Spucke weg!",
  ["4b:5f36"] = "Ich gehe überall-\
hin, wo es Käfer-\11POKéMON gibt.",
  ["4b:5f61"] = "Ich verstehe. So\
kämpfst du also.",
  ["4b:5f81"] = "Mit meinem BLUZUK\
habe ich das\12Käferturnier\
im NATIONALPARK\11gewonnen.",
  ["4b:5fc3"] = "Ich übe mich im\
Feuerspucken.",
  ["4b:5fe5"] = "Aua! Ich habe mir\
die Nasenspitze\11verbrannt!",
  ["4b:6009"] = "Der POKéMON-\
Marsch im Radio\11lockt wilde\11POKéMON an.",
  ["4b:6037"] = "Bei Nacht lauern\
Gefahren!",
  ["4b:6053"] = "Schwupps!",
  ["4b:605c"] = "Du weißt, dass\
die Nacht auf\11ihre Weise\11schön sein kann.\12Aber übertreibe\
es nicht, O.K.?",
  ["4b:60a3"] = "Deine POKéMON\
sehen ziemlich\11stark aus.\12Du wärst über-\
all sicher.",
  ["4b:60e1"] = "ROUTE 35",
  ["4b:6321"] = "Das ist ein merk-\
würdiger Baum.\11Möchtest du die\11SCHIGGYKANNE\11benutzen?",
  ["4b:6346"] = "{PLAYER} benutzt\
SCHIGGYKANNE.",
  ["4b:6360"] = "Der merkwürdige\
Baum mag die\11SCHIGGYKANNE\11nicht!\12Der merkwürdige\
Baum greift an!",
  ["4b:63a7"] = "Oje!\12Ich wollte den\
Baum mit einem\12mächtigen Hieb\
entzweibrechen.\12Aber ich habe es\
nicht geschafft.\11Ich habe versagt!",
  ["4b:6408"] = "Hast du diesen\
seltsamen Baum\11weggeschafft?\12Ich bin\
beeindruckt! Ich\11möchte dir dies\11geben.",
  ["4b:6464"] = "Das ist der\
ZERTRÜMMERER.\12Damit kannst du\
Felsen mit einem\12einzigen, gut \
gezielten Schlag\11zertrümmern.\12Sind dir irgend-\
welche Steine im\11Weg, dann\11zertrümmere sie\11einfach!",
  ["4b:64f0"] = "Ein merkwürdiger\
Baum blockiert die\11Straße nach\11DUKATIA CITY.\12Wegen dieses\
Baumes kann ich\12nicht Einkaufen\
gehen. Man sollte\11etwas dagegen tun.",
  ["4b:6568"] = "Dieser merkwürdige\
Baum ist spurlos\11verschwunden.\12Ach! Der Baum war\
in Wirklichkeit\11ein POKéMON?",
  ["4b:65b7"] = "Ich werde jetzt\
deine Gedanken\11lesen!",
  ["4b:65d8"] = "Ich habe mich wohl\
bei dir verlesen!",
  ["4b:65e8"] = "Ich wäre wirklich\
stark, wenn ich \12wüsste, was mein\
Gegner denkt.",
  ["4b:662a"] = "Dank meiner\
Studien bin ich\11für jedes POKéMON\11bereit!",
  ["4b:665a"] = "Ups! Ein Fehler\
in der Berechnung?",
  ["4b:6674"] = "Mist! Ich lerne\
auch fünf Stunden\11am Tag.\12Es gibt Vieles,\
das du nicht aus\11Büchern lernen\11kannst.",
  ["4b:66cc"] = "DONATUS: Wer bist\
du?\12Ich bin DONATUS\
von Donnerstag.",
  ["4b:66f9"] = "Hier bitte. Das\
kannst du haben.",
  ["4b:6713"] = "DONATUS: Ein\
POKéMON, das\12Gestein-Attacken\
benutzt, sollte\11dies mit sich\11tragen.\12Es verstärkt\
Stein-Attacken.",
  ["4b:6776"] = "DONATUS: Ich bin\
DONATUS von\12Donnerstag. Ich\
bin das zweite von\11sieben Kindern.",
  ["4b:67bf"] = "DONATUS: Heute ist\
nicht Donnerstag.\11Wie bedauerlich!",
  ["4b:67f0"] = "ROUTE 36",
  ["4b:67fa"] = "ALPH-RUINEN\
NORDEINGANG",
  ["4b:6818"] = "TIPPS für TRAINER\
Der Status der\12POKéMON ist unter-\
schiedlich, sogar\12innerhalb der\
selben Spezies.\12Zu Beginn ist er\
vielleicht noch\11ähnlich.\12Doch die Unter-\
schiede werden \12deutlicher, wenn\
die POKéMON\11heranwachsen.",
  ["4b:68ba"] = "TIPPS für TRAINER\
Setze den\12SCHAUFLER ein, um\
an den Eingang\12eines Ortes\
zurückzugelangen.\12Das ist sehr nütz-\
lich beim Erkunden\12von Höhlen und an-\
deren Umgebungen.",
  ["4c:4093"] = "NORA: JO und ich\
arbeiten immer\11zusammen!",
  ["4c:40bc"] = "NORA & JO: Du\
bist gemein!",
  ["4c:40d5"] = "NORA: Ich kenne\
die Gedanken\12meiner Schwester\
und die meiner\11POKéMON.",
  ["4c:410f"] = "JO: NORA und ich\
arbeiten immer\11zusammen!",
  ["4c:4138"] = "NORA & JO: Du\
bist gemein!",
  ["4c:4151"] = "JO: Wir fühlen\
dasselbe wie\11unsere POKéMON.",
  ["4c:4180"] = "POKéMON können\
nicht agieren,\11wenn sie\11schlafen.\12Ich werde dir zei-\
gen, wie furcht-\11erregend das ist!",
  ["4c:41ca"] = "Ich habe\
verloren. Wie\11betrüblich…",
  ["4c:41e5"] = "Im Kampf stellt\
es eine gute\11Taktik dar, die\11gegnerischen POKé-\11MON in Schlaf zu\11versetzen oder sie\11zu paralysieren.",
  ["4c:422d"] = "SONNFRIED: Hi!\12Ich bin SONNFRIED\
von Sonntag. Soll\11heißen, heute ist\11Sonntag!",
  ["4c:4269"] = "Man hat mir auf-\
getragen, dir das\11zu geben, wenn ich\11dich treffe!",
  ["4c:4294"] = "SONNFRIED: Dieses\
Ding…\12Äh…\12… Was war das\
nochmal…\12…\12Ah! Jetzt erinnere\
ich mich!\12Ein POKéMON, das\
Elektro-Attacken\12verwendet, sollte\
dies erhalten.\12Meine Schwester\
MONJA behauptet,\11es verstärkt\11Elektro-Attacken!",
  ["4c:4336"] = "SONNFRIED: Meine\
Geschwister heißen\11MONJA, DIETLINDE,\11MITKO, DONATUS,\11FRIEDA und SAMSON.\12Sie sind alle\
älter als ich!",
  ["4c:43a8"] = "SONNFRIED: Ist\
heute nicht Sonn-\11tag? Äh… Das habe\11ich vergessen!",
  ["4c:43d1"] = "ROUTE 37",
  ["4c:45a8"] = "Fliege hoch in die\
Luft, mein\11herrliches\11Vogel-POKéMON!",
  ["4c:45d6"] = "Ich fühle mich,\
als würde ich mich\11selbst in die\11Lüfte erheben.",
  ["4c:45f9"] = "Ich habe vor,\
in ANEMONIA CITY\12zu trainieren und\
meinen POKéMON\11das Fliegen\11beizubringen.",
  ["4c:4638"] = "Jetzt probiere ich\
etwas aus, das ich\11heute gelernt\11habe.",
  ["4c:4661"] = "Ich fürchte, ich\
habe noch nicht\11genug gelernt.",
  ["4c:4681"] = "Ich habe so viele\
Prüfungen, dass\12ich nicht viel\
Zeit für POKéMON\11habe.\12Wenn ich also mal\
Zeit zum Spielen\11habe, dann konzen-\11triere ich mich.",
  ["4c:46f0"] = "Bist du ein guter\
Trainer?\12Wenn ja, zeigst du\
mir, wie man ein\11guter Trainer\11wird?",
  ["4c:472e"] = "Ich verstehe. So\
kämpfst du also.",
  ["4c:4752"] = "Ich kenne etwas\
sehr Bekömmliches!\12Die Milch von der\
KUHMUH-FARM ist\11bekannt für ihren\11guten Geschmack.",
  ["4c:4796"] = "Hallo! Du bist ja\
ein süßer Trainer!\12Darf ich mir deine\
POKéMON anschauen?",
  ["4c:47ca"] = "Ich bin froh, dass\
ich deine POKéMON\11sehen durfte!",
  ["4c:47eb"] = "Wenn ich POKé-\
MON sehe, scheint\11mich das zu\11entspannen.",
  ["4c:481d"] = "Ich war im Aus-\
land. Deswegen\12kenne ich alle\
POKéMON-Arten!",
  ["4c:4856"] = "Deine Fähigkeiten\
sind Spitzen-\11klasse!",
  ["4c:4872"] = "Alle Menschen auf\
der ganzen Welt\12leben glücklich\
zusammen mit den\11POKéMON.",
  ["4c:48b2"] = "ROUTE 38\12OLIVIANA CITY -\
TEAK CITY",
  ["4c:48d9"] = "TIPPS für TRAINER\
Wenn sich ein\12POKéMON weiter-\
entwickelt, kannst\12du diesen Prozess\
aufhalten.\12Drücke während\
der Entwicklung\11den B-Knopf.\12So wird das POKé-\
MON erschreckt und\11es bricht die\11Entwicklung ab.",
  ["4c:4abc"] = "MILTANK: Muh!",
  ["4c:4acc"] = "Ich bin gerade\
wieder in OLIVIANA\11angekommen.\12Wie steht es nun\
mit dem POKéMON-\11Kampf?",
  ["4c:4b05"] = "Aah!",
  ["4c:4b10"] = "Meine POKéMON\
wurden eingefangen\11und sind im Aus-\11land aufgezogen\11worden.\12Sie begleiten mich\
auf meinen langen\11Reisen.",
  ["4c:4b68"] = "Macht es dir etwas\
aus, wenn ich mit\11meinen POKéMON\11angebe?",
  ["4c:4b94"] = "Ich hatte nicht\
einmal Zeit\11anzugeben…",
  ["4c:4bae"] = "Ich höre mir deine\
Prahlerei gar\11nicht an!\12Wir POKé-FANS\
haben ein Gelübde,\12das uns verbietet,\
Leuten beim\11Prahlen zuzuhören!",
  ["4c:4c11"] = "Was für süße\
POKéMON!\12Zeigen wir uns\
gegenseitig unsere\11POKéMON, und zwar\11gleichzeitig!",
  ["4c:4c53"] = "Mir macht es\
nichts aus,\11zu verlieren.",
  ["4c:4c68"] = "Weißt du über\
Baby-POKéMON\11Bescheid?\12Die sind bestimmt\
super-süß!",
  ["4c:4ca2"] = "Zeig doch mal, was\
deine POKéMON\11drauf haben.",
  ["4c:4ccd"] = "He, deine POKéMON\
sind sehr fähig!",
  ["4c:4ced"] = "Du weißt von den\
unterschiedlichen\11POKé-Fähigkeiten?\12Bei den Menschen\
ist das ganz\11ähnlich. Jeder hat\11unterschiedliche\11Talente.",
  ["4c:4d5a"] = "ROUTE 39\12OLIVIANA CITY -\
TEAK CITY",
  ["4c:4d81"] = "KUHMUH-FARM\12Unsere Bekömmliche\
Milch Ist Sehr\11Erfrischend",
  ["4c:4dad"] = "TIPPS für TRAINER\
Benutze KOPFNUSS,\12um POKéMON\
aus den Bäumen\11zu schütteln.\12Auf den Bäumen\
leben verschiedene\11Arten von POKéMON.\12Benutze KOPFNUSS\
an jedem Baum, den\11du siehst!",
  ["4c:4f84"] = "Du musst dich erst\
aufwärmen, bevor\11du schwimmen\11gehst.\12Das ist\
Grundwissen.",
  ["4c:4fc3"] = "O.K.! Onkel! Ich\
gebe auf!",
  ["4c:4fd7"] = "ANEMONIA CITY ist\
ziemlich weit\11weg von hier.",
  ["4c:5009"] = "Ein junger Kerl\
wie du sollte\11schwimmen.\12SURFER kann hier\
nicht eingesetzt\11werden.",
  ["4c:5044"] = "Oh, oh. Ich habe\
verloren…",
  ["4c:5054"] = "Schwimmen hält\
deinen ganzen\11Körper fit und\11gesund.",
  ["4c:5087"] = "Gehst du nach\
ANEMONIA CITY?\12Wie wäre es erst\
mit einem kleinen\11Kampftraining?",
  ["4c:50c3"] = "Diesmal habe ich\
verloren!",
  ["4c:50d5"] = "Ich behaupte,\
dass ich besser\11schwimme als du!",
  ["4c:5103"] = "Ich habe keine\
Schwimmreifen.\12Ich halte mich an\
einem Wasser-\11POKéMON fest!",
  ["4c:5137"] = "Oh, ich fühle mich\
so schwindelig!",
  ["4c:514f"] = "Ich lasse mich im\
Wasser treiben und\11von den Wellen\11davontragen.",
  ["4c:5183"] = "Du kannst es zwar\
nicht von hier\12sehen, aber ANEMO-\
NIA CITY liegt\11jenseits des\11Meeres.",
  ["4c:51c4"] = "MONJA: Es freut\
mich, dich kennen-\12zulernen. Ich bin\
MONJA von Montag.",
  ["4c:51f4"] = "Als Zeichen\
unserer Freund-\11schaft schenke ich\11dir dies!",
  ["4c:522a"] = "MONJA: Dieses\
Item verstärkt\12Flug-Attacken.\12Damit solltest du\
ein Vogel-POKéMON\11ausstatten.",
  ["4c:529a"] = "MONJA: Meine\
Geschwister\12findest du\
überall.\12Du solltest sie\
alle finden!",
  ["4c:52f5"] = "MONJA: Ich\
fürchte, heute ist\11nicht Montag. Wie\11schade…",
  ["4c:5325"] = "ROUTE 40\12ANEMONIA CITY -\
OLIVIANA CITY",
  ["4c:54a1"] = "Das Wasser ist\
schön warm. Ich\11bin also sehr\11locker und gelenk.\12Natürlich trete\
ich gegen dich an!",
  ["4c:54e4"] = "Oje! Ich habe eine\
Gänsehaut!",
  ["4c:5500"] = "Ist es nicht\
sehr entspannend,\11sich auf dem\11Wasser treiben\11zu lassen?",
  ["4c:552b"] = "Ich bin etwas\
müde. Wenn ich\11gewinne, leihst du\11mir dein POKéMON.",
  ["4c:5559"] = "Keuch, japs…",
  ["4c:5566"] = "ANEMONIA CITY ist\
noch so weit weg.\12Aber der Rückweg\
nach OLIVIANA CITY\11ist auch nicht\11viel kürzer.\12Was soll ich tun?",
  ["4c:55c0"] = "Siehst du diese\
Inseln, die von\11den Strudeln\11blockiert werden?\12Dort gibt es\
bestimmt ein\11Geheimnis!",
  ["4c:5612"] = "Was ist das\
Geheimnis deiner\11Stärke?",
  ["4c:5636"] = "Die Nacht war\
dunkel und ein\11Sturm wütete…\12Da sah ich dieses\
riesige POKéMON\11über den Inseln\11aufsteigen.\12Aus seinen\
silbernen Flügeln\11fielen ein paar\11Federn.",
  ["4c:56b8"] = "Hier gibt es hohe\
Wellen.\12Das macht dich\
schnell müde.",
  ["4c:56f4"] = "Ich bin besiegt!",
  ["4c:56fe"] = "Die Strömung ist\
zu stark. Ich kann\11die Insel nicht\11erreichen.",
  ["4c:572f"] = "Suchst du die\
Geheimnisse der\11STRUDELINSELN?",
  ["4c:575e"] = "Ach. Du hast viel\
Ausdauer!",
  ["4c:577f"] = "Ein Geheimnis\
der STRUDELINSELN…\12Es ist kohlraben-\
schwarz darinnen!",
  ["4c:57b6"] = "Ich bin auf dem\
Weg zu den\11STRUDELINSELN.\12Ich gehe mit\
meinen Freunden\11auf Erkundungs-\11reise.",
  ["4c:57f9"] = "Ist es so richtig?",
  ["4c:5811"] = "Tief versteckt\
auf den STRUDEL-\11INSELN soll ein\11großes POKéMON\11leben.\12Was für ein POKé-\
MON das wohl ist?",
  ["4c:586c"] = "Du gleitest so\
elegant auf deinem\11POKéMON dahin.",
  ["4c:5896"] = "Ich bin\
geschlagen…",
  ["4c:58a3"] = "Gab es da nicht\
einmal einen Hit,\11der von einem\11Jungen handelte,\11der auf einem\11LAPRAS ritt?",
  ["4c:58d8"] = "Das Wetter ist so\
herrlich. Ich bin\11richtig benommen!",
  ["4c:5904"] = "Ooh!",
  ["4c:590b"] = "Ein Sonnenbrand\
ist sehr schlecht\11für die Haut.\12Aber ich benutze\
keine Sonnencreme.\12Ich möchte das\
Wasser nicht\11verschmutzen.",
  ["4c:5962"] = "Wenn du eine Pause\
brauchst, dann\11halte deinen Kopf\11über Wasser und\11paddle mit den\11Füßen.\12Auf diese Weise\
legst du eine\12Ruhepause ein und\
sammelst Energie.",
  ["4c:59c5"] = "Oh! Du bist aus-\
geruhter als ich.",
  ["4c:59ea"] = "Ich habe tief aus\
dem Inneren der\11STRUDELINSELN ein\11Brüllen gehört.",
  ["4c:5a17"] = "Nachts sammeln\
sich die STERNDUS\11nahe der Wasser-\11oberfläche.",
  ["4c:5a49"] = "Oje…",
  ["4c:5a54"] = "In der Gruppe\
fangen die\11STERNDUS an,\11zu leuchten.\12Das ist\
wunderschön und\11beängstigend\11zugleich.",
  ["4c:5c16"] = "Jetzt demonstriere\
ich dir die Kraft\11des POKéMON,\11das ich gefangen\11habe!",
  ["4c:5c4a"] = "Was? Das kann\
nicht sein.",
  ["4c:5c62"] = "Mit dem POKéMON,\
das ich gefangen\12habe, möchte ich\
der CHAMP der\11Trainer werden.\12Das ist das Beste\
am Angeln!",
  ["4c:5cbf"] = "Ach ist das schön,\
im Freien zu sein!\11Ich fühle mich so\11frei!",
  ["4c:5cec"] = "Hahaha!",
  ["4c:5cf6"] = "Schaut man auf,\
in dieses überwäl-\12tigend schöne Blau\
des Himmels, dann\11verliert eine\11Niederlage völlig\11an Bedeutung!",
  ["4c:5d33"] = "HEH!\12Das ist mein\
Geheimversteck!\11Verschwinde, du\11Außenseiter!",
  ["4c:5d6a"] = "Ich hätte meinen\
MONDSTEIN benutzen\11sollen…",
  ["4c:5d8d"] = "Du erstellst einen\
POKéDEX?\12Wow, du kennst\
bestimmt einige\11sehr seltene\11POKéMON!\12Darf ich bitte mal\
eines sehen?",
  ["4c:5dee"] = "ROUTE 42\12TEAK CITY -\
MAHAGONIA CITY",
  ["4c:5e16"] = "KESSELBERG\12WASSERFALL-HÖHLE\
Voraus",
  ["4c:5e3a"] = "KESSELBERG\12WASSERFALL-HÖHLE\
Voraus",
  ["4c:5e5e"] = "ROUTE 42\12TEAK CITY -\
MAHAGONIA CITY",
  ["4d:418e"] = "Ich liebe POKéMON!\12Deshalb habe ich\
angefangen, POKé-\12MON zu sammeln und\
damit werde ich\11auch nicht mehr\11aufhören!",
  ["4d:41d8"] = "Wie konntest du\
mir das antun?",
  ["4d:41f6"] = "Du fragst, was ich\
außer POKéMON\11noch mag?\12MARGIT vom Radio!\
Die ist bestimmt\11süß!",
  ["4d:423d"] = "Heh! Hast du\
seltene POKéMON?",
  ["4d:425e"] = "Meine armen POKé-\
MON-Lieblinge!",
  ["4d:427d"] = "Ich wäre schon\
froh, wenn ich nur\11ein einziges\11seltenes POKéMON\11hätte.",
  ["4d:42aa"] = "Stell dir mal vor!\12So ein {RIVAL}\
hat sich über\11mein POKéMON\11lustig gemacht!\12Unverschämtheit!\
Mein POKéMON\11ist toll!",
  ["4d:42fa"] = "Mein NIDOKING hat\
sich wacker ge-\11schlagen!",
  ["4d:431c"] = "Für die meisten\
Menschen ist es\12ganz natürlich,\
unterschiedliche\11Arten von POKéMON\11zu mögen.\12Es geht bei\
POKéMON nicht\11darum, das\11Stärkste von allen\11zu haben.\11",
  ["4d:4385"] = "Ich bin gerade\
ziemlich am Boden.\12Vielleicht liegt\
das an dem Item,\11das ich benutze.\12Kämpfen wir! Das\
hebt vielleicht\11meine Laune!",
  ["4d:43d4"] = "Ich habe verloren,\
aber ich fühle\11mich trotzdem\11besser.",
  ["4d:43f7"] = "KURTs KÖDERBALL\
eignet sich am\12besten, um POKé-\
MON, die an der\11Angel hängen,\11einzufangen.\12Er ist viel\
effektiver als\11der HYPERBALL.",
  ["4d:4459"] = "Man kann so viel\
unternehmen mit\11seinen POKéMON -\11das macht\11unheimlich viel\11Spaß!",
  ["4d:4489"] = "Verlieren macht\
überhaupt keinen\11Spaß…",
  ["4d:44a2"] = "Was geht da vor\
sich am\11SEE DES ZORNS?\12Wir wollen dort\
zelten.",
  ["4d:44e5"] = "Gehst du auch zum\
SEE DES ZORNS?\12Spielen wir ein\
bisschen!",
  ["4d:4528"] = "Ich habe zu lange\
gespielt!",
  ["4d:453c"] = "Ich mache ein\
Picknick mit\11meinen POKéMON.\12Setz dich doch zu\
uns.",
  ["4d:456f"] = "ROUTE 43\12SEE DES ZORNS -\
MAHAGONIA CITY",
  ["4d:4596"] = "ROUTE 43\12SEE DES ZORNS -\
MAHAGONIA CITY",
  ["4d:45bd"] = "TIPPS für TRAINER\12Alle POKéMON haben\
Vor- und Nach-\12teile. Das hängt\
ganz davon ab,\11welchem Element\11sie angehören.\12Sind zwei POKéMON\
unterschiedlicher\12Elemente, kann\
sogar ein POKéMON\11verlieren, das\11einen höheren\11Level hat.\12Finde heraus,\
welche Elemente\12effektiv oder\
ineffektiv gegen\11deine POKéMON\11sind.",
  ["4d:488b"] = "Aah! Wegen dir\
habe ich ein\11QUAPSEL verloren!\12Was wirst du\
deswegen unter-\11nehmen?",
  ["4d:48d1"] = "Vergiss es\
einfach.",
  ["4d:48e8"] = "Dieses QUAPSEL,\
das geflohen ist…\11Das war riesig.\12Ich könnte\
schwören, dass es\0115 Meter lang war!",
  ["4d:4937"] = "Ich angle so\
lange, bis ich\11nicht mehr kann.\12Und ich kämpfe\
bis zum Umfallen.\12So gehe ich\
auch mit meinen\11POKéMON um.",
  ["4d:4995"] = "Hmm… \
Das ist nicht\12richtig.",
  ["4d:49af"] = "Das sind 100 Siege\
und 101 verlorene\11Kämpfe.\12Ich kämpfe jetzt\
eine Weile lang\11nicht mehr.",
  ["4d:49ef"] = "Hast du schon von\
dem legendären\11Vogel-POKéMON\11gehört?",
  ["4d:4a1b"] = "Puh! Du bist nicht\
von schlechten\11Eltern.",
  ["4d:4a33"] = "ARKTOS, ZAPDOS\
und LAVADOS sind\12die drei\
legendären Vogel-\11POKéMON.\12Es gibt aber auch\
andere legendäre\11Vogel-POKéMON.",
  ["4d:4aa7"] = "Ich gewinne\
hundertprozentig!",
  ["4d:4ac0"] = "Aah… Das ist\
eine schockierende\11Niederlage…",
  ["4d:4adf"] = "Es ist wichtig,\
von sich selbst\11überzeugt zu sein.",
  ["4d:4b0f"] = "Ich tue alles,\
um seltene POKéMON\11in die Finger zu\11bekommen!",
  ["4d:4b3e"] = "Ach, deine POKéMON\
sind ja niedlich.",
  ["4d:4b61"] = "Ein POKéMON,\
dessen Färbung\12sich von der\
normalen unter-\11scheidet, ist\11wertvoller.\12Was? Willst du\
behaupten, das sei\11nicht wahr?",
  ["4d:4bbf"] = "Ich kann sehen,\
dass du ein guter\11Trainer bist.\12Ich kenne mich gut\
mit POKéMON aus\11und ich sehe, dass\11du das auch tust.",
  ["4d:4c26"] = "Puh! Das war ja\
der totale\11Reinfall!",
  ["4d:4c49"] = "Wow! Du hast ja\
viele ORDEN!\12Kein Wunder, dass\
du so stark bist.\12Ich frage mich,\
ob JENS, der\12ARENALEITER von\
TEAK CITY, noch\11immer trainiert?\12Er hat mich\
wirklich fertig\11gemacht.",
  ["4d:4cd0"] = "Du siehst sehr\
stark aus.\12Gute Trainer\
suchen instinktiv\11nach starken\11Gegnern.",
  ["4d:4d14"] = "Nein! So geht das\
auf gar keinen\11Fall.",
  ["4d:4d30"] = "Mit den Kämpfen\
steigen unsere\11Erfahrungen und\11wir werden besser.\12Ich habe viele\
Kämpfe ausge-\11tragen, um das zu\11werden, was ich\11heute bin - ein\11Profi.",
  ["4d:4d96"] = "ROUTE 44\
EISPFAD VORAUS",
  ["4d:4daf"] = "ROUTE 44\12MAHAGONIA CITY -\
EBENHOLZ CITY",
  ["4d:4feb"] = "Sei auf alles\
vorbereitet!\12Lass mich mal\
sehen, wie gut\11deine POKéMON\11trainiert sind!",
  ["4d:5039"] = "Oh, ich habe\
verloren!",
  ["4d:504b"] = "Ich gehe zum\
EISPFAD bei\12EBENHOLZ CITY,\
um etwas mehr\11zu trainieren.",
  ["4d:5087"] = "He! Du hast Mumm\
in den Knochen!\11Aber weißt du was?\12Wenn es um echte\
Courage geht, bin\11ich der Mann!",
  ["4d:50dc"] = "Meine POKéMON\
waren leider nicht\11couragiert genug!",
  ["4d:50fb"] = "Mensch, wie ich\
diese KP-PLUS\11liebe! Mm, lecker!\12Ich trinke immer\
die von meinen\11POKéMON!\12Ich kann nichts\
dagegen tun!",
  ["4d:5147"] = "Meine POKéMON\
sind voller\11Energie!",
  ["4d:5162"] = "Ojemine! Ich bin\
der große\11Verlierer!",
  ["4d:517e"] = "Ich bin eher\
langsam, was das\11Denken betrifft,\11weißt du?\12Deswegen setze ich\
alles auf Kraft.",
  ["4d:51c4"] = "Warum ich auf\
Berge klettere?\12Weil es sie\
gibt.\12Warum ich\
POKéMON trainiere?\12Weil es sie\
gibt!",
  ["4d:5220"] = "Niederlagen…\
Die gibt es auch!",
  ["4d:523b"] = "POKéMON zu\
entdecken, war das\12Beste, was mir\
passieren konnte.",
  ["4d:5276"] = "Ich habe hier\
ganz allein\11trainiert.\12Sieh die Früchte\
meiner Arbeit!",
  ["4d:52b1"] = "Aahh!",
  ["4d:52bc"] = "Das schreit nach\
extremen\11Maßnahmen.\12Ich ziehe mich\
zurück in die\11Berge, um mich im\11Alleinsein zu\11üben.",
  ["4d:530e"] = "Was hältst du vom\
POKéMON-Training?",
  ["4d:5339"] = "Du verdienst meine\
ganze Hochachtung.",
  ["4d:5350"] = "Wie ich sehe,\
ziehst du deine\11POKéMON mit\11Sorgfalt auf.\12Die Gemeinschaft,\
die du bildest,\11wird dich in\11gefährlichen\11Situationen\11retten.",
  ["4d:53b2"] = "Welche Kampf-\
technik verwendest\11du?\12Setze starke\
Attacken nicht\11völlig willkürlich\11ein!",
  ["4d:5405"] = "Gut. Dann habe ich\
eben verloren.",
  ["4d:5414"] = "Ich mag keine\
übermäßig starken\11Attacken.\12Ich will gewinnen,\
aber ich möchte\11dabei keine POKé-\11MON verletzen.",
  ["4d:5490"] = "ROUTE 45\
BERGWEG VORAUS",
  ["4d:561f"] = "Also gut! Ich\
zeige dir die\11Kraft von Berg-\11POKéMON!",
  ["4d:5652"] = "Gnade! Ich kenne\
jetzt deine Kraft!",
  ["4d:5674"] = "Es ist vorbei.\
Auch gut. Wir\11WANDERER sind eben\11so.",
  ["4d:56a5"] = "Ich trainiere auch\
POKéMON!\12Möchtest du gegen\
mich kämpfen?",
  ["4d:56d6"] = "Wah…?",
  ["4d:56dd"] = "Ich habe mein\
Bestes gegeben und\11das reichte leider\11nicht.\12Ich gebe ganz\
offen zu - ich\11habe verloren.",
  ["4d:571b"] = "Ich trainiere auch\
POKéMON!\12Kämpfen wir!",
  ["4d:573b"] = "So ein Mist!",
  ["4d:5749"] = "Ich habe schon in\
vielen ARENEN\12gekämpft, aber die\
in DUKATIA CITY\11hat mir am besten\11gefallen.\12Sie ist voller\
schöner Blumen!",
  ["4d:57aa"] = "ROUTE 46\
BERGWEG VORAUS",
  ["4d:588a"] = "Warst du schon in\
der PKMN-ARENA von\11MARMORIA CITY?\12Der LEITER dort\
verwendet Gestein-\11POKéMON.",
  ["4d:58c8"] = "Nachts spielen\
PIEPIS beim\11MONDBERG.\12Aber nicht in\
jeder Nacht.",
  ["4d:590e"] = "Oh, du bist den\
ganzen Weg \11von JOHTO bis\11hierher gekommen?\12Das weckt\
Erinnerungen. Als\12ich noch jung war,\
habe ich in JOHTO\11oft trainiert.\12Du erinnerst\
mich an mich\12selbst als junger\
Mann.\12Hier. Ich möchte,\
dass du dieses\11Item, das ich in\11JOHTO fand,\11behältst.",
  ["4d:59f2"] = "Neue und un-\
bekannte Orte zu\11erforschen und\11fremde Menschen\11kennenzulernen…\12Das ist das Schöne\
am Reisen.",
  ["4d:5a47"] = "MARMORIA CITY\
Eine Steingraue\11Stadt",
  ["4d:5a66"] = "PKMN-ARENA von\
MARMORIA CITY\11LEITUNG: ROCKO\12Der Felsenharte\
POKéMON-Trainer",
  ["4d:5aa6"] = "Hier ist eine\
Nachricht…\12MARMORIAS MUSEUM\
DER WISSENSCHAFT\11ist wegen Reno-\11vierungsarbeiten\11geschlossen…",
  ["4d:5af1"] = "Hier ist eine\
Nachricht…\12SOUVENIRLADEN AM\
MONDBERG\11Jetzt geöffnet!",
  ["4d:5b24"] = "Willkommen in\
MARMORIA CITY!",
  ["4d:5c1a"] = "Meine Käfer-POKé-\
MON sind zäh. Du\11wirst verlieren!",
  ["4d:5c43"] = "Ich wurde\
vermöbelt…",
  ["4d:5c53"] = "Ich werde mir\
stärkere Käfer-\11POKéMON suchen.",
  ["4d:5c7c"] = "Wenn du mit Shorts\
in hohem Gras\12läufst, bekommst\
du dann Schrammen\11an deinen Beinen?",
  ["4d:5cc2"] = "Au, Aua, Aua!",
  ["4d:5cd5"] = "Sie stechen,\
wenn du ein Bad\11nimmst.",
  ["4d:5d00"] = "Warum mögen\
Mädchen keine\11Käfer-POKéMON?",
  ["4d:5d1f"] = "Sinnlos!",
  ["4d:5d29"] = "Käfer-POKéMON\
zischen wie\12Plüschtiere, wenn\
du sie auf den\11Bauch drückst.\12Ich mag das\
Gefühl!",
  ["4d:5d80"] = "ROUTE 2\12VERTANIA CITY -\
MARMORIA CITY",
  ["4d:5da5"] = "DIGDAs HÖHLE",
  ["4e:4062"] = "He, Kleiner! Ich\
hatte gerade einen\12doppelten Espresso\
und ich bin\11total aufgedreht!\12Ich brauche jetzt\
jemandem zum\11Reden und zwar\11dich!\12Man sieht es mir\
jetzt vielleicht\12nicht mehr an,\
aber ich war ein\11Experte im Fangen\11von POKéMON.\12Glaubst du mir?",
  ["4e:412c"] = "Also gut. Ja, ich\
war wirklich etwas\12Besonderes, das\
kann ich dir\11sagen!",
  ["4e:4174"] = "Was? Du kleiner\
Frechdachs!\12Wenn ich etwas\
jünger wäre, würde\12ich dir schon das\
eine oder andere\11zeigen! Grummel.",
  ["4e:41ce"] = "Bis vor kurzem\
gab es in dieser\11PKMN-ARENA\11keinen LEITER.\12Ein junger Mann\
aus ALABASTIA ist\12hier der LEITER\
geworden, aber er\11ist oft unterwegs.",
  ["4e:423b"] = "Wirst du den\
ARENALEITER\11herausfordern?\12Viel Glück! Du\
wirst es brauchen.",
  ["4e:4281"] = "Gähn!\12Ich bin wohl in\
der Sonne\11eingeschlafen.\12… Ich hatte diesen\
Traum von einem\12TRAUMATO, das\
meinen Traum\12fressen wollte.\
Das ist doch\12merkwürdig,\
nicht wahr?\12Nanu!\
Was ist das?\12Wo ist diese TM\
hergekommen?\12Unheimlich!\
Hier, du kannst\11die TM behalten.",
  ["4e:4343"] = "TM42 enthält\
TRAUMFRESSER…\12…Zzzzz…",
  ["4e:4367"] = "Ich habe gehört,\
dass man viele\12Items im VERTANIA-\
WALD findet.",
  ["4e:43ac"] = "VERTANIA CITY\12Das Immergrüne\
Paradies",
  ["4e:43d8"] = "PKMN-ARENA von\
VERTANIA CITY\11LEITUNG: …\12Der Rest des Tex-\
tes ist unlesbar…",
  ["4e:441d"] = "Willkommen in\
VERTANIA CITY,\12dem Tor zum\
INDIGO PLATEAU",
  ["4e:4456"] = "TRAINER-HAUS\12Der Club, in dem\
Top-Trainer\11kämpfen",
  ["4e:44fc"] = "POKéMON LIGA\12SIEGESSTRASSE\
EINGANG",
  ["4e:455e"] = "Wenn sich zwei\
Trainer begegnen,\11wollen sie sofort\11kämpfen.",
  ["4e:4592"] = "Argh… Ich\
habe erneut\11verloren…",
  ["4e:45b2"] = "Es ist ein\
ungeschriebenes\12Gesetz, dass Trai-\
ner kämpfen, wenn\11sie sich begegnen.",
  ["4e:45f0"] = "Du da!\
Willst du kämpfen?",
  ["4e:460c"] = "Versagt und weg…",
  ["4e:461b"] = "Du bist stark.\12Du hast offenbar\
hart trainiert.",
  ["4e:4650"] = "ROUTE 1\12ALABASTIA -\
VERTANIA CITY",
  ["4e:46c2"] = "Ich trainiere auch\
POKéMON. Sie\12dienen mir als\
Leibwächter.",
  ["4e:46fb"] = "Die Technik ist\
unglaublich!\12Du kannst jetzt\
POKéMON durch die\11Zeit senden, wie\11E-Mails.",
  ["4e:4746"] = "ALABASTIA\12Eine Stätte des\
Friedens und der\11Reinheit",
  ["4e:4778"] = "HAUS von ROT",
  ["4e:4785"] = "PROF. EICH\
POKéMON LABOR",
  ["4e:479c"] = "HAUS von BLAU",
  ["4e:482b"] = "Mach weiter so!",
  ["4e:4847"] = "Gluck…",
  ["4e:484e"] = "Dieser arrogante\
Typ war beim\11Vulkan auf der\11ZINNOBERINSEL.",
  ["4e:487b"] = "Hi!\12Ich wollte mich\
gerade mit Sonnen-\11milch eincremen.",
  ["4e:48ab"] = "Ich habe Angst vor\
einem Sonnenbrand…",
  ["4e:48c6"] = "Ich muss mich\
vor Hautreizungen\11in Acht nehmen.",
  ["4e:48fc"] = "Angeln langweilt\
mich. Lass uns\11kämpfen!",
  ["4e:4921"] = "Riesenpleite…",
  ["4e:4931"] = "Ich widme mich\
wieder dem Angeln…",
  ["4e:49a7"] = "Wer bist du?\12Na, du bist\
augenscheinlich\11ein Trainer…\12Ich heiße BLAU.\12Ich war einmal ein\
CHAMP, wenn auch\12nur für kurze\
Zeit…\12Dieser nervige ROT\
hat mich ganz\12schön fertig-\
gemacht…\12Wie dem auch sei,\
was willst du?\12Willst du gegen\
mich kämpfen?\12…Ich sage es nur\
ungern, aber ich\12habe gar keine\
Lust zu Kämpfen.\12Sieh dich gut\
um…\12Ein Vulkan bricht\
aus und vernichtet\12auf einen Schlag\
eine ganze Stadt.\12Wir werden weiter-\
hin mit unseren\12POKéMON siegen\
oder verlieren.\12Aber wenn sich die\
Natur erhebt, ist\11alles im Nu dahin.\12…\12So ist das\
eben…\12Trotz allem bin\
ich immer noch ein\11Trainer.\12Wenn ich einen\
starken Gegner\11treffe, möchte ich\11gegen ihn kämpfen.\12Wenn du gegen mich\
kämpfen möchtest,\12dann besuche die\
PKMN-ARENA in\11VERTANIA CITY.\12Dort werde ich\
mich deiner\11annehmen.",
  ["4e:4c48"] = "Hier ist eine\
Nachricht…\12Die PKMN-ARENA der\
ZINNOBERINSEL\12wurde auf die\
SEESCHAUMINSELN\11verlegt.\12PYRO",
  ["4e:4c97"] = "ZINNOBERINSEL\12Die Feurige Stadt\
Brennender\11Begierde",
  ["4e:4d3d"] = "Im Wasser fühle\
ich mich so\11leicht.",
  ["4e:4d5f"] = "Oh, nein!",
  ["4e:4d68"] = "Beim Schwimmen\
wird der gesamte\12Körper trainiert.\
Schwimmen ist\11gesund.",
  ["4e:4da5"] = "Du besitzt eine\
umwerfende Anzahl\12ARENA-ORDEN. Lass\
uns kämpfen!",
  ["4e:4de5"] = "Nein!",
  ["4e:4dea"] = "SURFER ist nicht\
mehr die einzige\11VM, die du im\11Wasser einsetzen\11kannst.",
  ["4e:4e20"] = "Ich denke es ist\
unmöglich, den\12ganzen Weg nach\
JOHTO zu\11schwimmen.",
  ["4e:4e58"] = "Yippie!",
  ["4e:4e60"] = "Ich schwimme auch\
in Teichen und\11Flüssen.",
  ["4e:4e97"] = "Was steht auf\
diesem Schild?\12ARENA der\
ZINNOBERINSEL\12LEITUNG: PYRO",
  ["4e:4fa6"] = "Warst du schon\
einmal nachts im\11Meer?",
  ["4e:4fd8"] = "Gulp…",
  ["4e:4fdf"] = "Nachts wird das\
Meer schwarz. Es\12scheint, als\
wollte es dich\11verschlingen.",
  ["4e:5025"] = "Uff, uff…\
Nur… noch… ein\12kleines Stück… bis\
… FUCHSANIA CITY…",
  ["4e:5058"] = "Ich ertrinke!",
  ["4e:5066"] = "Ich… bat meine\
Freundin nach\11FUCHSANIA CITY…\11zu schwimmen…",
  ["4e:509a"] = "Schwächlinge\
wiedern mich an!",
  ["4e:50b9"] = "Ich schlage dich\
beim Schwimmen…",
  ["4e:50d8"] = "Es ist nur eine\
kurze Distanz\12zwischen FUCHSANIA\
CITY und den\11SEESCHAUMINSELN…\12Uah, mein Freund\
ist so groß und\12dennoch ein\
Schwächling!",
  ["4e:5144"] = "Schwimmen? Ich bin\
ein miserabler\11Schwimmer.\12Ich plansche\
lieber in dieser\11Riesenpfütze.",
  ["4e:5191"] = "Ich dachte, ich\
könnte gewinnen.",
  ["4e:51a9"] = "Schwimmen mag\
nicht meine Stärke\11sein, dennoch\11liebe ich das\11Meer.",
  ["4e:51da"] = "Tut mir Leid.\
Die Strasse ist\11aufgrund von Bau-\11arbeiten gesperrt.\12Wenn du zu der\
ZINNOBERINSEL\12möchtest, gehst\
du von ALABASTIA\11gen Süden.",
  ["4e:524f"] = "Ich bin total\
verschwitzt. Es\11ist Zeit zum\11schwimmen.",
  ["4e:5270"] = "Es würde zu lange\
dauern, diesen\11Felsen zu bewegen…",
  ["4e:52a8"] = "Die Bauarbeiten\
sind beendet.\12Jetzt kann ich\
wieder angeln.",
  ["4e:52e7"] = "ROUTE 19\12FUCHSANIA CITY -\
SEESCHAUMINSELN",
  ["4e:5310"] = "Sei auf der Hut,\
wenn du zu den\11SEESCHAUMINSELN\11schwimmst.\12ORDNUNGSAMT\
FUCHSANIA CITY",
  ["4e:53eb"] = "Einer der TOP VIER\
war früher einmal\12der ARENALEITER in\
FUCHSANIA CITY.",
  ["4e:5429"] = "KOGAs Tochter ist\
jetzt ARENA-\12LEITERIN, nachdem\
ihr Vater den TOP\12VIER beigetreten\
ist.",
  ["4e:5479"] = "Schade, dass die\
SAFARI-ZONE\12geschlossen ist…\
Das ist schließ-\12lich FUCHSANIAs\
Hauptattraktion.",
  ["4e:54c8"] = "FUCHSANIA CITY\12Sieh nur! Die\
Rosarote\11Lieblichkeit!",
  ["4e:54f0"] = "PKMN-ARENA von\
FUCHSANIA CITY\11LEITUNG: JANINA\12Die Giftige\
Ninja-Meisterin",
  ["4e:5531"] = "Hier ist eine\
Nachricht…\12Bis auf weiteres\
bleibt das BÜRO\12der SAFARI-ZONE\
geschlossen.",
  ["4e:557b"] = "SAFARI-ZONE\
HAUS DES WÄRTERS",
  ["4e:5596"] = "Der WÄRTER ist\
verreist. Deshalb\12ist die SAFARI-\
ZONE\11geschlossen.",
  ["4e:55dd"] = "Verunreinigung des\
Parks ist\11verboten.\12Hinterlasse\
bitte keinen\11Abfall.",
  ["4e:56d3"] = "Wenn du nach\
POKéMON suchst,\12musst du ins\
hohe Gras gehen.",
  ["4e:5713"] = "Yippi!",
  ["4e:571c"] = "Da du so stark\
bist, muss es\11Spaß machen, gegen\11dich zu kämpfen.",
  ["4e:574e"] = "Der RADWEG ist\
eine schnelle\11Abkürzung nach\11PRISMANIA CITY.",
  ["4e:577c"] = "…Uff!",
  ["4e:5784"] = "Wenn du kein\
FAHRRAD hast,\12darfst du die\
Abkürzung nicht\11benutzen.",
  ["4e:57c8"] = "ROUTE 18\12PRISMANIA CITY -\
FUCHSANIA CITY",
  ["4e:587f"] = "Heh, du! Bist\
du aus JOHTO?",
  ["4e:58a1"] = "Boah, du legst\
aber los!",
  ["4e:58b2"] = "Wer't nicht frech,\
du Null aus JOHTO!",
  ["4e:58d3"] = "Wow! Das ist ein\
tolles FAHRRAD!",
  ["4e:58ef"] = "Aber du siehst\
nicht nur cool\11aus…",
  ["4e:590d"] = "Ich sehe zwar cool\
aus, bin aber\11schwach, also bin\11ich nicht wirklich\11cool.\12Ich muss härter\
trainieren…",
  ["4e:5957"] = "Hey! Wie wäre\
es mit einem\11Schnellkampf?",
  ["4e:597a"] = "Ups! Du hast\
ganz schön Kraft!",
  ["4e:599c"] = "Freihändig fahren\
gilt als cool\11auf dem RADWEG.",
  ["4e:59d3"] = "Wir sind die\
furchtlosen Helden\11des RADWEGS!",
  ["4e:59f1"] = "Argh! Bumm und\
krach!",
  ["4e:5a0a"] = "Durch rücksichts-\
loses Fahren\11passieren viele\11Unfälle! Bleib\11locker!",
  ["4e:5aa6"] = "RADWEG\12Es geht den ganzen\
Weg nur bergab!",
  ["4e:5b3a"] = "Dieses QUAPPO ist\
mein Partner.\12Ich frage mich, ob\
es sich wohl je in\11ein Frosch-POKéMON\11weiterentwickelt.",
  ["4e:5b88"] = "QUAPPO: Quaak!",
  ["4e:5b9b"] = "Ich habe schon\
wieder bei dem\12Spielautomaten\
verloren…\12Wir Mädchen\
spielen auch an\12den Automaten.\
Versuche es doch\11selbst mal.",
  ["4e:5c00"] = "Hier sind vor\
kurzem SLEIMAS\11aufgetaucht.\12Siehst du den\
Teich da vor dem\12Haus? Dort leben\
jetzt SLEIMAS.\12Wo kommen sie her?\
Das ist ein\11echtes Problem…",
  ["4e:5c99"] = "Hihihi! Diese\
PKMN-ARENA ist\12toll! Sie ist nur\
für Mädchen!",
  ["4e:5cd2"] = "Soll ich dir ein\
Geheimnis\11erzählen?\12PRISMANIA-VILLA\
hat eine geheime\11Hintertür.",
  ["4e:5d12"] = "Im Restaurant wird\
ein Wettessen ab-\11gehalten.\12Ihnen beim Essen\
nur zuzusehen,\11bringt mich schon\11zum Platzen…",
  ["4e:5d7a"] = "Das EINKAUFS-\
ZENTRUM in\12PRISMANIA CITY\
bietet die größte\12und beste Auswahl\
an Artikeln.\12Was du da nicht\
findest, wirst\12du nirgends\
finden.\12Herrje… Ich klinge\
wie ein Vertreter.",
  ["4e:5e18"] = "Mir wird ganz\
schwindelig, wenn\12ich beim Laufen\
auf den Boden\11gucke.",
  ["4e:5e52"] = "PRISMANIA CITY\12Die Stadt der\
Regenbogen-Träume",
  ["4e:5e7b"] = "PKMN-ARENA von\
PRISMANIA CITY\12LEITUNG:\
ERIKA\12Die Prinzessin mit\
Herz für die Natur",
  ["4e:5ebb"] = "Im EINKAUFSZENTRUM\
von PRISMANIA CITY\11Findest du Alles,\11was dein Herz\11Begehrt!",
  ["4e:5ee6"] = "PRISMANIA-VILLA",
  ["4e:5ef7"] = "Der Spielplatz\
Für Jedermann --\12SPIELHALLE von\
PRISMANIA",
  ["4e:5f2a"] = "TIPPS für TRAINER\12Der MEGABLOCK\
schützt POKéMON\12vor SPEZIAL-\
Attacken wie z.B.\11Feuer und Wasser.\12Hol dir deine\
Items im EINKAUFS-\11ZENTRUM von\11PRISMANIA CITY!",
  ["4e:6081"] = "Was steht auf dem\
Flugblatt?\12… Ruppige Trainer\
tragen auf dem\12TUNNELPFAD Kämpfe\
aus.\12Da sich die\
Beschwerden der\11Anwohner häuften,\11wurde der\11TUNNELPFAD auf\11unbestimmte Zeit\11geschlossen.\12ORDNUNGSAMT\
PRISMANIA CITY",
  ["4e:614f"] = "Es ist verriegelt…",
  ["4f:407f"] = "Hast du etwas\
vergessen?",
  ["4f:409d"] = "Uah!",
  ["4f:40a6"] = "Ehe ich Lehrer\
wurde, vergaß ich\12immer eine Menge\
Dinge.",
  ["4f:40e4"] = "Bei schönem Wetter\
würden die Kinder\12lieber im Schulhof\
spielen, als in\12den Klassenzimmern\
zu lernen.",
  ["4f:414c"] = "Ich wollte nicht\
verlieren…",
  ["4f:4163"] = "Lernen ist sehr\
wichtig, aber\11Bewegung ist\11genauso essen-\11tiell.",
  ["4f:419c"] = "Warte! Ich muss\
meine Mutter\11anrufen.",
  ["4f:41be"] = "Tut mir Leid,\
Mutter!\11Ich wurde besiegt!",
  ["4f:41d9"] = "Meine Mutter macht\
sich immer große\12Sorgen um mich.\
Ständig muss ich\11sie anrufen.",
  ["4f:421d"] = "Lass uns kämpfen.\
Ich werde nicht\11verlieren!",
  ["4f:4238"] = "Ich hätte meine\
Hausaufgaben\11machen sollen!",
  ["4f:4255"] = "Sayonara! Das habe\
ich in meinem\11Japanischkurs\11gelernt.",
  ["4f:428a"] = "Wir machen einen\
Ausflug zum RADIO-\12TURM in LAVANDIA,\
um dort etwas in\11Sozialkunde zu\11lernen.",
  ["4f:42cc"] = "Du bist unheimlich\
stark!",
  ["4f:42e3"] = "Ich bin müde vom\
Laufen. Ich muss\11eine Pause machen.",
  ["4f:4313"] = "Sport ist mein\
Lieblingsfach!",
  ["4f:432e"] = "Oh, nein!\
Wie konnte ich nur\12verlieren?",
  ["4f:4349"] = "Wenn POKéMON ein\
Unterrichtsfach\11wäre, dann wäre\11ich bestimmt der\11Beste!",
  ["4f:437c"] = "Route 15\12FUCHSANIA CITY -\
LAVANDIA",
  ["4f:4458"] = "Eines kann ich dir\
sagen! Es war\12harte Arbeit, mei-\
ne prämierten\11POKéMON zu fangen.",
  ["4f:4495"] = "Uaaaah!",
  ["4f:449e"] = "SCHIGGY, GLUMANDA\
und BISASAM…\12Ich denke, das ist\
ein ausgeglichenes\11Team.",
  ["4f:44e8"] = "Ich träume davon,\
mit meinen ge-\11liebten Vogel-\11POKéMON zu\11fliegen.",
  ["4f:4517"] = "Ich kann träumen,\
aber ich kann\11nicht fliegen…",
  ["4f:453a"] = "Du hast POKéMON,\
welche die VM\12FLIEGEN kennen?\
Ich beneide dich.",
  ["4f:457a"] = "Bist du gegen alle\
ARENA-Trainer\11angetreten?",
  ["4f:45a0"] = "Oh, wow! Zu\
stark für mich!",
  ["4f:45bd"] = "Besitzt du die\
ORDEN von KANTO,\12bist du im\
Vorteil, wenn du\11via Link-Kabel\11gegen einen Freund\11antrittst.",
  ["4f:46a7"] = "Verbeuge dich vor\
meinen königlichen\11POKéMON!",
  ["4f:46c7"] = "Wie… Wie kannst\
du es wagen, die\11Monarchie zu\11verspotten?",
  ["4f:46e8"] = "Möchte nicht jeder\
eines Tages einmal\11König sein?",
  ["4f:4714"] = "Hihi! Möchtest du\
gegen mein\11PIKACHU-Team\11antreten?",
  ["4f:4747"] = "PI-PIKACHU!",
  ["4f:4754"] = "Es scheint, dass\
du viele POKéMON\12hast, aber PIKACHU\
ist immer noch das\11Beste.",
  ["4f:4796"] = "Agilität ist die\
wichtigste Eigen-\11schaft von Vogel-\11POKéMON.",
  ["4f:47c2"] = "Du hast mich\
aufgrund deiner\11Schnelligkeit\11besiegt…",
  ["4f:47e0"] = "Deine POKéMON sind\
in der Tat sehr\11gut trainiert.",
  ["4f:4809"] = "Schau dir meine\
POKéMON an. Sieh\12ihre Farben und\
ihr Gefieder.",
  ["4f:484e"] = "Verflixt!\
Nicht gut genug!",
  ["4f:4867"] = "Wenn du deine\
POKéMON pflegst,\11sind sie fröhlich.",
  ["4f:488b"] = "Ich sollte zum\
FELSTUNNEL gehen\11und mir ein ONIX\11fangen.",
  ["4f:48be"] = "Ich habe verloren…",
  ["4f:48c7"] = "Es scheint, als\
würden sich geo-\11logische Gegeben-\11heiten nicht\11ändern.\12Aber sie ändern\
sich; langsam,\11ganz langsam.",
  ["4f:4921"] = "TIPPS für TRAINER\12Schau! Hier, an\
der linken Seite\11des Pfostens.",
  ["4f:4960"] = "ROUTE 13\12NÖRDLICH ZUR\
SCHWEIGEBRÜCKE",
  ["4f:4982"] = "Nördlich nach\
LAVANDIA\12Westlich nach\
FUCHSANIA CITY",
  ["4f:4a69"] = "Geduld ist das\
Zauberwort. Das\11gilt fürs Angeln\11und für POKéMON.",
  ["4f:4a9a"] = "Guaah!",
  ["4f:4aa3"] = "Ich bin zu unge-\
duldig für das\11Angeln…",
  ["4f:4ac2"] = "Wenn ich beim\
Angeln Radio hören\11kann, bin ich\11glücklich.",
  ["4f:4b0b"] = "Das blöde Radio\
beunruhigt mich!",
  ["4f:4b2b"] = "Kennst du schon\
die Radiosender\12aus KANTO? Es gibt\
viele hier.",
  ["4f:4b74"] = "Was ist in unserem\
alltäglichen Leben\11am wichtigsten?",
  ["4f:4ba5"] = "Die Antwort gibt\
es demnächst!",
  ["4f:4bc4"] = "Meiner Meinung\
nach ist Strom\12das Wichtigste\
in unserem Leben.\12Wenn dem nicht so\
wäre, hätten die\12Leute nicht so\
einen Aufstand\12fabriziert, als\
das KRAFTWERK\11außer Betrieb war.",
  ["4f:4c6b"] = "Erinnerst du dich?",
  ["4f:4c7d"] = "Du erinnerst dich?",
  ["4f:4c8f"] = "Das Reißen an der\
ANGEL, wenn du\12ein POKéMON\
fangen möchtest…\12Das ist das\
Schönste für einen\11Angler wie mich.",
  ["4f:4cf7"] = "ROUTE 12\
NORDEN: LAVANDIA",
  ["4f:4d18"] = "ANGELPLATZ",
  ["4f:4de8"] = "Bei POKéMON wird\
nicht gemogelt.\12Immer fair\
spielen.",
  ["4f:4e25"] = "Huch? Wie konnte\
das passieren?",
  ["4f:4e40"] = "Ich habe immer\
fair und ehrenhaft\11gekämpft.\12Ich habe es noch\
nie bedauert.",
  ["4f:4e81"] = "Es juckt und\
sticht, wenn ich\12mit meinen Shorts\
durchs Gras laufe.",
  ["4f:4ebf"] = "Aiyaaah!\
Ich bekam Dresche!",
  ["4f:4ed8"] = "Im Gras werde ich\
mehr POKéMON\11fangen.",
  ["4f:4f03"] = "…",
  ["4f:4f06"] = "…",
  ["4f:4f09"] = "…\12Ich verlor, als\
ich meine Augen\11schloss…",
  ["4f:4f2f"] = "Ich kann es sehen…\12Ich kann alles\
über dich sehen…",
  ["4f:4f5b"] = "Deine Stärke\
konnte ich nicht\11sehen…",
  ["4f:4f7a"] = "Deine Überzeugung\
ist stark…\12Du bist stark,\
weil du an deine\11POKéMON glaubst.",
  ["4f:4fc6"] = "ROUTE 11",
  ["4f:5048"] = "Ein recht beein-\
druckendes\11Gebäude, nicht?\12Das ist der RADIO-\
TURM von KANTO.",
  ["4f:5080"] = "In KANTO werden\
viele, gute Radio-\11programme\11gesendet.",
  ["4f:50a2"] = "Die Leute kommen\
von überall her,\12um den Seelen\
dahingegangener\11POKéMON Respekt\11zu erweisen.",
  ["4f:50f2"] = "Mit einer POKé-\
FLÖTE weckst du\11schlafende\11POKéMON.\12Jeder Trainer muss\
das wissen!",
  ["4f:513d"] = "LAVANDIA\12Die Liebliche\
Lilafarbene Stadt",
  ["4f:5162"] = "KANTO RADIO-\
STATION\12Deine Lieblings-\
programme zu jeder\11Tages- und Nacht-\11zeit!",
  ["4f:51a7"] = "WAISENHAUS für\
POKéMON\11von LAVANDIA",
  ["4f:51c6"] = "RUHESTÄTTE\12Mögen die Seelen\
der POKéMON hier\11in Frieden Ruhen",
  ["4f:5308"] = "Der HAFEN von\
ORANIA CITY ist\11das Tor KANTOs\11zum Meer.\12Hier legen Luxus-\
dampfer aus aller\11Welt an.",
  ["4f:5362"] = "Mein POKéMON\
ebnet das Land\11für ein Bauwerk.\12Aber ich habe\
nicht genug Geld\11für das Projekt…",
  ["4f:53bd"] = "MACHOLLO: Guooh\
gogogoh!",
  ["4f:53d5"] = "Ein MACHOLLO\
brüllt laut,\11während es auf\11den Boden stampft.",
  ["4f:540d"] = "Es gibt acht\
ARENEN in KANTO.\12Das große Gebäude\
ist die PKMN-ARENA\11von ORANIA CITY.",
  ["4f:5457"] = "RELAXO schläft\
friedlich…",
  ["4f:5477"] = "Der POKéCOM wird\
in der Nähe des\11schlafenden\11RELAXOs platziert…\12…\12RELAXO ist\
aufgewacht!",
  ["4f:54bb"] = "In KANTO treffen\
sich talentierte\11Trainer.\12ARENALEITER sind\
besonders stark.\12Es ist nicht\
leicht, sie zu\11besiegen.",
  ["4f:551e"] = "Du sammelst ORDEN\
der ARENEN in\11KANTO?\12Findest du nicht\
auch, dass die\11Trainer hier stark\11sind?",
  ["4f:557b"] = "Ich schätze, du\
hast diesen Wett-\12kampf der ARENEN\
in KANTO bald\11beendet.\12Lass mich wissen,\
wenn du alle acht\11ORDEN hast.",
  ["4f:55e6"] = "Gratuliere!\12Du hast alle ORDEN\
der ARENEN in\11KANTO.\12Ich habe hier eine\
Belohnung für\11deine\11Anstrengungen.",
  ["4f:563d"] = "Es ist vorteil-\
haft, wenn du\12POKéMON verschie-\
dener Elemente\11kämpfen lässt.\12Ich bin sicher,\
dass die ORDEN der\11ARENEN in KANTO\11dir helfen werden.",
  ["4f:56ac"] = "ORANIA CITY\12Der Hafen Der\
Stimmungsvollen\11Sonnenuntergänge",
  ["4f:56da"] = "PKMN-ARENA von\
ORANIA CITY\11LEITUNG:\11MAJOR BOB\12Der Blitzschnelle\
Amerikaner",
  ["4f:571b"] = "POKéMON-FANCLUB\12Alle POKéMON-Fans\
sind willkommen!",
  ["4f:5741"] = "DIGDAS HÖHLE",
  ["4f:5751"] = "EINGANG zum HAFEN\
von ORANIA CITY",
  ["4f:5820"] = "Die Strasse zum\
KRAFTWERK bleibt\12gesperrt, bis das\
Problem gelöst\11wurde.",
  ["4f:5864"] = "TUNNELPFAD\12AZURIA CITY -\
ORANIA CITY",
  ["4f:5923"] = "Hier lebt ein\
kleines Mädchen,\12das hervorragend\
Menschen nachahmt.\12Sie imitiert sogar\
Menschen, mit\12denen sie sich\
gerade unterhält.\12Das ist sehr\
verwirrend.",
  ["4f:59a3"] = "Die NACHAHMERIN\
sieht unglücklich\12aus. Sie hat ihre\
Lieblings-POKé-\11PUPPE - PIEPI -\11verloren.",
  ["4f:59f6"] = "Du bist von JOHTO\
hergekommen?\12Wenn der MAGNETZUG\
läuft, bist du\11ganz schnell\11wieder zu Hause.",
  ["4f:5a44"] = "Du kommst aus\
JOHTO?\12Mit dem MAGNETZUG\
bist du ganz\11schnell wieder\11zu Hause.",
  ["4f:5a94"] = "Ich ging zur PKMN-\
ARENA, weil ich\11unbedingt kämpfen\11wollte…\12Wie sich heraus-\
stellte, bin ich\12ausgerechnet in\
der verlassenen\12PKMN-ARENA\
gelandet.\12War mir das\
peinlich!",
  ["4f:5b24"] = "Das ist die SILPH\
CO., berühmt für\11ihre POKéMON-\11Artikel.\12TEAM ROCKET wollte\
sie wegen dieser\12Waren für sich\
nutzen.",
  ["4f:5b92"] = "Mampf… Mampf…\12Wie ich höre,\
braute sich da\11etwas im KRAFTWERK\11zusammen.\12Mampf… Mampf…",
  ["4f:5be1"] = "Mampf… Mampf…\12Wie ich höre,\
braut sich da\11etwas im KRAFTWERK\11zusammen.\12Mampf… Mampf…\
Aah, ich bin satt!",
  ["4f:5c3b"] = "Ich finde es\
unheimlich, wenn\12ich zum ersten Mal\
einen engen Gang\11betrete.",
  ["4f:5c7b"] = "In VERTANIA CITY\
gibt es ein HAUS\12für TRAINER. Dort\
treffen sich\12Trainer der ganzen\
Welt.",
  ["4f:5cdb"] = "Über unsere Stadt\
wurde mal im Radio\11berichtet.\12Es ist schön, dass\
für deine Stadt\12geworben wird,\
aber es ist auch\11ein bisschen\11peinlich.",
  ["4f:5d4d"] = "SAFFRONIA CITY\12Golden Schimmernde\
Stadt des Handels",
  ["4f:5d7c"] = "PKMN-ARENA von\
SAFFRONIA CITY\11LEITUNG: SABRINA\12Die Meisterin der\
Psycho-POKéMON!",
  ["4f:5dbf"] = "Willkommen!\
KARATE DOJO",
  ["4f:5de0"] = "SILPH CO.\
BÜROGEBÄUDE",
  ["4f:5dfb"] = "HAUS von\
MR. PSYCHO",
  ["4f:5e0f"] = "SAFFRONIA CITY\
MAGNETZUG-\11BAHNHOF",
  ["4f:5f1e"] = "Die Strasse zum\
KRAFTWERK bleibt\12gesperrt, bis das\
Problem gelöst\11wurde.",
  ["4f:5f62"] = "TUNNELPFAD\12AZURIA CITY -\
ORANIA CITY",
  ["4f:5f93"] = "Was ist das?\12Haus zu verkaufen…\
Hier wohnt\11niemand.",
  ["4f:60b0"] = "Das KRAFTWERK von\
KANTO befindet\12sich am Ende von\
ROUTE 9. Es muss\12dort einen Stör-\
fall gegeben\11haben.",
  ["4f:610c"] = "Sammelst du jede\
Art von POKéMON?\12Das ist bestimmt\
sehr schwer. Aber\11Spaß macht es\11sicher auch.",
  ["4f:6170"] = "Am KAP im Norden\
treffen sich viele\12Pärchen. Gerade\
Mädchen gehen dort\11gerne hin!",
  ["4f:61b1"] = "LAHMUS: Jarah?",
  ["4f:61c2"] = "Mein LAHMUS und\
ich sind ein un-\11schlagbares Team!",
  ["4f:61f1"] = "LAHMUS, mach deine\
KONFUSION vor!",
  ["4f:6213"] = "…",
  ["4f:6216"] = "Ich bin ein großer\
Fan von der ARENA-\11LEITERIN in AZURIA\11CITY. Ihr Name ist\11MISTY.",
  ["4f:623d"] = "Ich habe so einen\
zwielichtigen Typ\11zum KAP bei AZURIA\11CITY gehen sehen.",
  ["4f:6271"] = "Hier soll es mal\
eine Höhle gegeben\12haben, in der\
mächtige und\11grässliche POKéMON\11gehaust haben.",
  ["4f:62b6"] = "Ach ja?\12Mein DETEKTOR\
schlägt aus…",
  ["4f:62da"] = "AZURIA CITY\12Umgeben Von Einer\
Mystischen Blauen\11Aura",
  ["4f:630d"] = "PKMN-ARENA von\
AZURIA CITY \11LEITUNG: MISTY\12Die Jungenhafte\
Meerjungfrau",
  ["4f:6349"] = "Hier ist eine\
Nachricht…\12Der FAHRRADLADEN\
ist jetzt in\11JOHTO, in\11DUKATIA CITY…",
  ["4f:6394"] = "Hier ist eine\
Nachricht…\12Stoppt die Krimi-\
nalität und macht\12aus dieser Stadt\
einen Ort, an dem\11man sicher ist und\11gerne lebt!\12ORDNUNGSAMT VON\
AZURIA CITY",
  ["4f:6403"] = "KAP bei AZURIA\
CITY voraus",
  ["4f:6418"] = "Abgeschlossen…",
  ["50:4080"] = "Ich möchte den\
FELSTUNNEL\11erforschen.",
  ["50:40a0"] = "Boah! Vorsicht!",
  ["50:40b4"] = "Meine POKéMON\
wurden verletzt,\12obwohl ich den\
FELSTUNNEL noch\11nicht betreten\11hatte.\12Ich bringe sie\
besser sofort in\11ein PKMN-CENTER.",
  ["50:411a"] = "Warst du schon\
beim Picknicken?\12Das macht großen\
Spaß!",
  ["50:414f"] = "Ohhhh!",
  ["50:4157"] = "Wir backen viele\
gute Sachen, die\12wir mit allen\
teilen. Sie\11schmecken lecker!",
  ["50:419d"] = "Hey, du Lump!\
Wirf deinen Müll\11nicht hier hin!",
  ["50:41b5"] = "Ich wollte nur\
klarstellen, dass…",
  ["50:41d1"] = "Entschuldige!\
Ich habe mich\11geirrt.",
  ["50:4202"] = "Die Leute sollten\
ihren Müll nicht\11hier liegen\11lassen.",
  ["50:422c"] = "Ohh… Ich habe\
verloren…",
  ["50:423a"] = "Energiesparen ist\
wichtig, aber die\12Natur ist noch\
viel wichtiger.",
  ["50:4283"] = "Wenn sie kommt,\
kommt sie vom\11SILBERBERG…\12Der SILBERBERG ist\
in JOHTO, oder?",
  ["50:42d2"] = "Ich war zu sehr\
mit Singen\11beschäfigt…",
  ["50:42eb"] = "Bei Kämpfen spielt\
Konzentration eine\11wichtige Rolle.",
  ["50:430d"] = "Ich verrate dir\
ein Geheimnis.\12Aber zuerst müssen\
wir kämpfen!",
  ["50:433b"] = "Oh, Mist!\
Ich habe verloren…",
  ["50:4353"] = "Du musst einen\
kleinen Fluss\11durchqueren, um\11zum KRAFTWERK\11zu gelangen.",
  ["50:437d"] = "ROUTE 9\12AZURIA CITY -\
FELSTUNNEL",
  ["50:443b"] = "Hey, Kleiner! Ich\
sein von TEAM\11ROCKET.\12Sein aus fremde\
Land, Trainer eins\11ich sein!\12Geglaubt, wenn\
nix Energie mehr,\12mache viel Panik\
bei Leute!\12Geheim mein\
Auftrag sein, ich\11dir nix verraten!\12Doch! Wenn mich\
besiegen, ich sein\12lieb und dir\
verrate Geheimnis.\12Du, Kind! Kämpfen\
lass uns!",
  ["50:4574"] = "Uff! Nein,\
glauben nicht ich\11kann!\12Stark sehr du\
sein! Ich nix\11Gegner für dich!",
  ["50:45cd"] = "O.K. Verraten dir\
meine Geheimnis.\12SPULE, gestohlen\
von mir, versteckt\12in Arena der\
AZURIA CITY.\12Wasser sein gute\
Versteck. In\12Mitte von ARENA\
Wasser sein.\12Bub, du mich\
vergessen nicht!\12Besiege dir wird\
TEAM ROCKET tun.\12Werden kommen aus\
JOHTO, mein\12Freunde. Rächen\
sie werden tun.",
  ["50:46f3"] = "…\12Was du sagen? TEAM\
ROCKET nix mehr\12gibt? Kaputt\
gemacht, du sagen?\12Oh, nein! Ich\
tun was jetzt\11machen?",
  ["50:48e7"] = "MISTY: Aww! Warum\
musst du jetzt\12auftauchen und uns\
stören?\12Weißt du, wie\
man Menschen wie\11dich nennt?\12Plage! Du hast\
richtig gehört,\11Plage!\12…\12…Oh? Die ORDEN,\
die du hast… Sind\11das ARENA-ORDEN\11aus JOHTO?\12Wenn du acht hast,\
musst du gut sein.\12O.K. Komm in die\
ARENA von AZURIA\11CITY.\12Ich freue mich,\
gegen dich zu\11kämpfen.\12Ich bin MISTY, die\
ARENALEITERIN von\11AZURIA CITY.",
  ["50:4a2e"] = "Besiege alle sechs\
Trainer und du\11erhältst einen\11wunderbaren Preis!\12Glaubst du, du\
hast das Zeug\11dazu?",
  ["50:4a83"] = "Wow! Gut gemacht.",
  ["50:4a96"] = "Ich gab mein\
Bestes. Ich habe\11mir nichts\11vorzuwerfen.",
  ["50:4ab9"] = "Ich bin Numero 2!\
Jetzt wird es\11ernst!",
  ["50:4ad6"] = "Wie konnte ich\
nur verlieren?",
  ["50:4ae9"] = "Ich habe alles\
gegeben. Ich kann\11mir nichts\11vorwerfen.",
  ["50:4b0c"] = "Ich bin Nummer 3!\
Das wird nicht\11leicht.",
  ["50:4b2a"] = "Oh! Vermöbelt!",
  ["50:4b3d"] = "Ich habe alles\
gegeben. Ich kann\11mir nichts\11vorwerfen.",
  ["50:4b60"] = "Der Vierte!\
Bist du müde?",
  ["50:4b7a"] = "Auch ich habe\
verloren…",
  ["50:4b87"] = "Ich gab mein\
Bestes. Ich habe\11mir nichts\11vorzuwerfen.",
  ["50:4baa"] = "O.K.! Nummer 5.\
Ich zermalme dich!",
  ["50:4bc8"] = "Uff! Zu stark.",
  ["50:4bd9"] = "Ich gab mein\
Bestes. Ich habe\11mir nichts\11vorzuwerfen.",
  ["50:4bfc"] = "Ich bin der\
Letzte, aber ich\11sage dir, ich bin\11eine harte Nuss!",
  ["50:4c2c"] = "Du machst Witze.",
  ["50:4c3c"] = "Ich gab mein\
Bestes. Ich habe\11mir nichts\11vorzuwerfen.",
  ["50:4c5f"] = "Uffuffuff…\12Ich habe mit den\
sechs Trainern\11nichts zu tun.\12Ich habe hier auf\
dich gewartet, um\12dich zu besiegen,\
da du nach den\11vielen Kämpfen\11müde sein musst.",
  ["50:4ce2"] = "Bist du nicht\
müde?",
  ["50:4cfb"] = "Tut mir Leid… Ich\
werde nicht mehr\11mogeln…",
  ["50:4d1c"] = "Du hast einen\
Kampf mehr be-\12stritten, als du\
erwartet hast.\11Dennoch hast du\11gewonnen.\12Wie versprochen,\
hier ist der\11Preis.",
  ["50:4d7e"] = "Nachdem ich ge-\
sehen habe, wie\12du kämpfst, möchte\
ich sehen, wie es\11mir ergeht.\12Wie sieht's aus?\
Ich fordere dich\11heraus.",
  ["50:4dde"] = "Das war der beste\
Kampf meines\11Lebens!",
  ["50:4e01"] = "Der Kampf war\
großartig!\12Du und deine POKé-\
MON seid ein\11perfektes Team!",
  ["50:4e48"] = "KÜSTENHAUS\
BILLs HAUS",
  ["50:4f79"] = "Ah! Das Wetter\
ist so schön\11wie immer.",
  ["50:4f9c"] = "Die Sonne scheint,\
dennoch bin ich\11nass…",
  ["50:4fb8"] = "Bei Regen ist\
eine Zündung sehr\11schwierig…",
  ["50:4fe2"] = "Hmmm… Ich weiß\
nicht, was ich\11tun soll…",
  ["50:5001"] = "Ich wusste es…",
  ["50:5012"] = "Du hast gleich\
einen starken\11Eindruck gemacht.\12Ich hatte Angst,\
gegen dich zu\11kämpfen…",
  ["50:5043"] = "Ich bin schnell\
wie der Wind!",
  ["50:505d"] = "Hinfortgeweht!",
  ["50:506a"] = "Ich trage das\
ganze Jahr Shorts.\12Das ist meine\
Auffassung von\11Mode.",
  ["50:50a8"] = "Komm schnell her\
und schau!",
  ["50:50c8"] = "Das macht Spaß!",
  ["50:50d9"] = "Ich bin der beste\
Feuerspucker\11in KANTO.\12Aber nicht der\
beste Trainer…",
  ["50:5124"] = "MONDBERGPLATZ\12Geh einfach die\
Treppe hoch",
  ["50:51d5"] = "Es gibt Neuig-\
keiten über den\11Vorfall im\11KRAFTWERK.",
  ["50:520a"] = "Ich habe verloren?\
Das ist auch eine\11Neuigkeit…",
  ["50:5223"] = "Ich gehe zum\
KRAFTWERK. Ist es\11beim FELSTUNNEL?",
  ["50:525b"] = "Ich spüre, dass\
ich gewinnen kann.\12Mal sehen, ob\
das stimmt!",
  ["50:5293"] = "Argh, du bist zu\
stark.",
  ["50:52ad"] = "Ich hörte, dass\
PIEPI am MONDBERG\12auftaucht. Aber wo\
soll das sein?",
  ["50:52eb"] = "Ähm…\
Ich…",
  ["50:52f3"] = "…",
  ["50:52f6"] = "……Ich sollte\
wohl noch mehr\11trainieren…",
  ["50:5311"] = "MONDBERGPLATZ\12Geh die Treppe\
hinauf",
  ["50:53ef"] = "Wir repräsentieren\
die POKéMON-\11TRAINERGILDE aus\11KANTO.\12Hier kommst du\
unter die Räder!",
  ["50:543f"] = "En-entschuldigung!",
  ["50:5449"] = "Die GILDE der\
POKéMON-Trainer\11aus KANTO wird\11immer existieren!",
  ["50:5475"] = "Das ORDNUNGSAMT\
hat unseren\12TUNNELPFAD zu-\
schütten lassen.\11Das ängstigt mich!",
  ["50:54b5"] = "V-vergib mir!",
  ["50:54c4"] = "Vermöbelt von\
einem Rowdy aus\11JOHTO…",
  ["50:54e8"] = "Wir sind die\
POKéMON-Trainer-\11GILDE aus KANTO!\11Nimm dich in Acht!",
  ["50:551b"] = "Uah! Entschuldige!",
  ["50:552a"] = "Wir versuchen,\
ab jetzt niemanden\11mehr zu stören…",
  ["50:5557"] = "Wie funktioniert\
der MAGNETZUG?",
  ["50:557a"] = "Ich möchte nur den\
MAGNETZUG sehen…",
  ["50:55a0"] = "Die Kraft von\
Magneten ist\11beeindruckend!",
  ["50:55c4"] = "Wir kommen nicht\
ohne Strom aus.\12Das KRAFTWERK\
versorgt uns\11mit Strom.",
  ["50:5615"] = "Verschwende keinen\
Strom!",
  ["50:562e"] = "Das KRAFTWERK\
nördlich von\12LAVANDIA versorgt\
den MAGNETZUG mit\11Strom.",
  ["50:5675"] = "Es ist verriegelt…",
  ["50:5682"] = "Das Flugblatt ist\
zerrissen.\12Es ist nicht mehr\
lesbar…",
  ["50:571c"] = "KRAFTWERK KANTO",
  ["50:5776"] = "Hahahah!",
  ["50:5780"] = "Hahaha-hatschi!",
  ["50:5790"] = "Ich habe Heu-\
schnupfen!\12Haha-hatschi!",
  ["50:57bd"] = "Du magst POKéMON,\
nicht wahr?\12Ich auch!",
  ["50:57df"] = "Ich gebe zu, ich\
habe verloren.",
  ["50:57fe"] = "Sieh nur, was du\
meinen POKéMON\11angetan hast…\12Das werde ich dir\
nie verzeihen…",
  ["50:5831"] = "ROUTE 10\12AZURIA CITY -\
LAVANDIA",
  ["50:588f"] = "INDIGO PLATEAU\12Das Ultimative\
Ziel aller\11Trainer!\12HAUPTQUARTIER der\
POKéMON LIGA",
  ["51:400e"] = "Seeleute sind sehr\
großzügig.\12Einer hat meinem\
POKéMON STÄRKE\12beigebracht. Jetzt\
kann es Felsen be-\11wegen.",
  ["51:4067"] = "Da gibt es jeman-\
den in ANEMONIA\11CITY jenseits des\11Meeres.\12Ich habe gehört,\
wie er mit seinen\11seltenen POKéMON\11angegeben hat.",
  ["51:419a"] = "…Danke für deine\
Hilfe beim LEUCHT-\11TURM…\12Erlaube mir, mich\
vorstellen zu dür-\11fen!\12Ich bin JASMIN,\
eine ARENA-LEITE-\11RIN. Ich setze\11STAHL-POKéMON ein.\12…Hast du von die-\
sem Typ schon ge-\11hört?\12Er wurde erst vor\
kurzer Zeit ent-\11deckt.\12…Ähm… Darf ich be-\
ginnen?",
  ["51:429c"] = "…Du bist ein bes-\
serer Trainer als\12ich. Das betrifft\
sowohl Geschick,\12als auch Fein-\
gefühl.\12In Übereinstimmung\
mit den Regeln der\12LIGA überreiche\
ich dir diesen\11ORDEN.",
  ["51:431b"] = "{PLAYER} erhält\
STAHLORDEN.",
  ["51:4335"] = "Der STAHLORDEN\
erhöht die VERT\11deiner POKéMON.\12…Ähm… Bitte nimm\
auch das…",
  ["51:4386"] = "…Mit dieser TM\
kannst du deinen\11POKéMON EISEN-\11SCHWEIF lehren.",
  ["51:43b2"] = "Ähm… Ich weiß\
nicht, wie ich das\11sagen soll, aber…\11Viel Glück!",
  ["51:43e3"] = "JASMIN setzt den\
neu entdeckten Typ\11Stahl ein.\12Ich weiß nicht\
viel darüber.",
  ["51:4432"] = "Das war großartig!\12Der Typ Stahl,\
was?\12Das war eine un-\
heimliche Begeg-\11nung der unbe-\11kannten Art.",
  ["51:4489"] = "JASMIN, die ARE-\
NALEITERIN ist im\11LEUCHTTURM.\12Sie kümmert sich\
um ein krankes\11POKéMON.\12Ein starker Trai-\
ner muss auch Mit-\11gefühl zeigen.",
  ["51:4583"] = "Als mein POKéMON\
krank war, hat der\12APOTHEKER in TEAK\
CITY eine Medizin\11zubereitet.",
  ["51:45d1"] = "RIZEROS: Gugooh!",
  ["51:4624"] = "Auf dem Weg nach\
ANEMONIA CITY\12siehst du vier\
verlassene Inseln.\12Ungezogene Kinder\
werden zur Bestra-\11fung auf diese In-\11seln geschickt!",
  ["51:4692"] = "Wenn ich ungezogen\
bin, macht mir Pa-\11pa mit gruseligen\11Geschichten Angst.",
  ["51:472a"] = "OLIVIANA CITY\
liegt am Meer!\12Daher sollte man\
dort auch jede\11Menge Fische fin-\11den!\12Ich fische hier\
seit 30 Jahren.\12Willst du das Meer\
und die Fische\11sehen?",
  ["51:47bc"] = "Ah, hahah!\
Und da haben wir\11einen neuen\11Angler!",
  ["51:47e8"] = "Fische findet man\
nicht nur im Meer.\12Sie sind überall,\
wo es Wasser gibt.",
  ["51:482d"] = "Waaas? Du willst\
nicht fischen!?\11Unfassbar!",
  ["51:4860"] = "Wie steht's? Den\
großen Fang ge-\11macht?",
  ["51:48bd"] = "Ha! Deine POKéMON\
sind ja nur Flie-\11gengewichte!\12Sie haben nicht\
die Kraft, Felsen\11aus dem Weg zu\11räumen.\12Hier, nimm das und\
bring ihnen STÄRKE\11bei!\12Du benötigst den\
ORDEN von DUKATIA\12CITY, um sie\
außerhalb von\12Kämpfen einsetzen\
zu können.",
  ["51:4980"] = "Der Einzige, auf\
den du dich auf\12hoher See verlas-\
sen kannst, bist\11du selbst!\12Ich bin so stolz\
auf mich selbst!",
  ["51:49e0"] = "Geht's übers\
Meer? Pass auf!\12Auf dem Weg nach\
ANEMONIA CITY gibt\11es Strudel.\12Deine POKéMON\
müssen eine spe-\12zielle Attacke be-\
herrschen, um an\12den Strudeln vor-\
beizukommen.",
  ["51:4aaa"] = "Können deine POKé-\
MON schon Leute\12übers Wasser tra-\
gen?",
  ["51:4aec"] = "Ich habe mein\
SMETTBO von meinem\11Freund aus Übersee\11bekommen.\12Es hatte einen\
BRIEF von ihm da-\11bei.\12Willst du wissen,\
was er schreibt?\12Mal sehen… Oh!\
Das ist ein Ge-\11heimnis!",
  ["51:4bb0"] = "Wo sagtest du,\
kommst du her?\12NEUBORKIA?\12PROF. LIND wohnt\
dort,\11nicht wahr?\12Du hast einen\
langen Weg auf\11dich genommen, um\11hierher zu ge-\11langen.",
  ["51:4d04"] = "MILTANK ist krank…\12Es braucht viele\
BEEREN.",
  ["51:4d30"] = "Wir füttern\
MILTANK!",
  ["51:4d46"] = "MILTANK: …Muh…",
  ["51:4d56"] = "Sein Ruf ist\
schwach…",
  ["51:4d68"] = "MILTANK: MUH!",
  ["51:4d77"] = "Gibst du MILTANK\
eine BEERE?",
  ["51:4d91"] = "{PLAYER} gibt\
MILTANK eine\11BEERE.",
  ["51:4dad"] = "MILTANK ist etwas\
gesünder geworden!",
  ["51:4dd1"] = "MILTANK ist viel\
gesünder geworden!",
  ["51:4df0"] = "MILTANK ist völlig\
gesund geworden!",
  ["51:4e11"] = "{PLAYER} hat keine\
BEEREN…",
  ["51:4e24"] = "{PLAYER} möchte\
keine BEERE\11verwenden.\12MILTANK sieht\
traurig aus.",
  ["51:4f0d"] = "Mein MILTANK gibt\
keine Milch\11mehr.\12Diese FARM ist\
berühmt für die\11Milch, die hier\11produziert wird.\12Fast jeder trinkt\
sie gern.\12Es würde mir viel\
Milch geben, wenn\12ich es mit vielen\
BEEREN füttern\11würde. Glaube ich\11zumindest.",
  ["51:4fb7"] = "Wie findest du\
die MILCH von\11meinem MILTANK?\12Sie ist mein gan-\
zer Stolz, Junge.\12Gib sie einem\
POKéMON, um dessen\11KP aufzufrischen!\12Ich gebe sie dir\
für nur ¥500.",
  ["51:5031"] = "Bitte sehr!\
Trink aus und\11genieße es!",
  ["51:5050"] = "Tut mir Leid, mein\
Sohn. Wenn du kein\11Geld hast, kann\11ich dir nichts\11verkaufen!",
  ["51:506f"] = "Ich schätze,\
dein BEUTEL ist\11voll, Kleiner.",
  ["51:508e"] = "Du hast kein\
Interesse? Komm\11aber wieder, hörst\11du?",
  ["51:50b3"] = "Dann melke ich\
mal weiter.",
  ["51:50cd"] = "Unsere Milch wird\
sogar nach KANTO\11geliefert.\12Wenn uns unser\
MILTANK keine\12Milch mehr gibt,\
haben wir echte\11Probleme.",
  ["51:512d"] = "Du hast unserem\
MILTANK geholfen!\12Jetzt gibt es\
wieder Milch!\12Hier, für deine\
Mühe.",
  ["51:519e"] = "Das hier ist\
SCHNARCHER.\12Das ist eine\
seltene Attacke,\12die nur ein schla-\
fendes POKéMON\11einsetzen kann.\12Überlege dir gut,\
wie du sie\11anwendest,\11Kleiner.",
  ["51:526c"] = "Ich hörte, dass\
ein rotes GARADOS\12am SEE erschienen\
sein soll.\12Das ist seltsam,\
da schon normale\12GARADOS in diesem\
See sehr selten\12sind…",
  ["51:52de"] = "Mein Lieblingspro-\
gramm im Radio?\11Ich würde sagen\11POKéMON-MUSIK.",
  ["51:530d"] = "Ich habe Gelächter\
im Radio gehört…\12Das war unheim-\
lich.",
  ["51:545d"] = "POKéMON machen in\
ihrem Leben viele\12Erfahrungen. Genau\
wie Menschen.\12Auch ich habe in\
meinem Leben viel\11gesehen und er-\11litten.\12Da ich der Älteste\
bin, lass mich dir\11zeigen, was ich\11meine.\12Ich war schon mit\
POKéMON zusammen,\12bevor du geboren\
wurdest.\12Ich verliere nicht\
gerne.\12Ich, NORBERT, der\
Wintertrainer,\12werde meine Macht\
demonstrieren!",
  ["51:5583"] = "Ich bin von deinem\
Können beein-\11druckt.\12Mit deinem starken\
Willen, wirst du\12alle Widrigkeiten\
in deinem Leben\11überstehen.\12Du bist dieses\
ORDENS würdig!",
  ["51:560b"] = "{PLAYER} erhält\
EISORDEN.",
  ["51:5625"] = "Dieser ORDEN hebt\
den SPEZ-Wert dei-\11ner POKéMON.\12Außerdem können\
deine POKéMON\11WHIRLPOOL einset-\11zen, um echte\11Strudel zu\11überwinden.\12Und dies… dies ist\
ein Geschenk von\11mir!",
  ["51:56bf"] = "Diese TM enthält\
EISSTURM.\12Sie verursacht\
Schaden und ver-\11ringert die Ge-\11schwindigkeit.\12Sie stellt die\
Härte des Winters\11dar.",
  ["51:5729"] = "Wenn Eis und\
Schnee geschmolzen\11sind, kehrt der\11Frühling wieder.\12Du und deine\
POKéMON werden\12noch viele Jahre\
zusammen sein.\12Genießt eure ge-\
meinsame Zeit!",
  ["51:57b1"] = "Ich werde deine\
POKéMON einfrie-\11ren, so dass sie\11sich nicht bewegen\11können.",
  ["51:57e0"] = "Mist! Ich konnte\
nichts tun.",
  ["51:57fd"] = "Ich glaube, es\
gibt eine Attacke\12die POKéMON\
auch ausführen\12können, wenn sie\
gefroren sind.",
  ["51:5835"] = "Diese ARENA hat\
einen rutschigen\12Boden. Das ist\
doch lustig, oder?\12Aber wir sind\
nicht hier, um zu\11spielen!",
  ["51:588d"] = "Siehst du jetzt,\
wie ernst wir es\11meinen?",
  ["51:58ad"] = "Diese ARENA ist\
toll. Ich liebe\11es, mit meinen\11POKéMON hier zu\11snowboarden!",
  ["51:58df"] = "Ich kenne NORBERTs\
Geheimnis.",
  ["51:58f6"] = "O.K. Ich verrate\
dir NORBERTs Ge-\11heimnis.",
  ["51:5917"] = "Das Geheimnis von\
NORBERTs Kraft…\12Er meditiert täg-\
lich unter einem\12Wasserfall, um\
Geist und Körper\11zu stärken.",
  ["51:597e"] = "Um zu NORBERT, un-\
serem ARENALEITER,\12zu gelangen, musst\
du denken, bevor\11du loslegst.",
  ["51:59c4"] = "Beim Schifahren\
würde ich nie ge-\11gen dich verlie-\11ren.",
  ["51:59e6"] = "Wenn du nicht ge-\
nau rutschst,\12kommst du in die-\
ser ARENA nicht\11weit.",
  ["51:5a27"] = "Sieh dir meinen\
Parallelschwung\11an!",
  ["51:5a44"] = "Nein! Jetzt bin\
ich weggerutscht!",
  ["51:5a5f"] = "Ich hätte mit mei-\
nen Schi-Künsten\11nicht so angeben\11sollen…",
  ["51:5a8f"] = "NORBERT ist ein\
Veteran, der seine\12POKéMON schon\
fast seit 50 Jah-\11ren trainiert.\12Angeblich friert\
er seine Gegner\12gerne mit Eis-\
Attacken ein.\12Das heißt, du\
solltest ihn mit\12deinem brennenden\
Ehrgeiz schmelzen!",
  ["51:5b45"] = "NORBERT ist nicht\
übel, aber du\11bist noch besser!\12Das war ein heißer\
Kampf, der die\12Kluft zwischen den\
Generationen über-\11wunden hat.",
  ["51:5c32"] = "Wie? TEAM ROCKET\
ist wieder da?\12Ich sah einige\
Männer in Schwarz\11am SEE DES ZORNS…",
  ["51:5c83"] = "Ich verhindere,\
dass sich meine\11POKéMON zu\11rasch entwickeln.\12Ich bringe ihnen\
verschiedene\11Attacken bei, be-\11vor ich sie sich\11entwickeln lasse.",
  ["51:5ce8"] = "POKéMON werden\
stärker, wenn sie\12sich entwickeln.\
Aber sie erlernen\12neue Attacken auch\
langsamer.",
  ["51:5d88"] = "Der KESSELBERG\
ist wie ein\12Irrgarten, also\
verlaufe dich\11nicht.",
  ["52:406c"] = "Wenn du nicht im\
Besitz des ORDENS\12von TEAK CITY\
bist, darfst du\12den ZINNTURM nicht\
betreten.",
  ["52:40cc"] = "Wenn du nicht im\
Besitz des ORDENS\12von TEAK CITY\
bist, darfst du\12den ZINNTURM nicht\
betreten. Ah!\12Das ist der ORDEN\
von TEAK CITY! Du\11darfst passieren.",
  ["52:413f"] = "Der ZINNTURM ist\
als Brutstätte für\12fliegende POKéMON\
gedacht.",
  ["52:417d"] = "Der ZINNTURM bebt!\
Ein POKéMON muss\12auf der Spitze ge-\
landet sein!",
  ["52:41b9"] = "Zwei Türme…\
Zwei POKéMON…\12Aber als einer\
niederbrannte,\12flogen beide POKé-\
MON fort und kamen\11nie wieder zurück.",
  ["52:4304"] = "Hi, ich bin BILL.\
Und wer bist du?\12Hmm, {PLAYER}?\
Du bist gerade zum\11richtigen Zeit-\11punkt gekommen.",
  ["52:434e"] = "Ich bin soeben mit\
den Arbeiten an\11der ZEITKAPSEL\11fertig geworden.\12Du weißt doch,\
dass man POKéMON\11tauschen kann.\12Meine ZEITKAPSEL\
ermöglicht auch\12Tauschhandel mit\
der Vergangenheit.\12Aber du kannst\
nichts in die Ver-\12gangenheit senden,\
was damals nicht\11existierte.\12Solltest du das\
versuchen, erlei-\11det der PC in der\11Vergangenheit ei-\11nen Absturz.\12Also musst du al-\
les entfernen, was\12es in der Vergan-\
genheit nicht gab.\12Einfach gesagt: Du\
darfst keine neuen\12Attacken oder\
POKéMON mit der\12ZEITKAPSEL ver-\
schicken.\12Keine Sorge. Ich\
bin jetzt fertig.\12Schon morgen wer-\
den ZEITKAPSELN in\12allen POKéMON\
CENTERN zur Verfü-\11gung stehen.\12Ich muss zurück\
nach DUKATIA CITY,\11um meine Freunde\11zu besuchen.\12Tschü-hüs!",
  ["52:4581"] = "Sowohl der Tanz\
der KIMONO GIRLS\12als auch die Art,\
wie sie ihre POKé-\12MON einsetzen, ist\
wunderbar!",
  ["52:45d6"] = "JENS, der ARENA-\
LEITER, ist soooo\11cool.\12Auch seine POKéMON\
sind sehr stark.",
  ["52:461c"] = "SEE DES ZORNS…\12Das Erscheinen ei-\
nes GARADOS-\11Schwarms…\12Das riecht nach\
Verschwörung!",
  ["52:46d3"] = "Dies geschah, als\
ich jung war.\12Der Himmel färbte\
sich schwarz. Ein\12riesiges, fliegen-\
des POKéMON\12verdunkelte die\
Sonne.\12Ich frage mich,\
was das für ein\12POKéMON war. Es\
war wie ein Vogel\11und ein Drache.",
  ["52:4782"] = "Ob es wirklich ein\
so großes POKéMON\12gibt? Wenn ja, so\
muss es unfassbar\11mächtig sein.",
  ["52:48b8"] = "Du hast hübsche\
POKéMON. Darf ich\11sehen, wie sie\11kämpfen?",
  ["52:48e9"] = "Oh, du bist sehr\
stark.",
  ["52:4903"] = "Das war ein toller\
Kampf. Ich würde\11dich gerne mal\11wiedersehen.",
  ["52:4938"] = "Ich tanze immer\
mit meinen POKé-\12MON. Natürlich\
trainiere ich sie\11auch.",
  ["52:4974"] = "Oh, beinahe!\
Fast hätte ich\11dich gehabt.",
  ["52:4995"] = "Rhythmus ist nicht\
nur zum Tanzen,\12sondern auch für\
POKéMON wich-\11tig.",
  ["52:49c9"] = "Ist meine Haar-\
spange nicht\11hübsch?\12Oh, ein POKéMON-\
Kampf?",
  ["52:49f6"] = "Ich habe keine\
POKéMON mehr\11übrig…",
  ["52:4a12"] = "Jeden Monat stecke\
ich mir eine ande-\11re Blume in die\11Spange.",
  ["52:4a4a"] = "Oh, du bist ein\
süßer Trainer.\11Willst du kämpfen?",
  ["52:4a7f"] = "Du bist stärker\
als du aussiehst.",
  ["52:4a9e"] = "Ich habe viel\
trainiert. Also\12dachte ich, ich\
wäre gut. Aber ich\11bin es wohl nicht.",
  ["52:4ae6"] = "Gefällt dir mein\
Tanz? Ich kenne\11mich auch gut mit\11POKéMON aus.",
  ["52:4b14"] = "Ooh, du kennst\
dich auch gut mit\11POKéMON aus.",
  ["52:4b32"] = "Ich werde nicht\
aufhören zu tan-\12zen, solange es\
Leute gibt, denen\12ich dadurch Freude\
bereite.\12Auch meine POKéMON\
unterstützen mich\11dabei.",
  ["52:4b94"] = "Die KIMONO GIRLS\
sind nicht nur\12großartige Tänzer,\
sie sind auch gute\11POKéMON-Trainer.\12Ich fordere sie\
ständig heraus,\12konnte sie aber\
noch nie besiegen…",
  ["52:4c1b"] = "Junge! Wenn du\
alle KIMONO GIRLS\12besiegst, gebe ich\
dir ein Geschenk.",
  ["52:4c5e"] = "Die Art wie du\
kämpfst ist wie\11ein Tanz.\12So etwas sieht man\
nicht oft!\12Ich möchte dir et-\
was geben. Nur zu!\11Nimm es ruhig!",
  ["52:4cdf"] = "Das ist SURFER.\12Damit können POKé-\
MON jedes Gewässer\11überqueren.",
  ["52:4d19"] = "Ich wünschte, mei-\
ne POKéMON wären\11so elegant wie die\11KIMONO GIRLS…",
  ["52:4d4e"] = "RIZEROS: Gugooh\
gugogooh!",
  ["52:4d68"] = "Dieser Mann hat\
immer sein RIZEROS\11dabei.\12Er sagt, dass er\
ein POKéMON haben\11will, das SURFEN\11und tanzen kann.\12Versucht er etwa,\
ein Mono-Synchron-\11Schwimm-POKéMON zu\11besitzen?",
  ["52:4dee"] = "Die KIMONO GIRLS\
sind so hübsch…\12Aber sie müssen\
hart trainieren.\12Und sie müssen\
so viele Dinge\12lernen, bevor sie\
öffentlich auftre-\11ten.\12Aber wenn du etwas\
liebst, ist alles\11möglich.",
  ["52:4ebd"] = "Eine hübsche, mit\
Blumen dekorierte\11Tafel.",
  ["52:4f8c"] = "Mein EVOLI ent-\
wickelte sich zu\11einem PSIANA.\12Aber das EVOLI\
meines Freundes\11wurde zu einem\11NACHTARA.\12Ich frage mich,\
wieso? Wir haben\12unsere EVOLIS\
gleich aufgezogen…",
  ["52:5019"] = "Setzt du BELEBER\
ein, wacht ein be-\12siegtes POKéMON\
wieder auf.",
  ["52:516b"] = "Gut, dass du ge-\
kommen bist.\12Hier in TEAK CITY\
werden POKéMON\11verehrt.\12Man sagt, dass le-\
gendäre POKéMON\12nur wahrlich star-\
ken Trainern er-\11scheinen werden.\12Ich glaube an die-\
se Legende. Daher\12habe ich mein gan-\
zes Leben lang im\12Geheimen trai-\
niert.\12Als Resultat kann\
ich nun Dinge se-\11hen, die andere\11nicht sehen kön-\11nen.\12Noch ein wenig…\12Mit ein wenig mehr\
könnte ich eine\12Zukunft sehen, in\
der ich das legen-\12däre POKéMON\
treffe.\12Du könntest mir\
dabei helfen!",
  ["52:52f4"] = "Ich bin noch nicht\
gut genug…\12Dieser ORDEN soll\
dir gehören.",
  ["52:532d"] = "{PLAYER} erhält\
PHANTOMORDEN.",
  ["52:5343"] = "Durch den PHANTOM-\
ORDEN gehorchen\12dir POKéMON bis zu\
LV50.\12Außerdem können\
POKéMON, die SUR-\12FER beherrschen,\
diesen auch außer-\12halb eines Kampfes\
einsetzen.\12Bitte nimm auch\
dies an.",
  ["52:53d6"] = "Das ist SPUKBALL.\
Er verursacht\12Schaden und ver-\
ringert die SPE-\11ZIAL-VERT.\12Setze ihn ein,\
wenn er dir ge-\11fällt.",
  ["52:542f"] = "Ich verstehe…\12Deine Reise hat\
dich an die ent-\11legensten Orte ge-\11führt.\12Du hast viel mehr\
gesehen als ich.\12Dafür beneide ich\
dich…",
  ["52:54a7"] = "Ich habe den Früh-\
ling mit meinen\12POKéMON verbracht.\
Dann den Sommer,\12den Herbst und den\
Winter…\12Dann kam wieder\
der Frühling. Wir\12haben viel Zeit\
miteinander ver-\12bracht.",
  ["52:5527"] = "Siege und Nieder-\
lagen - ich hatte\11beides.",
  ["52:554d"] = "Woher kommen\
POKéMON?",
  ["52:5568"] = "Hältst du unseren\
POKéMON stand?",
  ["52:5591"] = "Ah! Gut gemacht!",
  ["52:55a1"] = "Wir setzen nur\
Geist-POKéMON ein.\12Normal-Attacken\
zeigen bei ihnen\11keine Wirkung!",
  ["52:55e5"] = "Ich werde siegen!",
  ["52:55f3"] = "I-I-Ich habe\
verloren!",
  ["52:5602"] = "Wer siegen will,\
wird es auch tun!",
  ["52:5628"] = "Verwirrt dich un-\
ser unsichtbarer\12Boden? Besiege\
mich und ich gebe\11dir einen Tipp!",
  ["52:5669"] = "W-Was?",
  ["52:5674"] = "Gut, ich verrate\
dir das Geheimnis\12des unsichtbaren\
Bodens.\12Der Weg liegt vor\
unseren Augen!",
  ["52:56d2"] = "Die Trainer hier\
haben geheime Mo-\11tive.\12Gewinnst du, so\
verraten sie dir\12vielleicht ein\
paar Geheimnisse\11über TEAK CITY.",
  ["52:573c"] = "Wow, {PLAYER}.\
Du warst großar-\11tig!\12Vor lauter Angst\
habe ich mich in\11die Ecke gekauert!",
  ["52:58cc"] = "Ah, suchst du mit\
deinen POKéMON\11nach Abenteuern?\12Was wäre ein Aben-\
teuer ohne eine\11Schatzsuche?\12Hab ich Recht oder\
hab ich Recht?",
  ["52:5945"] = "Gut! Du trägst den\
wahren Abenteurer-\12geist in dir.\12Das mag ich! Nimm\
dies mit dir.",
  ["52:599e"] = "Manchmal liegen\
Items herum, die\12man leicht über-\
sieht.\12Setze den DETEKTOR\
ein, um Items auf-\12zuspüren, die sich\
in der Nähe befin-\12den.\12Den exakten Fund-\
ort musst du aber\12selbst herausfin-\
den.\12Ich hörte auch,\
dass in der TURM-\12RUINE von TEAK\
CITY Items zu fin-\12den wären.",
  ["52:5a95"] = "Oh… Jedem das\
Seine…",
  ["52:5ab6"] = "GESCHICHTE VON\
TEAK CITY\12Lesen?",
  ["52:5adc"] = "In TEAK CITY gab\
es zwei Türme.\12Jeder Turm war das\
Zuhause mächtiger\11fliegender POKé-\11MON.\12Doch einer der\
Türme brannte ab.\12Die beiden POKéMON\
wurden seitdem\11nicht mehr gese-\11hen…\12Weiterlesen?",
  ["52:5b92"] = "TEAK CITY war auch\
die Heimat dreier\12POKéMON, die\
durch die Stadt\11rannten.\12Es heißt, sie ent-\
standen durch Was-\12ser, Blitz und\
Feuer.\12Doch konnten sie\
ihre Kräfte nicht\11beherrschen.\12Also sind sie wie\
der Wind ins offe-\12ne Grasland ge-\
rannt.",
  ["53:40f3"] = "Ich bin SANDRA.\
Ich bin der welt-\11beste Drachen-\11meister.\12Ich kann selbst\
den TOP VIER der\12POKéMON LIGA\
widerstehen.\12Willst du noch im-\
mer gegen mich an-\11treten?\12…Gut.\
Dann los!\12Ich als Trainer\
werde all mein\12Können gegen jeden\
Gegner einsetzen!",
  ["53:41cf"] = "Ich habe verloren?\12Ich kann es nicht\
glauben. Das muss\11ein Irrtum sein…",
  ["53:4207"] = "Ich kann das nicht\
akzeptieren.\12Ich mag zwar ver-\
loren haben, aber\12du bist noch nicht\
für die POKéMON\11LIGA bereit.\12Ich hab's. Du\
sollst die Heraus-\11forderung der\11Drachen-Trainer\11annehmen.\12Hinter dieser ARE-\
NA befindet sich\11ein Ort namens\11DRACHENHÖHLE.\12Geh hin und bring\
mir den DRACHEN-\12ZAHN aus den\
Tiefen der HÖHLE!\12Durch diesen Test\
erweist du dich\12als wahrer Dra-\
chen-Trainer.\12Bestehst du ihn,\
werde ich auch\11deinen Sieg akzep-\11tieren.\12Erst dann sollst\
du den ORDEN er-\11halten.",
  ["53:4391"] = "SANDRA: Was ist\
los?\12Dieser Auftrag\
sollte kein Prob-\12lem für dich dar-\
stellen. Es sei\12denn, dein Sieg\
war reiner Zufall.",
  ["53:43f0"] = "SANDRA: Das hast\
du nicht in der\11DRACHENHÖHLE be-\11kommen.\12Das war ein ganz\
übler Schwindel-\12versuch… Ich bin\
sehr enttäuscht.",
  ["53:4451"] = "SANDRA: Du hast\
dich mir bewie-\11sen.\12Ich gebe dir diese\
TM.",
  ["53:44a7"] = "Sie enthält\
FEUERODEM.\12Nein, das hat\
nichts mit\11schlechtem Atem\11zu tun.\12Wenn du sie nicht\
willst, musst du\11sie nicht nehmen.",
  ["53:4525"] = "Du hast dir nun\
also alle ORDEN\11verdient.\12Dein Ziel ist die\
POKéMON LIGA am\12INDIGO PLATEAU.\12Weißt du, wie man\
dorthin gelangt?\12Geh von hier aus\
nach NEUBORKIA.\12SURFE dann nach\
Osten. Der Weg\11wird dann sehr be-\11schwerlich.\12Wage es nicht, in\
der POKéMON\11LIGA zu verlieren!\12Das würde meine\
Niederlage gegen\12dich noch ver-\
schlimmern!",
  ["53:4651"] = "Ist das dein ers-\
ter Kampf gegen\11Drachen?\12Ich zeige dir, wie\
stark sie sind!",
  ["53:4696"] = "Wie enttäuschend.",
  ["53:46a8"] = "Du hast SIEGFRIED,\
den Drachenmeister\12getroffen? Das\
kann nicht wahr\11sein.",
  ["53:46e5"] = "Die Chancen, gegen\
dich zu verlieren?\11Nicht mal ein Pro-\11zent!",
  ["53:4711"] = "Hm, eigenartig.",
  ["53:471d"] = "Ich kenne jetzt\
meine Schwachstel-\12len. Danke für den\
Hinweis!",
  ["53:4753"] = "Drachen sind hei-\
lige POKéMON.\12Sie sind voller\
Lebensenergie.\12Wenn du es nicht\
ernst meinst, dann\12wirst du sie nicht\
besiegen können.",
  ["53:47c0"] = "Großartig!",
  ["53:47cc"] = "Drachen sind\
schwach gegen Dra-\11chen-Attacken.",
  ["53:47fa"] = "Yo! CHAMP in spe!\12Es war eine lange\
Reise, aber bald\12sind wir da! Zähle\
auf mich!\12SANDRA setzt die\
mythischen und\11heiligen\11Drachen-POKéMON\11ein.\12So leicht sind die\
nicht zu besiegen.\12Aber angeblich\
sind sie anfällig\12gegen Eis-\
Attacken.",
  ["53:48e8"] = "Gegen SANDRA zu\
gewinnen ist eine\11Meisterleistung.\12Alles was dir nun\
noch bevorsteht,\11ist die POKéMON\11LIGA.\12Du bist auf dem\
besten Weg, der\11POKéMON-CHAMP\11zu werden!",
  ["53:4a3f"] = "Wir setzen nicht\
alle ausschließ-\11lich Drachen-POKé-\11MON ein.\12Meine Taktik ist\
es, POKéMON\12einzusetzen, die\
stärker sind als\11Drachen-POKéMON.",
  ["53:4aa9"] = "Du bist etwas Be-\
sonderes…",
  ["53:4abb"] = "Aber pass auf!\
Meine POKéMON wer-\11den noch mächti-\11ger.\12Sowohl als Trai-\
ner als auch als\11POKéMON-Team\11werden wir un-\11schlagbar sein.",
  ["53:4b20"] = "SANDRA unterzieht\
uns einem ausge-\11wogenen Training.\11Ich kann es mir\11nicht erlauben, zu\11verlieren.",
  ["53:4b69"] = "Arrrgh! Das ist\
verabscheuungs-\11würdig!",
  ["53:4b83"] = "Wow…\12Ich muss meinen\
Trainingsplan\12nochmals überden-\
ken…",
  ["53:4bad"] = "Der Felsen fiel\
hindurch!",
  ["53:4c64"] = "SANDRA und SIEG-\
FRIED haben hier\12trainiert, um ihre\
Fertigkeiten zu\11verfeinern.",
  ["53:4ca4"] = "DRATINI: Draa!",
  ["53:4d20"] = "Du kannst TOP-BE-\
LEBER zwar nicht\12kaufen, aber er\
füllt die KP be-\12siegter POKéMON\
wieder vollständig\11auf.\12Vorsicht! Die AP,\
oder ANGRIFFSPUNK-\12TE, werden nicht\
aufgefüllt.",
  ["53:4d9f"] = "TOP-SCHUTZ hält\
dir schwache POKé-\11MON vom Leib.\12Von allen SCHUTZ-\
Sprays hält es am\11längsten an.",
  ["53:4e3b"] = "Tief im Inneren\
des fernen INDIGO\12PLATEAUS befindet\
sich die POKéMON\11LIGA.\12Ich hörte, die\
besten Trainer des\12Landes versammeln\
sich dort.",
  ["53:4eb3"] = "Es gibt da eine\
Attacke, die ich\12unbedingt meinen\
POKéMON beibrin-\11gen musste.\12Also ging ich zum\
ATTACKEN-VERLER-\11NER, um eine VM-\11Attacke vergessen\11zu lassen.",
  ["53:4fa7"] = "PYRO, der ARENA-\
LEITER auf der\12ZINNOBERINSEL,\
lebt in einer Höh-\11le auf den SEE-\11SCHAUMINSELN…",
  ["53:4ff1"] = "Der Vulkanausbruch\
ist jetzt ein Jahr\11her.",
  ["53:507c"] = "Der Vulkan auf\
der ZINNOBERINSEL\11ist ausgebrochen.\12Durch die Eruption\
wurde die ROUTE 19\11durch Felsbrocken\11zugeschüttet.\12Ich frage mich,\
ob die Einwohner\11der ZINNOBERINSEL\11in Sicherheit\11sind…",
  ["53:50fc"] = "Auf der ZINNOBER-\
INSEL wurde\12niemand verletzt.\
Das ist großartig!",
  ["53:51ba"] = "PYRO: Wuah!\12Meine ARENA auf\
der ZINNOBERINSEL\11ist abgebrannt.\12Meine Feuer-POKé-\
MON und ich sind\12wegen des Vulkan-\
ausbruchs obdach-\11los.\12Buah!\12Aber ich führe\
meine Tätigkeit\12als ARENALEITER in\
dieser Höhle\11weiter aus.\12Wenn du mich\
besiegst, bekommst\11du einen ORDEN.\12Es wäre besser,\
du hast\11FEUERHEILER!",
  ["53:52b8"] = "PYRO: Gut gemacht.\
Ich bin\11ausgebrannt…\12Hier nimm den\
VULKANORDEN!",
  ["53:52f5"] = "{PLAYER} erhält\
VULKANORDEN.",
  ["53:530f"] = "PYRO: Diesmal habe\
ich verloren, aber\12beim nächsten Mal\
werde ich\11gewinnen.\12Ich werde meine\
ARENA auf der\12ZINNOBERINSEL\
wieder aufbauen\11und dann wirst du\11erneut gegen mich\11antreten.",
  ["53:538e"] = "PYRO: Meine Feuer-\
POKéMON werden\12noch stärker sein.\
Du wirst schon\11sehen!",
  ["53:53cb"] = "Jawohl!\12… Huh? Es ist\
schon vorüber?\12Sorry, Kumpel!\12Die ARENA auf der\
ZINNOBERINSEL\12existiert nicht\
mehr und ich\11wusste nicht, wo\11du steckst.\12Aber egal! Du\
bist auch ohne\12meinen Ratschlag\
zurechtgekommen.\11Ich wusste, du\11würdest gewinnen.",
  ["53:5477"] = "Eine POKéMON ARENA\
kann überall sein,\12solange der ARENA-\
LEITER dort ist.\12Man braucht dafür\
kein Gebäude.",
  ["53:5521"] = "…Du bist viel he-\
rumgekommen…\12Ich habe hier me-\
ditiert. In mir\12ist eine neue\
Kraft zum Leben\11erwacht.\12Lass mich meine\
Kraft mit deinen\12POKéMON teilen.\
Nimm dies, Kind.",
  ["53:55b4"] = "Siehst du es? Das\
ist KRAFTRESERVE!\12Sie bringt die\
wahre Kraft der\11POKéMON zum\11Vorschein.\12Vergiss nicht: Typ\
und Stärke der At-\11tacke hängen vom\11jeweiligen POKéMON\11ab.",
  ["53:5649"] = "Ich meditiere…",
  ["53:5704"] = "Der SEE DES ZORNS\
ist eigentlich ein\12Krater, der durch\
wütende GARADOS\11erschaffen wurde.\12Der Krater füllte\
sich mit Regenwas-\12ser und so ent-\
stand der See.\12Diese Geschichte\
erzählte schon\12der Ur-Urgroßvater\
meines Großvaters.\12Früher konnte man\
hier quicklebendi-\12ge KARPADORS fan-\
gen, aber…\12Ich verstehe\
nicht, was hier\11geschieht.",
  ["53:5823"] = "Der SEE hat sich\
verändert, seit\12diese Männer in\
Schwarz hier sind.",
  ["53:5866"] = "Der SEE DES ZORNS\
ist wieder normal.\12Die KARPADORS sind\
wieder zurück.\12Vielleicht geht\
nun mein Traum in\11Erfüllung, das\11größte KARPADOR\11der Welt zu sehen!\12Hast du eine\
ANGEL? Wenn ja,\11dann hilf mir\11bitte!",
  ["53:5914"] = "Ah, du hast ein\
KARPADOR! Lass uns\12sehen, wie groß\
das Kleine ist.",
  ["53:594d"] = "Wow! Das ist ja\
riesig!\12Ich ziehe meinen\
Hut vor dir!\12Nimm das als An-\
denken!",
  ["53:5999"] = "Wichtig ist nur\
die Erinnerung.\12Sieh es als eine\
Art Bonus!",
  ["53:59d7"] = "Wow! Das ist ja\
riesig!\12…Zumindest würde\
ich das gerne sa-\12gen, aber ich habe\
schon größere ge-\11sehen.",
  ["53:5a32"] = "Was? Das ist kein\
KARPADOR!",
  ["53:5a4f"] = "Oh… Du hast also\
keines, das es\12wert wäre, mir zu\
zeigen? Vielleicht\11beim nächsten Mal.",
  ["53:5af5"] = "Hier kamen nur\
Wanderer vorbei,\12die auf dem Weg\
zum SEE DES ZORNS\11waren.",
  ["53:5b3b"] = "In letzter Zeit\
geht niemand mehr\11zum SEE DES ZORNS.",
  ["53:5ca8"] = "Stehengeblieben!\12Der Wegzoll\
beträgt ¥1000.",
  ["53:5ce1"] = "Vielen Dank!",
  ["53:5cf2"] = "Dann zahle bitte,\
so viel du hast.",
  ["53:5d13"] = "Ha, ha, ha. Wir\
machen viel Geld.\12Jeder möchte\
wissen, was los\12ist am\
SEE DES ZORNS.",
  ["53:5d6d"] = "Diese Schläger-\
typen in Schwarz\11haben mich von\11meinem Posten\11verjagt.\12Sie haben das hier\
zurückgelassen.\12Ich bekomme bei\
diesem Ding eine\11Gänsehaut. Kannst\11du es bitte\11mitnehmen?",
  ["53:5dff"] = "Gehe durch dieses\
Tor. Dann meidest\11du das Gras.",
  ["54:4005"] = "Sammelst du ORDEN\
der PKMN-ARENEN\11von KANTO?",
  ["54:405a"] = "Ich habe gehört,\
dass ein zwielich-\11tiger Typ herum-\11schleichen soll.\12Ich werde nicht\
still halten, wenn\11sich herausstellt,\11dass er ein\11Dieb ist.",
  ["54:40c3"] = "Wir wurden von\
Räubern\11aufgehalten.",
  ["54:40e7"] = "DIGDA: Dig, Dig.",
  ["54:414d"] = "Mein Mann ist\
glücklich mit den\11POKéMON, die er im\11Tausch erhalten\11hat.",
  ["54:418a"] = "Ach… Ich bin so\
glücklich…",
  ["54:419c"] = "KANGAMA: Gamu\
gamu.",
  ["54:41b5"] = "ZUBAT: Zuba zuba.",
  ["54:4218"] = "ROUTE 9 führt\
nach Osten. Das\12KRAFTWERK liegt an\
ihrem Ende.",
  ["54:4257"] = "Mit einer Ge-\
schwindigkeit von\12über 550km/h reist\
der MAGNETZUG in\12null Komma nichts\
zwischen KANTO und\11JOHTO hin und her.\12Dadurch ist JOHTO\
ganz nah.",
  ["54:4453"] = "Ups! Tut ja so\
Leid mir! Du nicht\11verletzt, du O.K.?\12Ich schwer\
beschäftigt. Nicht\11Zeit für Reden.\11Nicht gut, wenn\11ich gesehen\11werden.",
  ["54:44cc"] = "Oh nein! Du mich\
schon hast gese-\11hen! Ich großes\11Fehler gemacht!",
  ["54:44fd"] = "He, du! Du ver-\
gessen, dass du\12mich gesehen, ja?\
Du nichts sehen,\12hören und wissen!\
Tschüss Kleiner!\12Und Tschüss!",
  ["54:4568"] = "Ich bin leider\
eine Zeit lang\11unterwegs. ARENA-\11LEITERIN, MISTY.",
  ["54:459a"] = "Nachdem MISTY\
nicht hier ist,\11sind wir TRAINER\11auch nicht da.",
  ["54:45cc"] = "MISTY: Ich habe\
dich erwartet, du\11Nervensäge!\12Du hast zwar\
viele ORDEN von\12JOHTO, aber unter-\
schätze mich\11lieber nicht!\12Meine Wasser-\
POKéMON sind hart!",
  ["54:4664"] = "MISTY: Du bist\
wirklich gut…\12Ich gebe zu, dass\
du sehr geschickt\11bist…\12Hier hast du den\
QUELLORDEN.",
  ["54:46c0"] = "{PLAYER} erhält\
QUELLORDEN.",
  ["54:46da"] = "MISTY: Gibt es\
viele starke\11Trainer wie dich\11in JOHTO?\12Eines Tages werde\
ich mich aufmachen\12und gegen einige\
ausgebildete\11Trainer kämpfen.",
  ["54:4762"] = "Es tut mir Leid,\
dass ich so lange\11weg war. Lass uns\11anfangen!",
  ["54:4790"] = "Ich gebe auf! Du\
hast gewonnen!",
  ["54:47ae"] = "Ich werde in Ruhe\
vor mich hin-\11schwimmen.",
  ["54:47c8"] = "Ich hoffe, meine\
elegante Art zu\11schwimmen zermürbt\11dich nicht.",
  ["54:47f7"] = "Oh, du hast mich\
ohne viel Auf-\11hebens erledigt…",
  ["54:4818"] = "Freue dich nicht\
zu sehr über\11deinen Sieg.\12MISTY wird dich\
fertig machen,\12wenn du selbst-\
gefällig wirst.",
  ["54:486a"] = "Glugger…\12Erster! Fang\
mich doch!",
  ["54:488c"] = "Das darf nicht\
wahr sein…",
  ["54:489b"] = "MISTY ist in den\
letzten Jahren\11immer besser\11geworden.\12Sei auf der Hut,\
sonst wirst du\11platt gemacht!",
  ["54:48ff"] = "He! Du CHAMP\
in spe!\12Nachdem MISTY weg\
war, bin ich auch\12los, um Spaß zu\
haben. Hi-hi-hi.",
  ["54:4952"] = "Oje, du bist\
ganz schön hart.\12Das war wie immer\
ein super Kampf!",
  ["54:4a25"] = "Du wirst auf dem\
Weg zum KAP bei\12AZURIA CITY viele\
Trainer treffen.\12Sie wollen heraus-\
finden, welche\12Chance sie gegen\
andere Trainer\11haben.",
  ["54:4a9e"] = "MISTY ist wahr-\
scheinlich die\12einzige, die die\
Trainer am KAP bei\11AZURIA CITY\11besiegen kann.",
  ["54:4b49"] = "Ein PKMN-CENTER\
neben einem\11Tunnel?\12Das ist sehr\
praktisch.",
  ["54:4b7e"] = "Der DIREKTOR des\
KRAFTWERKS sucht\12einen starken\
POKéMON-Trainer.\12Er braucht Hilfe\
bei der Suche nach\12einem gestohlenen\
Gegenstand.",
  ["54:4bf6"] = "Ich hörte, dass\
TEAM ROCKET sich\12in JOHTO re-\
formierte, aber\11kurz danach wieder\11zerschlagen wurde.\12Darüber weiß ich\
leider nichts.",
  ["54:4c64"] = "Wenn du das\
Gebäude verlässt,\12kannst du das Dach\
eines großen\11Hauses sehen.\12Das ist das\
KRAFTWERK.",
  ["54:4e31"] = "Ein Dieb ist in\
das KRAFTWERK\11eingebrochen…\12Was geschieht nur\
mit dieser Welt?",
  ["54:4e73"] = "Ich habe Nachricht\
aus AZURIA CITY.\12Eine zwielichtige\
Figur treibt sich\12dort in der\
Umgebung herum.",
  ["54:4ed0"] = "Kann ich mit\
deiner Unter-\11stützung rechnen?",
  ["54:4ef3"] = "Wir müssen mehr\
Wachpersonal\11einstellen.",
  ["54:4f20"] = "Ein wichtiges Teil\
des Generators\12wurde von dem\
Dieb entwendet.\12Ohne dieses Teil\
funktioniert der\11neue Genarator\11nicht!",
  ["54:4f89"] = "Der Generator\
funktioniert wie-\12der. Jetzt erzeu-\
gen wir genügend\11Energie.",
  ["54:4fca"] = "Das KRAFTWERK\
wurde vor langer\11Zeit stillgelegt.\12Wir haben es\
wieder in Betrieb\12genommen und ver-\
sorgen den MAGNET-\11ZUG mit Energie.",
  ["54:5040"] = "Der Generator\
läuft wieder!",
  ["54:505f"] = "Der DIREKTOR des\
KRAFTWERKS sitzt\11da vorne.\12Seit jemand den\
Generator demo-\11lierte, ist er\11traurig und wütend\11zugleich…",
  ["54:50d0"] = "Seit der Generator\
wieder läuft, ist\12der DIREKTOR\
wieder fröhlich.",
  ["54:5113"] = "Der MAGNETZUG\
verbraucht viel\11Energie.\12Ohne den neuen\
Generator fährt\11er nicht.",
  ["54:5176"] = "O.K. Der MAGNET-\
ZUG fährt\12wieder.",
  ["54:51b5"] = "DIREKTOR: Ich, ich\
werde ihm nie\11verzeihen!\12Wer wagt es,\
meinen Generator\11zu demolieren?\12Ich habe so lange\
daran gearbeitet!\12Wenn ich den\
erwische, dann\12lernt er meine\
BLITZKANONE\11kennen!",
  ["54:5259"] = "DIREKTOR: Das kann\
ich ihm nicht\11verzeihen!\12Der Schurke kann\
weinen und sich\12entschuldigen, ich\
werde ihn trotzdem\11bestrafen!\12Uahahaha!",
  ["54:52bf"] = "DIREKTOR: Ah!\
Oh ja!\12Das ist die\
fehlende SPULE\11meines geliebten\11Generators! Du\11hast sie gefunden?",
  ["54:5315"] = "Wahah! Danke!\12Als Belohnung gebe\
ich dir diese TM!",
  ["54:5345"] = "DIREKTOR: TM07\
enthält BLITZ-\12KANONE. Eine sehr\
starke Attacke!\12Sie ist nicht sehr\
präzise, aber du\12kannst jemanden\
damit ordentlich\11schmoren!",
  ["54:53c6"] = "DIREKTOR: Mein ge-\
liebter Generator!\12Produziere weiter\
viel Energie!",
  ["54:5612"] = "Hm? Kennst du\
BILL? Er ist mein\11Enkel.\12Er ist in JOHTO.\
Er kümmert sich\12um PCs und ich\
passe auf das\11Haus auf.",
  ["54:5676"] = "Hast du dieses\
POKéMON? Darf ich\11es sehen?",
  ["54:56a4"] = "Du zeigst es mir?\
Wie lieb von dir!",
  ["54:56c8"] = "Du hast es nicht?\
Das ist schade…",
  ["54:56ea"] = "Ah, das ist\
{STRBUF}?\12Ist das nicht\
niedlich!\11Das ist nett \11von dir.",
  ["54:5725"] = "Danke!\12Das ist ein\
Zeichen meiner\11Anerkennung.",
  ["54:5752"] = "Besuche mich bitte\
wieder.",
  ["54:576e"] = "Danke, dass du mir\
so viele niedliche\11POKéMON gezeigt\11hast.\12Ich habe mich\
wirklich amüsiert.\12Ich bin froh, dass\
ich das noch\11erleben durfte.",
  ["54:57d5"] = "Hm?\12Das ist nicht das\
POKéMON, von dem\11ich gehört habe.",
  ["54:5804"] = "Mein Enkel BILL\
hat mir von einem\12POKéMON mit einer\
langen Zunge\11erzählt.",
  ["54:5843"] = "Ah, mein Enkel\
erwähnte ein\12rundes, grünes \
POKéMON, auf\11dessen Kopf Blät-\11ter wachsen.",
  ["54:5897"] = "Kennst du ein\
Wasser-POKéMON\12mit einer roten\
Kugel im Körper?\12Es sieht aus wie\
ein Stern!\12Ich hörte, es\
taucht nachts auf.\12Ich würde es\
gerne sehen.",
  ["54:5942"] = "BILL erzählte mir\
von einem POKéMON,\12das seinem Trainer\
gegenüber sehr\11loyal ist.\12Es scheint ein\
guter BRÜLLER zu\11sein.",
  ["54:599b"] = "Ich hörte von\
einem niedlichen\11POKéMON, das\11sechs Schwänze\11hat.\12So ein niedliches\
POKéMON würde ich\11gerne umarmen.",
  ["54:59f5"] = "Kennst du dieses\
sehr beliebte\11POKéMON?\12Das POKéMON, mit\
dem gelben Körper\11und den roten\11Wangen.\12Ich würde gerne\
sehen, wie es vor\12seiner Entwicklung\
aussieht.",
  ["55:4013"] = "Beherrschen deine\
POKéMON VM-\11Attacken?\12Diese Attacken\
können auch einge-\12setzt werden, wenn\
dein POKéMON be-\11siegt worden ist.",
  ["55:4067"] = "Auf BILLs PC kön-\
nen bis zu 20\11POKéMON pro BOX\11gelagert werden.",
  ["55:4092"] = "Weißt du über\
APRIKOKOS Be-\11scheid?\12Brich eine auf,\
höhle sie aus und\12verbinde sie mit\
einer speziellen\11Vorrichtung.\12Dann kannst du\
POKéMON damit\11fangen.\12Vor der Erfindung\
von POKéBÄLLEN hat\12jeder APRIKOKOS\
verwendet.",
  ["55:41ed"] = "Alle FLEGMONS sind\
aus der Stadt ver-\11schwunden.\12Vielleicht ist der\
Patron des Waldes\11zornig auf uns…\12Es kann ein böses\
Omen sein. Besser,\11wir bleiben zu\11Hause.",
  ["55:4276"] = "Die FLEGMONS sind\
zurückgekehrt…\12Aber mein LEHRLING\
kam noch nicht aus\11dem STEINEICHEN-\11WALD zurück.\12Wo in aller Welt\
steckt der faule\11Kerl?",
  ["55:42ec"] = "Du hast TEAM\
ROCKET vertrieben\12und bist allein in\
den STEINEICHEN-\11WALD gegangen?\12Du hast ja Mut!\
Das mag ich! Komm,\11trainiere mit uns.",
  ["55:4359"] = "Wo sind nur all\
die FLEGMONS hin?\12Sind sie irgendwo\
zum Spielen hinge-\11gangen?",
  ["55:439e"] = "Es tut mir Leid.\
Ich habe dir noch\11nicht gedankt.\12Das ist HOLZKOHLE,\
die ich selbst ge-\11macht habe.\12Feuer-POKéMON\
wären froh, so et-\11was halten zu\11dürfen.",
  ["55:440c"] = "Die FLEGMONS sind\
wieder da, und du\11hast auch PORENTA\11gefunden.\12Du bist der\
Coolste!",
  ["55:445e"] = "PORENTA: Kwaa!",
  ["55:44c6"] = "Hier gibt es keine\
SUPERBÄLLE. Ich\12werde mit POKé-\
BÄLLEN auskommen\11müssen.\12Ich wünschte, KURT\
würde mir einen\11seiner BÄLLE\11machen.",
  ["55:452f"] = "Ein SUPERBALL eig-\
net sich besser\11zum Fangen von\11POKéMON als ein\11POKéBALL.\12Aber manchmal sind\
KURTs BÄLLE\11besser.",
  ["55:47ee"] = "Hm? Wer bist du?\12{PLAYER}, was? Du\
willst, dass ich\11ein paar BÄLLE\11mache?\12Verzeih, aber das\
muss warten.\12Kennst du TEAM\
ROCKET? Egal, ich\12erzähle dir ohne-\
hin darüber.\12TEAM ROCKET ist\
eine üble Bande,\12die POKéMON für\
ihre Zwecke ein-\11setzt.\12Man sagt, dass sie\
sich vor drei Jah-\11ren aufgelöst\11haben.\12Aber jetzt sind\
sie am BRUNNEN\12und schneiden die\
RUTEN von FLEGMONS\12ab, um sie zu ver-\
kaufen!\12Also werde ich\
ihnen eine Lektion\11erteilen!\12Haltet durch,\
FLEGMONS! Der alte\11KURT ist auf dem\11Weg!",
  ["55:4990"] = "KURT: Hi, {PLAYER}!\12Du hast dich am\
BRUNNEN wie\11ein wahrer Held\11benommen.\12Ich mag deinen\
Stil!\12Es wäre mir eine\
Ehre, für einen\12Trainer wie dich\
BÄLLE anzuferti-\11gen.\12Das ist alles, was\
ich habe. Aber\11bitte nimm es!",
  ["55:4a44"] = "KURT: Ich mache\
BÄLLE aus APRIKO-\11KOS.\12Pflücke sie von\
Bäumen und bring\11sie zu mir.\12Ich fertige daraus\
BÄLLE an.",
  ["55:4ab1"] = "KURT: Hast du eine\
APRIKOKO für mich?\12Schön! Ich werde\
einen BALL daraus\11machen.",
  ["55:4af4"] = "KURT: Ich werde\
einen Tag brau-\12chen, um einen\
BALL zu machen.\12Komm später wie-\
der!",
  ["55:4b37"] = "KURT: Oh…\
Du lässt mich im\11Stich?",
  ["55:4b53"] = "KURT: Ich arbeite!\
Stör mich nicht!",
  ["55:4b76"] = "KURT: Ah, {PLAYER}!\
Ich bin gerade\11fertig geworden.\11Hier hast du den\11BALL!",
  ["55:4ba5"] = "KURT: Er ist groß-\
artig geworden.\12Versuche, ein\
POKéMON damit\11zu fangen.",
  ["55:4bde"] = "Die FLEGMONS sind\
verschwunden… Wur-\12den sie von bösen\
Leuten gestohlen?",
  ["55:4c1a"] = "Großvater ist\
fort… Ich fühle\11mich so einsam…",
  ["55:4c38"] = "Das FLEGMON, das\
mir mein Vater\12gab, ist wieder\
da. Auch seine\12RUTE wächst wieder\
nach!",
  ["55:4c7e"] = "Papa arbeitet für\
SILPH CO., wo er\11POKéBÄLLE analy-\11siert.\12Ich muss mit Groß-\
vater und FLEGMON\11zu Hause bleiben.",
  ["55:4cdb"] = "FLEGMON: …\
Gähn?",
  ["55:4cee"] = "…Ein junger PROF.\
EICH?",
  ["55:4d03"] = "Eine Statue des\
Waldpatrons.",
  ["55:4e83"] = "Ich bin KAI!\
Ich verliere nie,\12wenn es um Käfer-\
POKéMON geht.\12Meine Forschungen\
machen mich zu ei-\12ner Autorität auf\
diesem Gebiet!\12Lass mich demonst-\
rieren, was ich\11gelernt habe!",
  ["55:4f26"] = "Erstaunlich!\
Du bist ein wahrer\11POKéMON-Experte!\12Meine Forschungen\
sind noch nicht\11abgeschlossen.\12O.K., du gewinnst.\
Nimm diesen ORDEN.",
  ["55:4f8c"] = "{PLAYER} erhält\
INSEKTORDEN.",
  ["55:4fa3"] = "Kennst du die Vor-\
züge des INSEKT-\11ORDENS?\12Durch ihn gehor-\
chen dir POKéMON\11bis zu Level 30.\12Deine POKéMON\
können ZERSCHNEI-\12DER nun auch\
außerhalb des\11Kampfes anwenden.\12Bitte nimm auch\
dies!",
  ["55:5060"] = "TM49 enthält\
ZORNKLINGE.\12Wird das Ziel ge-\
troffen, gewinnt\11die Attacke jede\11Runde an Stärke.\12Je länger der\
Kampf dauert, des-\11to besser wird der\11Angriff.\12Ist das nicht\
toll? Ich selbst\11habe diese Ent-\11deckung gemacht!",
  ["55:50fe"] = "Käfer-POKéMON\
sind ein weites\12Gebiet. Es gibt\
noch viele Geheim-\12nisse zu er-\
gründen.\12Studiere deine\
Lieblinge gründ-\11lich!",
  ["55:515e"] = "Käfer-POKéMON\
entwickeln sich\12sehr früh. Das\
heißt, dass sie\12auch schnell stär-\
ker werden.",
  ["55:519d"] = "Entwicklung allein\
ist nicht genug!",
  ["55:51b9"] = "POKéMON werden\
stärker, wenn sie\11sich entwickeln.\11Wirklich!",
  ["55:51e7"] = "Käfer-POKéMON\
sind cool und\12tough! Ich beweise\
es dir!",
  ["55:521a"] = "Du hast bewiesen,\
wie tough du bist…",
  ["55:5239"] = "Sie sind so cool,\
aber die meisten\12Mädchen mögen kei-\
ne Käfer-POKéMON.\12Ich weiß nicht,\
wieso…",
  ["55:527e"] = "Du hast die FLEG-\
MONS gerettet? Oh\11Mann, bist du\11stark!\12Aber meine ausge-\
wachsenen POKéMON\11sind auch sehr\11stark!",
  ["55:52da"] = "Urrgggh!",
  ["55:52e4"] = "Vielleicht sollte\
ich sie ein wenig\11besser trainieren…",
  ["55:530f"] = "EVA: Hi! Forderst\
du etwa den LEITER\11heraus?",
  ["55:5341"] = "EVA & UTE: Oh, um\
Himmels Willen!",
  ["55:5362"] = "EVA: Du bist wirk-\
lich stark!",
  ["55:537d"] = "UTE: Du willst den\
LEITER sehen? Aber\11wir kommen zuerst!",
  ["55:53ae"] = "EVA & UTE: Um\
Himmels Willen!",
  ["55:53cf"] = "UTE: Unsere Käfer-\
POKéMON haben ver-\11loren! Was für ei-\11ne Schande!",
  ["55:53fc"] = "Yo, Herausfor-\
derer!\12KAI ist zwar jung,\
aber sein Wissen\12über Käfer-POKé-\
MON ist unüber-\11trefflich.\12Ohne meine Tipps\
wird der Kampf für\11dich sehr hart.\12Mal sehen… Käfer-\
POKéMON mögen kein\11Feuer.\12Auch Flug-Attacken\
sind sehr effek-\11tiv.",
  ["55:54bf"] = "Gut gemacht! Das\
war ein Muster-\12kampf zweier ta-\
lentierter, junger\11Trainer.\12Mit Leuten wie dir\
sieht die Zukunft\11der POKéMON rosig\11aus!",
  ["56:400f"] = "Fängst du ein\
POKéMON, ist es\11vermutlich sehr\11schwach.\12Aber letztendlich\
wird es wachsen\11und stärker\11werden.\12Es ist wichtig,\
POKéMON sehr viel\11Liebe zu schenken.",
  ["56:4090"] = "POKéMON können\
Items wie TRANK\11und GEGENGIFT\11tragen.\12Aber offenbar sind\
sie nicht in der\12Lage, künstlich\
hergestellte Items\12zu benutzen.",
  ["56:41e0"] = "Ich bin FALK, der\
ARENALEITER von\11VIOLA CITY!\12Man sagt, dass man\
die Flügel von\12Flug-POKéMON mit\
einem elektrischen\12Blitz stutzen\
kann…\12So etwas werde ich\
niemals zulassen!\12Ich werde dich die\
wahre Kraft der\12Flug-POKéMON\
spüren lassen!",
  ["56:42b7"] = "…Verflixt! Mein\
Vater hat Flug-\11POKéMON geliebt…\12Also gut.\
Nimm dies!\12Es ist der offi-\
zielle FLÜGELORDEN\11der POKéMON\11LIGA.",
  ["56:431c"] = "{PLAYER} erhält den\
FLÜGELORDEN.",
  ["56:4335"] = "Der FLÜGELORDEN\
stärkt den ANGR-\11Wert deiner POKé-\11MON.\12Außerdem können\
deine POKéMON\12jederzeit BLITZ\
einsetzen.\12Hier - ich habe\
noch etwas für\11dich.",
  ["56:43b5"] = "Benutzt ein POKé-\
MON eine TM, er-\12lernt es sofort\
eine neue Attacke.\12Überlege dir den\
Einsatz gut - eine\11TM kann nur einmal\11eingesetzt werden.\12TM31 enthält\
LEHMSCHELLE.\12Sie fügt dem Geg-\
ner Schaden zu und\12reduziert gleich-\
zeitig seine Ge-\11nauigkeit.\12Mit anderen Wor-\
ten: Sie ist\11sowohl defensiv\11als auch offensiv.",
  ["56:44a2"] = "In so mancher\
Stadt warten noch\11ARENEN auf dich.\12Du solltest dein\
Können in diesen\11ARENEN beweisen.\12Ich werde noch\
härter trainieren,\12um der größte Vo-\
gel-Experte aller\11Zeiten zu werden!",
  ["56:453a"] = "Das Motto lautet:\
Courage!\12Sie alle hier üben\
Tag und Nacht,\12um Vogel-Meister-\
Trainer zu werden.\12Komm schon!",
  ["56:459c"] = "Gaaah!",
  ["56:45a4"] = "FALKs Fähigkeiten\
sind unübertreff-\11lich!\12Du solltest dich\
nicht überschät-\11zen, nur weil du\11mich geschlagen\11hast!",
  ["56:45ec"] = "Lass mich heraus-\
finden, ob du gut\11genug bist, um ge-\11gen FALK anzutre-\11ten!",
  ["56:4620"] = "Das kann nicht\
wahr sein!",
  ["56:4634"] = "Das ist peinlich!\
Von einem Anfänger\11besiegt…",
  ["56:4666"] = "Hey! Zwar bin ich\
kein Trainer, aber\11ich kann dir gute\11Tipps geben!\12Glaube mir!\
Wenn du es tust,\12kann dein Traum\
von der Meister-\12schaft in Erfül-\
lung gehen.\12Du glaubst mir?\
Dann pass auf!\12Typ Pflanze ist\
schwach gegen Typ\12Flug. Das solltest\
du dir merken.",
  ["56:4735"] = "Netter Kampf! Mach\
weiter so und bald\12schon wirst du der\
CHAMP sein!",
  ["56:48a8"] = "EARL, so lautet\
mein Name!\12Wunderbar sind\
POKéMON, oui!\12Isch werde dir\
beibringen, ein\12besserer Trainer\
zu werden!\12Was möchtest du\
wissen? Willst ein\11Gewinner du sein?",
  ["56:492a"] = "Gut! So lass misch\
dir erklären!\12Im Kampf wird das\
erste POKéMON auf\11der Liste begin-\11nen!\12Ändere die Auf-\
stellung in der\11Liste, um dich den\11Gegebenheiten an-\11zupassen!\12Möschtest du noch\
mehr ören?",
  ["56:49be"] = "Du möschtest also\
wissen, wie man\11POKéMON rischtisch\11trainiert?",
  ["56:49e8"] = "Gut! So lass misch\
erklären!\12Selbst, wenn ein\
POKéMON nur kurz\12an einem Kampf\
teilnimmt, erhält\11es einige EP.\12Platziere schwache\
POKéMON an der\12Spitze der Liste.\
Tausche sie dann\12im Kampf gegen ein\
anderes POKéMON.\12So können auch\
schwache POKéMON\11stark werden!",
  ["56:4a9e"] = "Oh! Du bist eine\
schlaue Schüler!\11Isch kann dir nun\11nischts mehr bei-\11bringen.\12Sei lieb zu deinen\
POKéMON!",
  ["56:4aed"] = "Ich mache mir No-\
tizen über die\11Ausführungen.\12Besser, ich\
schreibe auch\11alles von der Ta-\11fel ab.",
  ["56:4b47"] = "Ich tauschte mein\
bestes PKMN mit\11diesem Kerl.",
  ["56:4b74"] = "Hä? Das POKéMON,\
das ich bekommen\11habe, hält etwas!",
  ["56:4ba6"] = "Ein POKéMON, das\
eine BEERE hält,\11wird sich im Kampf\11selbst heilen.\12Noch viele andere\
Items können von\11POKéMON gehalten\11werden…\12Es ist nicht ein-\
fach, sich all\11diese Notizen zu\11machen…",
  ["56:4c1f"] = "Auf der Tafel wer-\
den die Statusver-\12änderungen von\
POKéMON während\12eines Kampfes er-\
klärt.",
  ["56:4c6b"] = "Wird ein POKéMON\
vergiftet, ver-\11liert es ständig\11KP.\12Die Vergiftung\
dauert auch nach\12dem Kampf noch an\
und es verliert\11weiterhin KP.\12Um es zu heilen,\
musst du GEGENGIFT\11einsetzen.",
  ["56:4ced"] = "Paralyse reduziert\
die Geschwindig-\11keit und verhin-\11dert eventuell\11jede Bewegung.\12Sie dauert nach\
dem Kampf noch an,\11also setze einen\11PARAHEILER ein.",
  ["56:4d4f"] = "Schläft ein POKé-\
MON, kann es nicht\11angreifen.\12Es wacht auch nach\
dem Kampf nicht\11auf.\12Wecke es mit Hilfe\
von AUFWECKER\11wieder auf.",
  ["56:4dc2"] = "Eine Verbrennung\
lässt die KP ste-\12tig sinken und re-\
duziert die An-\11griffskraft.\12Die Verbrennung\
bleibt nach dem\11Kampf bestehen.\12Verwende einen\
FEUERHEILER zur\11Heilung.",
  ["56:4e38"] = "Hat dein POKéMON\
Erfrierungen er-\11litten, ist es zu\11keiner Handlung\11fähig.\12Die Erfrierung\
hält auch nach dem\11Kampf an.\12Um es aufzutauen,\
verwende einen\11EISHEILER.",
  ["56:4ea3"] = "Es ist das Notiz-\
buch dieses Kin-\11des…\12Fange POKéMON\
mit POKéBÄLLEN.\12Bis zu sechs kön-\
nen sich gleich-\12zeitig im Team be-\
finden.\12Weiterlesen?",
  ["56:4f04"] = "Bevor man den\
POKéBALL wirft,\11muss das Ziel ge-\11schwächt werden.\12Ein vergiftetes\
oder verbranntes\11POKéMON kann\11leichter gefangen\11werden.\12Weiterlesen?",
  ["56:4f74"] = "Manche Attacken\
verwirren dein\11POKéMON.\12Ein verwirrtes\
POKéMON kann sich\11auch selbst ver-\11letzen.\12Nach einem Kampf\
endet auch die\11Verwirrung.\12Weiterlesen?",
  ["56:4ff4"] = "Leute, die POKé-\
MON fangen und in\12Kämpfen einsetzen,\
nennt man POKé-\11MON-Trainer.\12Man erwartet von\
ihnen, dass sie\12ARENEN besuchen\
und gegen andere\11Trainer antreten.\12Die nächste Seite\
ist… leer!\12Junge: E-he-he…\12Mehr habe ich\
nicht aufgeschrie-\11ben…",
  ["56:5167"] = "Sie verwendet die\
Namen ihrer Lieb-\11lingsspeisen,\12als Spitznamen für\
ihre POKéMON,\11meine ich.",
  ["56:51cb"] = "Ich nenne mein\
TAUBSI ERDBEERE!",
  ["56:51e9"] = "ERDBEERE: Taubsii!",
  ["56:52c2"] = "{PLAYER}, lange\
nicht gesehen.\12PROF. LIND hat\
mich gebeten, nach\11dir zu suchen.\12Er hat noch eine\
Bitte an dich.\12Nimm bitte das\
POKéMON-EI!",
  ["56:5332"] = "Wir haben ent-\
deckt, dass ein\12POKéMON erst\
schlüpft, nachdem\12es im EI gewachsen\
ist.\12Außerdem muss es\
sich in der Nähe\11anderer POKéMON\11befinden, um zu\11schlüpfen.\12{PLAYER}, du bist\
die einzige Per-\11son, auf die wir\11uns verlassen\11können.\12Bitte ruf PROF.\
LIND an, wenn das\11EI so weit ist!",
  ["56:5400"] = "Oh, du hast keinen\
Platz mehr für ein\11weiteres POKéMON.\12Ich warte hier,\
bis du Platz für\11das EI geschaffen\11hast.",
  ["56:545f"] = "A-Aber… PROF.\
LIND hat nach dir\11gefragt…",
  ["56:547f"] = "{PLAYER}, nimmst du\
das EI?",
  ["56:549a"] = "Ein Kerl namens\
BILL hat das\12POKéMON-PC-Lage-\
rungs-System\12erfunden.",
  ["56:54cd"] = "Es war vor etwa\
drei Jahren.\12TEAM ROCKET hatte\
etwas Übles mit\11den POKéMON vor.\12Aber die Gerech-\
tigkeit hat ge-\11siegt! Ein junger\11Trainer hat sie\11zerschlagen.",
  ["56:5549"] = "POKéMON sind\
schlau. Sie gehor-\12chen nur Trainern,\
vor denen sie auch\11Respekt haben.\12Hat der Trainer\
nicht genug ORDEN,\12machen sie, was\
sie wollen.",
  ["56:5628"] = "Ein POKéMON, das\
du durch Tausch\11erhalten hast,\11wird schneller\11wachsen.\12Aber wenn du nicht\
im Besitz des pas-\12senden ORDENS\
bist, gehorchen\11sie dir vielleicht\11nicht.",
  ["56:56c7"] = "ALPH-RUINEN\12Eine Besichti-\
gungsstätte\11für Touristen.\12Versuche, die\
schwenkbaren\12Steintafeln\
zu bewegen!",
  ["56:5712"] = "Du untersuchst\
die RUINEN?\12Ich sehe einen\
Wissenschaftler\11in spe.",
  ["56:574e"] = "Auf den\
Steintafeln\11sind Zeichnungen.\12Ich versuchte, \
sie zu bewegen.\12Ich frage mich, \
was sie\11darstellen.",
  ["56:5814"] = "Das ist ein\
hervorragender\11Platz zum Angeln.\12Du hast Leute\
beim Angeln\12gesehen? Wie\
steht es mit dir?\12Hättest du gerne\
eine ANGEL\11von mir?",
  ["56:5879"] = "He! Das höre ich\
wirklich gerne!\12Jetzt bist du\
auch ein Angler!",
  ["56:58ac"] = "Angeln ist toll!\12Probiere überall,\
wo Wasser ist,\12deine ANGEL aus;\
sei es am Meer\12oder an einem\
Fluss.",
  ["56:58fd"] = "Na, das ist aber\
ziemlich mager…",
  ["56:591e"] = "He, Kleiner. Wie\
beißen sie?",
  ["56:5943"] = "Was soll mein\
POKéMON tragen?\12Vielleicht ein\
Item, das seinen\12ANGR-Wert\
verstärkt…",
  ["56:5a70"] = "Entschuldige,\
mein Freund!\11Könntest du mir\11einen Gefallen\11tun?\12Könntest du dieses\
POKéMON, das einen\11BRIEF trägt,\11zu meinem Freund\11bringen?\12Du findest ihn\
auf ROUTE 31.",
  ["56:5adb"] = "Das würdest du\
tun? Super!\11Vielen Dank!\12Mein Freund ist\
ein Flegel!\11Er schläft die\11ganze Zeit.\12Du wirst ihn\
sofort erkennen!",
  ["56:5b4b"] = "{PLAYER} hat ein\
POKéMON, das einen\12BRIEF trägt,\
erhalten.",
  ["56:5b69"] = "Du darfst ihn le-\
sen, aber verliere\11ihn nicht!\11ROUTE 31!\12Stimmt! Ein\
merkwürdiger\11Baum hat die\11Straße blockiert.\12Ich frage mich,\
ob die Straße\11jetzt frei ist.",
  ["56:5be9"] = "Du kannst kein\
weiteres POKéMON\11mehr tragen…",
  ["56:5c07"] = "Oh… Dann\
geht das in\11Ordnung.…",
  ["56:5c1e"] = "Ich danke dir!\
Du hast die\11Lieferung für mich\11erledigt!\12Ich habe hier\
etwas für dich\11wegen der Un-\11annehmlichkeiten!",
  ["56:5c6c"] = "Mein Freund hat\
geschlafen, nicht\11wahr? Na, was\11habe ich dir\11gesagt?",
  ["56:5c9d"] = "Ein merkwürdiger\
Baum blockiert die\11Straße.\12Er fängt an zu\
zappeln, wenn man\11ihn anspricht.\12Ich habe gehört,\
dass er rasend\11wurde, als ihn\12jemand mit Wasser\
aus einer\11SCHIGGYKANNE\11begossen hat.",
  ["56:5d2d"] = "Ich mag das POKé-\
MON-Schlaflied,\11das im Radio\11gespielt wird.",
  ["56:5ef2"] = "Heute ist\
{STRBUF}.\11Das heißt, heute\12findet das Käfer-\
turnier statt.\12Die Regeln sind\
einfach.\12Fange ein Käfer-\
POKéMON mit einem\11deiner eigenen\11POKéMON.\12Das Käfer-POKéMON\
wird dann von der\11Jury bewertet.\12Möchtest du es\
versuchen?",
  ["56:5fa4"] = "Hier sind die\
PARKBÄLLE für das\11Turnier.",
  ["56:5fce"] = "{PLAYER} erhält\
20 PARKBÄLLE.",
  ["56:5fe9"] = "Wer das stärkste\
Käfer-POKéMON\11fängt, hat \11gewonnen.\12Du hast 20\
Minuten Zeit.\12Wenn du keine\
PARKBÄLLE mehr\11hast, ist das\11Turnier beendet.\12Du darfst das\
letzte POKéMON,\11das du gefangen\11hast, behalten.\12Los! Fang das\
stärkste Käfer-\12POKéMON, das du\
finden kannst!",
  ["56:60cd"] = "Oh, oh…\12Du hast mehr als\
ein POKéMON.\12Du musst\
{STRBUF}\12auswählen - dein\
erstes POKéMON\12Bist du damit\
einverstanden?",
  ["56:613e"] = "Gut. Wir passen\
währenddessen auf\11deine anderen\11POKéMON auf.",
  ["56:6172"] = "Die POKéMON von\
{PLAYER} wurden dem\11TURNIERHELFER\11übergeben.",
  ["56:619e"] = "Wähle bitte das\
POKéMON, mit dem\12du im Turnier\
antreten möchtest,\11aus und komm dann\11wieder.",
  ["56:61e3"] = "Na gut. Wir\
hoffen, dass du\11später einmal\11am Turnier teil-\11nimmst.",
  ["56:620f"] = "Oh, oh…\
Das erste POKéMON\12deines Teams kann\
nicht am Turnier\11teilnehmen.\12Tausche es bitte\
mit dem POKéMON\12aus, das am\
Turnier teilnehmen\12soll und komm dann\
wieder.",
  ["56:6283"] = "Oh, oh…\
Dein Team und\12deine PC-BOX sind\
voll besetzt.\12Du hast keinen\
Platz für ein\11Käfer-POKéMON,\11das du fängst.\12Schaffe Platz in\
deinem Team oder\12in deiner PC-BOX\
und komm dann\11wieder.",
  ["56:6326"] = "Oh, oh…\
Ein EI ist an\12erster Stelle in\
deinem Team.\12Tausche es bitte\
mit dem POKéMON,\12das du im Turnier\
einsetzen möchtest\12und komm dann\
wieder.",
  ["56:63a1"] = "Du hast noch {STRBUF}\
Minute(n).\12Möchtest du jetzt\
aufhören?",
  ["56:63e2"] = "Gut. Warte bitte\
am Nordtor auf\12die Bekanntgabe\
der Sieger.",
  ["56:642a"] = "Gut. Geh bitte\
wieder zurück nach\11draußen und komm\11zum Ende.",
  ["56:6456"] = "Das heutige\
Turnier ist be-\12endet. Wir hoffen,\
dass du wieder\11daran teilnehmen\11wirst.",
  ["56:649b"] = "Die Turniere\
werden regelmäßig\12hier im PARK\
abgehalten. Nimm\11doch auch daran\11teil!",
  ["56:64df"] = "Wann findet das\
nächste Käfer-\11turnier\11statt?",
  ["56:6515"] = "Das Käferturnier\
findet jeden\12Dienstag,\
Donnerstag und\11Samstag statt.\12Du erhältst nicht\
nur einen Preis\12allein für die\
Teilnahme, sondern\12auch ein Käfer-\
POKéMON, das du\11dort fängst.",
  ["56:660d"] = "Fragst du dich\
nicht, wer so\11etwas tun sollte\11und warum?",
  ["56:6648"] = "Hast du diesen\
merkwürdigen Baum\12auf der Straße\
gesehen?\12Das könnte\
erklären, weshalb\12immer weniger\
Menschen die\12ALPH-RUINEN\
besuchen.",
  ["56:69c0"] = "Heute ist\
{STRBUF}.\12Das bedeutet, dass\
heute das Käfer-\11turnier statt-\11findet.\12Die Regeln sind\
einfach.\12Fange ein Käfer-\
POKéMON mit einem\11deiner eigenen\11POKéMON.\12Das Käfer-POKéMON\
wird dann von der\11Jury bewertet.\12Möchtest du es\
einmal versuchen?",
  ["56:6a70"] = "Hier sind die\
PARKBÄLLE für das\11Turnier.",
  ["56:6a9a"] = "{PLAYER} erhält\
20 PARKBÄLLE.",
  ["56:6ab5"] = "Wer das stärkste\
Käfer-POKéMON\11fängt, hat \11gewonnen.\12Du hast 20\
Minuten Zeit.\12Wenn du keine\
PARKBÄLLE mehr\11hast, ist das\11Turnier beendet.\12Du darfst das\
letzte POKéMON,\11das du gefangen\11hast, behalten.\12Los! Fang das\
stärkste Käfer-\12POKéMON, das du\
finden kannst!",
  ["56:6b99"] = "Oh, oh…\12Du hast mehr als\
ein POKéMON.\12Du musst\
{STRBUF}\12auswählen - dein\
erstes POKéMON\12Bist du damit\
einverstanden?",
  ["56:6c0a"] = "Gut. Wir passen\
währenddessen auf\11deine anderen\11POKéMON auf.",
  ["56:6c3e"] = "Die POKéMON von\
{PLAYER} wurden dem\11TURNIERHELFER\11übergeben.",
  ["56:6c6a"] = "Wähle bitte das\
POKéMON, mit dem\12du im Turnier\
antreten möchtest\11aus und komm dann\11wieder.",
  ["56:6caf"] = "Na gut. Wir\
hoffen, dass du\11später einmal\11am Turnier teil-\11nimmst.",
  ["56:6cdb"] = "Oh, oh…\
Das erste POKéMON\12deines Teams kann\
nicht am Turnier\11teilnehmen.\12Tausche es bitte\
mit dem POKéMON\12aus, das am\
Turnier teilnehmen\11soll und komm dann\12wieder.",
  ["56:6d4f"] = "Oh, oh…\
Dein Team und\12deine PC-BOX sind\
voll besetzt.\12Du kannst ein\
Käfer-POKéMON,\11das du fängst,\11nirgends ablegen.\12Schaffe Platz in\
deinem Team oder\12in deiner PC-BOX\
und komme dann\11wieder.",
  ["56:6df2"] = "Oh, oh…\
Ein EI ist an\12erster Stelle in\
deinem Team.\12Tausche es bitte\
mit dem POKéMON\12aus, das am\11Turnier teilnehmen\
soll und komm dann\11wieder.",
  ["56:6e6d"] = "Du hast noch {STRBUF}\
Minute(n).\12Möchtest du jetzt\
aufhören?",
  ["56:6eac"] = "Gut. Warte bitte\
hier auf die\12Bekanntgabe\
der Sieger.",
  ["56:6ee7"] = "Gut. Geh bitte\
wieder zurück nach\11draußen und komm\11zum Ende.",
  ["56:6f12"] = "Das heutige\
Turnier ist be-\12endet. Wir hoffen,\
dass du wieder\11daran teilnehmen\11wirst.",
  ["56:6f57"] = "Manche POKéMON\
kann man nur im\11PARK antreffen.",
  ["56:6f80"] = "ULI: Wow, du hast\
mich besiegt! Du\11bist sehr gut!",
  ["56:6fab"] = "ULI: Glück spielt\
natürlich eine\11große Rolle dabei.\12Man weiß nie,\
welches POKéMON\11auftauchen wird.",
  ["56:6ff6"] = "ALAN: Ich beneide\
dich. Dieses Mal\11habe ich es\11einfach nicht\11geschafft.",
  ["56:7027"] = "ALAN: Du gewinnst\
vielleicht mit\11großen POKéMON?",
  ["56:7049"] = "LARS: Gut gemacht!\
Ich werde meine\11POKéMON besser\11trainieren.",
  ["56:707d"] = "LARS: Vielleicht\
erhältst du eine\12höhere Wertung für\
ein POKéMON mit\11ungewöhnlicher\11Farbe.",
  ["56:70c1"] = "WILHELM: Du bist\
der Sieger? Was\11hast du gefangen?",
  ["56:70f1"] = "WILHELM: Also, ich\
bin zufrieden,\12denn ich habe ein\
POKéMON gefangen,\11das ich haben\11wollte.",
  ["56:7135"] = "AXEL: Meine\
Gratulation! Du\11verdienst meinen\11ganzen Respekt!",
  ["56:7163"] = "AXEL: Ich habe\
vorher ein SICHLOR\11gefangen. Aber ich\11konnte nicht\11siegen.",
  ["56:7197"] = "TILL: Das POKé-\
MON, das du\11gefangen hast…\11Das ist cool!",
  ["56:71c4"] = "TILL: Mit einem\
Käfer-POKéMON, das\12einen hohen Level\
hat, steigen deine\11Gewinnchancen.\12Ich glaube aber,\
dass auch noch\11andere Kriterien\11in die Bewertung\11eingehen.",
  ["56:7232"] = "CINDY: Du hast\
gewonnen? Das ist\11großartig!\12Hättest du Lust,\
mit mir auf die\11Suche nach Käfer-\11POKéMON zu gehen?",
  ["56:727f"] = "CINDY: Ich liebe\
Käfer-POKéMON!",
  ["56:729f"] = "ENNO: Ich… Ich\
glaube einfach\11nicht, dass ich\11beim Käfer-\11turnier verloren\11habe…",
  ["56:72d0"] = "ENNO: Ich hörte,\
dass jemand mit\11einem RAUPY\11gewonnen hat!",
  ["56:7302"] = "GUIDO: Das nächste\
Mal gewinne ich!",
  ["56:7327"] = "GUIDO: Mist! Ich\
dachte, ich würde\11eine höhere\11Bewertung\11erreichen…",
  ["56:7356"] = "MICHEL: Könntest\
du mir ein paar\12Tipps geben? Ich\
möchte deinen Stil\11erlernen.",
  ["56:7396"] = "MICHEL: Ich habe\
viel gelernt, aber\12noch nicht genug,\
um zu siegen.",
  ["56:74dd"] = "Oh, oh… Dein\
BEUTEL ist voll.\12Wir bewahren\
deinen Preis auf.\11Aber nur heute.\12Schaffe bitte\
Platz und komm\11dann wieder.",
  ["56:754c"] = "{PLAYER}?\12Hier ist der\
Preis, den wir für\11dich aufbewahrt\11haben.",
  ["57:4122"] = "Ich bin BIANKA!\12Jeder hat sich für\
POKéMON inte-\11ressiert, also\11musste ich mit-\11machen!\12POKéMON sind\
superniedlich!\12Willst du kämpfen?\
Sei gewarnt, ich\11bin gut!",
  ["57:41a5"] = "Schluchz…\12…Waaaaaaah!\
Du bist gemein!\12Du solltest nicht\
so ernst sein! Du,\11du Kind, du!",
  ["57:41f5"] = "Waaaaah!\12Waaaaah!\12…Schnüff, japs…\
…Du bist gemein!",
  ["57:4223"] = "…Schnüff…\12Was? Was willst\
du? Einen ORDEN?\12Oh, stimmt, ich\
vergaß. Hier ist\11der BASISORDEN.",
  ["57:4278"] = "{PLAYER} erhält\
BASISORDEN.",
  ["57:4290"] = "Mit Hilfe des BA-\
SISORDENS können\12deine POKéMON\
STÄRKE auch außer-\12halb eines Kampfes\
einsetzen.\12Außerdem erhöht er\
die INIT deiner\11POKéMON.\12Oh, das hier\
kannst du auch\11haben!",
  ["57:4307"] = "Es ist ANZIEHUNG!\
Es bringt den\12Charme eines\
POKéMON voll zur\11Geltung.\12Passt das nicht\
perfekt zu einem\11süßen Ding wie\11mir?",
  ["57:4365"] = "Ah, die Flennerei\
hat gut getan! Be-\12suche mich mal\
wieder! Tschüssi!",
  ["57:43a0"] = "Glaub nicht, du\
hättest leichtes\11Spiel mit mir!",
  ["57:43bb"] = "Verflixt… Ich\
dachte, du wärest\11schwach…",
  ["57:43db"] = "Ich frage mich, ob\
in der Welt der\12POKéMON Männchen\
oder Weibchen\11stärker sind!",
  ["57:441b"] = "Ich habe niedliche\
POKéMON lieber\11als starke.\12Aber ich habe\
starke und nied-\11liche POKéMON!",
  ["57:4469"] = "Oh, nein, nein!",
  ["57:447a"] = "Ich trainiere, um\
BIANKA zu besie-\11gen… Aber es ist\11hoffnungslos.\12Wenn ich verliere,\
werde ich einfach\12härter trainieren!",
  ["57:44de"] = "Oh nein. Du hast\
BIANKA zum Weinen\11gebracht.\12Keine Sorge. Sie\
beruhigt sich bald\12wieder. Sie weint\
immer, wenn sie\11verloren hat.",
  ["57:4537"] = "Oh, du bist ja ein\
hübscher kleiner\12Trainer! Ich mag\
dich, aber ich\12werde mich nicht\
zurückhalten!",
  ["57:457e"] = "Mal sehen… Ups,\
schon vorbei?",
  ["57:4599"] = "Wow, du musst gut\
sein, wenn du es\11schaffst, mich zu\11schlagen. Mach\11weiter so!",
  ["57:45c8"] = "Schlag ordentlich\
zu, sonst werde\11ich es tun!",
  ["57:45f7"] = "Nein! Oh, MAUZI,\
es tut mir Leid!",
  ["57:4615"] = "Ich habe MAUZI die\
unterschiedlich-\11sten Attacken bei-\11gebracht…",
  ["57:4644"] = "Yo! CHAMP in spe!\12In dieser ARENA\
warten Trainer mit\11POKéMON des Typs\11Normal auf dich.\12Ich empfehle dir,\
Kampf-POKéMON ein-\11zusetzen.",
  ["57:46b1"] = "Du hast gewonnen?\
Toll! Ich war da-\11mit beschäftigt,\11die hübschen Damen\11hier zu bewundern.",
  ["57:4791"] = "…Seufz… Ich bin\
hierher gezogen,\12aber ich kann mei-\
ne FAHRRÄDER nicht\12verkaufen. Warum\
nur?\12Würdest du ein\
FAHRRAD fahren und\11so Werbung machen?",
  ["57:4802"] = "Ja? Großartig!\12Gib mir bitte Name\
und Nummer. Dann\12leihe ich dir ein\
FAHRRAD.",
  ["57:4852"] = "{PLAYER} leiht sich\
ein FAHRRAD aus.",
  ["57:4869"] = "Meine FAHRRÄDER\
sind erste Klasse!\12Du kannst sie\
überall fahren.",
  ["57:48a2"] = "…Seufz… Oh, für\
die Güte der\11Menschen…",
  ["57:48f7"] = "Ein nagelneues\
FAHRRAD!",
  ["57:49ad"] = "Behandelst du dein\
POKéMON gut, wird\12es dich regelrecht\
lieben.\12Oh! Lass mich dein\
{STRBUF} sehen…",
  ["57:4a06"] = "Es sieht sehr\
glücklich aus! Es\11muss dich sehr\11gern haben.",
  ["57:4a36"] = "Ich habe den Ein-\
druck, dass es dir\11wirklich vertraut.",
  ["57:4a64"] = "Es verhält sich\
dir gegenüber sehr\11freundlich. Es\11muss glücklich\11sein.",
  ["57:4a98"] = "Es ist sehr süß.",
  ["57:4aa9"] = "Du solltest es\
besser behandeln.\11Es hat sich noch\11nicht an dich ge-\11wöhnt.",
  ["57:4adb"] = "Es scheint dich\
gar nicht zu mö-\11gen. Es sieht ge-\11mein aus.",
  ["57:4b0e"] = "Ständig verliere\
ich in Kämpfen und\12meine POKéMON\
werden immer be-\11siegt…\12Das mag der Grund\
sein, warum mich\11meine POKéMON\11nicht mögen…",
  ["57:4b71"] = "Wenn ich meinem\
POKéMON ein Item\11gebe, dann freut\11es sich!",
  ["57:4c7e"] = "BILL: Hi, {PLAYER}!\
Tu uns einen Ge-\11fallen und nimm\11dieses EVOLI.\12Es kam hierher,\
als ich an der\11ZEITKAPSEL gear-\11beitet habe.\12Jemand sollte sich\
darum kümmern,\12aber ich gehe\
nicht gerne raus.\12Wirst du für mich\
mit ihm spielen,\11{PLAYER}?",
  ["57:4d49"] = "BILL: Ich wusste\
es! Großartig! Du\12bist ein wahrer\
Held!\12O.K., ich zähle\
auf dich. Pass gut\11darauf auf.",
  ["57:4db5"] = "{PLAYER} erhält\
EVOLI!",
  ["57:4dc8"] = "BILL: PROF. LIND\
sagt, EVOLI kann\12sich in neue, un-\
bekannte Arten\11entwickeln.",
  ["57:4e09"] = "Moment! Du hast\
keinen Platz mehr\11in deinem Team.",
  ["57:4e34"] = "Oh… Was soll ich\
tun?",
  ["57:4e49"] = "BILL: Ich habe mit\
einem TELEPORTER\11experimentiert.\12Ich sollte meine\
Versuche weiter-\11führen.",
  ["57:4e93"] = "Oh, du sammelst\
POKéMON? Mein Sohn\11BILL ist ein Ex-\11perte.\12Er musste zum\
POKéMON CENTER von\12TEAK CITY auf-\
brechen.",
  ["57:4efa"] = "Ich bin so froh,\
meinen Sohn wie-\11derzusehen.",
  ["57:4f1d"] = "Bist du ein\
Trainer?\12Ich habe eine\
nützliche Telefon-\11nummer für dich.",
  ["57:4f58"] = "{PLAYER} speichert\
BILLs Nummer.",
  ["57:4f72"] = "Mein Bruder hat\
das PC-POKéMON-\11Lagerungssystem\11erfunden.\12Ich wollte dir ge-\
rade BILLs Nummer\11geben…",
  ["57:4fc5"] = "Du kannst keine\
Nummern mehr spei-\11chern.",
  ["57:4fe8"] = "Mein großer Bruder\
BILL hat das PC-\12POKéMON-Lagerungs-\
system erfunden.",
  ["57:50d7"] = "Der Zug ist nicht\
gekommen…\12Ich hab's! Ich\
werde die Passa-\11giere auf dem\11Rücken tragen!\12Das wird nicht\
funktionieren.",
  ["57:512e"] = "Wir werden in Kür-\
ze nach SAFFRONIA\11CITY abreisen.\12Kommst du mit?\
",
  ["57:5164"] = "Darf ich deinen\
FAHRSCHEIN sehen?\12O.K. Bitte hier\
entlang.",
  ["57:51a0"] = "Verzeihung, aber\
du hast keinen\11FAHRSCHEIN.",
  ["57:51c3"] = "Besuche uns\
wieder!",
  ["57:51de"] = "Wir sind in DUKA-\
TIA CITY angekom-\11men.\12Beehre uns bald\
wieder!",
  ["57:5217"] = "Ich bin der PRÄSI-\
DENT.\12Mein Traum war es,\
einen Zug zu bau-\12en, der schneller\
fährt als jedes\11POKéMON.\12Dadurch würden\
JOHTO und KANTO\11näherrücken.",
  ["57:5311"] = "Oh, du bist besser\
als BIANKA.\12Hast du vom lau-\
fenden Baum ge-\11hört?\12Benetzt du ihn mit\
einer SCHIGGYKAN-\11NE, greift er an.\12Aber da du ja ei-\
nige ORDEN hast,\11sollte es kein\11Problem sein.",
  ["57:53b6"] = "Lalala lalalala.\
Da hast du Wasser,\11mein Hübsches!",
  ["57:53e9"] = "Als ich den lau-\
fenden Baum auf\12der ROUTE 36 goss,\
ist er aufgesprun-\11gen!\12Ich glaube, es ist\
ein POKéMON.\12Aber es bedarf ei-\
nes ARENALEITERS\11wie BIANKA, um es\11zu besiegen.",
  ["57:5485"] = "Hast du vom lau-\
fenden Baum ge-\11hört?\12Wenn du ihn gießt,\
schreckt er hoch!",
  ["57:5513"] = "Im oberen Stock-\
werk jedes POKé-\12MON CENTERs fin-\
dest du das KOLOS-\12SEUM. Hier kannst\
du gegen Freunde\11antreten.\12Kampfergebnisse\
werden an der Wand\12ausgehängt. Ich\
kann es mir nicht\12erlauben, zu ver-\
lieren.",
  ["57:5597"] = "Ich frage mich,\
wie viele Arten\12von POKéMON es\
wohl geben mag.\12Vor drei Jahren\
hat PROF. EICH\12verlautbart, dass\
es 150 verschie-\12dene Arten geben\
soll.",
  ["57:5614"] = "Ein starkes POKé-\
MON muss nicht\11zwingend gewinnen.\12Meist entscheidet\
der Vor- oder\11Nachteil des Typs.\12Ich glaube nicht,\
dass es ein POKé-\12MON gibt, das al-\
len anderen über-\12legen ist.",
  ["57:56fe"] = "Als ich einmal\
kämpfte, konnte\12mein POKéMON kei-\
ne Attacken mehr\11ausführen.\12Die ANGRIFFSPUNK-\
TE, oder AP, sei-\12ner Attacken waren\
verbraucht.",
  ["57:576f"] = "Manchmal kann auch\
ein gesundes\12POKéMON nicht mehr\
angreifen.\12In diesem Fall\
musst du es in ei-\11nem POKéMON CENTER\11oder mit einem\11Item heilen.",
  ["57:5a38"] = "Willkommen im\
KAUFHAUS von\11DUKATIA CITY.",
  ["57:5a5c"] = "Das KAUFHAUS\
bietet eine große\11Auswahl.\12Aber einige Items\
erhält man nur als\12Preis in der\
SPIELHALLE.",
  ["57:5abf"] = "Ich freue mich\
heute schon wieder\11aufs Einkaufen!",
  ["57:5adf"] = "Mama ist sehr gut\
im Schnäppchen-\11finden.\12Sie kauft ständig\
Waren unter dem\11Normalpreis.",
  ["57:5b25"] = "EG INFO-SCHALTER\12S1 TRAINER-\
   MARKT\12S2 KAMPF-\
   KOLLEKTION\12S3 ARZNEI\12S4 TM-ECKE\12S5 DACHTERRASSE",
  ["57:5cb7"] = "Der POKéCOM kann\
bis zu zehn Num-\11mern speichern.\12Es ist schwer zu\
entscheiden, wel-\11che Nummer man be-\11halten soll.",
  ["57:5d0d"] = "Ich habe mein ABRA\
in der SPIELHALLE\12gewonnen. Jetzt\
ist es mein bester\12Partner.",
  ["57:5d49"] = "Dieses KAUFHAUS\
zeigt mir, dass\12DUKATIA CITY eine\
sehr große Stadt\11ist.\12Dieses Angebot ist\
unübertrefflich!",
  ["57:5dba"] = "Ihr Reise-\
begleiter\12S1 TRAINER-\
   MARKT",
  ["57:5e5e"] = "Ich, ich bin wirk-\
lich ungeduldig!\12Im Kampf setze ich\
X-TEMPO ein, um\11die Geschwindig-\11keit meiner POKé-\11MON zu erhöhen.",
  ["57:5ea7"] = "Hey! Setzt du im\
Kampf X-SPEZIAL\11ein?\12Es ist toll. Es\
verstärkt alle\11SPEZIALATTACKEN!",
  ["57:5f09"] = "Für Sieges-\
hungrige\12S2 KAMPF-\
   KOLLEKTION",
  ["57:5f9d"] = "Hey! Ich mag star-\
ke POKéMON.\12Ich füttere sie\
mit PROTEIN, um\11ihren ANGR zu ver-\11stärken.",
  ["57:5fe7"] = "EISEN verstärkt\
die VERT deiner\11POKéMON.",
  ["57:6009"] = "Manche POKéMON\
entwickeln sich\11nur durch Tausch.\12Ich kenne vier:\
MASCHOK, KADABRA,\12ALPOLLO und\
GEOROK.\12Ich hörte, es gibt\
noch weitere.",
  ["57:60a2"] = "Wir kümmern uns um\
Ihre POKéMON!\12S3 ARZNEI",
  ["57:61d8"] = "Hallo! Oh, dein\
POKéMON…",
  ["57:61ef"] = "Es hängt sehr an\
dir.\12Diese Attacke\
passt genau zu\11euch beiden.",
  ["57:623b"] = "Oh, wie süß!\12Du solltest ihm\
gute TM-Attacken\11beibringen.",
  ["57:626d"] = "Es sieht böse aus.\
Wie wär's mit die-\11ser TM?",
  ["57:6297"] = "Es gibt für jedes\
POKéMON passen-\11de TMs.",
  ["57:62d6"] = "GEHEIMGABE.\12Mit nur einem\
kleinen Biep er-\11hältst du ein Ge-\11schenk.",
  ["57:630e"] = "Die GEHEIMGABE\
erfordert einen\11Game Boy Color.",
  ["57:6342"] = "An Sonntagen kommt\
eine Dame, um sich\11POKéMON anzusehen.\12Sie verteilt sogar\
TMs!",
  ["57:6388"] = "Ein POKéMON, das\
du durch Tausch\11erhalten hast,\11kannst du nicht\11umbenennen.\12Der Name spiegelt\
die Gefühle des\12Original-Trainers\
wieder.",
  ["57:63f9"] = "Rüste deine POKé-\
MON auf.\12S4 TM-ECKE",
  ["57:6560"] = "Ein Automat!\
Hier ist das Ange-\11bot.",
  ["57:6584"] = "Ding! Eine Dose\
{STRBUF}\11fällt heraus!",
  ["57:65a7"] = "Ups, nicht genug\
Geld.",
  ["57:65c0"] = "Du hast keinen\
Platz mehr.",
  ["57:65e0"] = "Hörst du den\
GLÜCKSKANAL?\12Möchtest du gewin-\
nen, tausche POKé-\12MON mit so vielen\
Leuten wie mög-\12lich, um verschie-\
dene ID-Nummern zu\11erhalten.",
  ["57:665f"] = "Wenn du müde bist,\
dann hol dir ein\11Getränk aus dem\11Automaten.\12Auch deine POKéMON\
werden sie mögen.",
  ["57:66af"] = "Gönn dir eine\
kleine Pause!\12S5 DACHTERRASSE",
  ["57:6ab5"] = "Willkommen!\12Wir tauschen deine\
Spielmünzen gegen\11tolle Preise!",
  ["57:6af0"] = "Welchen Preis\
möchtest du?",
  ["57:6b0d"] = "{STRBUF}.\
Ist das O.K.?",
  ["57:6b22"] = "Hier, bitte!",
  ["57:6b30"] = "Tut mir Leid, aber\
du brauchst mehr\11Münzen.",
  ["57:6b4d"] = "Du kannst nichts\
mehr tragen.",
  ["57:6b6e"] = "Sammle ein paar\
Münzen und komm\11dann wieder!",
  ["57:6b9a"] = "Oh? Du hast keinen\
MÜNZKORB.",
  ["57:6bba"] = "Ich spiele nur an\
diesem Automaten.\12Ich glaube, er\
spuckt mehr aus\12als die anderen.",
  ["57:6c03"] = "Ich liebe diesen\
neuen Automaten.\12Er stellt eine\
größere Herausfor-\11derung dar als\11jene in PRISMANIA\11CITY.",
  ["57:6c59"] = "Das Leben ist ein\
Spiel. Ich werde\11Karten spielen,\11bis ich umfalle!",
  ["57:6c90"] = "Karten…\12Ich ziehe sie den\
Automaten vor,\12weil man seine\
Chancen besser ab-\11schätzen kann.\12Aber der Gewinn\
ist viel geringer.",
  ["57:6cfc"] = "Ich höre erst auf,\
wenn ich gewinne!",
  ["57:6d16"] = "Ich habe meinen\
POKéMON BLIZZARD\11beigebracht.\12Es hat zwar gedau-\
ert, bis ich genug\12Münzen hatte, aber\
es hat sich ge-\11lohnt.",
  ["57:6d72"] = "Ich hatte an den\
Automaten kein\12Glück. Bei den\
Karten sieht es\12auch nicht anders\
aus…\12Ich war so zornig,\
dass ich meinen\12MÜNZKORB in den\
UNTERGRUND gewor-\11fen habe.",
  ["57:6f2c"] = "Vorsicht! Verlaufe\
dich nicht! Der\11STEINEICHENWALD\11ist groß.",
  ["57:6f5c"] = "Der WALD wird von\
seinem\11Schutzpatron\11bewacht.\12Mach keine\
Dummheiten!",
  ["57:6ffe"] = "Oh, Süßer. Du\
erstellst einen\11POKéDEX?\12Das muss schwierig\
sein, wenn du\11keine POKéMON\12triffst. Versuche\
es mit dieser TM.",
  ["57:7057"] = "Sie enthält\
LOCKDUFT.\12Benutze sie dort,\
wo POKéMON\11auftauchen.\12POKéMON werden\
von dem Duft\11angezogen.",
  ["57:70a2"] = "SMETTBO: Boh!",
  ["57:70b6"] = "Hast du den\
Schrein gesehen,\11der dem Schutz-\11patron huldigt?\12Er wacht über den\
WALD, aus einer\11anderen Zeit.\12Ich glaube, das\
ist ein\11Pflanzen-POKéMON.",
  ["57:71b8"] = "Opa hat nach dir\
gesucht.",
  ["59:400b"] = "Ich bin der PROFI-\
ANGLER, der äl-\11tere der GEBR.\11ANGLER.\12Kennst du zufällig\
ANGLER ALFRIED? Er\12angelt an der\
ROUTE 44.\12Er hat mir\
telefonisch einen\11super Tipp gesagt.\12Ihm habe ich es zu\
verdanken, dass\12ich ganz viele\
seltene POKéMON\12fangen konnte.\
Das war ein Tag!",
  ["59:40fa"] = "Das ist ein Foto,\
auf dem Angler zu\11sehen sind…\12Sie haben viel\
Spaß beim Angeln…",
  ["59:4177"] = "Vor DIGDAS\
HÖHLE liegt ein\11schlafendes POKé-\11MON.\12Das wäre eine\
fantastische Gele-\12genheit, es zu\
fangen! Aber wie\11weckt man es auf?",
  ["59:41ef"] = "Vor DIGDAS\
HÖHLE lag ein\12schlafendes POKé-\
MON.\12Aber jetzt scheint\
es verschwunden\11zu sein.",
  ["59:4255"] = "Auf dem SCHNELL-\
BOOT findet man\12viele Trainer,\
gegen die man\11kämpfen kann.",
  ["59:4292"] = "Ach? Du hast da\
einige ORDEN, die\11ich noch nie\11gesehen habe.\12Ah, jetzt begreife\
ich es. Du hast\12sie in JOHTO\
erhalten.",
  ["59:43d8"] = "Ich bin der\
VORSITZENDE des\11POKéMON-FANCLUB.\12Ich habe über\
150 POKéMON\11aufgezogen.\12Ich bin sehr \
kleinlich, was\11POKéMON betrifft.\12Bist du extra\
hierher gekommen,\11um etwas über\11meine POKéMON zu\11erfahren?",
  ["59:4468"] = "Sehr schön!\
Dann hör gut zu!\12Also… am liebsten\
habe ich GALLOPA…\12Es ist… süß… lieb…\
klug… anmutig…\11und… wunderbar…\11nicht wahr?…\11Zu sehr… wild…\11schön… liebenswert\11…Ich verehre es!\12Knuddle es… wenn…\
es schläft… warm\11und weich… Oh, und\11sensationell…\11großartig… einfach\11göttlich…\11Ups! Wie die Zeit\11vergeht! Ich habe\11dich zu lange\11aufgehalten!",
  ["59:4594"] = "Danke, dass du mir\
so lange zugehört\11hast. Das möchte\11ich dir geben!",
  ["59:45c9"] = "Das SONDERBONBON\
macht POKéMON\11stärker.\12Meine POKéMON\
sollen lieber\12durch ihre Kämpfe\
stärker werden. Du\11kannst es haben.",
  ["59:4637"] = "Hallo, {PLAYER}!\12Besuchst du mich\
wieder wegen\11meiner POKéMON?\12Nein? Oh… Ich\
hätte noch so\11viele Geschichten…",
  ["59:468f"] = "Schade…\12Komm wieder, wenn\
du mehr\12Geschichten hören\
möchtest.",
  ["59:46c4"] = "Unser VORSITZENDER\
ist sehr redselig\11in Bezug auf POKé-\11MON…",
  ["59:46f7"] = "Ich liebe es, wie\
PIEPI mit seinem\12Finger wackelt,\
wenn es METRONOM\12anwendet.\
Entzückend!",
  ["59:4756"] = "Ich mag PIEPI,\
aber ich könnte\12nie eines fangen.\
Die POKéPUPPE,\12die ich fand, muss\
mir genügen.",
  ["59:47b1"] = "Ah, jetzt verstehe\
ich. Das Mädchen,\12das diese POKé-\
PUPPE verloren\11hat, ist traurig…\12Könntest du dann\
die POKéPUPPE\12zu diesem armen,\
kleinen Mädchen\11zurückbringen?\12Eines Tages werde\
ich mich mit einem\12echten PIEPI an-\
freunden. Keine\11Bange!",
  ["59:4861"] = "{PLAYER} erhält\
POKéPUPPE.",
  ["59:4875"] = "Du wirst schon\
sehen. Ich freunde\12mich noch mit\
einem echten\11PIEPI an.",
  ["59:48af"] = "Dein BEUTEL ist\
voll.",
  ["59:48ca"] = "Schau dir mein\
süßes LORBLATT an!\12Das Blatt auf\
seinem Kopf ist so\11goldig!",
  ["59:4908"] = "Das ist ein\
PIEPI! Was?\12Ach so! Das ist\
eine POKéPUPPE\11von PIEPI.",
  ["59:4940"] = "LORBLATT: Bla,\
blatt!",
  ["59:4953"] = "Anderen Trainern\
hören wir höflich\11zu.",
  ["59:4980"] = "Wenn jemand\
prahlt, wird\12sofort zurück-\
geprahlt!",
  ["59:4a17"] = "Hast du schon von\
dem MAGNETZUG\11gehört?\12Er fährt nach\
DUKATIA CITY\11in JOHTO.",
  ["59:4a6d"] = "Ich möchte nach\
SAFFRONIA CITY, um\11den MAGNETZUG zu\11sehen.",
  ["59:4ae2"] = "TEAM ROCKET ist\
nicht mehr in\11KANTO.\12Das allein ist\
schon ein Grund\11zum Feiern.",
  ["59:4b21"] = "Ich habe vor, in\
SAFFRONIA CITY\11einkaufen zu\11gehen.",
  ["59:4b8b"] = "Im Laufe vieler\
Jahre haben die\11DIGDA einen langen\11Tunnel gebaut.\12Dieser Tunnel\
führt zu einer\11weit entfernten\11Stadt.",
  ["59:4c99"] = "MAJOR BOB: He,\
kleiner Kerl!\12Es war vielleicht\
nicht sehr klug,\12mich herauszufor-\
dern, aber das\11muss ich dir\11lassen - du hast\11Mut!\12Ich bin die Nummer\
Eins, was Elektro-\11POKéMON betrifft!\12Ich habe den\
Kampfplatz nie als\12Verlierer\
verlassen.\12Ich werde dir eine\
pfeffern, wie ich\11es mit meinen\11Feinden im Krieg\11tat!",
  ["59:4d8a"] = "MAJOR BOB: Ahh!\
Du bist stark!\12Also gut, mein\
Junge. Du erhältst\11den DONNERORDEN!",
  ["59:4dc9"] = "{PLAYER} erhält\
DONNERORDEN.",
  ["59:4de3"] = "MAJOR BOB: Der\
DONNERORDEN erhöht\12den INIT-Wert\
deiner POKéMON.\12Du darfst stolz\
darauf sein, mich\12besiegt zu haben,\
hörst du?",
  ["59:4e55"] = "MAJOR BOB: He,\
Junge! Schlägst\11du dich immer noch\11herum?\12Meine POKéMON und\
ich sind immer\11noch dabei!",
  ["59:4ea8"] = "Du willst MAJOR\
BOB besiegen?\12Da musst du erst\
an mir vorbei!",
  ["59:4ede"] = "Ich habe versagt,\
MAJOR BOB. Es tut\11mir Leid!",
  ["59:4f02"] = "Als ich noch bei\
der Armee war, hat\12MAJOR BOB mein\
Leben gerettet.",
  ["59:4f3a"] = "MAJOR BOB hat mein\
Talent für\12Elektro-POKéMON\
erkannt.\12Glaubst du, du\
kannst mich\11besiegen?",
  ["59:4f89"] = "Oh, wie\
schockierend!",
  ["59:4f9d"] = "Wenn die Fallen\
der Trainer\12funktionieren\
würden, wärst du\12schon längst\
hinüber…",
  ["59:4fd9"] = "Ich werde dich\
fertig machen! Du\11wirst gleich einen\11Schlag bekommen!",
  ["59:500c"] = "Ahh! Ich stand zu\
sehr unter Strom…",
  ["59:5028"] = "Lass dir den Sieg\
über mich nicht zu\12Kopf steigen…\
MAJOR BOB ist\11stark.",
  ["59:5069"] = "He! Du CHAMP\
in spe!\12Dieses Mal hattest\
du Glück.\12MAJOR BOB ist sehr\
vorsichtig. Er\12hat überall in der\
PKMN-ARENA Fallen\11aufgestellt.\12Aber,-- hihi --\
die Fallen funk-\11tionieren nicht.\12Du wirst MAJOR BOB\
problemlos\11erreichen.",
  ["59:5131"] = "Puh! Das war ein\
elektrisierendes\11Erlebnis!\12Das hat meine\
Nerven sehr\11strapaziert.",
  ["59:5170"] = "Nein! Hier ist\
nur Müll.",
  ["59:5250"] = "Willkommen in\
SAFFRONIA CITY,\11der Heimat des\11MAGNETZUGs!\12…Das sage ich\
sonst immer, aber\12der MAGNETZUG\
fährt momentan\11nicht.\12Die Stromzufuhr\
ist unterbrochen,\12weil es im\
KRAFTWERK ein\12Problem gibt.",
  ["59:531d"] = "Der MAGNETZUG ist\
das Aushängeschild\12von SAFFRONIA\
CITY.",
  ["59:53bb"] = "Hi!\12ROT ist schon seit\
langem fort.\12Er hat sich auch\
nicht gemeldet.\12Ich habe keine\
Ahnung, wo er ist\11oder was er tut.\12Wenn man nichts\
hört, soll das ja\12heißen, dass es\
ihm gut geht. Aber\11ich mache mir\11Sorgen um ihn.",
  ["59:547c"] = "Ich habe Angst,\
dass sich ROT\12verletzt oder\
krank wird. Aber\12er ist ein Junge\
und ich bin stolz,\12dass er macht, was\
ihm gefällt.",
  ["59:54e3"] = "Sie haben\
Programme, die man\11in JOHTO nicht\11empfängt…",
  ["59:554b"] = "{PLAYER} spielt\
N64.\12Mach besser\
weiter - du hast\11keine Zeit zu\11verlieren!",
  ["59:5582"] = "Es sieht aus, als\
wäre er seit\11langer Zeit nicht\11mehr benutzt\11worden…",
  ["59:562b"] = "SARAH: Hi! Mein\
kleiner Bruder ist\12ARENALEITER in\
VERTANIA CITY.\12Aber er verlässt\
die Stadt so oft,\12dass die Trainer\
Schwierigkeiten\11bekommen.",
  ["59:56b1"] = "SARAH: Hi! Gutes\
Timing. Ich war\11gerade dabei, Tee\11zu machen.\12Hättest du auch\
gern eine\11Tasse Tee?\12Oh, deine POKéMON\
sehen ein bisschen\11mitgenommen aus.\12Möchtest du, dass\
ich eines für dich\11verschönere?",
  ["59:573f"] = "SARAH: Welches\
soll ich ver-\12schönern?",
  ["59:5761"] = "SARAH: Gut. In\
kürzester Zeit\11wird es hübsch und\11adrett aussehen.",
  ["59:5791"] = "{STRBUF} sieht\
zufrieden aus.",
  ["59:57a5"] = "SARAH: Hier bitte.\
Schon fertig.\12Siehst du? Ist es\
jetzt nicht\11wunderschön?\12Es ist so ein\
süßes POKéMON.",
  ["59:57f5"] = "SARAH: Um diese\
Zeit trinke ich\12immer meinen Tee.\
Möchtest du auch\11eine Tasse Tee?",
  ["59:582f"] = "SARAH: Möchtest du\
keines deiner\12POKéMON ver-\
schönern lassen?\11Gut, dann trinken\11wir eben nur Tee.",
  ["59:5872"] = "SARAH: Es tut mir\
Leid, aber ich\11kann wirklich kein\11EI verschönern.",
  ["59:5922"] = "EICH: {PLAYER}!\
Schön, dass du\12den weiten Weg\
nach KANTO gemacht\11hast.\12Was hältst du von\
den Trainern hier\12draußen?\
Ziemlich stark,\12was?",
  ["59:599d"] = "Wie geht es mit\
dem POKéDEX voran?\12Mal sehen…",
  ["59:59c3"] = "Wenn du mal wieder\
in der Gegend\11bist, dann schau\11doch wieder rein.",
  ["59:59f7"] = "EICH: Wow! Das ist\
hervorragend!\12Du hast die ORDEN\
der ARENALEITER in\11KANTO erkämpft.\11Gut gemacht!\12Ich habe dich\
richtig\11eingeschätzt.\12Weißt du was,\
{PLAYER}? Ich\12werde es so ein-\
richten, dass du\11zum SILBERBERG\11gehen kannst.\12Der SILBERBERG ist\
ein großes Habitat\12für viele wilde\
POKéMON.\12Es ist zu\
gefährlich für\12einen Durch-\
schnittstrainer.\12Deshalb ist es\
verboten. Aber für\11dich, {PLAYER},\11können wir eine\11Ausnahme machen.\12Steige auf das\
INDIGO PLATEAU.\12Von dort kannst\
du den SILBERBERG\11erreichen.",
  ["59:5b9d"] = "EICH: Hm? Du hast\
keine ORDEN der\12PKMN-ARENEN\
in KANTO?\12Die ARENALEITER in\
KANTO sind genauso\12stark wie die\
in JOHTO.\12Ich schlage vor,\
du forderst sie\11heraus.",
  ["59:5c37"] = "EICH: Ah, du\
sammelst ORDEN der\11ARENALEITER von\11KANTO.\12Ich kann mir\
vorstellen, dass\12es schwer für dich\
ist, aber du\11sammelst wertvolle\11Erfahrungen.\12Besuche mich\
wieder, wenn du\12sie alle hast.\
Ich gebe dir dann\11ein Geschenk.\12Streng dich weiter\
so an, {PLAYER}!",
  ["59:5cf6"] = "Prof. EICHs POKé-\
MON-TALK wird in\12KANTO nicht im\
Radio gesendet.\12Das ist schade.\
Ich würde es gerne\11hören.",
  ["59:5d54"] = "Die Forschungen\
des PROFESSORs\11kommen dank deiner\12Arbeit am POKéDEX\
sehr gut voran.",
  ["59:5da2"] = "Erzähl es keinem,\
aber PROF. EICHs\12POKéMON-TALK wird\
nicht live\11gesendet.",
  ["59:5de5"] = "Drücke START, um\
das MENÜ zu\11öffnen.",
  ["59:5e04"] = "Möchtest du deinen\
Spielstand von\12Zeit zu Zeit\
speichern, dann\11wähle im MENÜ die\11Option SICHERN.",
  ["59:5e40"] = "Hier drin ist\
nichts…",
  ["59:5e59"] = "Auf dem PC ist\
eine E-Mail.\12…\12Wie kommen Sie\
mit Ihren\11Forschungen voran,\11PROF. EICH?\12Nun, ich ackere\
weiter.\12Ich habe Gerüchte\
gehört, dass\12sich {PLAYER}\
einen Namen macht.\12Es freut mich, das\
zu hören.\12PROF. LIND in\
NEUBORKIA",
  ["5a:400f"] = "NIDORAN, schüttle!",
  ["5a:4020"] = "NIDORAN: Nido,\
nido!",
  ["5a:40cb"] = "ROCKO: Wow, es\
kommt nicht oft\12vor, dass wir von\
einem Heraus-\11forderer aus JOHTO\11besucht werden.\12Ich bin ROCKO, der\
ARENALEITER von\12MARMORIA. Ich habe\
mich auf Gestein-\12POKéMON\
spezialisiert.\12Meine POKéMON sind\
gegen die meisten\12physischen Atta-\
cken immun. Es\12wird dir schwer\
fallen, ihnen\11Schaden zuzufügen.\12Na los!",
  ["5a:41b6"] = "ROCKO: Die mäch-\
tigen Attacken\11deiner POKéMON\11haben meine\11felsenfeste\11Verteidigung\11überwunden…\12Du bist stärker,\
als ich dachte…\12Komm - Nimm dir\
diesen ORDEN.",
  ["5a:4238"] = "{PLAYER} erhält\
FELSORDEN.",
  ["5a:4252"] = "ROCKO: Danke,\
{PLAYER}. Es war\12eine Freude, gegen\
dich zu kämpfen.\11Auch wenn ich ein\11bisschen beleidigt\11bin.\12Dieser FELSORDEN\
wird deine POKé-\12MON noch stärker\
machen.",
  ["5a:42d5"] = "ROCKO: Die Welt\
ist groß. Es gibt\12immer noch viele\
starke Trainer wie\11dich.\12Warte nur ab. Ich\
werde auch noch\11viel stärker.",
  ["5a:435d"] = "Die Trainer dieser\
PKMN-ARENA setzen\11Gestein-POKéMON\11ein.\12Gestein-POKéMON\
haben hohe\11VERT-Werte.\12Die Kämpfe können\
sehr lange\12dauern. Bist du\
bereit dafür?",
  ["5a:43ec"] = "Ich muss diese\
Kämpfe gewinnen…",
  ["5a:440a"] = "He, du da! Trainer\
aus JOHTO! ROCKO\12ist stark. Es wird\
dir übel bekommen,\12wenn du ihn nicht\
ernst nimmst.",
  ["5a:4469"] = "He! Ein CHAMP\
in spe!\12Das ist cool!\
Kämpfst du gegen\12die ARENALEITER in\
KANTO?\12Sie sind stark und\
ambitioniert, wie\12die ARENALEITER in\
JOHTO.",
  ["5a:4502"] = "He! Ein CHAMP\
in spe!\12Diese PKMN-ARENA\
stellte kein\12Problem für dich\
dar.\12Dein Einsatz\
ist wirklich\12beeindruckend. Das\
meine ich ehrlich.",
  ["5a:45d3"] = "Hi! Mach doch\
Bekanntschaft mit\11meinem GARADOS!\12Ich habe es als\
KARPADOR auf-\12gezogen. Kaum zu\
glauben, wie stark\11es geworden ist.",
  ["5a:4635"] = "Es gab mal einen\
komischen, alten\11Mann, der KARPADOR\11verkaufte.\12Er sagte immer,\
die KARPADORS im\12SEE DES ZORNS\
seien\11außergewöhnlich.",
  ["5a:46fc"] = "…Ja, und die\
PKMN-ARENA auf der\12ZINNOBERINSEL ist\
verschwunden. Das\12finde ich\
merkwürdig.\12…Ja? Ich\
telefoniere!\11Lass mich in Ruhe!",
  ["5a:4758"] = "PUMMELUFF: Puu\
pupuu.",
  ["5a:4770"] = "Die meisten POKé-\
MON werden\12schläfrig, wenn\
PUMMELUFF singt.\12Manche Attacken\
kann man nur an-\12wenden, wenn ein\
POKéMON schläft.",
  ["5a:485a"] = "Ich mache gerne\
ein Nickerchen,\11während das Radio\11läuft…\11…Zzzz…",
  ["5a:4a24"] = "In der POKéMON\
LIGA stellen dich\12die TOP VIER auf\
eine harte Probe.\12Du musst sie alle\
schlagen. Wenn du\12verlierst, musst\
du ganz von vorne\11anfangen!",
  ["5a:4aa1"] = "Moment noch!\12Akzeptierst du die\
Herausforderung\12der POKéMON LIGA?\12Das wird nicht\
passieren.\12Meine perfekt\
trainierten POKé-\12MON werden dich\
zermalmen.\12{PLAYER}!\
Ich fordere dich\11heraus!",
  ["5a:4b41"] = "…\
O.K. - Ich habe\12verloren…",
  ["5a:4b50"] = "…Mist… Ich\
kann nicht\11gewinnen…\12Ich… Ich muss mich\
mehr um meine\11POKéMON kümmern…\12Versuche, nicht\
zu verlieren!",
  ["5a:4ba9"] = "…\12Wow…\
Mit meinen\12Partnern werde\
ich der CHAMP\11sein!",
  ["5a:4be1"] = "Ah! Du forderst\
also die TOP VIER\12heraus? Bist du\
wirklich bereit?\12Wenn du mehr\
trainieren willst,\12kann dir mein\
ABRA helfen.\12Es kann dich\
nach Hause\11TELEPORTIEREN.\12Möchtest du jetzt\
nach Hause?",
  ["5a:4c93"] = "O.K. Stell\
dir dein Haus\11vor…",
  ["5a:4cbd"] = "O.K. Alles\
Gute!",
  ["5a:4cdf"] = "ABRA: Aabra…",
  ["5a:4ddd"] = "Willkommen in der\
POKéMON LIGA,\11{PLAYER}.\12Erlaube mir, mich\
vorzustellen. Ich\11bin WILLI.\12Ich habe die ganze\
Welt bereist, um\12meine Psycho-POKé-\
MON zu verbessern.\12Und schliesslich\
habe ich es in\11in die TOP VIER\11geschafft.\12Ich werde ständig\
besser!\12Verlieren ist\
keine Alternative!",
  ["5a:4ed8"] = "Ich… Ich kann…\
es nicht glauben…",
  ["5a:4ef0"] = "Auch wenn ich\
besiegt wurde,\11werde ich an\11meiner Überzeugung\11festhalten.\12Ich werde weiter\
kämpfen, bis ich\12besser bin, als\
alle anderen\11Trainer!\12{PLAYER}, schreite\
voran und lerne\12die Grausamkeit\
der TOP VIER\11kennen.",
  ["5a:503f"] = "Fwahahahaha!\12Ich bin KOGA.\
Einer der TOP\12VIER. Da ich ein\
Ninja bin, lebe\11ich in der Dunkel-\11heit.\12Mein komplizierter\
Stil wird dich\11verwirren und\11vernichten!\12Verwirrung,\
Schlaf, Gift…\12Auch du wirst ein\
Opfer meiner\11hinterhältigen\11Strategie!\12Fwahahahaha!\12Bei POKéMON geht\
es nicht nur um\12Kraft allein - das\
wirst du noch\11herausfinden!",
  ["5a:5155"] = "Ah!\
Du hast dich als\11würdig erwiesen!",
  ["5a:5176"] = "Ich habe alle\
meine Register\11gezogen.\12Alles war umsonst.\
Ich muss meine\11Fertigkeiten\11verbessern.\12Betritt den\
nächsten Raum und\11stelle dein Können\11unter Beweis!",
  ["5a:52aa"] = "Ich bin BRUNO.\
Ein weiteres\11Mitglied der\11TOP VIER.\12Ich trainiere, bis\
ich erschöpft bin,\11da ich an mein\11Potential glaube.\12Auf diese Art bin\
ich so stark\11geworden.\12Kannst du unserer\
Kraft widerstehen?\12Hm? Ich sehe, du\
fürchtest dich\12nicht und siehst\
entschlossen aus.\11Genau richtig für\11einen Kampf!\12Bereit, {PLAYER}?\
Du wirst dich\12unserer unbändigen\
Kraft beugen\11müssen!\12Uh Ah!",
  ["5a:53cf"] = "Warum? Wie konnte\
ich nur verlieren?",
  ["5a:53e8"] = "Da ich verloren\
habe, muss ich\11jetzt still sein…\12Bereite dich auf\
die nächste\11Herausforderung\11vor!",
  ["5a:54d3"] = "Ich bin MELANIE.\
Nummer 4 der\11TOP VIER.\12Du heißt {PLAYER}?\
Sehr amüsant.\12Ich liebe POKéMON\
des Typs Unlicht.\12Ihr wilder, harter\
Ruf gefällt mir.\12Und sie sind\
wirklich stark.\12Glaubst du, du\
kannst es mit uns\11aufnehmen? Los,\11ich will mich\11amüsieren.\12Auf geht's.",
  ["5a:55a4"] = "Nun, du bist\
gut. Das gefällt\11mir an einem\11Trainer.",
  ["5a:55d5"] = "Starke POKéMON.\12Schwache POKéMON.\12Das ist nur eine\
subjektive Ein-\11schätzung anderer\11Menschen.\12Wirklich begabte\
Trainer gewinnen\12mit ihren Lieb-\
lings-POKéMON.\12Ich mag deinen\
Stil. Du weißt,\11was wichtig ist.\12Schreite voran!\
Der CHAMP\11wartet.",
  ["5a:5816"] = "SIEGFRIED: Ich\
habe dich\11erwartet.\12{PLAYER}!\12Ich wusste, dass\
du mir aufgrund\12deiner Fähigkeiten\
eines Tages\11gegenüberstehen\11würdest.\12Worte sind hier\
fehl am Platze.\12Ein Kampf wird\
zeigen, wer\12der Stärkere von\
uns beiden ist.\12Ich, der beste\
aller Trainer und\12CHAMP der\
POKéMON LIGA…\12Ich, SIEGFRIED\
der Drachenmeis-\12ter, nehme deine\
Herausforderung\12an!",
  ["5a:5953"] = "Das ist ein\
seltsames Gefühl.\12Ich bin nicht\
wütend, dass ich\11verloren habe. Ich\11bin glücklich.\12Glücklich, dass\
ich den Aufstieg\12eines neuen\
CHAMPs miterleben\11durfte.",
  ["5a:59e1"] = "…Woa.\12Du bist sehr\
stark geworden,\11{PLAYER}.\12Deine POKéMON\
haben deine starke\12und aufrechte\
Persönlichkeit\11akzeptiert.\12Auch du wirst\
zusammen mit\12deinen POKéMON\
stärker werden.",
  ["5a:5a8c"] = "MARGIT: Oh, nein!\
Alles ist vorbei!\12PROF. EICH, wenn\
du nicht so lang-\11sam wärest…",
  ["5a:5aca"] = "PROF. EICH: Ah,\
{PLAYER}!\12Es ist schon\
lange her.\12Du siehst\
erwachsener aus.\12Dein Sieg in der\
LIGA ist einfach\11fantastisch!\12Deine Hingabe, das\
Vertrauen und die\12Liebe zu deinen\
POKéMON haben\11dir dies er-\11möglicht.\12Auch deine POKé-\
MON waren super.\12Ihr Glaube an dich\
hat sie all das\12durchstehen\
lassen.\12Glückwunsch,\
{PLAYER}!",
  ["5a:5bf6"] = "MARGIT: Ein\
Interview mit dem\11neuen CHAMP!",
  ["5a:5c26"] = "SIEGFRIED: Das\
wird mir alles\11ein wenig zu laut…\12{PLAYER}, kommst\
du mit mir?",
  ["5a:5c70"] = "MARGIT: Moment!\
Wir haben das\11Interview fast\11vergessen!",
  ["5a:5d51"] = "SIEGFRIED: Ich war\
schon lange nicht\11mehr hier.\12Hier werden die\
LIGA-CHAMPS\12für alle Ewigkeit\
gewürdigt.\12Ihre mutigen POKé-\
MON sind auch\11aufgeführt.\12Hier und heute\
wurden wir Zeuge\12des Aufstiegs ei-\
nes neuen LIGA-\12CHAMPS -- eines\
Trainers, der\12Leidenschaft für\
und Vertrauen in\11seine POKéMON hat.\12Ein Trainer,\
dessen Erfolg auf\12Ausdauer und\
Entschlossenheit\11basiert.\12Der neue LIGA-\
CHAMP, der\12alle Zeichen von\
Größe in sich\11vereint!\12{PLAYER}, darf ich\
dich und deine\12Partner als\
CHAMPS\11eintragen?",
  ["5b:41b3"] = "Wir legen bald\
ab! Geh an\11Bord.",
  ["5b:41de"] = "Du darfst jetzt\
nicht an Bord.",
  ["5b:41fa"] = "Willkommen auf \
dem SCHNELLBOOT\11M.S. AQUA.\12Trittst du heute\
deine Reise an?",
  ["5b:4238"] = "Zeige mir bitte\
dein\12BOOTSTICKET.",
  ["5b:4259"] = "Komm jederzeit\
wieder vorbei!",
  ["5b:4274"] = "{PLAYER} zeigt\
das BOOTSTICKET.\12In Ordnung.\
Dankeschön!",
  ["5b:42a9"] = "{PLAYER} sucht\
das BOOTS-\11TICKET…\12…Kein TICKET!\12Tut mir Leid!\
Du darfst nur\12mit TICKET\
an Bord.",
  ["5b:4310"] = "Das SCHNELLBOOT\
legt nächsten\11Montag ab.",
  ["5b:4336"] = "Das SCHNELLBOOT\
legt nächsten\11Freitag ab.",
  ["5b:435c"] = "Hier kannst du\
MUSCHAS leicht\12fangen. An anderen\
Orten sind sie\11seltener.",
  ["5b:439d"] = "Wie viele ANGELN\
hast du?\12Mit verschiedenen\
ANGELN, fängst du\11verschiedene\11POKéMON.",
  ["5b:43de"] = "M.S. AQUA benutzt\
Spezialdüsen,\11um über die Wellen\11zu gleiten!",
  ["5b:440a"] = "In KANTO gibt es\
viele POKéMON.\12Ich wünschte, ich\
könnte dorthin…",
  ["5b:443f"] = "Wir wollen nicht,\
dass du ins Wasser\12fällst. Darum\
lassen wir dich\11nicht herein.",
  ["5b:466e"] = "Wir legen bald ab.\
Komm bitte\11an Bord.",
  ["5b:4699"] = "Du kannst jetzt\
nicht an Bord.",
  ["5b:46b5"] = "Willkommen an Bord\
der M.S. AQUA.\12Trittst du heute\
deine Reise an?",
  ["5b:46f3"] = "Zeige mir bitte\
dein BOOTSTICKET!",
  ["5b:472f"] = "{PLAYER} zeigt\
das BOOTSTICKET.\12In Ordnung.\
Dankeschön!",
  ["5b:4764"] = "{PLAYER} sucht\
das BOOTS-\11TICKET…\12…Kein TICKET!\12Tut mir leid!\
Du darfst nur\12mit TICKET\
an Bord.",
  ["5b:47cb"] = "Komm jederzeit\
wieder vorbei!",
  ["5b:47f2"] = "Wir legen nächsten\
Sonntag ab.",
  ["5b:4818"] = "Du kommst aus\
JOHTO?\12Dort sollen viele\
seltene POKéMON\11leben.",
  ["5b:49ad"] = "Die M.S. AQUA ist\
auf dem Weg nach\11ORANIA CITY.\12Wir machen eine\
Durchsage, wenn\11wir dort ankommen.",
  ["5b:4a0d"] = "Die M.S. AQUA ist\
auf dem Weg nach\11OLIVIANA CITY.\12Wir machen eine\
Durchsage, wenn\11wir dort ankommen.",
  ["5b:4a6b"] = "Das ist deine\
Kabine.\12Wenn deine POKéMON\
verletzt sind,\12dann mach hier\
ein Nickerchen.\12Dadurch werden\
sie geheilt.",
  ["5b:4ac1"] = "Das ist deine\
Kabine.\12Du kannst deine\
POKéMON heilen,\11indem du ein\11Nickerchen machst.\12Das Schiff wird,\
während du\11schläfst, im Ziel-\11hafen einlaufen.",
  ["5b:4b32"] = "Alle Passagiere\
sind Trainer.\12Sie warten in\
ihren Kabinen auf\11Herausforderer.",
  ["5b:4b84"] = "Boah!\12Entschuldigung.\
Ich habe es eilig!\12Meine Enkelin\
fehlt noch!\12Sie ist noch\
klein. Sag mir\12bitte Bescheid,\
wenn du sie\11siehst!",
  ["5b:4c04"] = "Die M.S. AQUA legt\
in\12OLIVIANA CITY an.",
  ["5b:4c35"] = "Die M.S. AQUA legt\
in\12ORANIA CITY an.",
  ["5b:4dba"] = "Ich werde mein\
Können in KANTO\11testen.",
  ["5b:4de0"] = "Ich wollte\
gewinnen!",
  ["5b:4df2"] = "Trainer aus JOHTO\
können gegen die\12ARENALEITER aus\
KANTO antreten.",
  ["5b:4e2a"] = "Ich trainiere, um\
der CHAMP zu\11werden!",
  ["5b:4e4c"] = "Worin unter-\
scheiden wir uns?",
  ["5b:4e6e"] = "Eines Tages werde\
ich dich besiegen!",
  ["5b:4e8d"] = "Kennst du LILLY?\
Sie ist ein klasse\11DJ in KANTO.",
  ["5b:4eb8"] = "Uargh!",
  ["5b:4ec2"] = "LILLY ist gut,\
aber MARGIT ist\11die Beste!\12Ich möchte gerne\
alle Radiosender\11von JOHTO anhören!",
  ["5b:4f0e"] = "Bist du allein?\
Lass uns kämpfen!",
  ["5b:4f30"] = "Das ist zu viel\
für mich!",
  ["5b:4f4b"] = "Ich frage mich, ob\
es in KANTO Berge\12gibt, die eine\
Besteigung wert\11sind?",
  ["5b:4f89"] = "Richtig, ich bin\
ein Matrose.\12Ich habe nicht\
gefaulenzt!\12Die Kabine war\
frei, darum habe\11ich ein Nickerchen\11gemacht!\12Was soll's!\
Lass uns kämpfen!",
  ["5b:500e"] = "Es war alles meine\
Schuld!",
  ["5b:5028"] = "Als Matrose muss\
man körperlich\11arbeiten. Das ist\11sehr anstrengend!",
  ["5b:5068"] = "Oh, nein. Ich\
habe etwas sehr\11Wichtiges ver-\11loren.",
  ["5b:509a"] = "Ich… ich kann es\
nicht finden…",
  ["5b:50ae"] = "Ich gebe auf. Du\
musst nicht danach\12suchen. Vergiss\
es einfach!",
  ["5b:50ec"] = "Juhu!\
Was für ein Glück!",
  ["5b:50fc"] = "Pech gehabt!\
Ich habe verloren!",
  ["5b:5112"] = "Ich habe hier\
eine tolle Münze\12gefunden. Jemand\
muss sie verloren\11haben…",
  ["5b:5270"] = "Ich gehe nach\
KANTO, um meine\11Feuerspuck-Künste\11vorzuführen!",
  ["5b:52a4"] = "Zisch… Die\
Flamme ist klein…",
  ["5b:52be"] = "Ich denke, Feuer\
ist schwach auf\11hoher See.\12Das ist egal?\
Wirklich?",
  ["5b:52fa"] = "Ich besuche meine\
Oma, um einige\11Käfer zu fangen!",
  ["5b:5329"] = "Ooh, du bist eine\
harte Nuss!",
  ["5b:5347"] = "In JOHTO findest\
du viele POKéMON\11in den Bäumen!",
  ["5b:5379"] = "Ich versuche,\
meine Leiden zu\11vergessen. Lass\11uns kämpfen!",
  ["5b:53a4"] = "Mein Herz weint…",
  ["5b:53b5"] = "Eine Schiffsreise\
ist am besten,\11um ein gebrochenes\11Herz zu vergessen.\12Aber eine Reise\
mit dem SCHNELL-\11BOOT ist für\11die Trauer zu\11kurz.",
  ["5b:5418"] = "Ich werde meine\
Lieder bei der\12RADIOSTATION in\
DUKATIA CITY\11vorspielen.\11",
  ["5b:5456"] = "Yowza!\
Total verzerrt!",
  ["5b:5470"] = "Apropos RADIO-\
STATION: Wie \12lauten die\
Glückszahlen für\11diese Woche?",
  ["5b:54af"] = "Ein weiches Bett!\
Schlafenszeit…",
  ["5b:54cc"] = "Ah, ausgeruht und\
frisch!",
  ["5b:54e9"] = "Die M.S. AQUA\
legt in\12OLIVIANA CITY an.",
  ["5b:551a"] = "Die M.S. AQUA legt\
in\12ORANIA CITY an.",
  ["5b:570e"] = "Wow! Danke, dass\
du mitgekommen\11bist.\12Es war sehr\
schwer, das kleine\11Mädchen bei Laune\11zu halten.",
  ["5b:5760"] = "Hat dir die Fahrt\
mit der M.S. AQUA\11gefallen?\12Sie gleitet\
regelrecht über\11die Wellen.",
  ["5b:57aa"] = "Hallo! Ich kann…\
meine Enkelin\11nirgendwo finden.\12Wenn sie an Bord\
ist, ist alles\12in Ordnung. Aber\
was ist, wenn sie\11über Bord fiel?\12Sie ist ein\
Energiebündel und\12könnte jemanden\
nerven. Ich mache\11mir ernsthaft\11Sorgen…",
  ["5b:585a"] = "{PLAYER}, oder? Ich\
hörte, du hast\11meine Enkelin bei\11Laune gehalten.\12Ich möchte dir\
dafür danken.",
  ["5b:58b2"] = "Ich möchte, dass\
du das nimmst!",
  ["5b:58d5"] = "Wir reisen um\
die Welt.",
  ["5b:58f7"] = "KAPITÄN, spielst\
du mit mir?\12Mir ist langwei-\
lig! Ich möchte\11spielen!",
  ["5b:5936"] = "Hi! Willst du\
mit mir\11spielen?\12…Oh!\12Opa sorgt sich\
um mich?\12Ich muss los!\12Ich muss Opa\
finden!",
  ["5b:599b"] = "Hallo Opa, hier\
bin ich! Ich habe\12mit dem KAPITÄN\
und ihm hier\11gespielt!",
  ["5b:59dd"] = "Das Spielen hat\
mir Spaß gemacht!",
  ["5b:59f9"] = "Hey, Kleiner!\
Möchtest du gegen\11mich antreten?",
  ["5b:5a1c"] = "Du bist stark!",
  ["5b:5a2b"] = "Du reist ganz\
alleine?\12Ist deine Mutter\
nicht besorgt?",
  ["5b:5a5e"] = "Du denkst, ich\
bin noch ein Baby?\11Das ist gemein!",
  ["5b:5a84"] = "Oh! Wir haben\
verloren!",
  ["5b:5a92"] = "“Baby” ist kein\
schöner Name\11für Mädchen!",
  ["5b:5ab9"] = "Ich bin kein Baby!\12So etwas sagt man\
nicht zu einer\11Dame!",
  ["5b:5aea"] = "Oh! Wir haben\
verloren!",
  ["5b:5af8"] = "Manchmal sind\
Kinder schlauer\11als Erwachsene!",
  ["5b:5b25"] = "Ssh! Mein Gehirn\
empfängt Radio-\11wellen!",
  ["5b:5b51"] = "…Ich kann etwas\
hören!",
  ["5b:5b67"] = "Ich verstehe! Man\
kann den Radio-\11sender aus JOHTO\11auf dem SCHNELL-\11BOOT hören.",
  ["5b:5b9e"] = "Was denkst du?\
Meine POKéMON sind\11doch schön, oder?",
  ["5b:5bce"] = "Oh, nein! Meine\
schönen POKéMON!",
  ["5b:5bec"] = "Ich muss in den\
POKéMON-SALON, um\11sie zurechtmachen\11zu lassen!",
  ["5b:5c1f"] = "Ich gehe ins\
EINKAUFSZENTRUM\11und…",
  ["5b:5c4d"] = "Was wollte ich\
tun?",
  ["5b:5c66"] = "Oh, ja! Ich muss\
meine POKéMON von\11der PENSION\11abholen!",
  ["5b:5c97"] = "Was für POKé-\
BÄLLE hast du\11dabei?",
  ["5b:5cc4"] = "Warte! Halt!\
Nicht! Bitte!",
  ["5b:5cdf"] = "Der BALL, den du\
einsetzt, muss zu\11der Situation\11passen.",
  ["5b:5d15"] = "Die M.S. AQUA legt\
in\12ORANIA CITY an.",
  ["5b:5f4b"] = "Kumpel, könntest\
du mal nach meinem\11Kleinen suchen?\12Er faulenzt\
irgendwo. Dieser\11Müßiggänger!\12Ich würde ihn\
selbst suchen,\11aber ich bin\11gerade im Dienst.",
  ["5b:5fd7"] = "Oh,oh…\12Der KAPITÄN\
wird wütend sein…",
  ["5b:5ffe"] = "Danke, Junge!\
Ich habe mit ihm\12geredet, er wird\
nicht mehr\11faulenzen!",
  ["5b:603d"] = "Ein kleines\
Mädchen?\12Ich glaube, sie\
ist hier vorbei-\11gekommen.",
  ["5b:606d"] = "Der Speisesaal\
ist geradeaus.\12Die Treppen am\
Ende führen in\11die KAPITÄNS-\11KAJÜTE.",
  ["5b:60bd"] = "In den Pausen ist\
Kämpfen meine\11Lieblingsbeschäf-\11tigung.",
  ["5b:60ea"] = "Sieg oder\
Niederlage, meine\11Pause ist vorüber!",
  ["5b:6108"] = "Ich denke, ich\
werde nie\11gewinnen, wenn ich\11die Sache nicht\11ernst nehme.",
  ["5b:6133"] = "Mir ist lang-\
weilig. Willst du\11kämpfen?",
  ["5b:6151"] = "Au! Du bist zu\
stark!",
  ["5b:6169"] = "SAFFRONIA,\
PRISMANIA…\11Ich habe gehört,\12es gibt viele\
große Städte\11in KANTO.",
  ["5b:61a7"] = "Uff…\
Ich bin seekrank!",
  ["5b:61ba"] = "Ich kann mich\
nicht bewegen…",
  ["5b:61d2"] = "Ich reise nie\
mehr mit dem\12Schiff. Das\
nächste Mal nehme\11ich den MAGNETZUG.",
  ["5b:6210"] = "Hier arbeiten wir\
Matrosen!",
  ["5b:6230"] = "Ich habe auf\
eigenem Terrain\11verloren…",
  ["5b:624a"] = "Wir bringen unsere\
Passagiere von\12ORANIA CITY nach\
OLIVIANA CITY.",
  ["5b:628c"] = "Auch wenn wir\
mit dem Schiff\11fahren, kann ich\11nicht angeln!\12Wie langweilig!\
Lass uns kämpfen!",
  ["5b:62d8"] = "M-… mir ist nicht\
mehr langweilig…",
  ["5b:62f2"] = "Ich werde am Kai\
von ORANIA angeln.",
  ["5b:6317"] = "Ich trainiere\
meine Beine, indem\12ich das Schaukeln\
des Schiffes\11ausgleiche!",
  ["5b:6355"] = "Gestürzt und platt\
gemacht!",
  ["5b:636e"] = "Ich konnte den\
KARATE-MEISTER in\11JOHTO nicht\11finden.\12Er soll irgendwo\
in einer Höhle\11trainieren.",
  ["5b:63c9"] = "Ich bin Matrose!\12Aber ich trainiere\
POKéMON, um\11der CHAMP zu\11werden!",
  ["5b:640c"] = "Mein Trainings-\
rückstand ist\11offensichtlich…",
  ["5b:642f"] = "Acht ORDEN!\
Das heißt, du\12hast die ARENA-\
LEITER besiegt.\12Kein Wunder, dass\
du so stark bist!",
  ["5b:6486"] = "Lass die Finger\
von meinen\11Schülern!",
  ["5b:64a9"] = "Ah!",
  ["5b:64b1"] = "Wir machen einen\
Ausflug zu den\11RUINEN von\11VIOLA CITY.",
  ["5b:64e4"] = "Kennst du die\
ALPH-RUINEN?",
  ["5b:6504"] = "Ah!",
  ["5b:650d"] = "In den RUINEN\
empfängt das Radio\11seltsame Signale.",
  ["5b:653f"] = "In den ALPH-RUINEN\
gibt es seltsame\11Steinplatten.",
  ["5b:6576"] = "Ich wurde\
vermöbelt!",
  ["5b:6586"] = "Ich habe gelesen,\
dass es vier von\11den Steinplatten\11gibt.",
  ["5b:667f"] = "Die M.S. AQUA\
fährt immer\12montags und\
freitags nach\12KANTO.",
  ["5b:66ed"] = "Das SCHNELLBOOT\
fährt immer\11mittwochs und\11sonntags.",
  ["5b:680b"] = "MONDBERGPLATZ\
Schutt abladen\11verboten",
  ["5b:6882"] = "Bei Sonnenunter-\
gang kommt PIEPI\11heraus, um zu\11spielen.",
  ["5b:693b"] = "Uah!",
  ["5c:400f"] = "Ich wollte einen\
Geschenkartikel\12in der SAFARI-ZONE\
kaufen, aber sie\11ist geschlossen…",
  ["5c:4050"] = "In dieser Stadt\
lebt auch die\11Enkelin des\11WÄRTERS der\11SAFARI-ZONE.",
  ["5c:424f"] = "Hehehehe…\12Es tut mir Leid,\
dich enttäuschen\11zu müssen…\12Ich mache\
nur Witze!\12Jetzt geht es\
rund!\12Ich bin JANINA,\
ARENALEITERIN von\12FUCHSANIA CITY!",
  ["5c:42bb"] = "JANINA: Du bist\
recht stark. Ein\11klarer Sieg für\11dich…\12Nimm jetzt den\
SEELENORDEN.",
  ["5c:4305"] = "{PLAYER} erhält\
SEELENORDEN.",
  ["5c:431c"] = "JANINA: Du bist so\
stark! Ich habe\11ein Geschenk für\11dich!\12Es ist TOXIN, ein\
sehr starkes Gift,\12das dem Opfer\
ständig KP\11entzieht.",
  ["5c:438e"] = "JANINA: Ich werde\
mich jetzt mehr\12anstrengen und\
meine Fähigkeiten\11optimieren.\12Ich möchte meinen\
Vater und dich\11übertreffen!",
  ["5c:4400"] = "Hehehe!\12Ich bin JANINA,\
die ARENALEITERIN!\12Bin ich doch\
nicht! Reinge-\11fallen, Blödmann!",
  ["5c:4440"] = "Ich habe dich\
reingelegt…",
  ["5c:4453"] = "Wie erkennst du\
die Echte\11ARENALEITERIN?",
  ["5c:4480"] = "Reingelegt!\
Hahaha!",
  ["5c:4495"] = "Oh… Ich habe\
verloren… Du bist\11kein Schwächling…",
  ["5c:44b3"] = "Na, war meine\
Maskerade nicht\11perfekt?",
  ["5c:44d5"] = "Ich bin JANINA!\12Woher wusstest du,\
dass ich die Echte\11bin?\12Auf in den Kampf!",
  ["5c:450b"] = "Mist! Ich\
wollte gewinnen!",
  ["5c:4526"] = "Du musst langsam\
müde werden.",
  ["5c:4542"] = "Hahahaha!\12Du kannst Gift\
darauf nehmen,\11dass ich JANINA\11bin!",
  ["5c:456a"] = "Meine Verkleidung\
hat funktioniert!",
  ["5c:458b"] = "He, Holzkopf. War\
meine Verkleidung\11nicht hübsch?",
  ["5c:45ba"] = "He! Ein CHAMP\
in spe!\12Nanu! Sieh dich\
mal um. Alle\12Trainer sehen aus\
wie die ARENA-\11LEITERIN JANINA.\12Welche davon ist\
die echte JANINA?",
  ["5c:4646"] = "Das war ein\
hervorragender\11Kampf, Trainer\11aus JOHTO!",
  ["5c:46e4"] = "Mein Großvater\
besucht meinen\11Bruder BILL am KAP\11bei AZURIA CITY.",
  ["5c:471a"] = "Ich habe diese\
merkwürdigen,\11langsamen POKéMON\11auf dem RADWEG\11gesehen.",
  ["5c:47b5"] = "He! Du hast einen\
völlig neuen\11POKéDEX!\12Hat PROF. EICH\
dir den gegeben?",
  ["5c:47fd"] = "Ich habe mich in\
der PKMN-ARENA\12ganz schön\
erschreckt.\12Da waren viele\
Mädchen, die alle\11gleich aussahen.",
  ["5c:484f"] = "Ich bin JANINA!\
Hokus pokus…\11Fidibus!\11",
  ["5c:486f"] = "Siehst du! Jetzt\
sehe ich genauso\11aus wie sie!",
  ["5c:4907"] = "Mein Großvater ist\
der WÄRTER in der\11SAFARI-ZONE.\12Zumindest war er\
das…\12Er hat sich ent-\
schieden, Urlaub\12zu machen und ist\
verreist, ganz\11allein.\12Er hat einfach\
so die SAFARI-\11ZONE verlassen.",
  ["5c:49b2"] = "Viele Leute waren\
traurig, dass die\12SAFARI-ZONE ge-\
schlossen wurde.\11Aber Großvater ist\11so stur…",
  ["5c:4a0b"] = "Das Foto zeigt\
einen lächelnden,\12alten Mann umgeben\
von POKéMON.",
  ["5c:4a47"] = "Das Foto zeigt\
eine große Wiese,\12auf der seltene\
POKéMON\11herumtollen.",
  ["5c:4ac2"] = "Du arbeitest an\
einem POKéDEX? Das\12ist doch schon\
etwas.\11Gib nicht auf!",
  ["5c:4b31"] = "Trainer, die nach\
Stärke streben,\12erklimmen den SIL-\
BERBERG trotz sei-\12ner vielen Gefah-\
ren…\12Durch ihre treuen\
POKéMON haben\12sie das Gefühl,\
überall hinkommen\12zu können…",
  ["5c:4c13"] = "Oh, du hast\
mich gefunden.\12Bitte erzähl\
niemandem von mir.\12Ich gebe dir dies,\
wenn du mich nicht\11verrätst. Bitte?",
  ["5c:4c81"] = "Es ist hart so\
berühmt zu sein.\12Wo immer ich auch\
hingehe, die Leute\11folgen mir.\12Ich möchte nur\
meine Ruhe haben…",
  ["5c:4ce3"] = "IBITAK: Ibitaag!",
  ["5c:4fa4"] = "Willkommen im\
KABEL-CLUB-\11KOLOSSEUM.\12Du kannst hier\
gegen einen Freund\11antreten.\12Möchtest du gerne\
kämpfen?",
  ["5c:4ffe"] = "Willkommen im\
KABEL-CLUB-\11HANDELSCENTER.\12Du kannst hier\
POKéMON mit einem\11Freund tauschen.\12Möchtest du gerne\
tauschen?",
  ["5c:5068"] = "Willkommen in\
der ZEITKAPSEL.\12Du kannst in die\
Vergangenheit\11reisen und deine\11POKéMON tauschen.\12Möchtest du gerne\
durch die Zeit\11tauschen?",
  ["5c:50e2"] = "Dein Freund ist\
noch nicht fertig.",
  ["5c:50fd"] = "Bevor du die\
Verbindung her-\11stellst, musst du\11deinen Spielstand\11speichern.",
  ["5c:5130"] = "Bitte warten!",
  ["5c:513e"] = "Die Verbindung\
wurde aufgrund\11fehlender Aktionen\11abgebrochen.\12Nimm bitte Kontakt\
mit deinem Freund\11auf und komm dann\11wieder.",
  ["5c:519a"] = "Komm später\
wieder!",
  ["5c:51f2"] = "Du kannst hier\
keine Verbindung\11zur Vergangenheit\11herstellen.",
  ["5c:5213"] = "Dein Freund hat\
einen anderen Raum\11gewählt.",
  ["5c:5238"] = "Komm doch herein.",
  ["5c:5258"] = "Leider kannst du\
{STRBUF}\11nicht mitnehmen.",
  ["5c:5275"] = "{STRBUF}\
kann {STRBUF}\11nicht anwenden.",
  ["5c:529c"] = "Du kannst\
{STRBUF} nicht\11anwählen, weil es\11einen BRIEF trägt.",
  ["5c:52cd"] = "Leider wird die\
ZEITKAPSEL gerade\11repariert.",
  ["5c:52fc"] = "Leider wird der\
TAUSCHAUTOMAT\11gerade repariert.",
  ["5c:532c"] = "Leider wird der\
KAMPFAUTOMAT\11gerade repariert.",
  ["5c:535d"] = "Hallo! Du bist\
doch {PLAYER}.\12Ich habe hier\
Etwas für dich.",
  ["5c:5391"] = "Hier, bitte sehr!",
  ["5c:539f"] = "Hoffentlich können\
wir dir bald wie-\11der behilflich\11sein.",
  ["5c:53bc"] = "Oh, du hast keinen\
Platz dafür.\12Du kannst es dir\
in jedem PKMN-\12CENTER des\
Landes abholen.",
  ["5c:541a"] = "Nein? Das ist aber\
merkwürdig…",
  ["5c:553d"] = "Dein Freund ist\
jetzt bereit.",
  ["5c:55be"] = "Dein Freund ist\
jetzt bereit.",
  ["5d:401f"] = "Im Norden von\
LAVANDIA ist der\12FELSTUNNEL. Er\
führt zum\11KRAFTWERK.",
  ["5d:4072"] = "Es gibt eine\
Musiksendung im\11Radio, die Melo-\11dien auf der POKé-\11FLÖTE sendet.\12Ach ja? Ah, dein\
Radio braucht ein\11ZUSATZSET, damit\11du das empfangen\11kannst.",
  ["5d:40db"] = "Die RADIOSTATION\
kann nicht auf\12Sendung gehen,\
weil das KRAFTWERK\11nicht arbeitet.",
  ["5d:411e"] = "Der INTENDANT der\
RADIOSTATION war\11hoch erfreut.\12Er sagte, sie\
seien wieder auf\12Sendung, weil das\
KRAFTWERK wieder\11einwandfrei\11arbeite.",
  ["5d:4222"] = "Hier wohnt MR.\
FUJI, aber er ist\12jetzt nicht\
zu Hause.\12Er müsste in der\
RUHESTÄTTE sein.",
  ["5d:4271"] = "Es gibt kalt-\
herzige Menschen,\11die einfach ihre\11POKéMON im Stich\11lassen.\12Großvater nimmt\
die armen, heimat-\12losen POKéMON auf\
und sorgt für sie.",
  ["5d:42e7"] = "ENTON: Qua-qua?",
  ["5d:42fa"] = "NIDORINO: Nido!",
  ["5d:430b"] = "TAUBSI: Gru gru!",
  ["5d:437e"] = "LAVANDIA ist eine\
ruhige, kleine\12Stadt am Fuße der\
Berge.\12In letzter Zeit\
ist es durch den\12Bau des RADIOTURMs\
etwas geschäftiger\11geworden.",
  ["5d:445a"] = "Es ist unabding-\
bar, SCHUTZ bei\12sich zu haben,\
wenn man Höhlen\11erkundet.\12Obwohl ich Höhlen\
sehr gerne\12erforsche, habe\
ich noch nicht\11alle erforscht.",
  ["5d:44dd"] = "Ich habe von einem\
Kunstschmied\12gehört, der maß-\
gefertigte POKé-\12BÄLLE in AZALEA\
in JOHTO her-\11stellt. Ich\11wünschte, ich\11hätte auch welche.",
  ["5d:4586"] = "MR. FUJI: Sei\
willkommen.\12Hm… Du scheinst\
deine POKéMON\12mit Sorgfalt und\
Liebe aufzuziehen.\12Solche, die POKé-\
MON verehren,\12zollen hier den\
dahingegangenen\11POKéMON ihren\11Respekt.\12Bekunde bitte dein\
Beileid für die\12Seelen der\
dahingegangenen\11POKéMON.\12Ich bin sicher,\
das macht sie\11glücklich.",
  ["5d:4680"] = "Ich glaube, hier\
liegen noch andere\11POKéMON begraben.\12Es gibt viele\
Kammern, die nur\11MR. FUJI betreten\11darf.",
  ["5d:46e4"] = "Ich besuche mit\
meiner Mutter die\11Grabmale der\11POKéMON…",
  ["5d:470e"] = "Die POKéMON, die\
bei mir lebten…\12Ich hatte sie so\
lieb wie meine\11Enkelkinder…",
  ["5d:47f2"] = "Willkommen!\
Schau dich auf\12dieser Etage\
ruhig um.",
  ["5d:482d"] = "Du darfst leider\
nur das Erd-\11geschoss erkunden.\12Seit der RADIOTURM\
in JOHTO von einer\12Verbrechergang\
besetzt wurde,\12mussten wir unsere\
Sicherheitsmaß-\11nahmen erhöhen.",
  ["5d:48c3"] = "Viele Menschen\
arbeiten sehr hart\11im RADIOTURM.\12Sie müssen ihr\
Bestes geben für\11eine gute Sendung.",
  ["5d:492e"] = "Nein, nein, nein!\12Wir sind nicht\
mehr auf Sendung,\12seit das KRAFTWERK\
nicht mehr läuft.\12Alle Bemühungen,\
diese Station zum\12Laufen zu bringen,\
sind vergebens,\11wenn ich nichts\11senden kann.\12Ich bin ruiniert!",
  ["5d:49d4"] = "Ah! Dann bist du\
{PLAYER}, der das\12Problem mit dem\
KRAFTWERK gelöst\11hat?\12Dir habe ich es zu\
verdanken, dass\12ich nicht arbeits-\
los wurde! Du bist\11mein Lebensretter!\12Zum Dank gebe ich\
dir das hier.",
  ["5d:4a74"] = "Damit kannst du\
die Radioprogramme\12in KANTO\
empfangen.\12Hahahahaha!",
  ["5d:4ac6"] = "Hi, mein Freund!\12Ich bin der\
tolle MUSIK-\11REDAKTEUR!\12Was? Dein POKéCOM\
kann meine Musik-\12sendungen nicht\
empfangen? Wie\11traurig!\12Wenn du dir ein\
ZUSATZSET be-\12sorgst, empfängst\
du meine Send-\12ungen. Hol es dir\
bald!",
  ["5d:4b83"] = "Hi, mein Freund!\12Ich bin der\
tolle MUSIK-\11REDAKTEUR!\12Ich bin derjenige,\
der diese wunder-\12vollen Melodien\
auf Sendung\11bringt.\12Sei so frei\
und lausche der\11schönen Melodei!",
  ["5d:4c26"] = "EG REZEPTION\
S1 VERKAUF\11S2 PERSONAL\11S3 PRODUKTION\11S4 BÜRO DES\11   INTENDANTEN",
  ["5d:4c70"] = "Mach deine POKéMON\
mit den Fröhlichen\12Melodien der POKé-\
FLÖTE auf PROGRAMM\01120 wieder munter.",
  ["5d:4d5c"] = "Warst du schon in\
LAVANDIA?\12Dort steht ein\
hoher RADIOTURM.",
  ["5d:4df2"] = "Ich bin der\
jüngere Bruder des\11PROFI-ANGLERS.\12Wie ich sehe,\
macht dir Angeln\12Spaß. Darüber gibt\
es keinen Zweifel!\12Na? Das stimmt\
doch, oder?",
  ["5d:4e72"] = "Jawohl! Genau, wie\
ich dachte!\12Hier, Angelfreak!\
Nimm dies - die\11SUPERANGEL.",
  ["5d:4ebf"] = "Wirf sie aus und\
angle, wo immer\11es Wasser gibt.\12Denk daran - du\
kannst mit ver-\12schiedenen Angeln\
auch verschiedene\11POKéMON fangen.",
  ["5d:4f2f"] = "Hä? Meine Augen\
haben mich\11getäuscht.",
  ["5d:4ff8"] = "Ich… Ich bin\
schockiert!\12Ein Junge in dei-\
nem Alter mit\12stechenden Augen\
und langen Haaren\11kam hier rein.\12Er hat mich ge-\
zwungen, ihm meine\11preisgekrönten\11POKéMON zu geben!\12Ich habe zwar noch\
eines übrig, aber\11was soll ich tun, \11wenn er zurück-\11kommt?\12Du siehst stark\
aus. Würdest du\12auf mein POKéMON\
aufpassen?",
  ["5d:50e2"] = "Oh, ich danke dir!\12Bitte pass gut da-\
rauf auf!",
  ["5d:5110"] = "{PLAYER} erhält ein\
POKéMON.",
  ["5d:5124"] = "Du hast keinen\
Platz mehr in dei-\11nem Team.",
  ["5d:513e"] = "Oh nein… Was soll\
ich nur tun, wenn\11er zurückkommt?",
  ["5d:5165"] = "Hi! Wie geht es\
meinem POKéMON?\12Ich glaube, ich\
bin jetzt sicher.\11Kann ich es zu-\11rück haben?",
  ["5d:51a6"] = "Danke!",
  ["5d:51b2"] = "Hey, du hast mein\
POKéMON gar nicht\11dabei!",
  ["5d:51d8"] = "Mein POKéMON\
scheint dich zu\11mögen.\12Na gut, dann\
sollst du es be-\12halten. Aber ver-\
sprich mir, es gut\11zu behandeln.",
  ["5d:5234"] = "Oh, nein, nein…\
das ist so, als\11würde man beraubt\11werden.",
  ["5d:5261"] = "Für POKéMON ist\
es das höchste\12Glück, wenn sie\
bei jemandem sein\12dürfen, der sie\
gut behandelt.",
  ["5d:53ee"] = "WAHAHAH!\12Du hast es also\
bis hierher ge-\11schafft!\12Lass dir gesagt\
sein, dass ich ein\11harter Brocken\11bin.\12Meine POKéMON\
werden dich in\11Grund und Boden\11rammen!\12Pass auf!",
  ["5d:5464"] = "HARTWIG: Urggh!\
…\12Oooarrgh!",
  ["5d:547f"] = "Da! Jetzt hast du\
dich erschreckt!\12Wie?\
Es hat nichts mit\12POKéMON zu tun?\
Das ist wahr!\12Komm her. Lass uns\
kämpfen!",
  ["5d:54eb"] = "Wa…? Huch?\
Ich habe verloren?\12Wie wär's damit?\
Du bist des FAUST-\11ORDENS würdig!",
  ["5d:552a"] = "{PLAYER} erhält\
FAUSTORDEN.",
  ["5d:5542"] = "Durch den FAUSTOR-\
DEN gehorchen dir\12alle POKéMON\
bis LV 70. Dies\12gilt auch für Ge-\
tauschte.\12Außerdem können\
deine POKéMON\12FLIEGEN auch\
außerhalb eines\11Kampfes einsetzen.\12Hier, nimm auch\
dies!",
  ["5d:55cf"] = "Das ist WUCHT-\
SCHLAG.\12Er trifft zwar\
nicht immer, aber\12wenn er es tut,\
verwirrt er den\11Gegner!",
  ["5d:5625"] = "WAHAHAH! Es hat\
Spaß gemacht, ge-\11gen dich zu kämp-\11fen.\12Aber eine Nieder-\
lage bleibt eine\11Niederlage!\12Von jetzt an werde\
ich 24 Stunden am\11Tag trainieren!",
  ["5d:568c"] = "Meine POKéMON und\
mich verbindet un-\11sere Freundschaft.\12Dieses Band wird\
nie zerreissen!",
  ["5d:56de"] = "Das ist unmöglich!",
  ["5d:56ef"] = "Es scheint, als\
stündest auch du\11deinen POKéMON\11sehr nahe!",
  ["5d:5723"] = "Wir Meister der\
Kampfkunst haben\11vor nichts Angst!",
  ["5d:5745"] = "Schockierend!",
  ["5d:5756"] = "Kampf-POKéMON\
fürchten sich vor\11Psycho-Attacken…",
  ["5d:577f"] = "Worte sind nutz-\
los. Lass deine\11Fäuste sprechen!",
  ["5d:57b2"] = "…",
  ["5d:57b5"] = "Ich habe verloren!\
Ich bin sprachlos!",
  ["5d:57ce"] = "Gegen die Wut mei-\
ner Fäuste können\11deine POKéMON\11nichts ausrichten!",
  ["5d:57f7"] = "Ich wurde zer-\
schmettert!",
  ["5d:5809"] = "Meine POKéMON ha-\
ben verloren…\11Mein Stolz ist\11zerstört…",
  ["5d:58dd"] = "Hast du schon den\
POKéMANIAC getrof-\11fen?\12Er gibt immer mit\
seinen seltenen\11POKéMON an.",
  ["5d:5923"] = "Die Trainer in\
dieser Arena sind\11richtige Schläger-\11Typen.\12Wenn ich hier rum-\
stehe, schnappen\11sie mich.\12Ein Tipp: Der LEI-\
TER setzt gerne\12Kampf-POKéMON\
ein.\12Du solltest ihn\
mit Psycho-POKé-\11MON überraschen.\12Besiege seine\
POKéMON, bevor sie\12ihre Kraft ein-\
setzen können.",
  ["5d:5a2a"] = "{PLAYER}! Du hast\
gewonnen! Das habe\11ich dir gleich an-\11gesehen!",
  ["5d:5ac9"] = "Deinen POKéMON\
scheint es gut zu\12gehen. Bedrückt\
dich etwas?\12…\12Dem POKéMON vom\
LEUCHTTURM geht es\11nicht gut?\12Ich hab's!\12Das sollte das\
Problem lösen.",
  ["5d:5b52"] = "{PLAYER} erhält\
GEHEIMTRANK.",
  ["5d:5b6c"] = "Mein GEHEIMTRANK\
ist sehr stark.\12Ich biete ihn nur\
in Notfällen an.",
  ["5d:5bf5"] = "Deine POKéMON sind\
großartig!\12Wie wär's mit ei-\
nem Foto als Sou-\11venir?",
  ["5d:5c3e"] = "O.K.! Und jetzt\
sag: CHEESE!",
  ["5d:5c52"] = "Oh, schade. Ich\
dachte, das wäre\12ein schönes Anden-\
ken…",
  ["5d:5cb8"] = "Du kommst von\
OLIVIANA CITY?\12Hast du auf dem\
Weg hierher die\11vier Inseln ge-\11sehen?\12Ich habe gehört,\
dass sich dort ein\11mythisches Wesen\11verstecken soll.",
  ["5d:5d3b"] = "Man sagt auch,\
dass man es nur\12sehen kann, wenn\
man einen SILBER-\11FLÜGEL hat.\12Er muss den selben\
Geruch wie diese\11Kreatur haben.",
  ["5d:5da5"] = "Die Strudel rund\
um die Inseln wer-\12den sicher durch\
diese Kreatur er-\12zeugt.",
  ["5e:4011"] = "Hallo! Willkommen\
im EINKAUFSZENTRUM\11von PRISMANIA\11CITY!\12Die Übersicht\
ist an der Wand.",
  ["5e:4057"] = "Dieses EINKAUFS-\
ZENTRUM gehört\12derselben Kette\
an, wie das in\11DUKATIA CITY.\12Sie wurden beide\
zur selben Zeit\11renoviert.",
  ["5e:40cb"] = "Ich bin zum\
ersten Mal hier.\12Es ist so groß…\12Ich habe Angst,\
mich zu verlaufen.",
  ["5e:410c"] = "EG: KUNDEN-\
    INFORMATION\12S1: ZUBEHÖR für\
    TRAINER\12S2: TM-LADEN\12S3: GESCHENK-\
    ARTIKEL\12S4: DROGERIE\12S5: SPIEL-\
    AUTOMATEN",
  ["5e:41ed"] = "Ich bin erst vor\
kurzem Trainer\12geworden. Mein\
Sohn hat mir dazu\11geraten.\12Dieses riesige\
Angebot an nützli-\11chen Items ist\11überwältigend.",
  ["5e:4262"] = "Mein Papa hat sich\
sehr schwer getan,\12die Bezeichnungen\
aller Items zu\12lernen und zu\
unterscheiden,\12wann man sie\
einsetzt…",
  ["5e:42c0"] = "Nützliche Items\
für Trainer!\12S1: ZUBEHÖR für\
    TRAINER",
  ["5e:4377"] = "Ich kann mich\
nicht entscheiden,\12welches POKéMON\
diese TM erhalten\11soll…",
  ["5e:43aa"] = "Oh, oh! Ich habe\
mein POKéMON\12getauscht, ohne\
ihm UP-GRADE\11wegzunehmen.",
  ["5e:43eb"] = "Ja! Endlich habe\
habe ich mein\11PORYGON!\12Ich bin nicht sehr\
gut an den Spiel-\12automaten. Deswe-\
gen habe ich nie\11genügend Münzen…\12…Was?\12Das getauschte\
PORYGON hat sich\11in ein anderes\11POKéMON\11verwandelt!",
  ["5e:4485"] = "Im TM-LADEN erhält\
man seltene\11Attacken.",
  ["5e:44a9"] = "S2: TM-LADEN\12Mach Deine POKéMON\
Stärker!",
  ["5e:4545"] = "Ich möchte hier\
einen SURFERBRIEF\11an meine Freundin\11schicken.",
  ["5e:4579"] = "Das ist der\
einzige Ort, an\12dem man einen\
HERZBRIEF ver-\11schicken kann.",
  ["5e:45b0"] = "Lass Geschenke\
Für Dich Sprechen!\12S3: GESCHENK-\
....ARTIKEL",
  ["5e:4647"] = "Ich möchte Items\
kaufen, mit denen\12der Status meiner\
POKéMON verbessert\11wird, aber ich\11habe nicht genug\11Geld…",
  ["5e:4696"] = "Ich möchte AP-PLUS\
kaufen, damit die\12AP der Attacken\
steigen, aber das\12kann man nicht\
kaufen…",
  ["5e:46da"] = "Es macht POKé-\
MON glücklich,\11wenn sie Items\11benutzen dürfen.\12Allerdings mögen\
sie manche Items\11nicht…",
  ["5e:4724"] = "S4: DROGERIE",
  ["5e:486c"] = "Ein Automat!\
Hier ist die\11Anleitung.",
  ["5e:4890"] = "Klang!\12{STRBUF}\
liegt im Schacht.",
  ["5e:48aa"] = "Ups, ich habe\
nicht genug Geld…",
  ["5e:48c3"] = "Da ist nicht genug\
Platz für mehr\11Utensilien…",
  ["5e:48e3"] = "Ein Spielautomat\
mit einem\11Roulette…\12Die gibt es schon\
lange nicht mehr.",
  ["5e:492c"] = "Och! Hier gibt es\
keine Spiele!\12Ich wollte doch\
spielen…",
  ["5e:495a"] = "S5: DACHTERRASSE\
SPIELAUTOMATEN",
  ["5e:4a32"] = "Meine süßen POKé-\
MON sind meine\12Begleiter. Mit\
ihnen fühle ich\11mich nie allein.\12MAUZI bringt sogar\
Geld nach Hause.",
  ["5e:4a8c"] = "MAUZI: Mauz!",
  ["5e:4a9b"] = "PIEPI: Piep piep\
piep!",
  ["5e:4ab2"] = "NIDORAN: Nido\
nido!",
  ["5e:4ac7"] = "PRISMANIA-VILLA\
SUITE des MANAGERS",
  ["5e:4b55"] = "{PLAYER} hat den\
PC eingeschaltet.\12…\12Jemand war gerade\
dabei, eine E-Mail\11aufzusetzen.\12…Ich hoffe, du\
kommst einmal nach\11KANTO.\12Ich glaube, du\
wärst überrascht,\12wie viel sich hier\
verändert hat.\12Man sieht auch\
viele POKéMON, die\12nicht aus JOHTO\
stammen.\12An den PRODUZENTEN\12…",
  ["5e:4c48"] = "GAME FREAK\
KONFERENZRAUM",
  ["5e:4cea"] = "Ist das richtig?\12Ich bin der\
SPIELDESIGNER!\12Es ist schwer,\
den POKéDEX zu\11erstellen, aber\11gib nicht auf!",
  ["5e:4d41"] = "Wow! Hervorragend!\
Dein POKéDEX ist\11komplett!\12Gratuliere!",
  ["5e:4d7c"] = "…",
  ["5e:4d7f"] = "Der GRAFIKER wird\
dir ein DIPLOM\11ausdrucken.\12Gib ruhig damit\
an.",
  ["5e:4dd0"] = "Ich bin der\
GRAFIKER.\12Ich habe eine\
Zeichnung von dir\11angefertigt!",
  ["5e:4df4"] = "Ich bin der\
GRAFIKER.\12Oh, du hast deinen\
POKéDEX fertig\11gestellt?\12Möchtest du, dass\
ich dir ein DIPLOM\11ausdrucke?",
  ["5e:4e4c"] = "Gib mir bescheid,\
wenn ich dir dein\11DIPLOM ausdrucken\11soll.",
  ["5e:4eb1"] = "Wer, ich? Ich bin\
der PROGRAMMIERER.\12Probier die\
Spielautomaten\11aus!",
  ["5e:4ee6"] = "Sind die ZWILLINGE\
nicht\11anbetungswürdig?\12JASMIN ist auch\
sehr hübsch.\12Oh, ich bete\
sie an!",
  ["5e:4f27"] = "GAME FREAK\
ENTWICKLUNGSRAUM",
  ["5e:4f44"] = "Das ist eine sehr\
detaillierte\11Zeichnung eines\11hübschen Mädchens.",
  ["5e:4f6e"] = "Das ist das Spiel-\
programm. Die\12falsche Handhabe\
könnte Fehler im\11Spiel verursachen!",
  ["5e:4fb2"] = "Es ist angefüllt\
mit Utensilien.\11Da ist sogar eine\11POKéPUPPE.",
  ["5e:50ad"] = "Lass mich eine\
gruselige Ge-\11schichte erzählen…",
  ["5e:50d0"] = "Allerdings so\
unheimlich ist\12sie gar nicht,\
wenn es draußen\11noch hell ist.\12Komm wieder, wenn\
die Sonne unterge-\11gangen ist, O.K.?",
  ["5e:5129"] = "Es war einmal ein\
kleiner Junge. Er\12hat eines Tages\
ein neues FAHRRAD\11bekommen…\12Er wollte sofort\
darauf fahren…\12Das machte ihm so\
viel Spaß, dass er\12gar nicht be-\
merkte, dass die\12Sonne unterge-\
gangen war…\12Auf dem Weg nach\
Hause durch die\12pechschwarze Nacht\
wurde das Rad\11langsamer!\12Die Pedale wurden\
schwer wie Blei!\12Als er aufhörte,\
in die Pedale zu\12treten, rollte das\
Rad rückwärts!\12Es schien fast,\
als wäre das Rad\12verhext und ver-\
suche, ihn ins\12Verderben zu\
bringen!\12…\12…\12Kreiiisch!\12Der Junge war den\
RADWEG bergauf\11gefahren!\12…\
Ba-dum ba-dum!\12Es ist schön, dass\
du meiner Ge-\11schichte so\11aufmerksam\11gelauscht hast\11Nimm dies - TM03!",
  ["5e:5339"] = "TM03 enthält\
FLUCH.\12Das ist eine\
schreckliche\12Attacke, bei der\
die KP des Opfers\11verringert werden.",
  ["5e:53b4"] = "ERIKA versteht es\
meisterlich, mit\12Pflanzen-POKéMON\
umzugehen.\12Eine Unachtsamkeit\
wird dir bei ihr\11übel bekommen.",
  ["5e:5405"] = "Das Versteck von\
TEAM ROCKET befin-\12det sich im Keller\
der SPIELHALLE.\12Oh, warte. Das war\
vor drei Jahren.",
  ["5e:5571"] = "Willkommen!\12Du kannst deine\
Münzen nebenan\12gegen fabelhafte\
Preise ein-\11tauschen.",
  ["5e:55b6"] = "Die Spielautomaten\
sind alle\11hochmodern.",
  ["5e:55e3"] = "An diesem Automa-\
ten will ich\11spielen.\12An dem habe ich\
gestern haushoch\12verloren. Das will\
ich heute wieder-\11haben.",
  ["5e:5636"] = "Ich glaube, an\
diesem Automaten\11werde ich\11gewinnen…\12Die Gewinnchancen\
sind bei jedem\11Automaten anders.",
  ["5e:567d"] = "Hahahaha!\12Die Münzen kommen\
einfach herausge-\11purzelt!\12Hm? Was ist, Kind?\
Möchtest du\11spielen?\12Ich werde mein\
Glück mit dir\12teilen!",
  ["5e:56e6"] = "Hahahaha!\12Ich fühle mich\
wohl, wenn ich\12anderen etwas\
Gutes tue!",
  ["5e:572b"] = "He, du hast\
keinen MÜNZKORB.\12Wie soll ich dir\
Münzen geben,\11mein Kind?",
  ["5e:577a"] = "He, dein\
MÜNZKORB ist voll.\12Du hast wohl\
eine Glücks-\11strähne.",
  ["5e:57c6"] = "He! Ein CHAMP\
in spe!\12Spielst du auch an\
den Automaten?\12Ich möchte genug\
Münzen sammeln für\11ein prämiertes\11POKéMON.\12Aber ich habe noch\
nicht genug\11Münzen…",
  ["5e:584e"] = "Hm… Die Chancen,\
eine PIKACHU-Reihe\12zu bekommen,\
stehen gut, aber…\11Was nun?",
  ["5e:5894"] = "He!\12Hinter diesem\
Poster…\12Da ist nichts!",
  ["5e:58c2"] = "He!\12Hinter diesem\
Poster…\12Da ist nichts!",
  ["5e:58f0"] = "Da ist ein\
Feuerzeug.",
  ["5e:5908"] = "Eine Wasser-\
flasche…\12Die muss jemandem\
gehören, der sie\11holen wird…\12Was? Sie ist leer!",
  ["5e:5c59"] = "Ich wollte\
PANTIMOS haben,\11aber mir fehlten\011100 Münzen…",
  ["5e:5c8a"] = "Puh…\12Ich muss ruhig\
Blut bewahren…\12Wenn ich nervös\
werde, könnte ich\11mein ganzes Geld\11verlieren…",
  ["5e:5cdf"] = "Willkommen!\12Wir tauschen deine\
Münzen ein gegen\11fabelhafte Preise!",
  ["5e:5d15"] = "Welchen Preis\
hättest du gerne?",
  ["5e:5d32"] = "Du willst also\
{STRBUF}?",
  ["5e:5d4e"] = "Hier, bitte sehr!",
  ["5e:5d5c"] = "Du hast nicht\
genug Münzen.",
  ["5e:5d79"] = "Du hast dafür\
keinen Platz.",
  ["5e:5d93"] = "Oh. Komm bitte\
mit Münzen wieder!",
  ["5e:5db5"] = "Ach, du hast\
keinen MÜNZKORB?",
  ["5e:5ec9"] = "ERIKA: Hallo…\
Schönes Wetter,\12nicht?\
Einfach herrlich…\12…Ich könnte gleich\
einschlafen…\12Ich heiße ERIKA.\
Ich bin die ARENA-\12LEITERIN von\
PRISMANIA CITY.\12…Wirklich? Den\
ganzen Weg von \11JOHTO? Wie nett…\12Oh, entschuldige.\
Ich wusste\12nicht, dass du\
gegen mich kämpfen\11willst.\12Nun gut. Ich werde\
jedenfalls nicht\11verlieren.",
  ["5e:5fdf"] = "ERIKA: Oh!\
Ich gebe mich\11geschlagen…\12Du bist außerge-\
wöhnlich stark…\12Ich gebe dir den\
FARBORDEN…",
  ["5e:6037"] = "{PLAYER} erhält\
FARBORDEN.",
  ["5e:6051"] = "ERIKA: Das war ein\
herrlicher Kampf.\12Das spornt zu\
neuen Taten an.\12Nimm bitte diese\
TM an.\12Es ist GIGASAUGER.\12Das ist eine\
schöne Attacke.\12Die Hälfte des zu-\
gefügten Schadens\11wird zur Heilung\12deines POKéMON\
verwendet.\12Verwende sie,\
wann immer du\11möchtest…",
  ["5e:6130"] = "ERIKA: Eine\
Niederlage ist\12nicht sehr\
angenehm…\12Aber es ist ein\
Ansporn dazu, sich\12mehr anzustrengen,\
wenn man weiß,\12dass es starke\
Trainer gibt…",
  ["5e:619d"] = "Halt! Hier haben\
nur Mädchen\11Zutritt!",
  ["5e:61c1"] = "Ach ne!",
  ["5e:61cd"] = "Es ist nicht so,\
dass wir keine\11Jungen mögen.\12Aber es gibt\
einige Dinge, über\12die sich nur\
Mädchen unter-\11halten können.",
  ["5e:622f"] = "Oh, ein Kampf?\
Das macht mir ein\11bisschen Angst,\11aber von mir aus!",
  ["5e:625b"] = "Ach, das war es?",
  ["5e:626a"] = "Oh, sieh nur, all\
die ORDEN. Kein\12Wunder, dass ich\
verloren habe!",
  ["5e:62a1"] = "Hast du die\
Blumen betrachtet\11oder mich?",
  ["5e:62ce"] = "Wie ärgerlich!",
  ["5e:62dd"] = "Wie werde ich nur\
so damenhaft\11wie ERIKA?",
  ["5e:630e"] = "Wir zeigen dir\
POKéMON-Attacken,\11die ERIKA uns\11beigebracht hat!",
  ["5e:633e"] = "Oh… Wir haben\
verloren…",
  ["5e:634c"] = "ERIKA wird es dir\
heimzahlen!",
  ["5e:636d"] = "Wir werden ERIKA\
beschützen!",
  ["5e:638b"] = "Wir hatten keine\
Chance…",
  ["5e:639c"] = "ERIKA ist viel\
stärker!",
  ["5e:64ba"] = "Hi!\12Wir halten gerade\
ein Wettessen ab.\12Wir können dich\
im Moment leider\11nicht bedienen.",
  ["5e:6505"] = "…Schlürf,\
schlabber…",
  ["5e:6516"] = "Sprich mich\
nicht an!\12Du störst meine\
Konzentration!",
  ["5e:6546"] = "…Schluck…\
Schling…",
  ["5e:6554"] = "Quantität ist mir\
wichtiger als\11Qualität!\12Ich bin erst\
glücklich, wenn\11ich platze!",
  ["5e:658a"] = "Mampf, mampf…",
  ["5e:6599"] = "Das Essen hier ist\
gut, aber in\11DUKATIA CITY gibt\11es die besten\11Speisen der Welt.",
  ["5e:65dd"] = "Krümel… Mampf…",
  ["5e:65ee"] = "Hier wird dir\
niemand einen\12MÜNZKORB geben.\
Den bekommst du\11in JOHTO.",
  ["5e:6630"] = "Krümel… Kau…\12Ich esse immer\
weiter!",
  ["5e:6654"] = "Nachschub,\
CHEFKOCH!",
  ["5e:6661"] = "Wettessen! Essen\
bis zum Umfallen!\12Kein Zeitlimit!\
Der größte\12Vielfraß bekommt\
alles umsonst!",
  ["5e:66c3"] = "{PLAYER} hat\
{STRBUF}\11gefunden.",
  ["5e:66d5"] = "Aber {PLAYER} kann\
kein weiteres Item\11aufnehmen…",
  ["5e:6757"] = "Am Ende des\
RADWEGS ist\12FUCHSANIA CITY.",
  ["5e:67e6"] = "Der RADWEG\
fängt hier an.\12Es geht nur\
bergab, darum ist\11die Fahrt so\11erfrischend.\12Dieses Gefühl kann\
dir kein Schiff\12oder Zug\
vermitteln.",
  ["5e:6874"] = "Hey! Boah! Stopp!\12Du darfst nicht\
ohne FAHRRAD\12auf den RADWEG.",
  ["5e:690a"] = "Hast du von\
dem Vorfall im\11KRAFTWERK gehört?\12Es liegt östlich\
von hier, nahe\11LAVANDIA.",
  ["5e:6970"] = "Ich nehme meinen\
Posten als\11Wache ernst.\12Hey! Du hast\
einen POKéDEX.\12O.K. Du darfst\
passieren.",
  ["5e:6a0a"] = "RADWEG\
Ab hier geht's\11bergauf.",
  ["5e:6a2b"] = "Warte! Hast du\
kein FAHRRAD?\12Der RADWEG\
beginnt da vorne.\12Ohne FAHRRAD\
darfst du ihn\11nicht benutzen.",
  ["5f:4057"] = "BLAU: He! Hast du\
es endlich hierher\11geschafft?\12Auf den ZINNOBER-\
INSELN war mir\12nicht danach, aber\
jetzt können wir\11kämpfen.\12…\12Willst du etwa\
behaupten, du\11hättest alle\11ARENALEITER in\11JOHTO besiegt?\12He! Dann müssen\
die ARENALEITER in\11JOHTO ziemliche\11Jammerlappen sein.\12Aber - nur\
keine Bange.\12Ich werde dir\
sofort sagen, ob\12du ein guter\
Kämpfer bist.\12Fertig, JOHTO-\
Junge?",
  ["5f:4188"] = "BLAU: Was?\12Wie zum Teufel\
konnte ich gegen\11dich verlieren?\12…\12Also gut…\
Hier, nimm das -\11es ist der\11ERDORDEN.",
  ["5f:41e9"] = "{PLAYER} erhält\
ERDORDEN.",
  ["5f:4201"] = "BLAU: …\12In Ordnung. Ich\
hatte Unrecht. Du\12bist nicht aus\
Watte, sondern ein\11guter Trainer.\12Aber eines Tages\
werde ich dich\12besiegen. Ich\
vergesse dich\11nicht!",
  ["5f:4285"] = "BLAU: Hör gut zu.\12Es bekommt dir\
besser, nicht zu\11verlieren, bis ich\11dich besiegt habe!\11Klar?",
  ["5f:42c8"] = "He! Ein CHAMP\
in spe!\12Wie läuft es so?\
Du hast wohl\11gerade eine\11Glückssträhne.\12Der ARENALEITER\
hat den CHAMP\12vor drei Jahren\
besiegt.\12Das wird kein\
Kinderspiel!\12Gib alles, was\
du hast!",
  ["5f:437a"] = "Junge, Junge! Du\
bist sehr stark…\12Das war vielleicht\
ein erfrischender\12Kampf. Er hat mir\
Tränen in die\11Augen getrieben.",
  ["5f:442e"] = "Machst du dir\
viele Gedanken\12darüber, wie du\
deine POKéMON\11nennen sollst?\12Das Tauschen von\
POKéMON macht mehr\12Spaß, wenn sie\
Spitznamen haben.",
  ["5f:44a5"] = "Das sind HABBI--\
ein HABITAK--und\11FRATZI--ein\11RATTFRATZ.",
  ["5f:44d8"] = "HABBI: Kr-rrr!",
  ["5f:44ea"] = "FRATZI: Kikiii!",
  ["5f:4559"] = "Willkommen im\
TRAINERHAUS, dem\12neuesten und\
erlebnisreichsten\11Ort von VERTANIA\11CITY.\12Nur Trainer haben\
hier Zutritt.\12Du kannst gegen\
die Besten der\12Besten antreten!\
Geh nur die Treppe\11hinunter.",
  ["5f:45ff"] = "VERTANIA CITY ist\
dem INDIGO PLATEAU\11am nächsten.\12Man hat diesen Ort\
erbaut, weil ihn\12so viele Trainer\
auf ihrem Weg zum\12INDIGO PLATEAU \
passieren.",
  ["5f:468f"] = "Hier unten werden\
Übungskämpfe\11abgehalten.\12Ich würde liebend\
gerne sehen, wie\12Trainer aus JOHTO\
kämpfen.",
  ["5f:46f7"] = "Ich nehme an, du\
kannst nur dann\12CHAMP werden, wenn\
du viel herum-\12kommst und so\
viele Kämpfe wie\11möglich austrägst.\12Der CHAMP von\
ALABASTIA bereiste\12alle großen und\
kleinen Städte\11in KANTO.",
  ["5f:47a3"] = "Puh… Ich höre\
eine Zeit lang auf\11mit Kämpfen.",
  ["5f:47ce"] = "Übungskämpfe\
werden unten in\12der ÜBUNGSHALLE\
abgehalten.\12Auch erfahrene\
Trainer können\11gerne teilnehmen.",
  ["5f:4837"] = "Bei den Trainings-\
kämpfen gelten\12keine Regeln oder\
Vorgaben. Wie bei\12den Feldkämpfen\
ist alles erlaubt!",
  ["5f:489b"] = "…Was ist das?\
Eine strategische\11Notiz?\12Dieses Schrift-\
stück sieht aus\12wie die Spur eines\
ONIX…\11Völlig unlesbar…",
  ["5f:49fa"] = "Hi. Willkommen in\
unserer\11ÜBUNGSHALLE.\12Einmal pro Tag\
kannst du gegen\11einen Trainer\11kämpfen.",
  ["5f:4a44"] = "{STRBUF} ist\
heute dein Gegner.",
  ["5f:4a61"] = "Möchtest du\
kämpfen?",
  ["5f:4a7c"] = "Geh bitte einfach\
weiter.\12Du darfst sofort\
anfangen.",
  ["5f:4ab0"] = "Nur die Trainer,\
die kämpfen dür-\12fen, haben\
Zutritt.",
  ["5f:4af7"] = "Es tut mir Leid,\
das wäre für dich\12heute der zweite\
Kampf. Es ist aber\12nur ein Kampf pro\
Tag erlaubt.",
  ["5f:4b57"] = "Ich habe verloren…\
Mist…",
  ["5f:4b66"] = "Ich bin nur\
hergereist, um\11gegen dich zu\11kämpfen.",
  ["5f:4bd3"] = "Der ARENALEITER\
hier ist total\11cool.",
  ["5f:4bf9"] = "Warst du schon auf\
der ZINNOBER-\11INSEL?\12Es ist gleich die\
nächste Insel süd-\11lich von hier.",
  ["5f:4c8c"] = "Wo um Himmels\
Willen ist der\12ARENALEITER von\
VERTANIA? Ich will\11ihn herausfordern.",
  ["5f:4cd4"] = "In der PKMN-ARENA\
von VERTANIA gibt\11es keine TRAINER.\12Der ARENALEITER\
vertritt den\12Grundsatz, auch\
ohne die Hilfe von\11Untergebenen\11gewinnen\11zu können.",
  ["5f:4d4a"] = "Ich habe gehört,\
dass die PKMN-\11ARENA auf der\11ZINNOBERINSEL\11verschwunden ist.\12Ich frage mich,\
was aus PYRO, dem\11ARENALEITER\11geworden ist.",
  ["5f:4da7"] = "Mein großer Traum\
wäre es, ARENA-\11LEITER zu werden.",
  ["5f:4e44"] = "Hi! Ich bin froh\
dich zu sehen.\12Mich hat schon\
lange Zeit niemand\11mehr besucht.\12Ich bin über-\
glücklich! Das\11hier ist für dich.",
  ["5f:4ec4"] = "Das ist ein\
NUGGET.\12Ich kann dir keine\
weisen Ratschläge\12mitgeben, das hier\
muss ausreichen!",
  ["5f:4f34"] = "Bist du {PLAYER}?\12Ich bin der\
ASSISTENT von\11PROF. EICH.\12Ich wusste nicht,\
dass du hier\11bist.\12PROF. EICHs LABOR\
ist gleich hier\11in ALABASTIA.",
  ["5f:5008"] = "Nur Trainer, die\
sich als würdig\11erwiesen haben,\11dürfen eintreten.",
  ["5f:503e"] = "Du besitzt nicht\
alle ORDEN von\11JOHTO.\12Tut mir Leid. Ich\
darf dich nicht\11passieren lassen.",
  ["5f:5093"] = "Oh! Alle acht\
ORDEN von JOHTO!\12Geh bitte weiter!",
  ["5f:50d0"] = "Dieser Weg führt\
zum SILBERBERG.\12Dir werden be-\
ängstigend starke\11POKéMON begegnen.",
  ["5f:5116"] = "Du bist auf dem\
Weg zur POKéMON\11LIGA, nicht wahr?\12Die TOP VIER sind\
so stark, dass es\12einem Angst macht.\
Sie erwarten dich!",
  ["60:43f7"] = "LIND: {PLAYER}!\
Da bist du ja!\12Ich muss dich um\
etwas bitten.\12Ich habe einen Be-\
kannten namens MR.\11POKéMON.\12Ständig findet er\
eigenartiges Zeugs\12und fängt an, da-\
rüber zu fanta-\11sieren.\12Aber jetzt hat er\
mir eine E-Mail\12geschickt, in der\
steht, dass es\12sich diesmal um\
etwas Großes\12handeln muss.\12Das klingt zwar\
faszinierend, aber\12wir sind derzeit\
mitten in unseren\12eigenen POKéMON-\
Forschungen.\12Könntest du der\
Sache nachgehen?\12Ich gebe dir auch\
ein POKéMON als\11Partner.\12Es ist ein sehr\
seltenes POKéMON,\11das wir gerade\11erst entdeckt\11haben.\12Wähle eines aus!",
  ["60:4590"] = "Erscheint ein\
wildes POKéMON,\11lass deine POKéMON\11dagegen kämpfen.",
  ["60:45c2"] = "LIND: Warte! Wohin\
gehst du?",
  ["60:45e3"] = "LIND: Willst du\
FEURIGEL, das\11Feuer-POKéMON?",
  ["60:460e"] = "LIND: Wählst du\
KARNIMANI, das\11Wasser-POKéMON?",
  ["60:463a"] = "LIND: Entscheidest\
du dich für\12ENDIVIE, das\
Pflanzen-POKéMON?",
  ["60:4668"] = "LIND: Überlege es\
dir gut!\12Die Wahl deines\
Partners ist sehr\11wichtig.",
  ["60:46a2"] = "LIND: Ich bin auch\
der Meinung, dass\11dieses POKéMON\11sehr gut ist!",
  ["60:46c8"] = "{PLAYER} erhält\
{STRBUF}!",
  ["60:46db"] = "MR. POKéMON wohnt\
in der Nähe von\11ROSALIA CITY, der\11nächsten Stadt.\12Du gelangst fast\
ohne Umwege dort-\11hin.",
  ["60:472f"] = "Ist dein POKéMON\
verletzt, solltest\12du es mit Hilfe\
dieser Maschine\11heilen.",
  ["60:476c"] = "Ich gebe dir auch\
meine Telefon-\11nummer.\12Du kannst mich je-\
derzeit anrufen.",
  ["60:47a9"] = "{PLAYER} erhält\
LINDs Nummer.",
  ["60:47c3"] = "MR. POKéMON zieht\
durch das Land und\12sucht nach Rari-\
täten.\12Zu schade, dass er\
nur unbrauchbares\11Zeug findet…\12{PLAYER}, ich\
zähle auf dich!",
  ["60:4835"] = "Es beinhaltet ein\
von PROF. LIND ge-\11fangenes POKéMON.",
  ["60:485d"] = "Ich frage mich,\
wozu das gut ist!",
  ["60:4877"] = "POKéMON heilen?",
  ["60:4883"] = "LIND: {PLAYER}, das\
ist schrecklich…\12Oh, um was handelt\
es sich bei MR.\12POKéMONs großer\
Entdeckung?",
  ["60:48c8"] = "{PLAYER} übergibt\
PROF. LIND das\11RÄTSEL-EI.",
  ["60:48ef"] = "LIND: Das hier?",
  ["60:48fb"] = "Aber… ist das auch\
ein POKéMON-EI?\12Falls ja, dann ist\
es in der Tat eine\11große Entdeckung!",
  ["60:4936"] = "LIND: Wie?!?\12PROF. EICH hat dir\
einen POKéDEX\11gegeben?\12{PLAYER}, ist das\
wahr? D-Das ist ja\11unglaublich!\12Kein anderer ist\
wie er in der\11Lage, das wahre\11Potenzial eines\11Trainers zu er-\11kennen.\12Wow, {PLAYER}. Es\
ist vielleicht\12deine Bestimmung,\
der CHAMP zu\11werden.\12Es sieht auch so\
aus, als könntest\12du hervorragend\
mit POKéMON um-\11gehen.\12Du solltest die\
Herausforderung\12der POKéMON ARENEN\
annehmen.\12Die nächste ARENA\
befindet sich in\11VIOLA CITY.",
  ["60:4a85"] = "…{PLAYER}. Der\
Weg zum Ruhm ist\12lang und beschwer-\
lich.\12Bevor du los-\
ziehst, solltest\11du mit deiner Mama\11sprechen.",
  ["60:4af2"] = "LIND: Gib nicht\
auf! Ich rufe dich\12an, wenn ich etwas\
über dieses EI he-\11rausgefunden habe.",
  ["60:4b33"] = "LIND: {PLAYER}?\
Hast du schon mei-\11nen Assistenten\11getroffen?\12Er sollte mit dem\
EI im POKéMON-\12CENTER von VIOLA\
CITY warten.\12Du musst ihn ver-\
passt haben. Ver-\11suche, ihn dort zu\11finden.",
  ["60:4bd1"] = "LIND: He, hat sich\
das EI irgendwie\11verändert?",
  ["60:4bf6"] = "{PLAYER}? Ich\
dachte, etwas wäre\11aus dem EI ge-\11schlüpft.\12Wo ist das\
POKéMON?",
  ["60:4c28"] = "LIND: {PLAYER}, du\
siehst großartig\11aus!",
  ["60:4c41"] = "Was?\
Dieses POKéMON!?!",
  ["60:4c55"] = "Es ist aus dem EI\
geschlüpft! Also\11schlüpfen alle\11POKéMON aus EIERN…\12Nein, vermutlich\
trifft das nicht\11auf alle POKéMON\11zu.\12Es wartet wohl\
noch jede Menge\11Forschungsarbeit\11auf uns.",
  ["60:4cd2"] = "Danke, {PLAYER}!\
Du hilfst uns beim\12Aufklären vieler\
POKéMON-Mysterien!\12Bitte nimm dies\
als Zeichen unser-\11er Wertschätzung.",
  ["60:4d43"] = "Das ist ein\
EWIGSTEIN.\12Einige POKéMON\
entwickeln sich\12weiter, wenn sie\
einen bestimmten\11Level erreichen.\12Ein POKéMON,\
das den EWIGSTEIN\11trägt, wird sich\11aber nicht ent-\11wickeln.\12Gib ihn einem\
POKéMON, das\11sich nicht weiter-\11entwickeln soll!",
  ["60:4ded"] = "LIND: {PLAYER}, ich\
rufe dich an, wenn\11sich etwas tut.",
  ["60:4e1b"] = "…Seufz… Das\
gestohlene POKé-\11MON.\12Ich frage mich,\
wie es ihm geht.\12Man sagt, dass ein\
POKéMON, das von\12einem bösen Men-\
schen aufgezogen\11wird, selber böse\12wird.",
  ["60:4e86"] = "LIND: Hi, {PLAYER}!\
Dank dir komme ich\12mit meinen For-\
schungen hervor-\11ragend voran!\12Nimm dies als\
Zeichen meiner\11Dankbarkeit!",
  ["60:4ee7"] = "Der MEISTERBALL\
ist der Beste von \11allen!\12Er ist der ultima-\
tive BALL! Ihm\12kann kein POKéMON\
entwischen.\12Er wird nur aner-\
kannten POKéMON-\11Forschern über-\11reicht.\12Aber ich glaube,\
du hast bessere\12Verwendung dafür\
als ich, {PLAYER}!",
  ["60:4fa4"] = "LIND: {PLAYER}!\
Da bist du ja!\12Ich habe dich ge-\
rufen, weil ich\11dir etwas geben\11möchte.\12Es handelt sich um\
ein BOOTSTICKET.\12Jetzt kannst du\
auch in KANTO\11POKéMON fangen.",
  ["60:5020"] = "Das Schiff legt in\
OLIVIANA CITY ab.\12Aber das weißt du\
ja schon, {PLAYER}.\12Schließlich bist\
du mit deinen\11POKéMON schon\11viel herumge-\11kommen.\12Überbringe PROF.\
EICH in KANTO\11meine Grüße!",
  ["60:50e9"] = "{PLAYER}, ich\
will, dass du das\11mitnimmst.",
  ["60:5116"] = "Wir sind nur zu\
zweit und wir ha-\11ben viel zu tun.",
  ["60:5146"] = "Wir haben ein lau-\
tes Geräusch ge-\11hört…\12Als wir nach dem\
Rechten sahen,\11wurde ein POKéMON\11gestohlen.\12Ich kann nicht\
glauben, dass je-\11mand so etwas tun\11würde!\12…Seufz… Das\
gestohlene\11POKéMON.\12Ich frage mich,\
wie es ihm geht.\12Man sagt, dass ein\
POKéMON, das\12von einem bösen\
Menschen aufgezo-\11gen wird, selber\12böse wird.",
  ["60:5229"] = "{PLAYER}!\12Benutze diese\
auf deiner\11POKéDEX-Reise!",
  ["60:524b"] = "Um deinen POKéDEX\
zu vervollständi-\11gen, musst du\11POKéMON fangen.\12Wirf POKéBÄLLE\
nach wilden POKé-\11MON, um sie zu\11fangen.",
  ["60:52a1"] = "Ich hörte, dass\
hier ein POKéMON\11gestohlen worden\11sei…\12Ich habe von PROF.\
LIND einige Infor-\11mationen erhalten.\12Bei dem Dieb han-\
delt es sich um\11einen jungen Mann\11mit langen roten\11Haaren…\12Wie?\12Du hast gegen ei-\
nen solchen\11Trainer gekämpft?\12Hat er dir auch\
seinen Namen ge-\11nannt?",
  ["60:5371"] = "O.K.! Sein Name\
war also {RIVAL}.\12Danke, dass du mir\
bei den Ermitt-\11lungen geholfen\11hast!",
  ["60:53ae"] = "Das Fenster ist\
offen.\12Eine sanfte Brise\
weht herein.",
  ["60:53e2"] = "Hier ist er he-\
reingekommen!",
  ["60:53fd"] = "{PLAYER} öffnet\
ein Buch.\12Reise-Tipp 1:\12Drücke START, um\
das MENÜ zu\11öffnen.",
  ["60:543b"] = "{PLAYER} öffnet\
ein Buch.\12Reise-Tipp 2:\12Speichere deine\
Fortschritte mit\11SICHERN!",
  ["60:5477"] = "{PLAYER} öffnet\
ein Buch.\12Reise-Tipp 3:\12Öffne deinen\
BEUTEL und drücke\11SELECT, um deine\11Items zu ver-\11walten.",
  ["60:54c6"] = "{PLAYER} öffnet\
ein Buch.\12Reise-Tipp 4:\12Verwalte die At-\
tacken deiner\12POKéMON. Drücke\
den A-Knopf, um\12ihre Position zu\
verändern.",
  ["60:5521"] = "Die Verpackung\
des Snack, den\11PROF. LIND geges-\11sen hat, befindet\11sich hier…",
  ["60:5719"] = "Oh, {PLAYER}…!\
Unser Nachbar,\12PROF. LIND, hat\
nach dir gesucht.\12Er möchte, dass du\
etwas für ihn er-\11ledigst.\12Oh! Fast hätte ich\
es vergessen! Dein\12POKéMON-COM ist\
von der Reparatur\11zurück.\12Da hast du ihn!",
  ["60:57d2"] = "POKéMON-COM oder\
einfach nur\11POKéCOM.\12Ein wichtiges Ge-\
rät auf deinem\11Pfad als Trainer.\12Oh, der Wochentag\
ist noch nicht\11eingestellt.\12Das darfst du\
nicht vergessen!",
  ["60:5857"] = "Haben wir\
Sommerzeit?",
  ["60:5878"] = "Geh nach Hause, um\
deine Uhr auf SZ\11oder WZ einzu-\11stellen.\12Übrigens, weißt du\
über den Umgang\11mit dem TELEFON\11Bescheid?",
  ["60:58e0"] = "Muss man nicht\
einfach den POKé-\12COM einschalten\
und das TELEFON-\11Symbol anwählen?",
  ["60:591c"] = "Ich werde die An-\
leitung lesen.\12Schalte den POKé-\
COM ein und wähle\11das TELEFON-Symbol\11an!",
  ["60:5965"] = "Telefonnummern\
werden gespei-\12chert. Wähle ein-\
fach den Namen der\11Person, die du an-\11rufen möchtest.\12Ist das nicht\
praktisch?",
  ["60:59ca"] = "PROF. LIND wartet\
auf dich.\12Beeile dich, Baby!",
  ["60:59fa"] = "Wie lautete der\
Auftrag von PROF.\11LIND?\12…\12Das klingt nach\
einer wahren He-\11rausforderung.\12Aber du kannst\
stolz darauf sein,\11dass sich die Leu-\11te auf dich ver-\11lassen!",
  ["60:5a6c"] = "{PLAYER}, du\
schaffst es!\12Ich werde dir\
immer zur Seite\11stehen!",
  ["60:5a92"] = "Mamas Spezialität!\12ZINNOBER-VULKAN-\
BURGER!",
  ["60:5abc"] = "Die Spüle ist\
fleckenlos rein,\11so wie es Mama\11mag.",
  ["60:5ae9"] = "Mal sehen, was da\
im Kühlschrank zu\11finden ist…\12TAFELWASSER\
und leckere LIMO-\11NADE!",
  ["60:5b28"] = "Im Fernsehen läuft\
ein Film: Zwei\12Jungen fahren mit\
dem Zug unter ei-\12nem Himmel voller\
Sterne…\12Ich sollte mich\
auch besser auf\11den Weg machen!",
  ["60:5c5c"] = "PROF. EICHs POKé-\
MON-TALK! Schal-\11ten Sie auch das\11nächste Mal wieder\11ein!",
  ["60:5c8d"] = "POKéMON-PROGRAMM!",
  ["60:5c9c"] = "Hier ist DJ\
MARGIT, Ihr Co-\11Moderator!",
  ["60:5cbc"] = "POKéMON!\
POKéMON-PROGRAMM…",
  ["60:5d64"] = "PIKACHU ist ein\
entwickeltes\11POKéMON.\12PROF. LINDs Ent-\
deckungen sind\11wirklich erstaun-\11lich.\12Er ist berühmt für\
seine Forschungen\11auf dem Gebiet der\11POKéMON-Evolution.\12…Seufz…\12Ich wünschte, ich\
wäre ein Forscher\11wie er…",
  ["60:5e09"] = "PROF. EICHs POKé-\
MON-TALK! Schalten\11Sie auch das\11nächste Mal wieder\11ein!",
  ["60:5e3a"] = "POKéMON-PROGRAMM!",
  ["60:5e49"] = "Hier ist DJ\
MARGIT, Ihr Co-\11Moderator!",
  ["60:5e69"] = "POKéMON!\
POKéMON-PROGRAMM…",
  ["60:5eb8"] = "Hi, {PLAYER}! Mein\
Mann ist immer so\12beschäftigt. Ich\
hoffe, es geht ihm\11gut.\12Wenn er sich in\
seine POKéMON-\12Forschungen ver-\
tieft, vergisst er\11sogar zu essen.",
  ["60:5f2c"] = "Wenn ich groß bin,\
helfe ich meinem\11Papa!\12Ich werde ein\
großartiger POKé-\11MON-Professor!",
  ["60:5fdc"] = "POKéMON. Woher\
kommen sie?\12Wohin gehen sie?\12Warum war noch nie\
jemand Zeuge der\11Geburt eines\11POKéMON?\12Ich will es wis-\
sen. Ich werde\12mein Leben in den\
Dienst der POKé-\12MON-Forschung\
stellen!\12…\12Dies ist ein Teil\
von PROF. LINDs\11Aufzeichnungen.",
  ["60:610b"] = "Deine POKéMON\
sehen müde aus.\12Gönne ihnen eine\
kleine Pause.",
  ["60:6149"] = "Hier!\12Deine POKéMON\
sehen gut aus!\12Mach weiter so!",
  ["60:61b7"] = "Hier steht etwas\
geschrieben.\12Lesen?",
  ["60:61e0"] = "An meine Brüder\
und Schwestern:\12Wir sind stolz\
darauf, POKéMON-\11Trainern zu\11dienen.\12Wenn ein Trainer\
mit dir spricht,\11gib ihm etwas\11Nützliches.\12Eure\
MONJA\12Weiterlesen?",
  ["60:6277"] = "Montag, MONJA\
ROUTE 40\12Dienstag,\
DIETLINDE\11ROUTE 29\12Mittwoch, MITKO\
SEE DES ZORNS\12Donnerstag,\
DONATUS\11ROUTE 36\12Freitag, FRIEDA\
ROUTE 32\12Samstag, SAMSON\
EBENHOLZ CITY\12Sonntag, SONNFRIED\
ROUTE 37",
  ["60:6384"] = "Wohin möchtest du\
mit den POKéMON?\12Zur POKéMON LIGA?\12Sind deine POKéMON\
loyal genug, um\11zu gewinnen?\12Ich werde das\
überprüfen…",
  ["60:63e9"] = "Ah! Deine POKéMON\
vertrauen dir\11blind.\12Es ist schön, ei-\
nen guten Trainer\11zu treffen.\12Hier, ein Geschenk\
für deine Reise.",
  ["60:644d"] = "TM37 enthält\
SANDSTURM.\12Diese Attacke fügt\
beiden Kämpfern\11Schaden zu.\12Nur erfahrene\
Trainer sollten\11sie einsetzen.\12Setze sie ein,\
wenn du dich\11traust! Viel\11Glück!",
  ["60:64dd"] = "Fall es dir nicht\
mehr Vertrauen\12schenkt, wird es\
schwer für dich.\12Vertrauen ist der\
Bund zwischen\11POKéMON und den\11Trainern.",
  ["60:657f"] = "Du kannst die\
Stufen nicht\11hinaufklettern.\12Du kannst sie aber\
hinabspringen und\11sie als Abkürzung\11benutzen.",
  ["60:65cb"] = "Verschiedene\
POKéMON tauchen\11hier auf.\12Wenn du alle\
schnappen möch-\12test, dann musst\
du überall suchen.",
  ["61:400d"] = "Hallo!\12Der KARATE-\
MEISTER, der\12Leiter des KARATE\
DOJO, übt in einer\11Höhle in JOHTO.",
  ["61:4061"] = "Es geschieht, was\
geschehen muss!",
  ["61:4081"] = "Feinde, wo man\
hinsieht!",
  ["61:4180"] = "SABRINA: Ich\
wusste, dass du\11kommen würdest…\12Vor drei Jahren\
sah ich dich in\11einer Vision.\12Du willst meinen\
ORDEN haben.\12Ich habe keine\
Freude am Kämpfen,\12aber als LEITERIN\
ist es meine\12Pflicht, all denen\
einen ORDEN zu\12geben, die sich\
als würdig\11erwiesen haben.\12Da du es wünschst,\
werde ich dir\11meine psychischen\11Kräfte zeigen!",
  ["61:4295"] = "SABRINA: Deine\
Stärke…\12übertrifft meine\
Vorahnungen bei\11weitem…\12Vielleicht ist es\
nicht möglich,\12alles vorherzu-\
sagen, was die\11Zukunft bringt…\12Gut, du hast\
dir den SUMPFORDEN\11verdient.",
  ["61:4336"] = "{PLAYER} erhält\
SUMPFORDEN.",
  ["61:434e"] = "SABRINA: Der\
SUMPFORDEN\12aktiviert deine\
unterbewussten\11Kräfte…\12Obwohl ich nicht\
in der Lage war,\11deine Stärke\11vorauszusehen,\11weiß ich das ganz\11sicher.\12Du wirst ein\
gefeierter und\11beliebter CHAMP\11werden!",
  ["61:440d"] = "SABRINA: Deine Zu-\
neigung zu deinen\12POKéMON hat meine\
Psychostärke\11übertroffen…\12Die Kraft der\
Liebe ist meiner\12Ansicht nach auch\
eine Art von\11Psychostärke…",
  ["61:448a"] = "Die Kraft all\
derer, die du\11besiegt hast,\11offenbart sich\11mir!",
  ["61:44bc"] = "Stark…\
Viel zu stark…",
  ["61:44d5"] = "Woher kommt deine\
Kraft?",
  ["61:44f8"] = "Psychische Stärke\
ist die Kraft\11deiner Seele.",
  ["61:4522"] = "Deine Seele ist\
stärker als meine!",
  ["61:4547"] = "Du hast auch deine\
Seele gestärkt,\11nicht nur deine\11Fähigkeiten.",
  ["61:457e"] = "Hehehehe…\
Ich habe es\11deutlich vor mir.\12Ich kann in deine\
Seele blicken!",
  ["61:45b5"] = "Obwohl ich in dir\
lesen kann, habe\11ich verloren…",
  ["61:45d7"] = "Mist! Ich habe\
vergessen, dass\11ich meine Nieder-\11lage gegen dich\11voraussah.",
  ["61:460d"] = "Das KARATE DOJO\
nebenan war früher\11die PKMN-ARENA der\11Stadt.",
  ["61:4643"] = "Ich war leicht\
zu besiegen…",
  ["61:4654"] = "Der KARATE-\
MEISTER, Leiter\12des KARATE DOJO,\
ist gerade von\11SABRINA besiegt\11worden.",
  ["61:46a2"] = "He! Ein CHAMP\
in spe!\12Ein Trainer\
deines Kalibers\12braucht sicher\
keine Anweisung,\12wie mit Psycho-\
POKéMON umzugehen\11ist, nicht wahr?\12Ich erwarte\
Großes von dir!\12Viel Glück!",
  ["61:4741"] = "Das war wieder ein\
fantastischer\11Kampf!",
  ["61:486d"] = "In LAVANDIA CITY\
ist ein großer\11RADIOTURM.",
  ["61:4894"] = "Ich möchte noch\
stärker werden,\11aber das bin ich\11noch nicht…\12Kannst du mir\
zeigen, wie man\11stärker wird?",
  ["61:493b"] = "Im Norden von\
LAVANDIA CITY ist\11ein großes\11KRAFTWERK.",
  ["61:496e"] = "Ich bin gerade\
durch den FELS-\12TUNNEL gekommen.\
Da war irgendetwas\11im Gange beim\11KRAFTWERK.",
  ["61:49c9"] = "Die Höhlen stürzen\
leicht ein.\12In letzter Zeit\
sind einige Höhlen\12verschwunden. Wie\
die Höhle vor\11AZURIA CITY.\12Für einen Profi-\
WANDERER ist das\11Grundwissen.",
  ["61:4a60"] = "Die ZENTRALE von\
SILPH CO. und der\12MAGNETZUG-BAHNHOF\
sind sehenswürdige\12Orte in SAFFRONIA\
CITY.",
  ["61:4b33"] = "…\12…\12…\12…\12Du wolltest es so!",
  ["61:4b56"] = "TM29 ist PSYCHO-\
KINESE.\12Sie kann die\
SPEZ-Werte des\11Gegners senken.",
  ["61:4c45"] = "Es tut mir Leid,\
aber der MAGNETZUG\11ist im Moment\11nicht in Betrieb.",
  ["61:4c79"] = "Abfahrt nach\
DUKATIA CITY in\11wenigen Minuten.\12Steigst du auch\
ein?",
  ["61:4cb3"] = "Darf ich bitte\
deinen FAHRSCHEIN\11sehen?\12Danke sehr. Hier\
lang, bitte.",
  ["61:4cef"] = "Es tut mir Leid,\
aber du hast\11keinen FAHRSCHEIN.",
  ["61:4d11"] = "Beehre uns\
bald wieder.",
  ["61:4d2c"] = "Ankunft in\
SAFFRONIA CITY.\12Beehre uns\
bald wieder.",
  ["61:4d63"] = "Der MAGNETZUG\
ist mit modernster\12Technik ausge-\
stattet und\12erreicht durch die\
Nutzung von Elek-\12trizität und\
Magneten unglaub-\12liche Geschwin-\
digkeit.\12Ohne Elektrizität\
allerdings…",
  ["61:4dfa"] = "Puh…\12Wie oft bin ich\
von KANTO nach\12JOHTO und zurück\
gefahren?",
  ["61:4e44"] = "Bevor der MAGNET-\
ZUG-BAHNHOF erbaut\12wurde, stand dort\
ein Haus.\12Ein kleines\
Mädchen, NACH-\11AHMERIN genannt,\11lebte dort.",
  ["61:4eb9"] = "Hallo. Hast du\
einen FAHRSCHEIN?\12Ich habe einen.\
Alle Einwohner in\12SAFFRONIA CITY,\
die den MAGNETZUG\12benutzen, haben\
einen FAHRSCHEIN.",
  ["61:4f9c"] = "Willkommen. Das\
ist das BÜRO-\11GEBÄUDE der\11SILPH CO.",
  ["61:4fcf"] = "Nur das Personal\
hat Zutritt zu den\11oberen Geschossen.\12Aber, da du nun\
schon mal da bist,\12gebe ich dir\
dieses hübsche\11Souvenir.",
  ["61:5041"] = "Das ist das\
neueste Produkt\12der SILPH CO. Das\
gibt es noch nir-\11gends zu kaufen.",
  ["61:50cd"] = "Meine Tochter\
macht gerne\11Menschen nach.\12Dieses Hobby hat\
ihr den Spitznamen\12NACHAHMERIN einge-\
bracht.",
  ["61:512e"] = "Meine Tochter ist\
sehr ichbezogen…\12Sie hat nur wenige\
Freunde.",
  ["61:516c"] = "Vor kurzem hat sie\
ihre POKéPUPPE,\12die ihr ein Junge\
vor drei Jahren\12geschenkt hat,\
verloren.\12Ihre Nachahmerei\
ist seitdem sogar\11noch besser\11geworden…",
  ["61:51e4"] = "HEITEIRA: Teirii!",
  ["61:52f1"] = "{PLAYER}: Hi! Magst\
du POKéMON?\12{PLAYER}: Äh, nein,\
ich frage dich.\12{PLAYER}: Was?\
Du bist komisch!",
  ["61:533f"] = "NACHAHMERIN: Hm?\
Das Nachahmen\11aufgeben?\12Aber das ist\
meine liebste\11Beschäftigung!",
  ["61:537b"] = "{PLAYER}: Hi!\
Ich habe gehört,\12dass du deine\
Lieblings-\12POKéPUPPE\
verloren hast.\12{PLAYER}: Gibst du\
mir einen FAHR-\11SCHEIN, wenn ich\11sie finde?\12{PLAYER}: Ich suche\
sie für dich.\12Du glaubst, sie\
auf dem Weg nach\11ORANIA CITY\11verloren zu haben?",
  ["61:542d"] = "NACHAHMERIN:\
Bitte?\12Ich soll dir nicht\
sagen, was du zu\11tun hast?\12Aber ich mache mir\
wirklich Sorgen…\11Was, wenn jemand\11sie findet?",
  ["61:5496"] = "NACHAHMERIN: Jaa!\
Das ist meine\11PIEPI-POKéPUPPE!\12Siehst du die\
Naht am rechten\12Bein? Das ist\
der Beweis!",
  ["61:54f9"] = "Also gut. Hier ist\
der FAHRSCHEIN für\11den MAGNETZUG! Wie\11versprochen.",
  ["61:552b"] = "NACHAHMERIN: Das\
ist der FAHRSCHEIN\11für den MAGNETZUG.\12Der Mann von der\
Eisenbahn gab mir\12das, als sie unser\
altes Haus nieder-\12rissen, um den\
BAHNHOF zu bauen.",
  ["61:55af"] = "{PLAYER}: Hi!\
Vielen Dank für\11den FAHRSCHEIN!\12{PLAYER}: Bitte?\12{PLAYER}: Ist es\
wirklich so toll,\11jede Bewegung\11nachzuahmen?",
  ["61:560c"] = "NACHAHMERIN: \
Darauf kannst du\11wetten!",
  ["61:562d"] = "DODRI: Gii giii!",
  ["61:5640"] = "SPIEGLEIN, SPIEG-\
LEIN AN DER WAND,\12WER IST DIE\
\
SCHÖNSTE IM GANZEN\12LAND?",
  ["61:567b"] = "Das ist ein\
seltenes POKéMON!\11Was?\12Es ist nur eine\
Puppe…",
  ["61:5702"] = "In JOHTO gibt es\
viele historische\12Städte, die ich\
gerne besichtigen\11würde!",
  ["61:5766"] = "Du kommst aus\
JOHTO, nicht wahr?\12Wie gefällt dir\
KANTO? Schön hier,\11oder nicht?",
  ["61:57ff"] = "Yippi!\12Ich spüre einen\
dunklen Schatten,\11der über dir\11schwebt.\12Benutze dies, um\
ihn loszuwerden!",
  ["61:5851"] = "Du schwebtest in\
Lebensgefahr!\11Jetzt bist du\11in Sicherheit.",
  ["61:5888"] = "Meine Oma befasst\
sich mit dem\12Vertreiben von,\
wie sie sagt,\11bösen Geistern.\12Es tut mir Leid,\
dass sie dich\11erschreckt hat.",
  ["62:402c"] = "Die POKéBÄLLE\
sind leider aus-\11verkauft!\12Hoffentlich kommt\
bald eine neue\11Lieferung!",
  ["62:406b"] = "POKéBÄLLE sind\
wieder auf Lager!\11Jetzt kann ich\11POKéMON fangen!",
  ["62:4098"] = "Als ich durch das\
Gras spazierte,\12hat ein Käfer-\
POKéMON mein\12POKéMON ver-\
giftet!\12Ich ging einfach\
weiter, aber dann\11wurde mein POKé-\11MON plötzlich be-\11siegt.\12Du solltest stän-\
dig ein GEGENGIFT\11mit dir führen.",
  ["62:4182"] = "Das ist toll! Ich\
kann so viele\12POKéMON lagern,\
wie ich will, und\11das umsonst!",
  ["62:41c0"] = "Dieser PC steht\
jedem Trainer kos-\11tenfrei zur Verfü-\11gung.",
  ["62:41e9"] = "Das KOMMUNIKA-\
TIONS-ZENTRUM im\11oberen Stock wurde\11gerade erst einge-\11richtet.\12Aber an der Fer-\
tigstellung wird\11noch gearbeitet.",
  ["62:423e"] = "Das KOMMUNIKA-\
TIONS-ZENTRUM im\11oberen Stock wurde\11gerade erst einge-\11richtet.\12Ich habe dort be-\
reits POKéMON\11getauscht.",
  ["62:42e2"] = "Möchtest du he-\
rausfinden, wie\12gut du als POKé-\
MON-Trainer bist?\12Dann solltest du\
alle POKéMON ARE-\12NEN in JOHTO auf-\
suchen und ORDEN\11sammeln.",
  ["62:435d"] = "Wenn ich älter\
bin, werde ich\11auch ein ARENA-\11LEITER!\12Ich werde meine\
POKéMON gegen\12die meiner Freunde\
antreten lassen,\12damit sie stärker\
werden!",
  ["62:4405"] = "Als ich noch ein\
Junge war, war ich\11ein richtiger\11Heißsporn!\12Ich gebe dir einen\
Rat: Fange viele\11POKéMON!\12Behandle sie alle\
mit Freundlich-\11keit!",
  ["62:44bb"] = "POKéMON sammeln\
in Kämpfen Erfah-\12rung und verändern\
ihre Gestalt.",
  ["62:44f4"] = "POKéMON\
wechseln?\12Ich wäre scho-\
ckiert, wenn das\11jemand tun würde!",
  ["62:457a"] = "Du weißt, dass\
POKéMON BEEREN\11fressen.\12Die KP meiner \
POKéMON sind ge-\11stiegen, weil sie\11eine BEERE fraßen.\12Hier, ich teile\
mit dir!",
  ["62:45e4"] = "Suche in Bäumen\
nach BEEREN. Sie\11fallen einfach\11herunter.",
  ["62:4755"] = "Hallo! Du musst\
{PLAYER} sein.\12PROF. LIND sagte,\
dass du kommst.",
  ["62:4797"] = "PROF. LIND soll\
das hier unter-\11suchen.",
  ["62:47c1"] = "{PLAYER} erhält\
RÄTSEL-EI.",
  ["62:47da"] = "Ich kenne ein\
Paar, das eine\11POKéMON-PENSION \11leitet.\12Sie gaben mir\
das EI.\12Ich war derart\
fasziniert, dass\11ich PROF. LIND ei-\11ne E-Mail schrieb.\12Was die Entwick-\
lung von POKéMON\11betrifft, ist\11PROF. LIND eine\11Kapazität.",
  ["62:4881"] = "Sogar PROF. EICH\
schätzt ihn sehr.",
  ["62:48a6"] = "Ich gehe davon\
aus, dass PROF.\11LIND mehr darüber\11weiß.",
  ["62:48dc"] = "Kehrst du zu PROF.\
LIND zurück?\12Dein POKéMON\
sieht müde aus.\11Du solltest eine\11kurze Pause\11einlegen.",
  ["62:4923"] = "Ich bin auf dich\
angewiesen!",
  ["62:4939"] = "Das Leben ist\
schön! Es gibt\12immer etwas Neues\
zu entdecken!",
  ["62:4974"] = "EICH: Aha! Du bist\
also {PLAYER}!\12Mein Name\
ist PROF. EICH!\11Ich bin von Beruf\11POKéMON-Forscher.\11Ich besuche gerade\11meinen alten\11Freund MR. POKé-\11MON.\12Ich hörte, du hast\
etwas für PROF.\12LIND besorgt, also\
habe ich gewartet.\12Oh! Was ist das?\
Ein seltenes\11POKéMON!\12Mal sehen…\12Hm, ich verstehe!\12Ich weiß, warum\
PROF. LIND dir ein\12POKéMON für die\
Besorgung gab.\12Für Forscher wie\
PROF. LIND und\12mich sind POKéMON\
unsere Freunde.\12Er erkannte, dass\
du deine POKéMON\12liebevoll und\
umsichtig\11umsorgst.\12…Ah!\12Du scheinst\
zuverlässig.\12Möchtest du mir\
auch helfen?\12Dies ist die\
neueste Version\11des POKéDEX.\12Er erfaßt\
automatisch Daten\11über POKéMON,\11die man gefangen\11oder gesehen hat!\12Er ist eine Art\
Hi-Tech-Lexikon!",
  ["62:4bbb"] = "{PLAYER} erhält\
POKéDEX!",
  ["62:4bcd"] = "Triff auf viele\
verschiedene POKé-\12MON und vervoll-\
ständige den\11POKéDEX!\12Ich bin schon zu\
lange hier.\12Ich muss nach\
DUKATIA CITY zu\11meiner Radioshow.\12{PLAYER}, ich\
zähle auf dich!",
  ["62:4c65"] = "Hm? Diese HAUT!\
Was ist das?\11Ein rotes\11GARADOS?\12Das ist selten!\
Ich muss es haben…\12{PLAYER}, möchtest\
du es tauschen?\12Ich kann dir den\
EP-TEILER, den mir\11PROF. EICH gegeben\11hat, anbieten.",
  ["62:4cfc"] = "Wirklich Schade!\
Das gibt es nur\11selten.",
  ["62:4d32"] = "Das sind auslän-\
dische Zeitungen.\12Ich kann die\
Schlagzeilen\11nicht lesen…",
  ["62:4d73"] = "Dies ist ein\
großer Computer.\11Hm, er ist kaputt.",
  ["62:4d9b"] = "Ein ganzer Stapel\
seltsamer Münzen!\12Vielleicht sind\
sie aus einem\11anderen Land…",
  ["62:4e29"] = "Hi, Kumpel!\
Warst du schon im\11KNOFENSA-TURM?",
  ["62:4e4f"] = "Ich bin zu weit\
gelaufen. Ich\11sollte zu Hause\11anrufen!",
  ["64:558c"] = "",
  ["64:558e"] = "Ich bin der\
PENSIONSLEITER.\11Soll ich eines\11deiner POKéMON\11aufziehen?",
  ["64:55bd"] = "Ich bin der\
PENSIONSLEITER.\11Kennst du dich\11mit EIERN aus?\12Ich habe POKéMON\
mit meiner\11Frau aufgezogen.\12Wir waren ent-\
setzt, als wir ein\11EI fanden!\12Das ist doch\
unglaublich, oder?\12Soll ich ein\
POKéMON aufziehen?",
  ["64:566a"] = "Ich bin die\
PENSIONSLEITERIN.\12Soll ich eines\
deiner POKéMON\11aufziehen?",
  ["64:56a0"] = "Ich bin die\
PENSIONSLEITERIN.\11Kennst du dich\11mit EIERN aus?\12Mein Mann und ich\
haben POKéMON\11aufgezogen.\12Wir waren er-\
staunt, als wir\11ein EI fanden!\12Das ist doch\
unglaublich, oder?\12Soll ich eines\
deiner POKéMON\11aufziehen?",
  ["64:575e"] = "Welches soll\
ich aufziehen?",
  ["64:577c"] = "Oh? Aber du hast\
nur ein POKéMON.",
  ["64:579d"] = "Tut mir Leid, aber\
ich kann kein EI\11annehmen.",
  ["64:57bf"] = "Entferne den\
BRIEF, ehe du mich\11aufsuchst.",
  ["64:57e4"] = "Wenn du mir das\
gibst, wer soll\11dann kämpfen?",
  ["64:5815"] = "O.K. Ich kümmere\
mich um dein\11{STRBUF}.",
  ["64:5830"] = "Hole es später\
wieder ab.",
  ["64:5849"] = "Wir sind genial,\
oder? Möchtest du\11dein {STRBUF}\11sehen?",
  ["64:587b"] = "Dein {STRBUF}\
ist groß geworden.\12Es ist um {NUM}\
Level gestiegen.\12Wenn du dein\
POKéMON zurück\11haben möchtest,\11kostet dich das\11¥{NUM}.",
  ["64:58e9"] = "Perfekt! Hier ist\
dein POKéMON.",
  ["64:5904"] = "{PLAYER} erhält\
{STRBUF}.",
  ["64:5917"] = "Huh? Schon zurück?\
Dein {STRBUF}\12sollte noch ein\
wenig hierbleiben.\12Wenn du dein\
POKéMON zurück-\11haben möchtest,\11zahle ¥100.",
  ["64:5987"] = "Du hast keinen\
Platz mehr.",
  ["64:59a1"] = "Du hast nicht\
genügend Geld.",
  ["64:59be"] = "Oh, in Ordnung.",
  ["64:59ce"] = "Komm wieder.",
  ["64:59db"] = "Noch nicht…",
  ["64:59e5"] = "Ah, du bist's!\12Wir haben uns um\
dein POKéMON\12gekümmert und\
waren sehr\11erstaunt!\12Dein POKéMON hatte\
ein EI!\12Wir wissen nicht,\
wie es dahin\12gekommen ist; dein\
POKéMON hat es.\11Möchtest du es?",
  ["64:5a8a"] = "{PLAYER} erhält\
das EI!",
  ["64:5a9f"] = "Pass gut darauf\
auf.",
  ["64:5ab6"] = "Gut, ich passe\
darauf auf. Danke!",
  ["64:5ad7"] = "Du kannst keine\
POKéMON mehr\11tragen. Komm\11später wieder.\11",
  ["65:4751"] = "Huch?\12",
  ["65:4759"] = "",
  ["65:475b"] = "{STRBUF}\
schlüpft aus dem\11EI!",
  ["65:4778"] = "Möchtest du\
{STRBUF} einen\11Spitznamen geben?",
  ["65:4793"] = "{STRBUF} hast du\
der PENSIONSLEI-\11TERIN anvertraut.",
  ["65:47c4"] = "{STRBUF} hast du\
dem PENSIONSLEITER\11anvertraut.",
  ["65:47f4"] = "Es strotzt vor\
Energie.",
  ["65:480f"] = "{STRBUF}\
ist uninteressant.",
  ["65:482d"] = "Es kümmert sich um\
{STRBUF}.",
  ["65:484c"] = "Es ist freundlich\
gegenüber\12{STRBUF}.",
  ["65:4866"] = "Es zeigt Interesse\
an {STRBUF}.",
  ["65:4883"] = "Hier sind keine\
BRIEFE.",
  ["65:4899"] = "Der leere BRIEF\
wurde eingesteckt.",
  ["65:48b9"] = "Dein BEUTEL\
ist voll.",
  ["65:48cc"] = "Soll der Inhalt\
des BRIEFES\11gelöscht werden?",
  ["65:48f1"] = "Es hat schon\
ein Item.",
  ["65:4911"] = "Du kannst einem EI\
keinen BRIEF\11geben.",
  ["65:492d"] = "Der BRIEF wurde\
aus dem EINGANG\11gelöscht.",
  ["65:4993"] = "Es gibt POKéMON,\
die einen\11BRIEF tragen.\12Entferne den\
BRIEF.",
  ["65:544a"] = "Entferne zuerst\
den BRIEF.",
  ["65:54fd"] = "Der Inhalt des\
BRIEFES wird\11gelöscht\11Einverstanden?",
  ["65:5522"] = "BRIEF entfernt von\
{STRBUF}.",
  ["65:553d"] = "Es ist nicht\
genügend Platz\11für entfernte\11BRIEFE.",
  ["65:5561"] = "Den entfernten\
BRIEF auf deinen\11PC übertragen?",
  ["65:5584"] = "Du kannst keine\
weiteren BRIEFE\11auf deinen PC\11übertragen.",
  ["65:559f"] = "Der BRIEF wurde\
auf deinen PC\11übertragen.",
  ["65:5c61"] = "Wie viele?",
  ["65:5c6c"] = "{NUM} x\
{STRBUF}?\12Das macht dann\
¥{NUM}.",
  ["65:5c8c"] = "Hallo, Kleiner.\12Ich verkaufe\
preiswerte\11Kräutermedizin.\12Sie wirkt, ist\
aber bitter.\12Deine POKéMON\
werden sie nicht\11mögen.\12Hihihihi…",
  ["65:5d07"] = "Wie viele?",
  ["65:5d12"] = "{NUM} x {STRBUF}\
kostet ¥{NUM}.",
  ["65:5d32"] = "Danke, Kleiner.\
Hihihihi…",
  ["65:5d4e"] = "Oh? In deinem\
BEUTEL ist kein\11Platz mehr.",
  ["65:5d6c"] = "Hihihi… Du hast\
nicht genug Geld.",
  ["65:5d8e"] = "Besuche mich\
wieder. Hihihihi…",
  ["65:5dab"] = "Heh! Bist du an\
Schnäppchen\11interessiert?\12Ich verkaufe\
seltene Items,\12aber leider sind\
es nur Einzel-\12stücke.",
  ["65:5e14"] = "{STRBUF}\
kostet ¥{NUM}.\12Kaufen?",
  ["65:5e31"] = "Danke.",
  ["65:5e3a"] = "Uhh, dein BEUTEL\
platzt aus\11allen Nähten.",
  ["65:5e5b"] = "Das hast du schon\
gekauft. Ich\11habe keines mehr.",
  ["65:5e8c"] = "Uhh, du bist knapp\
bei Kasse.",
  ["65:5eaa"] = "Schau mal\
wieder vorbei.",
  ["65:5ec3"] = "Was ist? Brauchst\
du Medizin ?",
  ["65:5ee2"] = "Wie viele?",
  ["65:5eed"] = "{NUM} x {STRBUF}\
kostet ¥{NUM}.",
  ["65:5f0f"] = "Vielen Dank!",
  ["65:5f1d"] = "Du hast keinen\
Platz mehr.",
  ["65:5f3c"] = "Wie? Das ist nicht\
genügend Geld.",
  ["65:5f5a"] = "In Ordnung.\
Bis die Tage.",
  ["65:5f76"] = "Du hast nichts\
zu verkaufen.",
  ["65:5f97"] = "Wie viele?",
  ["65:5fa2"] = "Ich zahle dir\
¥{NUM}.\12Reicht das?",
  ["65:5fc6"] = "Willkommen! Womit\
kann ich dienen",
  ["65:5fe4"] = "Hier, bitte.\
Dankeschön!",
  ["65:5ffe"] = "Du hast nicht\
genügend Geld.",
  ["65:601b"] = "Du kannst keine\
weiteren Items\11mehr tragen.",
  ["65:603b"] = "Leider kann ich\
dir das nicht\11abkaufen.",
  ["65:605d"] = "Komm wieder!",
  ["65:6071"] = "Kann ich noch\
etwas für dich\11tun?",
  ["65:6092"] = "Erhält ¥{NUM} für\
{NUM} x {STRBUF}.",

  -- Seven English pointer locations have no one-to-one address partner in
  -- the localized script graph. Six moved phone/swarm messages are copied
  -- from their official German records; one unused branch is translated in
  -- the same terminology and 18-glyph layout.
  ["41:4aba"] = "Oh, du bist also in\n{STRBUF}…\fIst dort nicht\n{STRBUF}?\fHast du es dir\nangesehen?",
  ["41:5cdb"] = "Willst du kämpfen?\nEs wird nicht so\fwie das letzte Mal\nsein.\fDies ist der Ort,\nan dem du\fmich findest:\n{STRBUF}.",
  ["41:5d37"] = "Willst du kämpfen?\nDiesmal werde ich\vgewinnen!\fIch warte auf dich\nin der Nähe von\f{STRBUF}.\nSuch mich, O.K.?",
  ["41:5e48"] = "Das musst du se-\nhen! Das ist wild!\fEin ganzer Schwarm\n{STRBUF}S ist in\f{STRBUF}\naufgetaucht!",
  ["41:5e9c"] = "Erstaunlich!\f{STRBUF}\nist DER Ort, um\f{STRBUF}S\nzu fangen.\f{PLAYER}, hol\ndeine ANGEL!",
  ["41:5efa"] = "Ein Freund hat mir\nFolgendes erzählt:\fEr sah eine Menge\n{STRBUF}S in\v{STRBUF}.\f{PLAYER}, das\nsolltest du dir\vansehen.",
  ["5b:4714"] = "Komm jederzeit\nwieder vorbei!",
}
